--
-- Name: auth_account_link_discord(bigint, character varying, text, text, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.auth_account_link_discord(p_auth_user_id bigint, p_provider_account_id character varying, p_access_token text DEFAULT NULL::text, p_refresh_token text DEFAULT NULL::text, p_expires_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_token_type text DEFAULT NULL::text, p_scope text DEFAULT NULL::text, p_id_token text DEFAULT NULL::text, p_session_state text DEFAULT NULL::text) RETURNS TABLE(auth_account_id bigint, auth_user_id bigint, provider text, provider_account_id character varying, account_type text, access_token text, refresh_token text, expires_dt timestamp with time zone, token_type text, scope text, id_token text, session_state text, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// LINKS THE AUTH USER TO THE SINGLE SUPPORTED DISCORD OAUTH ACCOUNT                                            ////
--//// PURPOSE: Preserves account linkage metadata without persisting Discord OAuth token values.                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing_auth_user_id bigint;
	v_existing_provider_account_id varchar(32);
	v_existing_account_owner_auth_user_id bigint;
BEGIN
	IF p_provider_account_id IS NULL OR btrim(p_provider_account_id) = '' THEN
		RAISE EXCEPTION 'Discord provider_account_id is required.';
	END IF;

	SELECT au.auth_user_id
	INTO v_existing_auth_user_id
	FROM web_priv.auth_users au
	WHERE au.discord_id    = p_provider_account_id
	  AND au.auth_user_id <> p_auth_user_id
	;

	IF FOUND THEN
		RAISE EXCEPTION
			'Discord ID % is already linked to auth user %.',
			p_provider_account_id,
			v_existing_auth_user_id;
	END IF;

	SELECT aa.provider_account_id
	INTO v_existing_provider_account_id
	FROM web_priv.auth_accounts aa
	WHERE aa.auth_user_id          = p_auth_user_id
	  AND aa.provider              = 'discord'
	  AND aa.provider_account_id <> p_provider_account_id
	;

	IF FOUND THEN
		RAISE EXCEPTION
			'Auth user % is already linked to a different Discord account %.',
			p_auth_user_id,
			v_existing_provider_account_id;
	END IF;

	SELECT aa.auth_user_id
	INTO v_existing_account_owner_auth_user_id
	FROM web_priv.auth_accounts aa
	WHERE aa.provider              = 'discord'
	  AND aa.provider_account_id   = p_provider_account_id
	  AND aa.auth_user_id        <> p_auth_user_id
	;

	IF FOUND THEN
		RAISE EXCEPTION
			'Discord account % is already linked in auth_accounts to auth user %.',
			p_provider_account_id,
			v_existing_account_owner_auth_user_id;
	END IF;

	UPDATE web_priv.auth_users au
	SET discord_id = p_provider_account_id
	WHERE au.auth_user_id = p_auth_user_id
	  AND au.is_disabled  = false
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Enabled auth user % does not exist.', p_auth_user_id;
	END IF;

	RETURN QUERY
	INSERT INTO web_priv.auth_accounts(auth_user_id,
								   provider,
								   provider_account_id,
								   account_type,
								   access_token,
								   refresh_token,
								   expires_dt,
								   token_type,
								   scope,
								   id_token,
								   session_state)
	VALUES (p_auth_user_id,
			'discord',
			p_provider_account_id,
			'oauth',
			NULL,
			NULL,
			p_expires_dt,
			p_token_type,
			p_scope,
			NULL,
			NULL)
	ON CONFLICT ON CONSTRAINT auth_accounts_provider_uq
	DO UPDATE
	SET auth_user_id   = EXCLUDED.auth_user_id,
		account_type   = EXCLUDED.account_type,
		access_token   = NULL,
		refresh_token  = NULL,
		expires_dt     = EXCLUDED.expires_dt,
		token_type     = EXCLUDED.token_type,
		scope          = EXCLUDED.scope,
		id_token       = NULL,
		session_state  = NULL,
		updated_dt     = now()
	RETURNING web_priv.auth_accounts.auth_account_id,
			  web_priv.auth_accounts.auth_user_id,
			  web_priv.auth_accounts.provider,
			  web_priv.auth_accounts.provider_account_id,
			  web_priv.auth_accounts.account_type,
			  web_priv.auth_accounts.access_token,
			  web_priv.auth_accounts.refresh_token,
			  web_priv.auth_accounts.expires_dt,
			  web_priv.auth_accounts.token_type,
			  web_priv.auth_accounts.scope,
			  web_priv.auth_accounts.id_token,
			  web_priv.auth_accounts.session_state,
			  web_priv.auth_accounts.created_dt,
			  web_priv.auth_accounts.updated_dt;
END;
$$;


