--
-- Name: auth_sync_discord_login(bigint, character varying, text, text, text, text, timestamp with time zone, boolean, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.auth_sync_discord_login(p_auth_user_id bigint, p_discord_id character varying, p_username text, p_global_name text, p_avatar_hash text, p_avatar_url text, p_created_from_snowflake timestamp with time zone, p_is_member boolean, p_joined_dt timestamp with time zone, p_roles jsonb, p_sync_source text DEFAULT 'login'::text) RETURNS TABLE(discord_user_id bigint, auth_user_id bigint, discord_id character varying, username text, global_name text, avatar_url text, is_member boolean, roles_synced_dt timestamp with time zone, last_login_dt timestamp with time zone, is_role_refresh_due boolean, is_authenticated boolean, is_admin boolean, is_editor boolean, max_rank integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// SYNCS CURRENT DISCORD LOGIN STATE AND RETURNS THE RESULTING ACCESS SUMMARY                                 ////
--//// -----------------------------------------Powered by Wooden Engine----------------------------------------- ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_discord_user_id bigint;
    v_sync_dt timestamptz;
    v_access record;
BEGIN
    v_sync_dt := now();

    PERFORM web_priv.discord_role_assert_defaults_present();

    PERFORM web_priv.auth_user_assert_discord_link(
        p_auth_user_id,
        p_discord_id
    );

    PERFORM web_priv.discord_role_upsert_discovered(
        p_roles
    );

    v_discord_user_id := web_priv.discord_user_upsert_from_login(
        p_auth_user_id,
        p_discord_id,
        p_username,
        p_global_name,
        p_avatar_hash,
        p_avatar_url,
        p_created_from_snowflake,
        p_is_member,
        p_joined_dt,
        v_sync_dt,
        true
    );

    PERFORM web_priv.discord_user_role_cache_replace(
        v_discord_user_id,
        p_roles,
        p_sync_source,
        v_sync_dt
    );

    SELECT *
      INTO v_access
      FROM web_priv.actor_get_access_summary(p_discord_id);

    RETURN QUERY
    SELECT
        du.discord_user_id,
        du.auth_user_id,
        du.discord_id,
        du.username,
        du.global_name,
        du.avatar_url,
        du.is_member,
        du.roles_synced_dt,
        du.last_login_dt,
        web_priv.discord_user_role_refresh_is_due(
            du.discord_id,
            interval '15 minutes'
        ) AS is_role_refresh_due,
        COALESCE(v_access.is_authenticated, false) AS is_authenticated,
        COALESCE(v_access.is_admin, false) AS is_admin,
        COALESCE(v_access.is_editor, false) AS is_editor,
        COALESCE(v_access.max_rank, 0) AS max_rank
    FROM web_priv.discord_users du
    WHERE du.discord_user_id = v_discord_user_id;
END;
$$;


