CREATE FUNCTION web_api.auth_user_create(p_name text, p_image text) RETURNS TABLE(auth_user_id bigint, discord_id character varying, name text, image text, is_disabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES A NEW AUTH USER ROW FOR THE CURRENT AUTH FLOW                                                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    RETURN QUERY
    INSERT INTO web_priv.auth_users (
        name,
        image
    )
    VALUES (
        p_name,
        p_image
    )
    RETURNING
        web_priv.auth_users.auth_user_id,
        web_priv.auth_users.discord_id,
        web_priv.auth_users.name,
        web_priv.auth_users.image,
        web_priv.auth_users.is_disabled,
        web_priv.auth_users.created_dt,
        web_priv.auth_users.updated_dt;
END;
$$;


