--
-- Name: auth_user_delete(bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.auth_user_delete(p_auth_user_id bigint) RETURNS TABLE(auth_user_id bigint, discord_id character varying, name text, image text, is_disabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES THE AUTH USER AND CASCADES RELATED AUTH AND DISCORD ROWS                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    RETURN QUERY
    DELETE FROM web_priv.auth_users au
     WHERE au.auth_user_id = p_auth_user_id
    RETURNING
        au.auth_user_id,
        au.discord_id,
        au.name,
        au.image,
        au.is_disabled,
        au.created_dt,
        au.updated_dt;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Auth user % does not exist.', p_auth_user_id;
    END IF;
END;
$$;


