--
-- Name: discord_role_create(character varying, text, text, character varying, character varying, integer, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.discord_role_create(p_actor_discord_id character varying, p_name text, p_source text, p_role_id character varying, p_color_hex character varying, p_rank integer, p_is_access_role boolean DEFAULT false, p_is_editor boolean DEFAULT false, p_is_admin boolean DEFAULT false, p_is_public_default boolean DEFAULT false, p_is_authenticated_default boolean DEFAULT false) RETURNS TABLE(id integer, name character varying, source text, role_id character varying, color_hex character varying, rank integer, is_access_role boolean, is_public_default boolean, is_authenticated_default boolean, is_admin boolean, is_editor boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES A DISCORD ROLE CONFIG ROW THROUGH THE ADMIN DATABASE API                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_source web_priv.enum_discord_roles_source;
    v_role_id varchar(32);
    v_id integer;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    IF btrim(COALESCE(p_name, '')) = '' THEN
        RAISE EXCEPTION 'discord_roles.name is required.';
    END IF;

    IF p_source = 'discord' THEN
        v_source := 'discord'::web_priv.enum_discord_roles_source;
    ELSIF p_source = 'virtual' THEN
        v_source := 'virtual'::web_priv.enum_discord_roles_source;
    ELSE
        RAISE EXCEPTION 'Unsupported discord_roles.source value: %.', p_source;
    END IF;

    v_role_id := NULLIF(btrim(p_role_id), '');

    IF v_source = 'discord'::web_priv.enum_discord_roles_source AND v_role_id IS NULL THEN
        RAISE EXCEPTION 'discord_roles.role_id is required for source = discord.';
    END IF;

    IF v_source = 'virtual'::web_priv.enum_discord_roles_source THEN
        v_role_id := NULL;
    END IF;

    INSERT INTO web_priv.discord_roles (
        name,
        source,
        role_id,
        color_hex,
        rank,
        is_access_role,
        is_editor,
        is_admin,
        is_public_default,
        is_authenticated_default
    )
    VALUES (
        btrim(p_name),
        v_source,
        v_role_id,
        NULLIF(btrim(p_color_hex), ''),
        p_rank,
        COALESCE(p_is_access_role, false),
        COALESCE(p_is_editor, false),
        COALESCE(p_is_admin, false),
        COALESCE(p_is_public_default, false),
        COALESCE(p_is_authenticated_default, false)
    )
    RETURNING web_priv.discord_roles.id
      INTO v_id;

    PERFORM web_priv.discord_role_assert_defaults_present();

    RETURN QUERY
    SELECT
        dr.id,
        dr.name,
        dr.source::text,
        dr.role_id,
        dr.color_hex,
        dr.rank,
        dr.is_access_role,
        dr.is_public_default,
        dr.is_authenticated_default,
        dr.is_admin,
        dr.is_editor,
        dr.created_dt,
        dr.updated_dt
      FROM web_priv.discord_roles dr
     WHERE dr.id = v_id;
END;
$$;


