-- Name: discord_user_update_notes(character varying, bigint, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.discord_user_update_notes(p_actor_discord_id character varying, p_discord_user_id bigint, p_notes text) RETURNS TABLE(discord_user_id bigint, auth_user_id bigint, discord_id character varying, username text, global_name text, avatar_hash text, avatar_url text, created_from_snowflake timestamp with time zone, is_member boolean, joined_dt timestamp with time zone, notes text, roles_synced_dt timestamp with time zone, last_login_dt timestamp with time zone, is_role_refresh_due boolean, valid_from timestamp with time zone, valid_to timestamp with time zone, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES DISCORD USER ADMIN NOTES THROUGH THE ADMIN DATABASE API                                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_discord_user_id bigint;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    UPDATE web_priv.discord_users du
       SET notes = NULLIF(btrim(p_notes), '')
     WHERE du.discord_user_id = p_discord_user_id
     RETURNING du.discord_user_id
      INTO v_discord_user_id;

    IF v_discord_user_id IS NULL THEN
        RAISE EXCEPTION 'discord_users row % was not found.', p_discord_user_id;
    END IF;

    RETURN QUERY
    SELECT
        vu.discord_user_id,
        vu.auth_user_id,
        vu.discord_id,
        vu.username,
        vu.global_name,
        vu.avatar_hash,
        vu.avatar_url,
        vu.created_from_snowflake,
        vu.is_member,
        vu.joined_dt,
        vu.notes,
        vu.roles_synced_dt,
        vu.last_login_dt,
        vu.is_role_refresh_due,
        vu.valid_from,
        vu.valid_to,
        vu.created_dt,
        vu.updated_dt
      FROM web_view.discord_users vu
     WHERE vu.discord_user_id = v_discord_user_id;
END;
$$;


