-- Name: web_category_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_category_delete(p_actor_discord_id character varying, p_category_id bigint) RETURNS TABLE(category_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A CATEGORY ROW THROUGH THE ADMIN DATABASE API                                                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    PERFORM 1
      FROM web_priv.web_categories AS c
     WHERE c.category_id = p_category_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Category % was not found.', p_category_id;
    END IF;

    PERFORM web_priv.web_category_assert_can_delete(p_category_id);
    PERFORM web_priv.web_category_record_history(p_category_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_categories AS c
     WHERE c.category_id = p_category_id;

    category_id := p_category_id;
END;
$$;


