    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// TOGGLES CATEGORY NAV VISIBILITY THROUGH THE ADMIN DATABASE API                                               ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    UPDATE web_priv.web_categories AS c
       SET nav_hidden = NOT c.nav_hidden,
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE c.category_id = p_category_id
     RETURNING c.category_id
          INTO category_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Category % was not found.', p_category_id;
    END IF;

    PERFORM web_priv.web_category_record_history(p_category_id, 'update', p_actor_discord_id);
    PERFORM web_priv.web_category_recalculate_dependents(p_category_id);
END;
$$;


