-- Name: web_category_update(character varying, bigint, text, text, boolean, text, integer, text, integer, bigint, bigint, bigint[]); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_category_update(p_actor_discord_id character varying, p_category_id bigint, p_title text, p_slug text, p_nav_hidden boolean, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_icon_key_id bigint, p_icon_color_id bigint, p_template_ids bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE(category_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES A CATEGORY ROW WITH EXPLICIT WRITE POLICY THROUGH THE ADMIN DATABASE API                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    UPDATE web_priv.web_categories AS c
       SET title = btrim(p_title),
           slug = btrim(p_slug),
           nav_hidden = p_nav_hidden,
           read_policy_code = p_read_policy_code,
           read_rank = p_read_rank,
           read_effective_policy_code = p_read_policy_code,
           read_effective_rank = p_read_rank,
           write_policy_code = p_write_policy_code,
           write_rank = p_write_rank,
           write_effective_policy_code = p_write_policy_code,
           write_effective_rank = p_write_rank,
           icon_key_id = p_icon_key_id,
           icon_color_id = p_icon_color_id,
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE c.category_id = p_category_id
     RETURNING c.category_id
          INTO category_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Category % was not found.', p_category_id;
    END IF;

    PERFORM web_priv.web_category_record_history(p_category_id, 'update', p_actor_discord_id);
    PERFORM web_priv.web_category_template_replace(p_actor_discord_id, p_category_id, p_template_ids);
