--
-- Name: web_content_create_admin(character varying, bigint, text, text, text, bigint, bigint, bigint, integer, text, timestamp with time zone, timestamp with time zone, text, integer, text, integer, text, boolean, text, bigint, text, bigint, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_create_admin(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_status_code text DEFAULT 'draft'::text, p_published_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_archived_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_read_policy_code text DEFAULT 'inherit'::text, p_read_rank integer DEFAULT NULL::integer, p_write_policy_code text DEFAULT 'inherit'::text, p_write_rank integer DEFAULT NULL::integer, p_nav_hidden_mode_code text DEFAULT 'inherit'::text, p_nav_hidden boolean DEFAULT NULL::boolean, p_icon_mode_code text DEFAULT 'template_default'::text, p_icon_key_id bigint DEFAULT NULL::bigint, p_icon_color_mode_code text DEFAULT 'template_default'::text, p_icon_color_id bigint DEFAULT NULL::bigint, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES CONTENT THROUGH THE ADMIN DB-FIRST API AND OWNS STATUS TIMESTAMPS                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_template_schema_version_no integer;
    v_status_code text;
    v_published_dt timestamp with time zone;
    v_archived_dt timestamp with time zone;
    v_slug text;
BEGIN
    v_status_code := COALESCE(NULLIF(BTRIM(LOWER(p_status_code)), ''), 'draft');

    IF v_status_code NOT IN ('draft', 'published', 'archived') THEN
        RAISE EXCEPTION 'Unsupported content status: %.', v_status_code;
    END IF;

    v_published_dt := CASE WHEN v_status_code = 'published' THEN CURRENT_TIMESTAMP ELSE NULL END;
    v_archived_dt := CASE WHEN v_status_code = 'archived' THEN CURRENT_TIMESTAMP ELSE NULL END;

    PERFORM web_priv.web_content_assert_category_subcategory(p_category_id, p_subcategory_id);
    PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'admin', p_category_id, p_subcategory_id);
    PERFORM web_priv.web_content_assert_template_allowed(p_template_id, p_category_id, p_subcategory_id, 'admin');
    PERFORM web_priv.web_content_assert_series_input(p_template_id, p_series_id, p_series_part_no, p_category_id, p_subcategory_id);
    PERFORM web_priv.web_content_assert_resolved_icon_defaults(
        p_template_id,
        COALESCE(p_icon_mode_code, 'template_default'),
        p_icon_key_id,
        COALESCE(p_icon_color_mode_code, 'template_default'),
        p_icon_color_id
    );

    v_slug := web_priv.web_content_make_unique_slug(p_slug, p_category_id, p_subcategory_id, NULL);

    SELECT t.schema_version_no
      INTO v_template_schema_version_no
      FROM web_priv.web_templates t
     WHERE t.template_id = p_template_id;

    INSERT INTO web_priv.web_content (
        template_id,
        template_schema_version_no,
        title,
        slug,
        summary,
        category_id,
        subcategory_id,
        series_id,
        series_part_no,
        author_discord_id,
        status_code,
        published_dt,
        archived_dt,
        read_policy_code,
        read_rank,
        read_effective_policy_code,
        read_effective_rank,
        write_policy_code,
        write_rank,
        write_effective_policy_code,
        write_effective_rank,
        nav_hidden_mode_code,
        nav_hidden,
        nav_hidden_effective,
        icon_mode_code,
        icon_key_id,
        icon_key_effective_id,
        icon_color_mode_code,
        icon_color_id,
        icon_color_effective_id,
        created_by_discord_id,
        updated_by_discord_id
    ) VALUES (
        p_template_id,
        v_template_schema_version_no,
        BTRIM(p_title),
        v_slug,
        NULLIF(BTRIM(p_summary), ''),
        p_category_id,
        p_subcategory_id,
        p_series_id,
        p_series_part_no,
        p_actor_discord_id,
        v_status_code,
        v_published_dt,
        v_archived_dt,
        COALESCE(NULLIF(BTRIM(p_read_policy_code), ''), 'inherit'),
        p_read_rank,
        'public',
        NULL,
        COALESCE(NULLIF(BTRIM(p_write_policy_code), ''), 'inherit'),
        p_write_rank,
        'min_rank',
        100,
        COALESCE(NULLIF(BTRIM(p_nav_hidden_mode_code), ''), 'inherit'),
        p_nav_hidden,
        false,
        COALESCE(NULLIF(BTRIM(p_icon_mode_code), ''), 'template_default'),
        p_icon_key_id,
        COALESCE(p_icon_key_id, (SELECT t.default_icon_key_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id)),
        COALESCE(NULLIF(BTRIM(p_icon_color_mode_code), ''), 'template_default'),
        p_icon_color_id,
        COALESCE(p_icon_color_id, (SELECT t.default_icon_color_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id)),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING web_content.content_id
         INTO content_id;

    PERFORM web_priv.web_content_recalculate_effective(content_id);
    PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, p_template_id, p_field_values);
    PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, p_template_id, 'admin', p_external_links);
    PERFORM web_priv.web_content_record_history(content_id, 'create', p_actor_discord_id);

    RETURN NEXT;
END;
$$;


