--
-- Name: web_content_create_public(character varying, bigint, text, text, text, bigint, bigint, bigint, integer, text, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_create_public(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_status_code text DEFAULT 'draft'::text, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES COMMUNITY CONTENT THROUGH THE PUBLIC/MEMBER DB-FIRST API                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_schema_version_no integer;
	v_slug text;
BEGIN
	IF jsonb_typeof(COALESCE(p_external_links, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_external_links must be a JSON array.';
	END IF;

	IF jsonb_array_length(COALESCE(p_external_links, '[]'::jsonb)) > 0 THEN
		RAISE EXCEPTION 'Public content external links are not enabled in v1.';
	END IF;

	PERFORM web_priv.web_content_assert_category_subcategory(p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_template_allowed(p_template_id, p_category_id, p_subcategory_id, 'public');
	PERFORM web_priv.web_content_assert_series_input(p_template_id, p_series_id, p_series_part_no, p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_resolved_icon_defaults(p_template_id,
												 'template_default',
												 NULL,
												 'template_default',
												 NULL);

	SELECT t.schema_version_no
	INTO v_template_schema_version_no
	FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id;

	INSERT INTO web_priv.web_content AS c(template_id,
										template_schema_version_no,
										title,
										slug,
										summary,
										category_id,
										subcategory_id,
										series_id,
										series_part_no,
										author_discord_id,
										status_code,
										published_dt,
										archived_dt,
										read_policy_code,
										read_rank,
										read_effective_policy_code,
										read_effective_rank,
										write_policy_code,
										write_rank,
										write_effective_policy_code,
										write_effective_rank,
										nav_hidden_mode_code,
										nav_hidden,
										nav_hidden_effective,
										icon_mode_code,
										icon_key_id,
										icon_key_effective_id,
										icon_color_mode_code,
										icon_color_id,
										icon_color_effective_id,
										created_by_discord_id,
										updated_by_discord_id)
	VALUES (p_template_id,
			v_template_schema_version_no,
			BTRIM(p_title),
			BTRIM(p_slug),
			NULLIF(BTRIM(p_summary), ''),
			p_category_id,
			p_subcategory_id,
			p_series_id,
			p_series_part_no,
			p_actor_discord_id,
			COALESCE(NULLIF(BTRIM(p_status_code), ''), 'draft'),
			NULL,
			NULL,
			'inherit',
			NULL,
			'public',
			NULL,
			'inherit',
			NULL,
			'min_rank',
			100,
			'inherit',
			NULL,
			false,
			'template_default',
			NULL,
			(SELECT t.default_icon_key_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id),
			'template_default',
			NULL,
			(SELECT t.default_icon_color_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING c.content_id
	INTO content_id;

	PERFORM web_priv.web_content_recalculate_effective(content_id);
	PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, p_template_id, p_field_values);
	PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, p_template_id, 'public', '[]'::jsonb);
	PERFORM web_priv.web_content_record_history(content_id, 'create', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_content_create_public(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb) OWNER TO cm;

--
-- Name: web_content_delete_admin(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_delete_admin(p_actor_discord_id character varying, p_content_id bigint) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES CONTENT THROUGH THE ADMIN DB-FIRST API                                                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_content_id bigint;
    v_category_id bigint;
    v_subcategory_id bigint;
BEGIN
    SELECT
        c.content_id,
        c.category_id,
        c.subcategory_id
      INTO
        v_content_id,
        v_category_id,
        v_subcategory_id
      FROM web_priv.web_content c
     WHERE c.content_id = p_content_id;

    IF v_content_id IS NULL THEN
        RAISE EXCEPTION 'Content % was not found.', p_content_id;
    END IF;

    PERFORM web_priv.web_content_assert_actor_can_author(
        p_actor_discord_id,
        'admin',
        v_category_id,
        v_subcategory_id
    );

    PERFORM web_priv.web_content_record_history(v_content_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_content c
     WHERE c.content_id = v_content_id;

    content_id := v_content_id;
    RETURN NEXT;
END;
$$;


