--
-- Name: web_content_kind_create(character varying, text, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_kind_create(p_actor_discord_id character varying, p_content_kind_code text, p_label text, p_description text, p_public_route_prefix text, p_renderer_code text, p_is_enabled boolean DEFAULT true) RETURNS TABLE(content_kind_code text, label text, description text, public_route_prefix text, renderer_code text, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES A CONTENT KIND ROW THROUGH THE ADMIN DATABASE API                                                    ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_content_kind_code text;
	v_label text;
	v_description text;
	v_public_route_prefix text;
	v_renderer_code text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_content_kind_code := NULLIF(BTRIM(LOWER(p_content_kind_code)), '');
	v_label := NULLIF(BTRIM(p_label), '');
	v_description := NULLIF(BTRIM(p_description), '');
	v_public_route_prefix := NULLIF(BTRIM(LOWER(COALESCE(p_public_route_prefix, ''))), '');
	v_renderer_code := COALESCE(NULLIF(BTRIM(LOWER(p_renderer_code)), ''), 'page');

	IF v_content_kind_code IS NULL THEN
		RAISE EXCEPTION 'web_content_kind_c.content_kind_code is required.';
	END IF;

	IF v_content_kind_code !~ '^[a-z0-9._-]{1,64}$' THEN
		RAISE EXCEPTION 'web_content_kind_c.content_kind_code must match ^[a-z0-9._-]{1,64}$.';
	END IF;

	IF v_label IS NULL THEN
		RAISE EXCEPTION 'web_content_kind_c.label is required.';
	END IF;

	IF v_public_route_prefix IS NOT NULL AND v_public_route_prefix <> ALL (ARRAY['map'::text, 'tool'::text, 'app'::text, 'event'::text, 'custom'::text, 'external'::text, 'video'::text]) THEN
		RAISE EXCEPTION 'web_content_kind_c.public_route_prefix is invalid: %.', v_public_route_prefix;
	END IF;

	IF v_renderer_code <> ALL (ARRAY['page'::text, 'map'::text, 'tool'::text, 'app'::text, 'event'::text, 'custom'::text, 'external_link'::text, 'youtube'::text, 'stream'::text, 'calendar'::text]) THEN
		RAISE EXCEPTION 'web_content_kind_c.renderer_code is invalid: %.', v_renderer_code;
	END IF;

	INSERT INTO web_priv.web_content_kind_c(content_kind_code,
										 label,
										 description,
										 public_route_prefix,
										 renderer_code,
										 is_enabled,
										 created_by_discord_id,
										 updated_by_discord_id)
	VALUES (v_content_kind_code,
			v_label,
			v_description,
			v_public_route_prefix,
			v_renderer_code,
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id);

	PERFORM web_priv.web_content_kind_record_history(v_content_kind_code, 'create', p_actor_discord_id);

	RETURN QUERY
	SELECT ck.content_kind_code,
		   ck.label,
		   ck.description,
		   ck.public_route_prefix,
		   ck.renderer_code,
		   ck.is_enabled,
		   ck.created_dt,
		   ck.updated_dt
	FROM web_view.web_content_kind_admin ck
	WHERE ck.content_kind_code = v_content_kind_code;
END;
$_$;


ALTER FUNCTION web_api.web_content_kind_create(p_actor_discord_id character varying, p_content_kind_code text, p_label text, p_description text, p_public_route_prefix text, p_renderer_code text, p_is_enabled boolean) OWNER TO cm;

--
-- Name: web_content_kind_delete(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_kind_delete(p_actor_discord_id character varying, p_content_kind_code text) RETURNS TABLE(content_kind_code text, label text, description text, public_route_prefix text, renderer_code text, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_kind_delete                                                               ////
--//// PURPOSE: Deletes a content kind row after named dependency validation                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_content_kind_code text;
	v_subject_label text;
	v_deleted web_priv.web_content_kind_c%ROWTYPE;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_content_kind_code := NULLIF(btrim(lower(p_content_kind_code)), '');

	IF v_content_kind_code IS NULL THEN
		RAISE EXCEPTION 'Content kind code is required.';
	END IF;

	SELECT ck.label || ' (' || ck.content_kind_code || ')'
	INTO v_subject_label
	FROM web_priv.web_content_kind_c ck
	WHERE ck.content_kind_code = v_content_kind_code;

	v_subject_label := COALESCE(v_subject_label, v_content_kind_code);

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_templates t WHERE t.content_kind_code = v_content_kind_code;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.template_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT t.label || ' (' || t.template_code || ')' AS label,
					 t.template_id
			  FROM web_priv.web_templates t
			  WHERE t.content_kind_code = v_content_kind_code
			  ORDER BY t.label, t.template_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'content kind', v_subject_label, 'template', 'templates', v_reference_count, v_reference_labels);
	END IF;

	PERFORM web_priv.web_content_kind_record_history(v_content_kind_code, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_content_kind_c ck
	WHERE ck.content_kind_code = v_content_kind_code
	RETURNING ck.*
	INTO v_deleted;

	IF v_deleted.content_kind_code IS NULL THEN
		RAISE EXCEPTION 'Content kind % was not found.', v_content_kind_code;
	END IF;

	RETURN QUERY
	SELECT v_deleted.content_kind_code,
		   v_deleted.label,
		   v_deleted.description,
		   v_deleted.public_route_prefix,
		   v_deleted.renderer_code,
		   v_deleted.is_enabled,
		   v_deleted.created_dt,
		   v_deleted.updated_dt;
END;
$$;


ALTER FUNCTION web_api.web_content_kind_delete(p_actor_discord_id character varying, p_content_kind_code text) OWNER TO cm;

--
-- Name: web_content_kind_update(character varying, text, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_kind_update(p_actor_discord_id character varying, p_content_kind_code text, p_label text, p_description text, p_public_route_prefix text, p_renderer_code text, p_is_enabled boolean) RETURNS TABLE(content_kind_code text, label text, description text, public_route_prefix text, renderer_code text, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES A CONTENT KIND ROW THROUGH THE ADMIN DATABASE API                                                    ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_content_kind_code text;
	v_label text;
	v_description text;
	v_public_route_prefix text;
	v_renderer_code text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_content_kind_code := NULLIF(BTRIM(LOWER(p_content_kind_code)), '');
	v_label := NULLIF(BTRIM(p_label), '');
	v_description := NULLIF(BTRIM(p_description), '');
	v_public_route_prefix := NULLIF(BTRIM(LOWER(COALESCE(p_public_route_prefix, ''))), '');
	v_renderer_code := COALESCE(NULLIF(BTRIM(LOWER(p_renderer_code)), ''), 'page');

	IF v_content_kind_code IS NULL THEN
		RAISE EXCEPTION 'web_content_kind_c.content_kind_code is required.';
	END IF;

	IF v_label IS NULL THEN
		RAISE EXCEPTION 'web_content_kind_c.label is required.';
	END IF;

	IF v_public_route_prefix IS NOT NULL AND v_public_route_prefix <> ALL (ARRAY['map'::text, 'tool'::text, 'app'::text, 'event'::text, 'custom'::text, 'external'::text, 'video'::text]) THEN
		RAISE EXCEPTION 'web_content_kind_c.public_route_prefix is invalid: %.', v_public_route_prefix;
	END IF;

	IF v_renderer_code <> ALL (ARRAY['page'::text, 'map'::text, 'tool'::text, 'app'::text, 'event'::text, 'custom'::text, 'external_link'::text, 'youtube'::text, 'stream'::text, 'calendar'::text]) THEN
		RAISE EXCEPTION 'web_content_kind_c.renderer_code is invalid: %.', v_renderer_code;
	END IF;

	UPDATE web_priv.web_content_kind_c ck
	SET label = v_label,
		description = v_description,
		public_route_prefix = v_public_route_prefix,
		renderer_code = v_renderer_code,
		is_enabled = COALESCE(p_is_enabled, ck.is_enabled),
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE ck.content_kind_code = v_content_kind_code;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'web_content_kind_c row % was not found.', v_content_kind_code;
	END IF;

	PERFORM web_priv.web_content_kind_record_history(v_content_kind_code, 'update', p_actor_discord_id);

	RETURN QUERY
	SELECT ck.content_kind_code,
		   ck.label,
		   ck.description,
		   ck.public_route_prefix,
		   ck.renderer_code,
		   ck.is_enabled,
		   ck.created_dt,
		   ck.updated_dt
	FROM web_view.web_content_kind_admin ck
	WHERE ck.content_kind_code = v_content_kind_code;
END;
$$;


ALTER FUNCTION web_api.web_content_kind_update(p_actor_discord_id character varying, p_content_kind_code text, p_label text, p_description text, p_public_route_prefix text, p_renderer_code text, p_is_enabled boolean) OWNER TO cm;

