CREATE FUNCTION web_api.web_content_media_replace_admin(p_actor_discord_id character varying, p_content_id bigint, p_media_refs jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint, media_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_media_replace_admin                                                         ////
--//// PURPOSE: App-callable admin/editor wrapper for replacing structured content-media references.              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_media_count integer;
BEGIN
	PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);
	PERFORM web_priv.web_content_media_replace(p_actor_discord_id,
											   p_content_id,
											   COALESCE(p_media_refs, '[]'::jsonb));

	SELECT COUNT(*)::integer
	INTO v_media_count
	FROM web_priv.web_content_media_r r
	WHERE r.content_id = p_content_id
	;

	RETURN QUERY
	SELECT p_content_id,
		   v_media_count;
END;
$$;


