--
-- Name: web_content_public_find_by_path(character varying, text, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_public_find_by_path(p_actor_discord_id character varying, p_public_route_prefix text, p_category_slug text, p_subcategory_slug text, p_content_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_public_find_by_path                                                          ////
--//// PURPOSE: Resolves one public content document with read access, fields, and series episode context         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'doc', jsonb_build_object(
		'id', c.content_id::text,
		'title', c.title,
		'slug', c.slug,
		'summary', c.summary,
		'categoryId', cat.category_id::text,
		'categoryTitle', cat.title,
		'categorySlug', cat.slug,
		'subcategoryId', sc.subcategory_id::text,
		'subcategoryTitle', sc.title,
		'subcategorySlug', sc.slug,
		'contentKindCode', t.content_kind_code,
		'contentKindLabel', ck.label,
		'publicRoutePrefix', ck.public_route_prefix,
		'rendererCode', ck.renderer_code,
		'publishedAt', c.published_dt,
		'series', CASE WHEN s.series_id IS NULL THEN NULL
			ELSE jsonb_build_object(
				'id', s.series_id::text,
				'title', s.title,
				'slug', s.slug,
				'partNo', c.series_part_no,
				'previousEpisode', prev_ep.doc,
				'nextEpisode', next_ep.doc
			)
			END
	),
	'fields', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
			'id', tf.template_field_id::text,
			'fieldListCode', fl.field_list_code,
			'label', COALESCE(NULLIF(btrim(tf.label_override), ''::text), fl.label),
			'fieldTypeCode', fl.field_type_code,
			'renderDestinationCode', fl.render_destination_code,
			'layoutWidthCode', tf.layout_width_code,
			'layoutAlignCode', tf.layout_align_code,
			'showLabel', tf.show_label_flag,
			'labelStyleCode', tf.label_style_code,
			'labelPositionCode', tf.label_position_code,
			'labelSeparatorCode', tf.label_separator_code,
			'valueColumnName', ft.value_column_name,
			'displayOrder', tf.display_order,
			'value', CASE ft.value_column_name
				WHEN 'value_text' THEN to_jsonb(v.value_text)
				WHEN 'value_long_text' THEN to_jsonb(v.value_long_text)
				WHEN 'value_integer' THEN to_jsonb(v.value_integer)
				WHEN 'value_numeric' THEN to_jsonb(v.value_numeric)
				WHEN 'value_boolean' THEN to_jsonb(v.value_boolean)
				WHEN 'value_date' THEN to_jsonb(v.value_date)
				WHEN 'value_timestamp' THEN to_jsonb(v.value_timestamp)
				WHEN 'value_discord_id' THEN to_jsonb(v.value_discord_id)
				WHEN 'value_media_id' THEN to_jsonb(v.value_media_id::text)
				WHEN 'value_content_id' THEN to_jsonb(v.value_content_id::text)
				WHEN 'value_option_key' THEN to_jsonb(v.value_option_key)
				WHEN 'value_rich_text_json' THEN v.value_rich_text_json
				ELSE 'null'::jsonb
				END,
			'optionLabel', fo.label,
			'media', CASE WHEN m.media_id IS NULL THEN NULL
				ELSE jsonb_build_object(
					'id', m.media_id::text,
					'originalFilename', m.original_filename,
					'storageRelPath', m.storage_rel_path,
					'mimeType', m.mime_type,
					'sizeBytes', m.size_bytes,
					'width', m.width_px,
					'height', m.height_px,
					'altText', m.alt_text
				)
				END
		) ORDER BY fl.render_destination_code, tf.display_order, tf.template_field_id)
		FROM web_priv.web_template_fields tf
		JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
		JOIN web_priv.web_template_field_type_c ft ON ft.field_type_code = fl.field_type_code
		LEFT JOIN web_priv.web_content_field_values v ON v.content_id          = c.content_id
														AND v.template_field_id = tf.template_field_id
														AND v.value_seq_no      = 1
		LEFT JOIN web_priv.web_template_field_options fo ON fo.field_list_id = fl.field_list_id
															AND fo.option_key    = v.value_option_key
															AND fo.is_enabled    = true
		LEFT JOIN web_priv.web_media m ON m.media_id = v.value_media_id
									AND web_priv.web_media_actor_can_read(p_actor_discord_id, m.media_id)
		WHERE tf.template_id = c.template_id
		  AND tf.is_enabled  = true
		  AND fl.is_enabled  = true
	), '[]'::jsonb)
)
FROM web_priv.web_content c
JOIN web_priv.web_templates t ON t.template_id = c.template_id
JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
LEFT JOIN web_priv.web_series s ON s.series_id = c.series_id
								AND web_priv.actor_passes_effective_policy(p_actor_discord_id,
																	   s.read_effective_policy_code,
																	   s.read_effective_rank)
LEFT JOIN LATERAL (SELECT jsonb_build_object(
							'id', pc.content_id::text,
							'title', pc.title,
							'slug', pc.slug,
							'partNo', pc.series_part_no,
							'categorySlug', pcat.slug,
							'subcategorySlug', psc.slug,
							'publicRoutePrefix', pck.public_route_prefix,
							'rendererCode', pck.renderer_code,
							'href', CASE WHEN COALESCE(NULLIF(btrim(pck.public_route_prefix), ''), '') = '' THEN
								'/' || pcat.slug || '/' || psc.slug || '/' || pc.slug
								ELSE '/' || pck.public_route_prefix || '/' || pcat.slug || '/' || psc.slug || '/' || pc.slug
								END,
							'publishedAt', pc.published_dt
						) AS doc
					 FROM web_priv.web_content pc
					 JOIN web_priv.web_templates pt ON pt.template_id = pc.template_id
					 JOIN web_priv.web_content_kind_c pck ON pck.content_kind_code = pt.content_kind_code
					 JOIN web_priv.web_categories pcat ON pcat.category_id = pc.category_id
					 JOIN web_priv.web_subcategories psc ON psc.subcategory_id = pc.subcategory_id
					 WHERE s.series_id IS NOT NULL
					   AND c.series_part_no IS NOT NULL
					   AND pc.series_id = s.series_id
					   AND pc.content_id <> c.content_id
					   AND pc.status_code = 'published'
					   AND pc.series_part_no IS NOT NULL
					   AND pc.series_part_no < c.series_part_no
					   AND pck.renderer_code = ANY (ARRAY['page'::text,
															'map'::text,
															'tool'::text,
															'app'::text,
															'event'::text,
															'custom'::text,
															'youtube'::text,
															'stream'::text,
															'calendar'::text])
					   AND web_priv.actor_passes_effective_policy(p_actor_discord_id,
																pc.read_effective_policy_code,
																pc.read_effective_rank)
					 ORDER BY pc.series_part_no DESC,
							  pc.published_dt DESC NULLS LAST,
							  pc.content_id DESC
					 LIMIT 1) prev_ep ON true
LEFT JOIN LATERAL (SELECT jsonb_build_object(
							'id', nc.content_id::text,
							'title', nc.title,
							'slug', nc.slug,
							'partNo', nc.series_part_no,
							'categorySlug', ncat.slug,
							'subcategorySlug', nsc.slug,
							'publicRoutePrefix', nck.public_route_prefix,
							'rendererCode', nck.renderer_code,
							'href', CASE WHEN COALESCE(NULLIF(btrim(nck.public_route_prefix), ''), '') = '' THEN
								'/' || ncat.slug || '/' || nsc.slug || '/' || nc.slug
								ELSE '/' || nck.public_route_prefix || '/' || ncat.slug || '/' || nsc.slug || '/' || nc.slug
								END,
							'publishedAt', nc.published_dt
						) AS doc
					 FROM web_priv.web_content nc
					 JOIN web_priv.web_templates nt ON nt.template_id = nc.template_id
					 JOIN web_priv.web_content_kind_c nck ON nck.content_kind_code = nt.content_kind_code
					 JOIN web_priv.web_categories ncat ON ncat.category_id = nc.category_id
					 JOIN web_priv.web_subcategories nsc ON nsc.subcategory_id = nc.subcategory_id
					 WHERE s.series_id IS NOT NULL
					   AND c.series_part_no IS NOT NULL
					   AND nc.series_id = s.series_id
					   AND nc.content_id <> c.content_id
					   AND nc.status_code = 'published'
					   AND nc.series_part_no IS NOT NULL
					   AND nc.series_part_no > c.series_part_no
					   AND nck.renderer_code = ANY (ARRAY['page'::text,
															'map'::text,
															'tool'::text,
															'app'::text,
															'event'::text,
															'custom'::text,
															'youtube'::text,
															'stream'::text,
															'calendar'::text])
					   AND web_priv.actor_passes_effective_policy(p_actor_discord_id,
																nc.read_effective_policy_code,
																nc.read_effective_rank)
					 ORDER BY nc.series_part_no ASC,
							  nc.published_dt ASC NULLS LAST,
							  nc.content_id ASC
					 LIMIT 1) next_ep ON true
WHERE c.status_code = 'published'
  AND cat.slug = p_category_slug
  AND sc.slug = p_subcategory_slug
  AND c.slug = p_content_slug
  AND COALESCE(ck.public_route_prefix, '') = COALESCE(NULLIF(btrim(lower(p_public_route_prefix)), ''), '')
  AND ck.renderer_code = ANY (ARRAY['page'::text,
									'map'::text,
									'tool'::text,
									'app'::text,
									'event'::text,
									'custom'::text,
									'youtube'::text,
									'stream'::text,
									'calendar'::text])
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank)
LIMIT 1;
$$;


ALTER FUNCTION web_api.web_content_public_find_by_path(p_actor_discord_id character varying, p_public_route_prefix text, p_category_slug text, p_subcategory_slug text, p_content_slug text) OWNER TO cm;

--
-- Name: web_content_public_find_redirect_by_path(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_public_find_redirect_by_path(p_actor_discord_id character varying, p_raw_path text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_public_find_redirect_by_path                                                 ////
--//// PURPOSE: Resolves old public path redirects using content-level read access                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_normalized_path text;
	v_result jsonb;
BEGIN
	BEGIN
		SELECT parsed.normalized_path
		INTO v_normalized_path
		FROM web_priv.web_content_parse_public_path(p_raw_path) parsed
		LIMIT 1;
	EXCEPTION WHEN OTHERS THEN
		RETURN NULL;
	END;

	WITH redirect_row AS (
		SELECT r.content_redirect_id,
			   r.content_id,
			   r.old_path,
			   r.redirect_type_code
		FROM web_priv.web_content_redirects r
		WHERE r.old_path = v_normalized_path
		  AND r.is_enabled = true
		LIMIT 1
	),
	target AS (
		SELECT r.content_redirect_id,
			   r.content_id,
			   r.old_path,
			   r.redirect_type_code,
			   c.title,
			   web_priv.web_content_current_public_path(c.content_id) AS redirect_path
		FROM redirect_row r
		JOIN web_priv.web_content c ON c.content_id = r.content_id
		JOIN web_priv.web_templates t ON t.template_id = c.template_id
		JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
		JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
		JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
		WHERE c.status_code = 'published'
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank)
	)
	SELECT jsonb_build_object(
		'redirectPath', t.redirect_path,
		'contentId', t.content_id::text,
		'title', t.title,
		'redirectTypeCode', t.redirect_type_code
	)
	INTO v_result
	FROM target t
	WHERE t.redirect_path IS NOT NULL
	  AND t.redirect_path <> t.old_path
	LIMIT 1;

	RETURN v_result;
END;
$$;


ALTER FUNCTION web_api.web_content_public_find_redirect_by_path(p_actor_discord_id character varying, p_raw_path text) OWNER TO cm;

--
-- Name: FUNCTION web_content_public_find_redirect_by_path(p_actor_discord_id character varying, p_raw_path text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_content_public_find_redirect_by_path(p_actor_discord_id character varying, p_raw_path text) IS 'Resolves an old full public path redirect to a current public path when the actor can read the target content.';


--
-- Name: web_content_public_list_category(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_public_list_category(p_actor_discord_id character varying, p_category_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RETURNS PUBLIC SUBCATEGORIES AND CONTENT FOR ONE CATEGORY                                                    ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'category', jsonb_build_object('id', cat.category_id::text, 'title', cat.title, 'slug', cat.slug),
	'subcategories', COALESCE((
		SELECT jsonb_agg(jsonb_build_object('id', sc.subcategory_id::text, 'title', sc.title, 'slug', sc.slug, 'href', '/' || cat.slug || '/' || sc.slug) ORDER BY sc.title, sc.subcategory_id)
		FROM web_priv.web_subcategories sc
		WHERE sc.category_id = cat.category_id
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.read_effective_policy_code, sc.read_effective_rank)
	), '[]'::jsonb),
	'content', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
			'id', c.content_id::text,
			'title', c.title,
			'slug', c.slug,
			'summary', c.summary,
			'href', CASE WHEN ck.public_route_prefix IS NULL THEN '/' || cat.slug || '/' || sc.slug || '/' || c.slug ELSE '/' || ck.public_route_prefix || '/' || cat.slug || '/' || sc.slug || '/' || c.slug END,
			'rendererCode', ck.renderer_code,
			'contentKindCode', t.content_kind_code
		) ORDER BY c.published_dt DESC NULLS LAST, c.updated_dt DESC, c.content_id DESC)
		FROM web_priv.web_content c
		JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
		JOIN web_priv.web_templates t ON t.template_id = c.template_id
		JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
		WHERE c.category_id = cat.category_id
		  AND c.status_code = 'published'
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.read_effective_policy_code, sc.read_effective_rank)
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank)
	), '[]'::jsonb)
)
FROM web_priv.web_categories cat
WHERE cat.slug = p_category_slug
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, cat.read_effective_policy_code, cat.read_effective_rank)
LIMIT 1;
$$;


ALTER FUNCTION web_api.web_content_public_list_category(p_actor_discord_id character varying, p_category_slug text) OWNER TO cm;

--
-- Name: web_content_public_list_subcategory(character varying, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_public_list_subcategory(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_public_list_subcategory                                                       ////
--//// PURPOSE: Returns collection hub payload when collection or content-level read access allows visibility                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'category', jsonb_build_object(
		'id', cat.category_id::text,
		'title', cat.title,
		'slug', cat.slug
	),
	'collection', jsonb_build_object(
		'id', sc.subcategory_id::text,
		'title', sc.title,
		'slug', sc.slug
	),
	'actions', jsonb_build_object(
		'canCreate', COALESCE(actor_summary.is_authenticated, false) = true
				 AND COALESCE(actor_summary.is_member, false)        = true
				 AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, cat.category_id, sc.subcategory_id)
				 AND web_priv.web_member_collection_has_public_template(cat.category_id, sc.subcategory_id),
		'hasManageableContent', COALESCE(actor_summary.is_authenticated, false) = true
							 AND COALESCE(actor_summary.is_member, false)        = true
							 AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, cat.category_id, sc.subcategory_id)
							 AND EXISTS (SELECT 1
										 FROM web_priv.web_content manageable
										 JOIN web_priv.web_templates manageable_template ON manageable_template.template_id = manageable.template_id
										 WHERE manageable.category_id        = cat.category_id
										   AND manageable.subcategory_id     = sc.subcategory_id
										   AND manageable.author_discord_id = p_actor_discord_id
										   AND manageable_template.surface_scope_code = 'public'
										   AND web_priv.actor_passes_effective_policy(p_actor_discord_id, manageable.write_effective_policy_code, manageable.write_effective_rank)
										   AND web_priv.web_member_template_allowed_for_collection(manageable.template_id, cat.category_id, sc.subcategory_id, 'public'))
	),
	'content', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
			'id', content.content_id::text,
			'title', content.title,
			'slug', content.slug,
			'summary', content.summary,
			'templateId', template.template_id::text,
			'templateLabel', template.label,
			'href', CASE WHEN kind.public_route_prefix IS NULL
				THEN '/' || cat.slug || '/' || sc.slug || '/' || content.slug
				ELSE '/' || kind.public_route_prefix || '/' || cat.slug || '/' || sc.slug || '/' || content.slug
				END,
			'rendererCode', kind.renderer_code,
			'contentKindCode', template.content_kind_code,
			'contentKindLabel', kind.label,
			'publishedAt', content.published_dt,
			'updatedAt', content.updated_dt,
			'iconKey', CASE WHEN content_icon.icon_id IS NULL THEN NULL
				ELSE jsonb_build_object(
					'key', content_icon.key,
					'label', content_icon.label,
					'source', content_icon.source_code,
					'lucideName', content_icon.lucide_name,
					'iconMedia', CASE WHEN content_icon_media.media_id IS NULL THEN NULL
						ELSE jsonb_build_object(
							'id', content_icon_media.media_id::text,
							'filename', content_icon_media.filename,
							'originalFilename', content_icon_media.original_filename,
							'mimeType', content_icon_media.mime_type,
							'storageRelPath', content_icon_media.storage_rel_path
						)
						END
				)
				END,
			'iconColor', CASE WHEN content_icon_color.theme_color_id IS NULL THEN NULL
				ELSE jsonb_build_object('preview', content_icon_color.preview)
				END
		) ORDER BY content.published_dt DESC NULLS LAST,
				 content.updated_dt DESC,
				 content.content_id DESC)
		FROM web_priv.web_content content
		JOIN web_priv.web_templates template ON template.template_id = content.template_id
		JOIN web_priv.web_content_kind_c kind ON kind.content_kind_code = template.content_kind_code
		LEFT JOIN web_priv.web_icons content_icon ON content_icon.icon_id = content.icon_key_effective_id
		LEFT JOIN web_priv.web_media content_icon_media ON content_icon_media.media_id = content_icon.media_id
		LEFT JOIN web_priv.web_theme_colors content_icon_color ON content_icon_color.theme_color_id = content.icon_color_effective_id
		WHERE content.category_id    = cat.category_id
		  AND content.subcategory_id = sc.subcategory_id
		  AND content.status_code    = 'published'
		  AND kind.renderer_code     = ANY (ARRAY['page'::text,
								  'map'::text,
								  'tool'::text,
								  'app'::text,
								  'event'::text,
								  'custom'::text,
								  'youtube'::text,
								  'stream'::text,
								  'calendar'::text])
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, content.read_effective_policy_code, content.read_effective_rank)
	), '[]'::jsonb)
)
FROM web_priv.web_categories cat
JOIN web_priv.web_subcategories sc ON sc.category_id = cat.category_id
CROSS JOIN web_priv.actor_get_access_summary(p_actor_discord_id) actor_summary
WHERE cat.slug = btrim(p_category_slug)
  AND sc.slug  = btrim(p_subcategory_slug)
  AND (web_priv.actor_passes_effective_policy(p_actor_discord_id, cat.read_effective_policy_code, cat.read_effective_rank)
   AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.read_effective_policy_code, sc.read_effective_rank)
   OR EXISTS (SELECT 1
              FROM web_priv.web_content visible_content
              JOIN web_priv.web_templates visible_template ON visible_template.template_id = visible_content.template_id
              JOIN web_priv.web_content_kind_c visible_kind ON visible_kind.content_kind_code = visible_template.content_kind_code
              WHERE visible_content.category_id    = cat.category_id
                AND visible_content.subcategory_id = sc.subcategory_id
                AND visible_content.status_code    = 'published'
                AND visible_kind.renderer_code     = ANY (ARRAY['page'::text,
                                                                'map'::text,
                                                                'tool'::text,
                                                                'app'::text,
                                                                'event'::text,
                                                                'custom'::text,
                                                                'youtube'::text,
                                                                'stream'::text,
                                                                'calendar'::text])
                AND web_priv.actor_passes_effective_policy(p_actor_discord_id, visible_content.read_effective_policy_code, visible_content.read_effective_rank)))
LIMIT 1
;
$$;


ALTER FUNCTION web_api.web_content_public_list_subcategory(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) OWNER TO cm;

--
-- Name: FUNCTION web_content_public_list_subcategory(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_content_public_list_subcategory(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) IS 'Returns a public collection hub payload when the collection itself or published content inside it is readable.';


--
-- Name: web_content_set_status_admin(character varying, bigint, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_set_status_admin(p_actor_discord_id character varying, p_content_id bigint, p_status_code text) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CHANGES ADMIN CONTENT STATUS AND OWNS STATUS TIMESTAMPS                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_content_id bigint;
    v_category_id bigint;
    v_subcategory_id bigint;
    v_status_code text;
BEGIN
    v_status_code := NULLIF(BTRIM(LOWER(p_status_code)), '');

    IF v_status_code IS NULL THEN
        RAISE EXCEPTION 'Content status is required.';
    END IF;

    IF v_status_code NOT IN ('draft', 'published', 'archived') THEN
        RAISE EXCEPTION 'Unsupported content status: %.', v_status_code;
    END IF;

    SELECT
        c.content_id,
        c.category_id,
        c.subcategory_id
      INTO
        v_content_id,
        v_category_id,
        v_subcategory_id
      FROM web_priv.web_content c
     WHERE c.content_id = p_content_id;

    IF v_content_id IS NULL THEN
        RAISE EXCEPTION 'Content % was not found.', p_content_id;
    END IF;

    PERFORM web_priv.web_content_assert_actor_can_author(
        p_actor_discord_id,
        'admin',
        v_category_id,
        v_subcategory_id
    );

    UPDATE web_priv.web_content c
       SET status_code = v_status_code,
           published_dt = CASE WHEN v_status_code = 'published' THEN CURRENT_TIMESTAMP ELSE NULL END,
           archived_dt = CASE WHEN v_status_code = 'archived' THEN CURRENT_TIMESTAMP ELSE NULL END,
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE c.content_id = v_content_id;

    PERFORM web_priv.web_content_record_history(v_content_id, 'update', p_actor_discord_id);

    content_id := v_content_id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_content_set_status_admin(p_actor_discord_id character varying, p_content_id bigint, p_status_code text) OWNER TO cm;

--
-- Name: FUNCTION web_content_set_status_admin(p_actor_discord_id character varying, p_content_id bigint, p_status_code text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_content_set_status_admin(p_actor_discord_id character varying, p_content_id bigint, p_status_code text) IS 'Changes content status from the admin/editor context, owns status timestamps, and records content history.';


--
-- Name: web_content_update_admin(character varying, bigint, bigint, text, text, text, bigint, bigint, bigint, integer, text, timestamp with time zone, timestamp with time zone, text, integer, text, integer, text, boolean, text, bigint, text, bigint, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_update_admin(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_status_code text DEFAULT 'draft'::text, p_published_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_archived_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_read_policy_code text DEFAULT 'inherit'::text, p_read_rank integer DEFAULT NULL::integer, p_write_policy_code text DEFAULT 'inherit'::text, p_write_rank integer DEFAULT NULL::integer, p_nav_hidden_mode_code text DEFAULT 'inherit'::text, p_nav_hidden boolean DEFAULT NULL::boolean, p_icon_mode_code text DEFAULT 'template_default'::text, p_icon_key_id bigint DEFAULT NULL::bigint, p_icon_color_mode_code text DEFAULT 'template_default'::text, p_icon_color_id bigint DEFAULT NULL::bigint, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_content_update_admin                                                                ////
--//// PURPOSE: Updates admin content and records full-path redirects when public route identity changes           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_schema_version_no integer;
	v_status_code text;
	v_existing_status_code text;
	v_existing_published_dt timestamp with time zone;
	v_existing_archived_dt timestamp with time zone;
	v_existing_template_id bigint;
	v_existing_category_id bigint;
	v_existing_subcategory_id bigint;
	v_old_public_path text;
	v_new_public_path text;
	v_published_dt timestamp with time zone;
	v_archived_dt timestamp with time zone;
	v_slug text;
BEGIN
	v_status_code := COALESCE(NULLIF(BTRIM(LOWER(p_status_code)), ''), 'draft');

	IF v_status_code NOT IN ('draft', 'published', 'archived') THEN
		RAISE EXCEPTION 'Unsupported content status: %.', v_status_code;
	END IF;

	SELECT c.status_code,
		   c.published_dt,
		   c.archived_dt,
		   c.template_id,
		   c.category_id,
		   c.subcategory_id
	INTO v_existing_status_code,
		 v_existing_published_dt,
		 v_existing_archived_dt,
		 v_existing_template_id,
		 v_existing_category_id,
		 v_existing_subcategory_id
	FROM web_priv.web_content c
	WHERE c.content_id = p_content_id
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Content % was not found.', p_content_id;
	END IF;

	v_old_public_path := web_priv.web_content_current_public_path(p_content_id);

	v_published_dt := CASE WHEN v_status_code = 'published'
						  THEN COALESCE(CASE WHEN v_existing_status_code = 'published' THEN v_existing_published_dt ELSE NULL END,
										CURRENT_TIMESTAMP)
						  ELSE NULL
						  END;

	v_archived_dt := CASE WHEN v_status_code = 'archived'
						 THEN COALESCE(CASE WHEN v_existing_status_code = 'archived' THEN v_existing_archived_dt ELSE NULL END,
									   CURRENT_TIMESTAMP)
						 ELSE NULL
						 END;

	PERFORM web_priv.web_content_assert_category_subcategory(p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'admin', p_category_id, p_subcategory_id);

	IF p_template_id = v_existing_template_id
	   AND p_category_id = v_existing_category_id
	   AND p_subcategory_id IS NOT DISTINCT FROM v_existing_subcategory_id THEN
		PERFORM 1
		FROM web_priv.web_templates t
		WHERE t.template_id = p_template_id
		  AND t.surface_scope_code IN ('admin', 'public')
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Template % is not allowed for admin content authoring.', p_template_id;
		END IF;
	ELSE
		PERFORM web_priv.web_content_assert_template_allowed(p_template_id, p_category_id, p_subcategory_id, 'admin');
	END IF;

	PERFORM web_priv.web_content_assert_series_input(p_template_id, p_series_id, p_series_part_no, p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_resolved_icon_defaults(p_template_id,
															  COALESCE(p_icon_mode_code, 'template_default'),
															  p_icon_key_id,
															  COALESCE(p_icon_color_mode_code, 'template_default'),
															  p_icon_color_id);

	v_slug := web_priv.web_content_make_unique_slug(p_slug, p_category_id, p_subcategory_id, p_content_id);

	SELECT t.schema_version_no
	INTO v_template_schema_version_no
	FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id
	;

	UPDATE web_priv.web_content c
	SET template_id = p_template_id,
		template_schema_version_no = v_template_schema_version_no,
		title = BTRIM(p_title),
		slug = v_slug,
		summary = NULLIF(BTRIM(p_summary), ''),
		category_id = p_category_id,
		subcategory_id = p_subcategory_id,
		series_id = p_series_id,
		series_part_no = p_series_part_no,
		status_code = v_status_code,
		published_dt = v_published_dt,
		archived_dt = v_archived_dt,
		read_policy_code = COALESCE(NULLIF(BTRIM(p_read_policy_code), ''), 'inherit'),
		read_rank = p_read_rank,
		write_policy_code = COALESCE(NULLIF(BTRIM(p_write_policy_code), ''), 'inherit'),
		write_rank = p_write_rank,
		nav_hidden_mode_code = COALESCE(NULLIF(BTRIM(p_nav_hidden_mode_code), ''), 'inherit'),
		nav_hidden = p_nav_hidden,
		icon_mode_code = COALESCE(NULLIF(BTRIM(p_icon_mode_code), ''), 'template_default'),
		icon_key_id = p_icon_key_id,
		icon_color_mode_code = COALESCE(NULLIF(BTRIM(p_icon_color_mode_code), ''), 'template_default'),
		icon_color_id = p_icon_color_id,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE c.content_id = p_content_id
	RETURNING c.content_id
	INTO content_id
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Content % was not found.', p_content_id;
	END IF;

	PERFORM web_priv.web_content_recalculate_effective(content_id);

	v_new_public_path := web_priv.web_content_current_public_path(content_id);
	PERFORM web_priv.web_content_redirect_ensure_for_path_change(
		p_actor_discord_id,
		content_id,
		v_old_public_path,
		v_new_public_path
	);

	PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, p_template_id, p_field_values);
	PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, p_template_id, 'admin', p_external_links);
	PERFORM web_priv.web_content_record_history(content_id, 'update', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_content_update_admin(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_published_dt timestamp with time zone, p_archived_dt timestamp with time zone, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_mode_code text, p_icon_key_id bigint, p_icon_color_mode_code text, p_icon_color_id bigint, p_field_values jsonb, p_external_links jsonb) OWNER TO cm;

--
-- Name: FUNCTION web_content_update_admin(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_published_dt timestamp with time zone, p_archived_dt timestamp with time zone, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_mode_code text, p_icon_key_id bigint, p_icon_color_mode_code text, p_icon_color_id bigint, p_field_values jsonb, p_external_links jsonb); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_content_update_admin(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_published_dt timestamp with time zone, p_archived_dt timestamp with time zone, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_mode_code text, p_icon_key_id bigint, p_icon_color_mode_code text, p_icon_color_id bigint, p_field_values jsonb, p_external_links jsonb) IS 'Updates admin content, keeps slugs collision-safe, and automatically records full-path redirects when the public content route changes.';


--
-- Name: web_content_update_public(character varying, bigint, bigint, text, text, text, bigint, bigint, bigint, integer, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_content_update_public(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES COMMUNITY CONTENT THROUGH THE PUBLIC/MEMBER DB-FIRST API                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_schema_version_no integer;
	v_author_discord_id character varying(32);
	v_slug text;
BEGIN
	IF jsonb_typeof(COALESCE(p_external_links, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_external_links must be a JSON array.';
	END IF;

	IF jsonb_array_length(COALESCE(p_external_links, '[]'::jsonb)) > 0 THEN
		RAISE EXCEPTION 'Public content external links are not enabled in v1.';
	END IF;

	SELECT c.author_discord_id
	INTO v_author_discord_id
	FROM web_priv.web_content c
	WHERE c.content_id = p_content_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Content % was not found.', p_content_id;
	END IF;

	IF v_author_discord_id IS DISTINCT FROM p_actor_discord_id THEN
		RAISE EXCEPTION 'Actor % does not own content %.', p_actor_discord_id, p_content_id;
	END IF;

	PERFORM web_priv.web_content_assert_category_subcategory(p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_template_allowed(p_template_id, p_category_id, p_subcategory_id, 'public');
	PERFORM web_priv.web_content_assert_series_input(p_template_id, p_series_id, p_series_part_no, p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_resolved_icon_defaults(p_template_id,
												 'template_default',
												 NULL,
												 'template_default',
												 NULL);

	v_slug := web_priv.web_content_make_unique_slug(p_slug, p_category_id, p_subcategory_id, p_content_id);

	SELECT t.schema_version_no
	INTO v_template_schema_version_no
	FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id;

	UPDATE web_priv.web_content c
	SET template_id = p_template_id,
		template_schema_version_no = v_template_schema_version_no,
		title = BTRIM(p_title),
		slug = v_slug,
		summary = NULLIF(BTRIM(p_summary), ''),
		category_id = p_category_id,
		subcategory_id = p_subcategory_id,
		series_id = p_series_id,
		series_part_no = p_series_part_no,
		read_policy_code = 'inherit',
		read_rank = NULL,
		write_policy_code = 'inherit',
		write_rank = NULL,
		nav_hidden_mode_code = 'inherit',
		nav_hidden = NULL,
		icon_mode_code = 'template_default',
		icon_key_id = NULL,
		icon_color_mode_code = 'template_default',
		icon_color_id = NULL,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE c.content_id = p_content_id
	RETURNING c.content_id
	INTO content_id;

	PERFORM web_priv.web_content_recalculate_effective(content_id);
	PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, p_template_id, p_field_values);
	PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, p_template_id, 'public', '[]'::jsonb);
	PERFORM web_priv.web_content_record_history(content_id, 'update', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_content_update_public(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_field_values jsonb, p_external_links jsonb) OWNER TO cm;

--
-- Name: web_external_link_host_create(character varying, text, text, text, text, boolean, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_external_link_host_create(p_actor_discord_id character varying, p_host_pattern text, p_match_mode_code text, p_allowed_surface_scope_code text, p_comment text, p_is_enabled boolean DEFAULT true, p_valid_from_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_valid_to_dt timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(external_link_host_id bigint, host_pattern text, match_mode_code text, allowed_surface_scope_code text, comment text, valid_from_dt date, valid_to_dt date, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// BACKWARD-COMPATIBILITY CREATE WRAPPER FOR HOST-ONLY EXTERNAL LINK RULES                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT created.external_link_host_id,
	   created.host_pattern,
	   created.host_match_mode_code AS match_mode_code,
	   created.allowed_surface_scope_code,
	   created.comment,
	   created.valid_from_dt,
	   created.valid_to_dt,
	   created.is_enabled,
	   created.created_dt,
	   created.updated_dt
FROM web_api.web_external_link_host_create(p_actor_discord_id,
										 p_host_pattern,
										 p_match_mode_code,
										 '/',
										 'any_path',
										 p_allowed_surface_scope_code,
										 p_comment,
										 p_is_enabled,
										 p_valid_from_dt,
										 p_valid_to_dt) created
;
$$;


ALTER FUNCTION web_api.web_external_link_host_create(p_actor_discord_id character varying, p_host_pattern text, p_match_mode_code text, p_allowed_surface_scope_code text, p_comment text, p_is_enabled boolean, p_valid_from_dt timestamp with time zone, p_valid_to_dt timestamp with time zone) OWNER TO cm;

--
-- Name: FUNCTION web_external_link_host_create(p_actor_discord_id character varying, p_host_pattern text, p_match_mode_code text, p_allowed_surface_scope_code text, p_comment text, p_is_enabled boolean, p_valid_from_dt timestamp with time zone, p_valid_to_dt timestamp with time zone); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_external_link_host_create(p_actor_discord_id character varying, p_host_pattern text, p_match_mode_code text, p_allowed_surface_scope_code text, p_comment text, p_is_enabled boolean, p_valid_from_dt timestamp with time zone, p_valid_to_dt timestamp with time zone) IS 'Backward-compatible host-only create wrapper for external link whitelist rows.';


--
-- Name: web_external_link_host_create(character varying, text, text, text, text, text, text, boolean, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_external_link_host_create(p_actor_discord_id character varying, p_host_pattern text, p_host_match_mode_code text, p_path_pattern text, p_path_match_mode_code text, p_allowed_surface_scope_code text, p_comment text, p_is_enabled boolean DEFAULT true, p_valid_from_dt timestamp with time zone DEFAULT NULL::timestamp with time zone, p_valid_to_dt timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(external_link_host_id bigint, host_pattern text, host_match_mode_code text, match_mode_code text, path_pattern text, path_match_mode_code text, allowed_surface_scope_code text, comment text, valid_from_dt date, valid_to_dt date, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES AN EXTERNAL LINK HOST AND PATH WHITELIST ROW THROUGH THE ADMIN DATABASE API                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_external_link_host_id bigint;
	v_host_pattern text;
	v_host_match_mode_code text;
	v_path_pattern text;
	v_path_match_mode_code text;
	v_allowed_surface_scope_code text;
	v_comment text;
	v_valid_from_dt date;
	v_valid_to_dt date;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_host_pattern := NULLIF(btrim(lower(p_host_pattern)), '');
	v_host_match_mode_code := COALESCE(NULLIF(btrim(lower(p_host_match_mode_code)), ''), 'exact_host');
	v_path_pattern := COALESCE(NULLIF(btrim(p_path_pattern), ''), '/');
	v_path_match_mode_code := COALESCE(NULLIF(btrim(lower(p_path_match_mode_code)), ''), 'any_path');
	v_allowed_surface_scope_code := NULLIF(btrim(lower(p_allowed_surface_scope_code)), '');
	v_comment := NULLIF(btrim(p_comment), '');
	v_valid_from_dt := p_valid_from_dt::date;
	v_valid_to_dt := p_valid_to_dt::date;

	IF v_host_pattern IS NULL THEN
		RAISE EXCEPTION 'web_external_link_host_c.host_pattern is required.';
	END IF;

	IF v_host_pattern !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' THEN
		RAISE EXCEPTION 'web_external_link_host_c.host_pattern must be a normalized exact host such as youtube.com.';
	END IF;

	IF v_host_match_mode_code <> 'exact_host' THEN
		RAISE EXCEPTION 'web_external_link_host_c.host_match_mode_code must be exact_host.';
	END IF;

	IF v_path_match_mode_code NOT IN ('any_path', 'exact_path', 'path_prefix') THEN
		RAISE EXCEPTION 'web_external_link_host_c.path_match_mode_code must be any_path, exact_path, or path_prefix.';
	END IF;

	IF v_path_match_mode_code = 'any_path' THEN
		v_path_pattern := '/';
	END IF;

	IF left(v_path_pattern, 1) <> '/'
	   OR v_path_pattern ~ '[[:space:]?#]'
	   OR position(chr(92) in v_path_pattern) > 0
	   OR v_path_pattern LIKE '%..%'
	   OR v_path_pattern LIKE '%//%'
	   OR (v_path_pattern <> '/' AND right(v_path_pattern, 1) = '/') THEN
		RAISE EXCEPTION 'web_external_link_host_c.path_pattern must be a clean path such as /@channel or /news/item.';
	END IF;

	IF v_path_match_mode_code <> 'any_path' AND v_path_pattern = '/' THEN
		RAISE EXCEPTION 'web_external_link_host_c.path_pattern must be more specific than / for exact_path or path_prefix.';
	END IF;

	IF v_allowed_surface_scope_code IS NULL OR v_allowed_surface_scope_code NOT IN ('admin', 'public', 'all') THEN
		RAISE EXCEPTION 'web_external_link_host_c.allowed_surface_scope_code must be admin, public, or all.';
	END IF;

	IF v_valid_to_dt IS NOT NULL AND v_valid_from_dt IS NOT NULL AND v_valid_to_dt < v_valid_from_dt THEN
		RAISE EXCEPTION 'web_external_link_host_c.valid_to_dt must be greater than or equal to valid_from_dt.';
	END IF;

	IF EXISTS (SELECT 1
			   FROM web_priv.web_external_link_host_c h
			   WHERE h.host_pattern = v_host_pattern
				 AND h.host_match_mode_code = v_host_match_mode_code
				 AND h.path_pattern = v_path_pattern
				 AND h.path_match_mode_code = v_path_match_mode_code
				 AND h.allowed_surface_scope_code = v_allowed_surface_scope_code) THEN
		RAISE EXCEPTION 'web_external_link_host_c row already exists for %, %, %, %, %.',
			v_host_pattern,
			v_host_match_mode_code,
			v_path_pattern,
			v_path_match_mode_code,
			v_allowed_surface_scope_code;
	END IF;

	INSERT INTO web_priv.web_external_link_host_c AS h(host_pattern,
											   host_match_mode_code,
											   path_pattern,
											   path_match_mode_code,
											   allowed_surface_scope_code,
											   comment,
											   is_enabled,
											   valid_from_dt,
											   valid_to_dt,
											   created_by_discord_id,
											   updated_by_discord_id)
	VALUES (v_host_pattern,
			v_host_match_mode_code,
			v_path_pattern,
			v_path_match_mode_code,
			v_allowed_surface_scope_code,
			v_comment,
			COALESCE(p_is_enabled, true),
			v_valid_from_dt,
			v_valid_to_dt,
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING h.external_link_host_id
	INTO v_external_link_host_id;

	PERFORM web_priv.web_external_link_host_record_history(v_external_link_host_id, 'create', p_actor_discord_id);

	RETURN QUERY
	SELECT h.external_link_host_id,
		   h.host_pattern,
		   h.host_match_mode_code,
		   h.match_mode_code,
		   h.path_pattern,
		   h.path_match_mode_code,
		   h.allowed_surface_scope_code,
		   h.comment,
		   h.valid_from_dt,
		   h.valid_to_dt,
		   h.is_enabled,
		   h.created_dt,
		   h.updated_dt
	FROM web_view.web_external_link_hosts_admin h
	WHERE h.external_link_host_id = v_external_link_host_id;
END;
