    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES AN EXTERNAL LINK HOST WHITELIST ROW THROUGH THE ADMIN DATABASE API                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_deleted web_priv.web_external_link_host_c%ROWTYPE;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	IF p_external_link_host_id IS NULL OR p_external_link_host_id <= 0 THEN
		RAISE EXCEPTION 'web_external_link_host_c.external_link_host_id is required.';
	END IF;

	IF NOT EXISTS (SELECT 1
			   FROM web_priv.web_external_link_host_c h
			   WHERE h.external_link_host_id = p_external_link_host_id) THEN
		RAISE EXCEPTION 'web_external_link_host_c row % was not found.', p_external_link_host_id;
	END IF;

	PERFORM web_priv.web_external_link_host_record_history(p_external_link_host_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_external_link_host_c h
	WHERE h.external_link_host_id = p_external_link_host_id
	RETURNING h.*
	INTO v_deleted;

	RETURN QUERY
	SELECT v_deleted.external_link_host_id,
		   v_deleted.host_pattern,
		   v_deleted.host_match_mode_code,
		   v_deleted.host_match_mode_code AS match_mode_code,
		   v_deleted.path_pattern,
		   v_deleted.path_match_mode_code,
		   v_deleted.allowed_surface_scope_code,
		   v_deleted.comment,
		   v_deleted.valid_from_dt,
		   v_deleted.valid_to_dt,
		   v_deleted.is_enabled,
		   v_deleted.created_dt,
		   v_deleted.updated_dt;
END;
$$;


