--
-- Name: web_external_link_validate(text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_external_link_validate(p_raw_url text, p_surface_scope_code text DEFAULT 'admin'::text) RETURNS TABLE(is_allowed boolean, normalized_url text, url_scheme text, url_host text, url_path text, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_external_link_validate                                                              ////
--//// PURPOSE: Validates a user-entered external link against host/path whitelist rules                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_raw_url text;
	v_surface_scope_code text;
	v_parsed record;
BEGIN
	v_raw_url := btrim(COALESCE(p_raw_url, ''));
	v_surface_scope_code := lower(btrim(COALESCE(p_surface_scope_code, 'admin')));

	is_allowed := false;
	normalized_url := NULL;
	url_scheme := NULL;
	url_host := NULL;
	url_path := NULL;
	error_message := NULL;

	IF v_raw_url = '' THEN
		error_message := 'External URL is required.';
		RETURN NEXT;
		RETURN;
	END IF;

	IF v_surface_scope_code NOT IN ('admin', 'public') THEN
		error_message := 'Surface scope must be admin or public.';
		RETURN NEXT;
		RETURN;
	END IF;

	IF v_raw_url LIKE '//%' THEN
		error_message := 'Protocol-relative external links are not allowed.';
		RETURN NEXT;
		RETURN;
	END IF;

	SELECT parsed.url_scheme,
		   parsed.url_host,
		   parsed.url_path,
		   parsed.normalized_url
	INTO v_parsed
	FROM web_priv.web_content_parse_external_url(v_raw_url) parsed;

	url_scheme := v_parsed.url_scheme;
	url_host := v_parsed.url_host;
	url_path := v_parsed.url_path;
	normalized_url := v_parsed.normalized_url;
	is_allowed := COALESCE(web_priv.web_content_is_external_link_allowed(url_host, url_path, v_surface_scope_code, CURRENT_TIMESTAMP), false);

	IF is_allowed = false THEN
		error_message := 'External link is not whitelisted for this surface.';
	END IF;

	RETURN NEXT;
	RETURN;

EXCEPTION WHEN OTHERS THEN
	is_allowed := false;
	normalized_url := NULL;
	url_scheme := NULL;
	url_host := NULL;
	url_path := NULL;
	error_message := SQLERRM;

	RETURN NEXT;
	RETURN;
END;
$$;


ALTER FUNCTION web_api.web_external_link_validate(p_raw_url text, p_surface_scope_code text) OWNER TO cm;

