--
-- Name: web_icon_create(character varying, text, text, text, text, bigint, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_icon_create(p_actor_discord_id character varying, p_key text, p_label text, p_source_code text, p_lucide_name text, p_media_id bigint, p_is_enabled boolean) RETURNS TABLE(icon_id bigint, key text, label text, source_code text, lucide_name text, media_id bigint, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES AN ICON ROW THROUGH THE ADMIN DATABASE API                                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_key text;
    v_label text;
    v_source_code text;
    v_lucide_name text;
    v_media_id bigint;
    v_media web_priv.web_media%ROWTYPE;
    v_existing web_priv.web_icons%ROWTYPE;
    v_icon_id bigint;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    v_key := NULLIF(lower(btrim(p_key)), '');
    v_label := NULLIF(btrim(p_label), '');
    v_source_code := CASE WHEN lower(btrim(COALESCE(p_source_code, 'lucide'))) = 'media' THEN 'media' ELSE 'lucide' END;
    v_lucide_name := NULLIF(btrim(p_lucide_name), '');
    v_media_id := p_media_id;

    IF v_key IS NULL THEN
        RAISE EXCEPTION 'web_icons.key is required.';
    END IF;

    IF v_key !~ '^[a-z0-9._-]{1,64}$' THEN
        RAISE EXCEPTION 'web_icons.key must match ^[a-z0-9._-]{1,64}$.';
    END IF;

    IF v_label IS NULL THEN
        RAISE EXCEPTION 'web_icons.label is required.';
    END IF;

    IF v_source_code = 'lucide' THEN
        v_media_id := NULL;
        IF v_lucide_name IS NULL THEN
            v_lucide_name := v_key;
        END IF;
    ELSE
        v_lucide_name := NULL;
        IF v_media_id IS NULL THEN
            RAISE EXCEPTION 'web_icons.media_id is required when source_code = media.';
        END IF;

        SELECT *
          INTO v_media
          FROM web_priv.web_media_find_by_id(v_media_id);

        IF v_media.media_id IS NULL THEN
            RAISE EXCEPTION 'web_media row % was not found.', v_media_id;
        END IF;

        IF NOT (
            COALESCE(v_media.mime_type, '') ILIKE 'image/svg%'
            OR COALESCE(v_media.filename, '') ILIKE '%.svg'
            OR COALESCE(v_media.storage_rel_path, '') ILIKE '%.svg'
        ) THEN
            RAISE EXCEPTION 'Only SVG media is allowed for media-backed icons.';
        END IF;
    END IF;

    SELECT *
      INTO v_existing
      FROM web_priv.web_icon_find_by_key(v_key);

    IF v_existing.icon_id IS NOT NULL THEN
        RAISE EXCEPTION 'web_icons.key already exists: %.', v_key;
    END IF;

    INSERT INTO web_priv.web_icons (
        key,
        label,
        source_code,
        lucide_name,
        media_id,
        is_enabled,
        created_by_discord_id,
        updated_by_discord_id
    )
    VALUES (
        v_key,
        v_label,
        v_source_code,
        v_lucide_name,
        v_media_id,
        COALESCE(p_is_enabled, true),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING web_icons.icon_id
      INTO v_icon_id;

    PERFORM web_priv.web_icon_record_history(v_icon_id, 'create', p_actor_discord_id, now());

    RETURN QUERY
    SELECT
        i.icon_id,
        i.key,
        i.label,
        i.source_code,
        i.lucide_name,
        i.media_id,
        i.is_enabled,
        i.created_dt,
        i.updated_dt
      FROM web_priv.web_icons i
     WHERE i.icon_id = v_icon_id;
END;
$_$;


ALTER FUNCTION web_api.web_icon_create(p_actor_discord_id character varying, p_key text, p_label text, p_source_code text, p_lucide_name text, p_media_id bigint, p_is_enabled boolean) OWNER TO cm;

--
-- Name: FUNCTION web_icon_create(p_actor_discord_id character varying, p_key text, p_label text, p_source_code text, p_lucide_name text, p_media_id bigint, p_is_enabled boolean); Type: COMMENT; Schema: web_api; Owner: cm
--

