--
-- Name: web_icon_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_icon_delete(p_actor_discord_id character varying, p_icon_id bigint) RETURNS TABLE(icon_id bigint, key text, label text, source_code text, lucide_name text, media_id bigint, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES AN ICON ROW THROUGH THE ADMIN DATABASE API                                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_existing web_priv.web_icons%ROWTYPE;
    v_deleted web_priv.web_icons%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    SELECT *
      INTO v_existing
      FROM web_priv.web_icon_find_by_id(p_icon_id);

    IF v_existing.icon_id IS NULL THEN
        RAISE EXCEPTION 'web_icons row % was not found.', p_icon_id;
    END IF;

    PERFORM web_priv.web_icon_assert_can_delete(p_icon_id);
    PERFORM web_priv.web_icon_record_history(p_icon_id, 'delete', p_actor_discord_id, now());

    DELETE FROM web_priv.web_icons i
     WHERE i.icon_id = p_icon_id
     RETURNING i.*
      INTO v_deleted;

    IF v_deleted.icon_id IS NULL THEN
        RAISE EXCEPTION 'web_icons row % was not found.', p_icon_id;
    END IF;

    RETURN QUERY
    SELECT
        v_deleted.icon_id,
        v_deleted.key,
        v_deleted.label,
        v_deleted.source_code,
        v_deleted.lucide_name,
        v_deleted.media_id,
        v_deleted.is_enabled,
        v_deleted.created_dt,
        v_deleted.updated_dt;
END;
$$;


