--
-- Name: web_icon_update(character varying, bigint, text, text, text, bigint, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_icon_update(p_actor_discord_id character varying, p_icon_id bigint, p_label text, p_source_code text, p_lucide_name text, p_media_id bigint, p_is_enabled boolean) RETURNS TABLE(icon_id bigint, key text, label text, source_code text, lucide_name text, media_id bigint, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES AN ICON ROW THROUGH THE ADMIN DATABASE API                                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_existing web_priv.web_icons%ROWTYPE;
    v_label text;
    v_source_code text;
    v_lucide_name text;
    v_media_id bigint;
    v_media web_priv.web_media%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    SELECT *
      INTO v_existing
      FROM web_priv.web_icon_find_by_id(p_icon_id);

    IF v_existing.icon_id IS NULL THEN
        RAISE EXCEPTION 'web_icons row % was not found.', p_icon_id;
    END IF;

    v_label := NULLIF(btrim(p_label), '');
    v_source_code := CASE WHEN lower(btrim(COALESCE(p_source_code, v_existing.source_code))) = 'media' THEN 'media' ELSE 'lucide' END;
    v_lucide_name := NULLIF(btrim(p_lucide_name), '');
    v_media_id := p_media_id;

    IF v_label IS NULL THEN
        RAISE EXCEPTION 'web_icons.label is required.';
    END IF;

    IF v_source_code = 'lucide' THEN
        v_media_id := NULL;
        IF v_lucide_name IS NULL THEN
            v_lucide_name := v_existing.key;
        END IF;
    ELSE
        v_lucide_name := NULL;
        IF v_media_id IS NULL THEN
            RAISE EXCEPTION 'web_icons.media_id is required when source_code = media.';
        END IF;

        SELECT *
          INTO v_media
          FROM web_priv.web_media_find_by_id(v_media_id);

        IF v_media.media_id IS NULL THEN
            RAISE EXCEPTION 'web_media row % was not found.', v_media_id;
        END IF;

        IF NOT (
            COALESCE(v_media.mime_type, '') ILIKE 'image/svg%'
            OR COALESCE(v_media.filename, '') ILIKE '%.svg'
            OR COALESCE(v_media.storage_rel_path, '') ILIKE '%.svg'
        ) THEN
            RAISE EXCEPTION 'Only SVG media is allowed for media-backed icons.';
        END IF;
    END IF;

    UPDATE web_priv.web_icons i
       SET label = v_label,
           source_code = v_source_code,
           lucide_name = v_lucide_name,
           media_id = v_media_id,
           is_enabled = COALESCE(p_is_enabled, i.is_enabled),
           updated_by_discord_id = p_actor_discord_id
     WHERE i.icon_id = p_icon_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'web_icons row % was not found.', p_icon_id;
    END IF;

    PERFORM web_priv.web_icon_record_history(p_icon_id, 'update', p_actor_discord_id, now());

    RETURN QUERY
    SELECT
        i.icon_id,
        i.key,
        i.label,
        i.source_code,
        i.lucide_name,
        i.media_id,
        i.is_enabled,
        i.created_dt,
        i.updated_dt
      FROM web_priv.web_icons i
     WHERE i.icon_id = p_icon_id;
END;
$$;


