--
-- Name: web_internal_link_validate(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_internal_link_validate(p_actor_discord_id character varying, p_raw_path text) RETURNS TABLE(is_allowed boolean, normalized_path text, public_route_prefix text, category_slug text, subcategory_slug text, content_slug text, target_content_id text, target_title text, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_internal_link_validate                                                              ////
--//// PURPOSE: Validates an internal content route or old-path redirect against existence and actor read access   ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_content_doc jsonb;
	v_redirect_doc jsonb;
	v_parsed record;
	v_raw_path text;
	v_base_path text;
	v_suffix text;
	v_query_pos integer;
	v_hash_pos integer;
	v_split_pos integer;
BEGIN
	is_allowed := false;
	normalized_path := NULL;
	public_route_prefix := NULL;
	category_slug := NULL;
	subcategory_slug := NULL;
	content_slug := NULL;
	target_content_id := NULL;
	target_title := NULL;
	error_message := NULL;

	v_raw_path := btrim(COALESCE(p_raw_path, ''));
	IF v_raw_path = '' THEN
		error_message := 'Internal path is required.';
		RETURN NEXT;
		RETURN;
	END IF;

	v_query_pos := NULLIF(position('?' IN v_raw_path), 0);
	v_hash_pos  := NULLIF(position('#' IN v_raw_path), 0);

	IF v_query_pos IS NULL AND v_hash_pos IS NULL THEN
		v_split_pos := NULL;
	ELSIF v_query_pos IS NULL THEN
		v_split_pos := v_hash_pos;
	ELSIF v_hash_pos IS NULL THEN
		v_split_pos := v_query_pos;
	ELSE
		v_split_pos := LEAST(v_query_pos, v_hash_pos);
	END IF;

	IF v_split_pos IS NULL THEN
		v_base_path := v_raw_path;
		v_suffix := '';
	ELSE
		v_base_path := substring(v_raw_path from 1 for v_split_pos - 1);
		v_suffix := substring(v_raw_path from v_split_pos);
	END IF;

	IF v_suffix <> ''
	   AND (v_suffix ~ '[[:space:]]'
			OR v_suffix ~ '[[:cntrl:]]'
			OR position(CHR(92) in v_suffix) > 0
			OR v_suffix ~ '[<>"'']') THEN
		error_message := 'Internal link query strings and anchors contain an unsupported shape.';
		RETURN NEXT;
		RETURN;
	END IF;

	BEGIN
		SELECT *
		INTO v_parsed
		FROM web_priv.web_content_parse_public_path(v_base_path)
		LIMIT 1;
	EXCEPTION WHEN OTHERS THEN
		error_message := SQLERRM;
		RETURN NEXT;
		RETURN;
	END;

	normalized_path := v_parsed.normalized_path || v_suffix;
	public_route_prefix := v_parsed.public_route_prefix;
	category_slug := v_parsed.category_slug;
	subcategory_slug := v_parsed.subcategory_slug;
	content_slug := v_parsed.content_slug;

	v_content_doc := web_api.web_content_public_find_by_path(
		p_actor_discord_id,
		public_route_prefix,
		category_slug,
		subcategory_slug,
		content_slug
	);

	IF v_content_doc IS NOT NULL THEN
		is_allowed := true;
		target_content_id := v_content_doc #>> '{doc,id}';
		target_title := v_content_doc #>> '{doc,title}';
		error_message := NULL;

		RETURN NEXT;
		RETURN;
	END IF;

	v_redirect_doc := web_api.web_content_public_find_redirect_by_path(
		p_actor_discord_id,
		v_parsed.normalized_path
	);

	IF v_redirect_doc IS NOT NULL THEN
		normalized_path := (v_redirect_doc ->> 'redirectPath') || v_suffix;

		SELECT *
		INTO v_parsed
		FROM web_priv.web_content_parse_public_path(v_redirect_doc ->> 'redirectPath')
		LIMIT 1;

		public_route_prefix := v_parsed.public_route_prefix;
		category_slug := v_parsed.category_slug;
		subcategory_slug := v_parsed.subcategory_slug;
		content_slug := v_parsed.content_slug;
		is_allowed := true;
		target_content_id := v_redirect_doc ->> 'contentId';
		target_title := v_redirect_doc ->> 'title';
		error_message := NULL;

		RETURN NEXT;
		RETURN;
	END IF;

	error_message := 'Internal link target was not found or you do not have access.';
	RETURN NEXT;
	RETURN;

EXCEPTION WHEN OTHERS THEN
	is_allowed := false;
	normalized_path := NULL;
	public_route_prefix := NULL;
	category_slug := NULL;
	subcategory_slug := NULL;
	content_slug := NULL;
	target_content_id := NULL;
	target_title := NULL;
	error_message := SQLERRM;

	RETURN NEXT;
	RETURN;
END;
$$;


ALTER FUNCTION web_api.web_internal_link_validate(p_actor_discord_id character varying, p_raw_path text) OWNER TO cm;

--
-- Name: FUNCTION web_internal_link_validate(p_actor_discord_id character varying, p_raw_path text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_internal_link_validate(p_actor_discord_id character varying, p_raw_path text) IS 'Validates an internal content route or old-path redirect against route shape, existence, and actor read access. Safe query/hash suffixes are preserved after the base route is validated.';


--
-- Name: web_media_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_media_delete(p_actor_discord_id character varying, p_media_id bigint) RETURNS TABLE(media_id bigint, filename text, original_filename text, storage_rel_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A MEDIA ROW AFTER THE APPLICATION HAS STAGED OR REMOVED THE FILE ON DISK                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_deleted web_priv.web_media%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);
    PERFORM web_priv.web_media_assert_can_delete(p_media_id);

    SELECT m.*
      INTO v_deleted
      FROM web_priv.web_media m
     WHERE m.media_id = p_media_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'media % was not found.', p_media_id;
    END IF;

    PERFORM web_priv.web_media_record_history(v_deleted.media_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_media m
     WHERE m.media_id = p_media_id;

    RETURN QUERY
    SELECT
        v_deleted.media_id,
        v_deleted.filename,
        v_deleted.original_filename,
        v_deleted.storage_rel_path;
END;
$$;


