--

CREATE FUNCTION web_api.web_media_file_resolve_for_actor(p_actor_discord_id character varying, p_storage_rel_path text) RETURNS TABLE(media_id bigint, storage_rel_path text, filename text, original_filename text, mime_type text, size_bytes bigint, width_px integer, height_px integer, alt_text text, credit_text text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_media_file_resolve_for_actor                                                        ////
--//// PURPOSE: Resolves one media file path only when the actor may read the media.                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

SELECT m.media_id,
	   m.storage_rel_path,
	   m.filename,
	   m.original_filename,
	   m.mime_type,
	   m.size_bytes,
	   m.width_px,
	   m.height_px,
	   m.alt_text,
	   m.credit_text
FROM web_priv.web_media m
WHERE m.storage_rel_path = NULLIF(BTRIM(p_storage_rel_path), '')
  AND web_priv.web_media_actor_can_read(p_actor_discord_id, m.media_id)
LIMIT 1;
$$;


