--
-- Name: web_media_insert_uploaded(character varying, bigint, bigint, boolean, character varying, text, text, text, text, bigint, integer, integer, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_media_insert_uploaded(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint, p_is_shared boolean, p_owner_discord_id character varying, p_filename text, p_original_filename text, p_storage_rel_path text, p_mime_type text, p_size_bytes bigint, p_width_px integer, p_height_px integer, p_alt_text text, p_credit_text text) RETURNS TABLE(media_id bigint, category_id bigint, subcategory_id bigint, owner_discord_id character varying, is_shared boolean, filename text, original_filename text, storage_rel_path text, mime_type text, size_bytes bigint, width_px integer, height_px integer, alt_text text, credit_text text, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INSERTS A NEW MEDIA ROW AFTER THE APP HAS WRITTEN THE FILE TO DISK                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_filename text;
    v_original_filename text;
    v_storage_rel_path text;
    v_mime_type text;
    v_inserted web_priv.web_media%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);
    PERFORM web_priv.web_media_assert_valid_category_subcategory(p_category_id, p_subcategory_id);

    v_filename := NULLIF(btrim(p_filename), '');
    v_original_filename := NULLIF(btrim(p_original_filename), '');
    v_storage_rel_path := NULLIF(btrim(p_storage_rel_path), '');
    v_mime_type := NULLIF(btrim(p_mime_type), '');

    IF v_filename IS NULL THEN
        RAISE EXCEPTION 'media.filename is required.';
    END IF;

    IF v_original_filename IS NULL THEN
        RAISE EXCEPTION 'media.original_filename is required.';
    END IF;

    IF v_storage_rel_path IS NULL THEN
        RAISE EXCEPTION 'media.storage_rel_path is required.';
    END IF;

    IF v_mime_type IS NULL THEN
        RAISE EXCEPTION 'media.mime_type is required.';
    END IF;

    IF COALESCE(p_is_shared, false) = false AND NULLIF(btrim(p_owner_discord_id), '') IS NULL THEN
        RAISE EXCEPTION 'media.owner_discord_id is required when media.is_shared = false.';
    END IF;

    INSERT INTO web_priv.web_media (
        category_id,
        subcategory_id,
        owner_discord_id,
        is_shared,
        storage_rel_path,
        filename,
        original_filename,
        mime_type,
        size_bytes,
        width_px,
        height_px,
        alt_text,
        credit_text,
        created_by_discord_id,
        updated_by_discord_id
    )
    VALUES (
        p_category_id,
        p_subcategory_id,
        CASE WHEN COALESCE(p_is_shared, false) THEN NULL ELSE NULLIF(btrim(p_owner_discord_id), '') END,
        COALESCE(p_is_shared, false),
        v_storage_rel_path,
        v_filename,
        v_original_filename,
        v_mime_type,
        COALESCE(p_size_bytes, 0),
        p_width_px,
        p_height_px,
        NULLIF(btrim(p_alt_text), ''),
        NULLIF(btrim(p_credit_text), ''),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING *
      INTO v_inserted;

    PERFORM web_priv.web_media_record_history(v_inserted.media_id, 'create', p_actor_discord_id);

    RETURN QUERY
    SELECT
        v_inserted.media_id,
        v_inserted.category_id,
        v_inserted.subcategory_id,
        v_inserted.owner_discord_id,
        v_inserted.is_shared,
        v_inserted.filename,
        v_inserted.original_filename,
        v_inserted.storage_rel_path,
        v_inserted.mime_type,
        v_inserted.size_bytes,
        v_inserted.width_px,
        v_inserted.height_px,
        v_inserted.alt_text,
        v_inserted.credit_text,
        v_inserted.created_dt,
        v_inserted.updated_dt;
END;
$$;


