--
-- Name: web_media_relocate(character varying, bigint, bigint, bigint, boolean, character varying, text, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_media_relocate(p_actor_discord_id character varying, p_media_id bigint, p_category_id bigint, p_subcategory_id bigint, p_is_shared boolean, p_owner_discord_id character varying, p_filename text, p_storage_rel_path text, p_alt_text text, p_credit_text text) RETURNS TABLE(media_id bigint, category_id bigint, subcategory_id bigint, owner_discord_id character varying, is_shared boolean, filename text, storage_rel_path text, alt_text text, credit_text text, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES MEDIA PLACEMENT FIELDS AFTER THE APP HAS MOVED THE FILE ON DISK                                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_updated web_priv.web_media%ROWTYPE;
    v_filename text;
    v_storage_rel_path text;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);
    PERFORM web_priv.web_media_assert_valid_category_subcategory(p_category_id, p_subcategory_id);

    v_filename := NULLIF(btrim(p_filename), '');
    v_storage_rel_path := NULLIF(btrim(p_storage_rel_path), '');

    IF v_filename IS NULL THEN
        RAISE EXCEPTION 'media.filename is required.';
    END IF;

    IF v_storage_rel_path IS NULL THEN
        RAISE EXCEPTION 'media.storage_rel_path is required.';
    END IF;

    IF COALESCE(p_is_shared, false) = false AND NULLIF(btrim(p_owner_discord_id), '') IS NULL THEN
        RAISE EXCEPTION 'media.owner_discord_id is required when media.is_shared = false.';
    END IF;

    UPDATE web_priv.web_media m
       SET category_id = p_category_id,
           subcategory_id = p_subcategory_id,
           owner_discord_id = CASE WHEN COALESCE(p_is_shared, false) THEN NULL ELSE NULLIF(btrim(p_owner_discord_id), '') END,
           is_shared = COALESCE(p_is_shared, false),
           storage_rel_path = v_storage_rel_path,
           filename = v_filename,
           alt_text = NULLIF(btrim(p_alt_text), ''),
           credit_text = NULLIF(btrim(p_credit_text), ''),
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = now()
     WHERE m.media_id = p_media_id
     RETURNING *
      INTO v_updated;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'media % was not found.', p_media_id;
    END IF;

    PERFORM web_priv.web_media_record_history(v_updated.media_id, 'update', p_actor_discord_id);

    RETURN QUERY
    SELECT
        v_updated.media_id,
        v_updated.category_id,
        v_updated.subcategory_id,
        v_updated.owner_discord_id,
        v_updated.is_shared,
        v_updated.filename,
        v_updated.storage_rel_path,
        v_updated.alt_text,
        v_updated.credit_text,
        v_updated.updated_dt;
END;
$$;


ALTER FUNCTION web_api.web_media_relocate(p_actor_discord_id character varying, p_media_id bigint, p_category_id bigint, p_subcategory_id bigint, p_is_shared boolean, p_owner_discord_id character varying, p_filename text, p_storage_rel_path text, p_alt_text text, p_credit_text text) OWNER TO cm;

--
-- Name: FUNCTION web_media_relocate(p_actor_discord_id character varying, p_media_id bigint, p_category_id bigint, p_subcategory_id bigint, p_is_shared boolean, p_owner_discord_id character varying, p_filename text, p_storage_rel_path text, p_alt_text text, p_credit_text text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_media_relocate(p_actor_discord_id character varying, p_media_id bigint, p_category_id bigint, p_subcategory_id bigint, p_is_shared boolean, p_owner_discord_id character varying, p_filename text, p_storage_rel_path text, p_alt_text text, p_credit_text text) IS 'Updates media placement fields after the application has already moved the physical file on disk.';


--
-- Name: web_media_update_meta(character varying, bigint, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_media_update_meta(p_actor_discord_id character varying, p_media_id bigint, p_alt_text text, p_credit_text text) RETURNS TABLE(media_id bigint, alt_text text, credit_text text, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES MEDIA METADATA FIELDS THAT DO NOT AFFECT FILE PLACEMENT                                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_updated web_priv.web_media%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    UPDATE web_priv.web_media m
       SET alt_text = NULLIF(btrim(p_alt_text), ''),
           credit_text = NULLIF(btrim(p_credit_text), ''),
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = now()
     WHERE m.media_id = p_media_id
     RETURNING *
      INTO v_updated;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'media % was not found.', p_media_id;
    END IF;

    PERFORM web_priv.web_media_record_history(v_updated.media_id, 'update', p_actor_discord_id);

    RETURN QUERY
    SELECT
        v_updated.media_id,
        v_updated.alt_text,
        v_updated.credit_text,
        v_updated.updated_dt;
END;
$$;


