--
-- Name: web_member_authorable_collections(character varying); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_authorable_collections(p_actor_discord_id character varying) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_authorable_collections                                                       ////
--//// PURPOSE: Returns authorable collections only when public templates are valid for that exact placement     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT COALESCE(jsonb_agg(jsonb_build_object(
					'categoryId', c.category_id::text,
					'categoryTitle', c.title,
					'categorySlug', c.slug,
					'subcategoryId', sc.subcategory_id::text,
					'subcategoryTitle', sc.title,
					'subcategorySlug', sc.slug,
					'label', c.title || ' / ' || sc.title)
				ORDER BY c.title, sc.title, c.category_id, sc.subcategory_id), '[]'::jsonb)
FROM web_priv.web_categories c
JOIN web_priv.web_subcategories sc ON sc.category_id = c.category_id
CROSS JOIN web_priv.actor_get_access_summary(p_actor_discord_id) actor_summary
WHERE COALESCE(actor_summary.is_authenticated, false) = true
  AND COALESCE(actor_summary.is_member, false)        = true
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.write_effective_policy_code, sc.write_effective_rank)
  AND web_priv.web_member_collection_has_public_template(c.category_id, sc.subcategory_id)
;
$$;


ALTER FUNCTION web_api.web_member_authorable_collections(p_actor_discord_id character varying) OWNER TO cm;

--
-- Name: web_member_content_collection_by_path(character varying, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_collection_by_path(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_collection_by_path                                                  ////
--//// PURPOSE: Returns member-manageable content for one currently authorable public collection path            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'collection', jsonb_build_object(
		'categoryId', cat.category_id::text,
		'categoryTitle', cat.title,
		'categorySlug', cat.slug,
		'subcategoryId', sc.subcategory_id::text,
		'subcategoryTitle', sc.title,
		'subcategorySlug', sc.slug,
		'label', cat.title || ' / ' || sc.title
	),
	'rows', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
					'id', c.content_id::text,
					'title', c.title,
					'slug', c.slug,
					'summary', COALESCE(c.summary, ''),
					'statusCode', c.status_code,
					'templateId', t.template_id::text,
					'templateCode', t.template_code,
					'templateLabel', t.label,
					'contentKindCode', t.content_kind_code,
					'contentKindLabel', ck.label,
					'rendererCode', ck.renderer_code,
					'categoryId', cat.category_id::text,
					'categoryTitle', cat.title,
					'categorySlug', cat.slug,
					'subcategoryId', sc.subcategory_id::text,
					'subcategoryTitle', sc.title,
					'subcategorySlug', sc.slug,
					'seriesId', CASE WHEN s.series_id IS NULL THEN NULL ELSE s.series_id::text END,
					'seriesTitle', s.title,
					'seriesPartNo', c.series_part_no,
					'publicHref', CASE WHEN NULLIF(btrim(COALESCE(ck.public_route_prefix, '')), '') IS NULL
									   THEN '/' || cat.slug || '/' || sc.slug || '/' || c.slug
									   ELSE '/' || btrim(ck.public_route_prefix) || '/' || cat.slug || '/' || sc.slug || '/' || c.slug
									   END,
					'canViewPublic', c.status_code = 'published'
								 AND ck.renderer_code = ANY (ARRAY['page'::text,
														 'map'::text,
														 'tool'::text,
														 'app'::text,
														 'event'::text,
														 'custom'::text,
														 'youtube'::text,
														 'stream'::text,
														 'calendar'::text])
								 AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank),
					'publishedAt', c.published_dt,
					'archivedAt', c.archived_dt,
					'createdAt', c.created_dt,
					'updatedAt', c.updated_dt)
				ORDER BY c.updated_dt DESC, c.content_id DESC)
		FROM web_priv.web_content c
		JOIN web_priv.web_templates t ON t.template_id = c.template_id
		JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
		LEFT JOIN web_priv.web_series s ON s.series_id = c.series_id
		WHERE c.category_id        = cat.category_id
		  AND c.subcategory_id     = sc.subcategory_id
		  AND c.author_discord_id  = p_actor_discord_id
		  AND t.surface_scope_code = 'public'
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
		  AND web_priv.web_member_template_allowed_for_collection(c.template_id, cat.category_id, sc.subcategory_id, 'public')
	), '[]'::jsonb)
)
FROM web_priv.web_categories cat
JOIN web_priv.web_subcategories sc ON sc.category_id = cat.category_id
CROSS JOIN web_priv.actor_get_access_summary(p_actor_discord_id) actor_summary
WHERE cat.slug = btrim(p_category_slug)
  AND sc.slug  = btrim(p_subcategory_slug)
  AND COALESCE(actor_summary.is_authenticated, false) = true
  AND COALESCE(actor_summary.is_member, false)        = true
  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, cat.category_id, sc.subcategory_id)
  AND web_priv.web_member_collection_has_public_template(cat.category_id, sc.subcategory_id)
LIMIT 1
;
$$;


ALTER FUNCTION web_api.web_member_content_collection_by_path(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_collection_by_path(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_collection_by_path(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) IS 'Returns member-manageable content for one currently authorable public collection path.';


--
-- Name: web_member_content_create(character varying, bigint, text, text, text, bigint, bigint, bigint, integer, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_create(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_status_code text DEFAULT 'draft'::text, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb, p_media_refs jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_create                                                               ////
--//// PURPOSE: Creates public-scope member content with live collection, template, series, and media validation  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_status_code text;
	v_template_schema_version_no integer;
	v_resolved_media_refs jsonb := '[]'::jsonb;
	v_media_ref record;
	v_field_media record;
	v_resolved_media_id bigint;
	v_slug text;
BEGIN
	v_status_code := COALESCE(NULLIF(lower(btrim(p_status_code)), ''), 'draft');

	IF v_status_code NOT IN ('draft', 'published') THEN
		RAISE EXCEPTION 'Member content status % is not allowed during creation.', p_status_code;
	END IF;

	IF NULLIF(btrim(p_title), '') IS NULL THEN
		RAISE EXCEPTION 'Content title is required.';
	END IF;

	IF NULLIF(btrim(p_slug), '') IS NULL THEN
		RAISE EXCEPTION 'Content slug is required.';
	END IF;

	IF jsonb_typeof(COALESCE(p_field_values, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_field_values must be a JSON array.';
	END IF;

	IF jsonb_typeof(COALESCE(p_external_links, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_external_links must be a JSON array.';
	END IF;

	IF jsonb_array_length(COALESCE(p_external_links, '[]'::jsonb)) > 0 THEN
		RAISE EXCEPTION 'Public content external links are not enabled in v1.';
	END IF;

	IF jsonb_typeof(COALESCE(p_media_refs, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_media_refs must be a JSON array.';
	END IF;

	PERFORM web_priv.web_content_assert_category_subcategory(p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_template_allowed(p_template_id, p_category_id, p_subcategory_id, 'public');
	PERFORM web_priv.web_content_assert_series_input(p_template_id, p_series_id, p_series_part_no, p_category_id, p_subcategory_id);
	PERFORM web_priv.web_content_assert_resolved_icon_defaults(p_template_id,
													 'template_default',
													 NULL,
													 'template_default',
													 NULL);

	IF p_series_id IS NOT NULL THEN
		PERFORM 1
		FROM web_priv.web_series s
		WHERE s.series_id = p_series_id
		  AND s.author_discord_id = p_actor_discord_id
		  AND s.category_id = p_category_id
		  AND s.subcategory_id = p_subcategory_id
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, s.write_effective_policy_code, s.write_effective_rank)
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Series % is not manageable by actor % for this collection.', p_series_id, p_actor_discord_id;
		END IF;
	END IF;

	FOR v_field_media IN
		SELECT parsed.value_media_id
		FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(value_media_id bigint)
		WHERE parsed.value_media_id IS NOT NULL
	LOOP
		PERFORM 1
		FROM web_priv.web_media m
		WHERE m.media_id = v_field_media.value_media_id
		  AND m.owner_discord_id = p_actor_discord_id
		  AND m.is_shared = false
		  AND m.category_id = p_category_id
		  AND m.subcategory_id = p_subcategory_id
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Media % is not available for member content in this collection.', v_field_media.value_media_id;
		END IF;
	END LOOP;

	FOR v_media_ref IN
		SELECT parsed.media_id,
			   NULLIF(btrim(parsed.storage_rel_path), '') AS storage_rel_path,
			   NULLIF(btrim(lower(parsed.usage_code)), '') AS usage_code,
			   COALESCE(parsed.display_order, 1) AS display_order,
			   NULLIF(btrim(parsed.caption), '') AS caption
		FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																	 storage_rel_path text,
																	 usage_code text,
																	 display_order integer,
																	 caption text)
	LOOP
		IF v_media_ref.media_id IS NULL AND v_media_ref.storage_rel_path IS NULL THEN
			RAISE EXCEPTION 'Content media reference requires media_id or storage_rel_path.';
		END IF;

		IF v_media_ref.usage_code IS NULL THEN
			RAISE EXCEPTION 'Content media reference usage_code is required.';
		END IF;

		IF v_media_ref.display_order < 1 THEN
			RAISE EXCEPTION 'Content media reference display_order must be positive.';
		END IF;

		SELECT m.media_id
		INTO v_resolved_media_id
		FROM web_priv.web_media m
		WHERE (m.media_id = v_media_ref.media_id
			OR (v_media_ref.media_id IS NULL AND m.storage_rel_path = v_media_ref.storage_rel_path))
		  AND m.owner_discord_id = p_actor_discord_id
		  AND m.is_shared = false
		  AND m.category_id = p_category_id
		  AND m.subcategory_id = p_subcategory_id
		LIMIT 1
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Content media reference is not available for member content in this collection.';
		END IF;

		v_resolved_media_refs := v_resolved_media_refs || jsonb_build_array(jsonb_build_object(
			'media_id', v_resolved_media_id,
			'usage_code', v_media_ref.usage_code,
			'display_order', v_media_ref.display_order,
			'caption', v_media_ref.caption));
	END LOOP;

	v_slug := web_priv.web_content_make_unique_slug(p_slug, p_category_id, p_subcategory_id, NULL);

	SELECT t.schema_version_no
	INTO v_template_schema_version_no
	FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id
	;

	INSERT INTO web_priv.web_content AS c(template_id,
								  template_schema_version_no,
								  title,
								  slug,
								  summary,
								  category_id,
								  subcategory_id,
								  series_id,
								  series_part_no,
								  author_discord_id,
								  status_code,
								  published_dt,
								  archived_dt,
								  read_policy_code,
								  read_rank,
								  read_effective_policy_code,
								  read_effective_rank,
								  write_policy_code,
								  write_rank,
								  write_effective_policy_code,
								  write_effective_rank,
								  nav_hidden_mode_code,
								  nav_hidden,
								  nav_hidden_effective,
								  icon_mode_code,
								  icon_key_id,
								  icon_key_effective_id,
								  icon_color_mode_code,
								  icon_color_id,
								  icon_color_effective_id,
								  created_by_discord_id,
								  updated_by_discord_id)
	VALUES (p_template_id,
			v_template_schema_version_no,
			btrim(p_title),
			v_slug,
			NULLIF(btrim(p_summary), ''),
			p_category_id,
			p_subcategory_id,
			p_series_id,
			p_series_part_no,
			p_actor_discord_id,
			v_status_code,
			CASE WHEN v_status_code = 'published' THEN CURRENT_TIMESTAMP ELSE NULL END,
			NULL,
			'inherit',
			NULL,
			'public',
			NULL,
			'inherit',
			NULL,
			'min_rank',
			100,
			'inherit',
			NULL,
			false,
			'template_default',
			NULL,
			(SELECT t.default_icon_key_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id),
			'template_default',
			NULL,
			(SELECT t.default_icon_color_id FROM web_priv.web_templates t WHERE t.template_id = p_template_id),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING c.content_id
	INTO content_id;

	PERFORM web_priv.web_content_recalculate_effective(content_id);
	PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, p_template_id, p_field_values);
	PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, p_template_id, 'public', '[]'::jsonb);
	PERFORM web_priv.web_content_media_replace(p_actor_discord_id, content_id, v_resolved_media_refs);
	PERFORM web_priv.web_content_record_history(content_id, 'create', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_content_create(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_create(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_create(p_actor_discord_id character varying, p_template_id bigint, p_title text, p_slug text, p_summary text, p_category_id bigint, p_subcategory_id bigint, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb) IS 'Creates public-scope member content with live collection, template, series, and media validation.';


--
-- Name: web_member_content_create_meta(character varying, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_create_meta(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_create_meta                                                          ////
--//// PURPOSE: Returns collection-scoped public authoring metadata for the current member actor                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

WITH collection AS (SELECT c.category_id,
						   c.title AS category_title,
						   c.slug AS category_slug,
						   sc.subcategory_id,
						   sc.title AS subcategory_title,
						   sc.slug AS subcategory_slug
					FROM web_priv.web_categories c
					JOIN web_priv.web_subcategories sc ON sc.category_id = c.category_id
					WHERE c.slug = lower(btrim(p_category_slug))
					  AND sc.slug = lower(btrim(p_subcategory_slug))
					  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, c.category_id, sc.subcategory_id)
					  AND web_priv.web_member_collection_has_public_template(c.category_id, sc.subcategory_id)
					LIMIT 1),
	 valid_template AS (SELECT t.template_id,
							 t.template_code,
							 t.label,
							 t.content_kind_code,
							 ck.label AS content_kind_label,
							 t.surface_scope_code,
							 t.requires_series
					  FROM collection ctx
					  JOIN web_priv.web_templates t ON web_priv.web_member_template_allowed_for_collection(t.template_id,
																		ctx.category_id,
																		ctx.subcategory_id,
																		'public')
					  JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
					  ORDER BY t.label, t.template_id),
	 valid_field AS (SELECT tf.template_field_id,
						  tf.template_id,
						  vt.template_code,
						  vt.label AS template_label,
						  vt.content_kind_code,
						  vt.surface_scope_code,
						  vt.requires_series,
						  fl.field_list_id,
						  fl.field_list_code,
						  COALESCE(NULLIF(btrim(tf.label_override), ''), fl.label) AS label,
						  COALESCE(NULLIF(btrim(tf.help_text_override), ''), fl.help_text) AS help_text,
						  fl.field_type_code,
						  ft.label AS field_type_label,
						  COALESCE(NULLIF(btrim(fl.render_destination_code), ''), 'main') AS render_destination_code,
						  tf.layout_width_code,
						  tf.layout_align_code,
						  tf.show_label_flag,
						  tf.label_style_code,
						  tf.label_position_code,
						  tf.label_separator_code,
						  ft.value_column_name,
						  tf.display_order,
						  tf.is_required,
						  tf.is_enabled,
						  (SELECT COUNT(*)::integer
						   FROM web_priv.web_template_field_options fo
						   WHERE fo.field_list_id = fl.field_list_id
						     AND fo.is_enabled = true) AS option_count
				   FROM valid_template vt
				   JOIN web_priv.web_template_fields tf ON tf.template_id = vt.template_id
				   JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
				   JOIN web_priv.web_template_field_type_c ft ON ft.field_type_code = fl.field_type_code
				   WHERE tf.is_enabled = true
				     AND fl.is_enabled = true
				     AND ft.is_enabled = true)
SELECT CASE WHEN EXISTS (SELECT 1 FROM collection) THEN
	jsonb_build_object(
		'collection', (SELECT jsonb_build_object(
							'categoryId', ctx.category_id::text,
							'categoryTitle', ctx.category_title,
							'categorySlug', ctx.category_slug,
							'subcategoryId', ctx.subcategory_id::text,
							'subcategoryTitle', ctx.subcategory_title,
							'subcategorySlug', ctx.subcategory_slug,
							'label', ctx.category_title || ' / ' || ctx.subcategory_title)
					   FROM collection ctx),
		'templates', COALESCE((SELECT jsonb_agg(jsonb_build_object(
								'id', vt.template_id::text,
								'code', vt.template_code,
								'key', vt.template_code,
								'label', vt.label,
								'contentKindCode', vt.content_kind_code,
								'contentKindLabel', vt.content_kind_label,
								'surfaceScopeCode', vt.surface_scope_code,
								'requiresSeries', vt.requires_series)
							ORDER BY vt.label, vt.template_id)
						FROM valid_template vt), '[]'::jsonb),
		'fields', COALESCE((SELECT jsonb_agg(jsonb_build_object(
							'id', vf.template_field_id::text,
							'templateFieldId', vf.template_field_id,
							'templateId', vf.template_id::text,
							'templateCode', vf.template_code,
							'templateLabel', vf.template_label,
							'contentKindCode', vf.content_kind_code,
							'surfaceScopeCode', vf.surface_scope_code,
							'requiresSeries', vf.requires_series,
							'fieldListId', vf.field_list_id::text,
							'fieldListCode', vf.field_list_code,
							'label', vf.label,
							'helpText', vf.help_text,
							'fieldTypeCode', vf.field_type_code,
							'fieldTypeLabel', vf.field_type_label,
							'renderDestinationCode', vf.render_destination_code,
							'layoutWidthCode', vf.layout_width_code,
							'layoutAlignCode', vf.layout_align_code,
							'showLabel', vf.show_label_flag,
							'labelStyleCode', vf.label_style_code,
							'labelPositionCode', vf.label_position_code,
							'labelSeparatorCode', vf.label_separator_code,
							'valueColumnName', vf.value_column_name,
							'displayOrder', vf.display_order,
							'isRequired', vf.is_required,
							'isEnabled', vf.is_enabled,
							'optionCount', vf.option_count,
							'fieldToolCodes', COALESCE((SELECT jsonb_agg(rel.field_tool_code ORDER BY tool.display_order, rel.field_tool_code)
													 FROM web_priv.web_template_field_list_tools_r rel
													 JOIN web_priv.web_template_field_tools_c tool ON tool.field_tool_code = rel.field_tool_code
													 WHERE rel.field_list_id = vf.field_list_id
													   AND rel.is_enabled = true
													   AND tool.is_enabled = true), '[]'::jsonb))
							ORDER BY vf.template_id, vf.display_order, vf.template_field_id)
					 FROM valid_field vf), '[]'::jsonb),
		'fieldOptions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
							'id', fo.field_option_id::text,
							'fieldListId', fo.field_list_id::text,
							'fieldListCode', fl.field_list_code,
							'optionKey', fo.option_key,
							'label', fo.label,
							'displayOrder', fo.display_order)
							ORDER BY fl.field_list_code, fo.display_order, fo.option_key)
					 FROM web_priv.web_template_field_options fo
					 JOIN web_priv.web_template_field_list fl ON fl.field_list_id = fo.field_list_id
					 WHERE fo.is_enabled = true
					   AND EXISTS (SELECT 1
								   FROM valid_field vf
								   WHERE vf.field_list_id = fo.field_list_id)), '[]'::jsonb),
		'media', COALESCE((SELECT jsonb_agg(jsonb_build_object(
						'id', m.media_id::text,
						'originalFilename', m.original_filename,
						'storageRelPath', m.storage_rel_path,
						'mimeType', m.mime_type,
						'sizeBytes', m.size_bytes,
						'width', m.width_px,
						'height', m.height_px,
						'altText', m.alt_text,
						'categoryId', m.category_id::text,
						'subcategoryId', m.subcategory_id::text)
						ORDER BY m.original_filename, m.media_id)
				 FROM collection ctx
				 JOIN web_priv.web_media m ON m.category_id = ctx.category_id
									   AND m.subcategory_id = ctx.subcategory_id
				 WHERE m.owner_discord_id = p_actor_discord_id
				   AND m.is_shared = false), '[]'::jsonb),
		'series', COALESCE((SELECT jsonb_agg(jsonb_build_object(
						'id', s.series_id::text,
						'title', s.title,
						'slug', s.slug,
						'description', COALESCE(s.description, ''),
						'categoryId', s.category_id::text,
						'subcategoryId', s.subcategory_id::text,
						'nextPartNo', COALESCE((SELECT MAX(c.series_part_no) + 1
												 FROM web_priv.web_content c
												 WHERE c.series_id = s.series_id), 1))
						ORDER BY s.title, s.series_id)
				 FROM collection ctx
				 JOIN web_priv.web_series s ON s.category_id = ctx.category_id
										AND s.subcategory_id = ctx.subcategory_id
				 WHERE s.author_discord_id = p_actor_discord_id
				   AND web_priv.actor_passes_effective_policy(p_actor_discord_id, s.write_effective_policy_code, s.write_effective_rank)), '[]'::jsonb))
	ELSE NULL::jsonb
	END
;
$$;


ALTER FUNCTION web_api.web_member_content_create_meta(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_create_meta(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_create_meta(p_actor_discord_id character varying, p_category_slug text, p_subcategory_slug text) IS 'Returns collection-scoped public authoring metadata for the current member actor.';


--
-- Name: web_member_content_edit_meta(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_edit_meta(p_actor_discord_id character varying, p_content_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_edit_meta                                                            ////
--//// PURPOSE: Returns member-context edit metadata for one currently manageable public-scope content row        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

WITH target AS (SELECT c.content_id,
					   c.template_id,
					   c.title,
					   c.slug,
					   COALESCE(c.summary, '') AS summary,
					   c.status_code,
					   c.series_id,
					   c.series_part_no,
					   c.category_id,
					   c.subcategory_id,
					   cat.title AS category_title,
					   cat.slug AS category_slug,
					   sc.title AS subcategory_title,
					   sc.slug AS subcategory_slug,
					   t.template_code,
					   t.label AS template_label,
					   t.content_kind_code,
					   ck.label AS content_kind_label,
					   ck.renderer_code,
					   c.published_dt,
					   c.archived_dt,
					   c.created_dt,
					   c.updated_dt
				FROM web_priv.web_content c
				JOIN web_priv.web_templates t ON t.template_id = c.template_id
				JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
				JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
				JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
				CROSS JOIN web_priv.actor_get_access_summary(p_actor_discord_id) actor_summary
				WHERE c.content_id = p_content_id
				  AND c.author_discord_id = p_actor_discord_id
				  AND t.surface_scope_code = 'public'
				  AND COALESCE(actor_summary.is_authenticated, false) = true
				  AND COALESCE(actor_summary.is_member, false)        = true
				  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, c.category_id, c.subcategory_id)
				  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
				  AND web_priv.web_member_template_allowed_for_collection(c.template_id, c.category_id, c.subcategory_id, 'public')
				LIMIT 1),
	 valid_template AS (SELECT t.template_id,
						 t.template_code,
						 t.label,
						 t.content_kind_code,
						 ck.label AS content_kind_label,
						 t.surface_scope_code,
						 t.requires_series
				  FROM target ctx
				  JOIN web_priv.web_templates t ON web_priv.web_member_template_allowed_for_collection(t.template_id,
															ctx.category_id,
															ctx.subcategory_id,
															'public')
				  JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
				  ORDER BY t.label, t.template_id),
	 valid_field AS (SELECT tf.template_field_id,
						  tf.template_id,
						  vt.template_code,
						  vt.label AS template_label,
						  vt.content_kind_code,
						  vt.surface_scope_code,
						  vt.requires_series,
						  fl.field_list_id,
						  fl.field_list_code,
						  COALESCE(NULLIF(btrim(tf.label_override), ''), fl.label) AS label,
						  COALESCE(NULLIF(btrim(tf.help_text_override), ''), fl.help_text) AS help_text,
						  fl.field_type_code,
						  ft.label AS field_type_label,
						  COALESCE(NULLIF(btrim(fl.render_destination_code), ''), 'main') AS render_destination_code,
						  tf.layout_width_code,
						  tf.layout_align_code,
						  tf.show_label_flag,
						  tf.label_style_code,
						  tf.label_position_code,
						  tf.label_separator_code,
						  ft.value_column_name,
						  tf.display_order,
						  tf.is_required,
						  tf.is_enabled,
						  (SELECT COUNT(*)::integer
						   FROM web_priv.web_template_field_options fo
						   WHERE fo.field_list_id = fl.field_list_id
						     AND fo.is_enabled = true) AS option_count
				   FROM valid_template vt
				   JOIN web_priv.web_template_fields tf ON tf.template_id = vt.template_id
				   JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
				   JOIN web_priv.web_template_field_type_c ft ON ft.field_type_code = fl.field_type_code
				   WHERE tf.is_enabled = true
				     AND fl.is_enabled = true
				     AND ft.is_enabled = true),
	 field_values AS (SELECT v.template_field_id::text AS template_field_key,
						   CASE ft.value_column_name
						   WHEN 'value_text' THEN to_jsonb(v.value_text)
						   WHEN 'value_long_text' THEN to_jsonb(v.value_long_text)
						   WHEN 'value_integer' THEN to_jsonb(v.value_integer)
						   WHEN 'value_numeric' THEN to_jsonb(v.value_numeric)
						   WHEN 'value_boolean' THEN to_jsonb(v.value_boolean)
						   WHEN 'value_date' THEN to_jsonb(v.value_date)
						   WHEN 'value_timestamp' THEN to_jsonb(v.value_timestamp)
						   WHEN 'value_discord_id' THEN to_jsonb(v.value_discord_id)
						   WHEN 'value_media_id' THEN to_jsonb(v.value_media_id::text)
						   WHEN 'value_content_id' THEN to_jsonb(v.value_content_id::text)
						   WHEN 'value_option_key' THEN to_jsonb(v.value_option_key)
						   WHEN 'value_rich_text_json' THEN v.value_rich_text_json
						   ELSE 'null'::jsonb
						   END AS field_value
					FROM target ctx
					JOIN web_priv.web_content_field_values v ON v.content_id = ctx.content_id
					JOIN web_priv.web_template_fields tf ON tf.template_field_id = v.template_field_id
					JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
					JOIN web_priv.web_template_field_type_c ft ON ft.field_type_code = fl.field_type_code
					WHERE v.value_seq_no = 1)
SELECT CASE WHEN EXISTS (SELECT 1 FROM target) THEN
	jsonb_build_object(
		'collection', (SELECT jsonb_build_object(
							'categoryId', ctx.category_id::text,
							'categoryTitle', ctx.category_title,
							'categorySlug', ctx.category_slug,
							'subcategoryId', ctx.subcategory_id::text,
							'subcategoryTitle', ctx.subcategory_title,
							'subcategorySlug', ctx.subcategory_slug,
							'label', ctx.category_title || ' / ' || ctx.subcategory_title)
					   FROM target ctx),
		'doc', (SELECT jsonb_build_object(
					'id', ctx.content_id::text,
					'title', ctx.title,
					'slug', ctx.slug,
					'summary', ctx.summary,
					'statusCode', ctx.status_code,
					'templateId', ctx.template_id::text,
					'templateCode', ctx.template_code,
					'templateLabel', ctx.template_label,
					'contentKindCode', ctx.content_kind_code,
					'contentKindLabel', ctx.content_kind_label,
					'rendererCode', ctx.renderer_code,
					'categoryId', ctx.category_id::text,
					'categoryTitle', ctx.category_title,
					'categorySlug', ctx.category_slug,
					'subcategoryId', ctx.subcategory_id::text,
					'subcategoryTitle', ctx.subcategory_title,
					'subcategorySlug', ctx.subcategory_slug,
					'seriesId', CASE WHEN ctx.series_id IS NULL THEN NULL ELSE ctx.series_id::text END,
					'seriesPartNo', ctx.series_part_no,
					'publicHref', NULL,
					'canViewPublic', ctx.status_code = 'published',
					'publishedAt', ctx.published_dt,
					'archivedAt', ctx.archived_dt,
					'createdAt', ctx.created_dt,
					'updatedAt', ctx.updated_dt,
					'fieldValues', COALESCE((SELECT jsonb_object_agg(fv.template_field_key, fv.field_value)
											   FROM field_values fv), '{}'::jsonb))
				FROM target ctx),
		'templates', COALESCE((SELECT jsonb_agg(jsonb_build_object(
								'id', vt.template_id::text,
								'code', vt.template_code,
								'key', vt.template_code,
								'label', vt.label,
								'contentKindCode', vt.content_kind_code,
								'contentKindLabel', vt.content_kind_label,
								'surfaceScopeCode', vt.surface_scope_code,
								'requiresSeries', vt.requires_series)
							ORDER BY vt.label, vt.template_id)
						 FROM valid_template vt), '[]'::jsonb),
		'fields', COALESCE((SELECT jsonb_agg(jsonb_build_object(
						'id', vf.template_field_id::text,
						'templateFieldId', vf.template_field_id,
						'templateId', vf.template_id::text,
						'templateCode', vf.template_code,
						'templateLabel', vf.template_label,
						'contentKindCode', vf.content_kind_code,
						'surfaceScopeCode', vf.surface_scope_code,
						'requiresSeries', vf.requires_series,
						'fieldListId', vf.field_list_id::text,
						'fieldListCode', vf.field_list_code,
						'label', vf.label,
						'helpText', vf.help_text,
						'fieldTypeCode', vf.field_type_code,
						'fieldTypeLabel', vf.field_type_label,
						'renderDestinationCode', vf.render_destination_code,
						'layoutWidthCode', vf.layout_width_code,
						'layoutAlignCode', vf.layout_align_code,
						'showLabel', vf.show_label_flag,
						'labelStyleCode', vf.label_style_code,
						'labelPositionCode', vf.label_position_code,
						'labelSeparatorCode', vf.label_separator_code,
						'valueColumnName', vf.value_column_name,
						'displayOrder', vf.display_order,
						'isRequired', vf.is_required,
						'isEnabled', vf.is_enabled,
						'optionCount', vf.option_count,
						'fieldToolCodes', COALESCE((SELECT jsonb_agg(rel.field_tool_code ORDER BY tool.display_order, rel.field_tool_code)
												 FROM web_priv.web_template_field_list_tools_r rel
												 JOIN web_priv.web_template_field_tools_c tool ON tool.field_tool_code = rel.field_tool_code
												 WHERE rel.field_list_id = vf.field_list_id
												   AND rel.is_enabled = true
												   AND tool.is_enabled = true), '[]'::jsonb))
						ORDER BY vf.template_id, vf.display_order, vf.template_field_id)
				 FROM valid_field vf), '[]'::jsonb),
		'fieldOptions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
						'id', fo.field_option_id::text,
						'fieldListId', fo.field_list_id::text,
						'fieldListCode', fl.field_list_code,
						'optionKey', fo.option_key,
						'label', fo.label,
						'displayOrder', fo.display_order)
						ORDER BY fl.field_list_code, fo.display_order, fo.option_key)
				 FROM web_priv.web_template_field_options fo
				 JOIN web_priv.web_template_field_list fl ON fl.field_list_id = fo.field_list_id
				 WHERE fo.is_enabled = true
				   AND EXISTS (SELECT 1
							   FROM valid_field vf
							   WHERE vf.field_list_id = fo.field_list_id)), '[]'::jsonb),
		'media', COALESCE((SELECT jsonb_agg(jsonb_build_object(
					'id', m.media_id::text,
					'originalFilename', m.original_filename,
					'storageRelPath', m.storage_rel_path,
					'mimeType', m.mime_type,
					'sizeBytes', m.size_bytes,
					'width', m.width_px,
					'height', m.height_px,
					'altText', m.alt_text,
					'categoryId', m.category_id::text,
					'subcategoryId', m.subcategory_id::text)
					ORDER BY m.original_filename, m.media_id)
				 FROM target ctx
				 JOIN web_priv.web_media m ON m.category_id = ctx.category_id
									   AND m.subcategory_id = ctx.subcategory_id
				 WHERE m.owner_discord_id = p_actor_discord_id
				   AND m.is_shared = false), '[]'::jsonb),
		'series', COALESCE((SELECT jsonb_agg(jsonb_build_object(
					'id', s.series_id::text,
					'title', s.title,
					'slug', s.slug,
					'description', COALESCE(s.description, ''),
					'categoryId', s.category_id::text,
					'subcategoryId', s.subcategory_id::text,
					'nextPartNo', COALESCE((SELECT MAX(c.series_part_no) + 1
											 FROM web_priv.web_content c
											 WHERE c.series_id = s.series_id), 1))
					ORDER BY s.title, s.series_id)
				 FROM target ctx
				 JOIN web_priv.web_series s ON s.category_id = ctx.category_id
									AND s.subcategory_id = ctx.subcategory_id
				 WHERE s.author_discord_id = p_actor_discord_id
				   AND web_priv.actor_passes_effective_policy(p_actor_discord_id, s.write_effective_policy_code, s.write_effective_rank)), '[]'::jsonb))
	ELSE NULL::jsonb
	END
;
$$;


ALTER FUNCTION web_api.web_member_content_edit_meta(p_actor_discord_id character varying, p_content_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_edit_meta(p_actor_discord_id character varying, p_content_id bigint); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_edit_meta(p_actor_discord_id character varying, p_content_id bigint) IS 'Returns member-context edit metadata for one currently manageable public-scope content row.';


--
-- Name: web_member_content_list(character varying); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_list(p_actor_discord_id character varying) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_list                                                                 ////
--//// PURPOSE: Lists actor-owned public-scope content still manageable through live member authoring rules      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT COALESCE(jsonb_agg(jsonb_build_object(
					'id', c.content_id::text,
					'title', c.title,
					'slug', c.slug,
					'summary', COALESCE(c.summary, ''),
					'statusCode', c.status_code,
					'templateId', t.template_id::text,
					'templateCode', t.template_code,
					'templateLabel', t.label,
					'contentKindCode', t.content_kind_code,
					'contentKindLabel', ck.label,
					'rendererCode', ck.renderer_code,
					'categoryId', cat.category_id::text,
					'categoryTitle', cat.title,
					'categorySlug', cat.slug,
					'subcategoryId', sc.subcategory_id::text,
					'subcategoryTitle', sc.title,
					'subcategorySlug', sc.slug,
					'seriesId', CASE WHEN s.series_id IS NULL THEN NULL ELSE s.series_id::text END,
					'seriesTitle', s.title,
					'seriesPartNo', c.series_part_no,
					'publicHref', CASE WHEN NULLIF(btrim(COALESCE(ck.public_route_prefix, '')), '') IS NULL
								   THEN '/' || cat.slug || '/' || sc.slug || '/' || c.slug
								   ELSE '/' || btrim(ck.public_route_prefix) || '/' || cat.slug || '/' || sc.slug || '/' || c.slug
								   END,
					'canViewPublic', c.status_code = 'published'
							 AND ck.renderer_code = ANY (ARRAY['page'::text,
												 'map'::text,
												 'tool'::text,
												 'app'::text,
												 'event'::text,
												 'custom'::text,
												 'youtube'::text,
												 'stream'::text,
												 'calendar'::text])
							 AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank),
					'publishedAt', c.published_dt,
					'archivedAt', c.archived_dt,
					'createdAt', c.created_dt,
					'updatedAt', c.updated_dt)
				ORDER BY c.updated_dt DESC, c.content_id DESC), '[]'::jsonb)
FROM web_priv.web_content c
JOIN web_priv.web_templates t ON t.template_id = c.template_id
JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
LEFT JOIN web_priv.web_series s ON s.series_id = c.series_id
CROSS JOIN web_priv.actor_get_access_summary(p_actor_discord_id) actor_summary
WHERE COALESCE(actor_summary.is_authenticated, false) = true
  AND COALESCE(actor_summary.is_member, false)        = true
  AND c.author_discord_id                             = p_actor_discord_id
  AND t.surface_scope_code                            = 'public'
  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, c.category_id, c.subcategory_id)
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
  AND web_priv.web_member_template_allowed_for_collection(c.template_id, c.category_id, c.subcategory_id, 'public')
;
$$;


ALTER FUNCTION web_api.web_member_content_list(p_actor_discord_id character varying) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_list(p_actor_discord_id character varying); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_list(p_actor_discord_id character varying) IS 'Lists actor-owned public-scope content still manageable through live member authoring rules.';


--
-- Name: web_member_content_update(character varying, bigint, text, text, text, bigint, integer, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_content_update(p_actor_discord_id character varying, p_content_id bigint, p_title text, p_slug text, p_summary text, p_series_id bigint DEFAULT NULL::bigint, p_series_part_no integer DEFAULT NULL::integer, p_status_code text DEFAULT 'draft'::text, p_field_values jsonb DEFAULT '[]'::jsonb, p_external_links jsonb DEFAULT '[]'::jsonb, p_media_refs jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(content_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_content_update                                                               ////
--//// PURPOSE: Updates member-owned public-scope content through member-context validation and history           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_status_code text;
	v_existing_status_code text;
	v_existing_published_dt timestamp with time zone;
	v_existing_archived_dt timestamp with time zone;
	v_template_id bigint;
	v_category_id bigint;
	v_subcategory_id bigint;
	v_old_public_path text;
	v_new_public_path text;
	v_published_dt timestamp with time zone;
	v_archived_dt timestamp with time zone;
	v_resolved_media_refs jsonb := '[]'::jsonb;
	v_media_ref record;
	v_field_media record;
	v_resolved_media_id bigint;
	v_slug text;
BEGIN
	v_status_code := COALESCE(NULLIF(lower(btrim(p_status_code)), ''), 'draft');

	IF v_status_code NOT IN ('draft', 'published', 'archived') THEN
		RAISE EXCEPTION 'Member content status % is not allowed during edit.', p_status_code;
	END IF;

	IF NULLIF(btrim(p_title), '') IS NULL THEN
		RAISE EXCEPTION 'Content title is required.';
	END IF;

	IF NULLIF(btrim(p_slug), '') IS NULL THEN
		RAISE EXCEPTION 'Content slug is required.';
	END IF;

	IF jsonb_typeof(COALESCE(p_field_values, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_field_values must be a JSON array.';
	END IF;

	IF jsonb_typeof(COALESCE(p_external_links, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_external_links must be a JSON array.';
	END IF;

	IF jsonb_array_length(COALESCE(p_external_links, '[]'::jsonb)) > 0 THEN
		RAISE EXCEPTION 'Public content external links are not enabled in v1.';
	END IF;

	IF jsonb_typeof(COALESCE(p_media_refs, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_media_refs must be a JSON array.';
	END IF;

	SELECT c.status_code,
		   c.published_dt,
		   c.archived_dt,
		   c.template_id,
		   c.category_id,
		   c.subcategory_id
	INTO v_existing_status_code,
		 v_existing_published_dt,
		 v_existing_archived_dt,
		 v_template_id,
		 v_category_id,
		 v_subcategory_id
	FROM web_priv.web_content c
	JOIN web_priv.web_templates t ON t.template_id = c.template_id
	WHERE c.content_id = p_content_id
	  AND c.author_discord_id = p_actor_discord_id
	  AND t.surface_scope_code = 'public'
	  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Content % is not available for member editing.', p_content_id;
	END IF;

	v_old_public_path := web_priv.web_content_current_public_path(p_content_id);

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', v_category_id, v_subcategory_id);
	PERFORM web_priv.web_content_assert_template_allowed(v_template_id, v_category_id, v_subcategory_id, 'public');
	PERFORM web_priv.web_content_assert_series_input(v_template_id, p_series_id, p_series_part_no, v_category_id, v_subcategory_id);

	IF p_series_id IS NOT NULL THEN
		PERFORM 1
		FROM web_priv.web_series s
		WHERE s.series_id = p_series_id
		  AND s.author_discord_id = p_actor_discord_id
		  AND s.category_id = v_category_id
		  AND s.subcategory_id = v_subcategory_id
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, s.write_effective_policy_code, s.write_effective_rank)
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Series % is not manageable by actor % for this collection.', p_series_id, p_actor_discord_id;
		END IF;
	END IF;

	FOR v_field_media IN
		SELECT parsed.value_media_id
		FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(value_media_id bigint)
		WHERE parsed.value_media_id IS NOT NULL
	LOOP
		PERFORM 1
		FROM web_priv.web_media m
		WHERE m.media_id = v_field_media.value_media_id
		  AND m.owner_discord_id = p_actor_discord_id
		  AND m.is_shared = false
		  AND m.category_id = v_category_id
		  AND m.subcategory_id = v_subcategory_id
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Media % is not available for member content in this collection.', v_field_media.value_media_id;
		END IF;
	END LOOP;

	FOR v_media_ref IN
		SELECT parsed.media_id,
			   NULLIF(btrim(parsed.storage_rel_path), '') AS storage_rel_path,
			   NULLIF(btrim(lower(parsed.usage_code)), '') AS usage_code,
			   COALESCE(parsed.display_order, 1) AS display_order,
			   NULLIF(btrim(parsed.caption), '') AS caption
		FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
															 storage_rel_path text,
															 usage_code text,
															 display_order integer,
															 caption text)
	LOOP
		IF v_media_ref.media_id IS NULL AND v_media_ref.storage_rel_path IS NULL THEN
			RAISE EXCEPTION 'Content media reference requires media_id or storage_rel_path.';
		END IF;

		IF v_media_ref.usage_code IS NULL THEN
			RAISE EXCEPTION 'Content media reference usage_code is required.';
		END IF;

		IF v_media_ref.display_order < 1 THEN
			RAISE EXCEPTION 'Content media reference display_order must be positive.';
		END IF;

		SELECT m.media_id
		INTO v_resolved_media_id
		FROM web_priv.web_media m
		WHERE (m.media_id = v_media_ref.media_id
			OR (v_media_ref.media_id IS NULL AND m.storage_rel_path = v_media_ref.storage_rel_path))
		  AND m.owner_discord_id = p_actor_discord_id
		  AND m.is_shared = false
		  AND m.category_id = v_category_id
		  AND m.subcategory_id = v_subcategory_id
		LIMIT 1
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Content media reference is not available for member content in this collection.';
		END IF;

		v_resolved_media_refs := v_resolved_media_refs || jsonb_build_array(jsonb_build_object(
			'media_id', v_resolved_media_id,
			'usage_code', v_media_ref.usage_code,
			'display_order', v_media_ref.display_order,
			'caption', v_media_ref.caption));
	END LOOP;

	v_published_dt := CASE WHEN v_status_code = 'published'
						  THEN COALESCE(CASE WHEN v_existing_status_code = 'published' THEN v_existing_published_dt ELSE NULL END,
									CURRENT_TIMESTAMP)
						  ELSE NULL
						  END;

	v_archived_dt := CASE WHEN v_status_code = 'archived'
						 THEN COALESCE(CASE WHEN v_existing_status_code = 'archived' THEN v_existing_archived_dt ELSE NULL END,
								   CURRENT_TIMESTAMP)
						 ELSE NULL
						 END;

	v_slug := web_priv.web_content_make_unique_slug(p_slug, v_category_id, v_subcategory_id, p_content_id);

	UPDATE web_priv.web_content c
	SET title = btrim(p_title),
		slug = v_slug,
		summary = NULLIF(btrim(p_summary), ''),
		series_id = p_series_id,
		series_part_no = p_series_part_no,
		status_code = v_status_code,
		published_dt = v_published_dt,
		archived_dt = v_archived_dt,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE c.content_id = p_content_id
	RETURNING c.content_id
	INTO content_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Content % was not found.', p_content_id;
	END IF;

	PERFORM web_priv.web_content_recalculate_effective(content_id);

	v_new_public_path := web_priv.web_content_current_public_path(content_id);
	PERFORM web_priv.web_content_redirect_ensure_for_path_change(
		p_actor_discord_id,
		content_id,
		v_old_public_path,
		v_new_public_path
	);

	PERFORM web_priv.web_content_replace_field_values(p_actor_discord_id, content_id, v_template_id, p_field_values);
	PERFORM web_priv.web_content_replace_external_links(p_actor_discord_id, content_id, v_template_id, 'public', '[]'::jsonb);
	PERFORM web_priv.web_content_media_replace(p_actor_discord_id, content_id, v_resolved_media_refs);
	PERFORM web_priv.web_content_record_history(content_id, 'update', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_content_update(p_actor_discord_id character varying, p_content_id bigint, p_title text, p_slug text, p_summary text, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb) OWNER TO cm;

--
-- Name: FUNCTION web_member_content_update(p_actor_discord_id character varying, p_content_id bigint, p_title text, p_slug text, p_summary text, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_content_update(p_actor_discord_id character varying, p_content_id bigint, p_title text, p_slug text, p_summary text, p_series_id bigint, p_series_part_no integer, p_status_code text, p_field_values jsonb, p_external_links jsonb, p_media_refs jsonb) IS 'Updates member-owned public-scope content through member-context validation and history.';


--
-- Name: web_member_media_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_media_delete(p_actor_discord_id character varying, p_media_id bigint) RETURNS TABLE(media_id bigint, storage_rel_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_media_delete                                                                 ////
--//// PURPOSE: Deletes actor-owned member media after live permission and dependency validation                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing web_priv.web_media%ROWTYPE;
BEGIN
	SELECT m.*
	INTO v_existing
	FROM web_priv.web_media m
	WHERE m.media_id = p_media_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Media % was not found.', p_media_id;
	END IF;

	IF v_existing.is_shared = true OR v_existing.owner_discord_id IS DISTINCT FROM p_actor_discord_id THEN
		RAISE EXCEPTION 'Actor % does not own media %.', p_actor_discord_id, p_media_id;
	END IF;

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', v_existing.category_id, v_existing.subcategory_id);
	PERFORM web_priv.web_media_assert_can_delete(p_media_id);
	PERFORM web_priv.web_media_record_history(v_existing.media_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_media m
	WHERE m.media_id = p_media_id;

	media_id := v_existing.media_id;
	storage_rel_path := v_existing.storage_rel_path;
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_media_delete(p_actor_discord_id character varying, p_media_id bigint) OWNER TO cm;

--
-- Name: web_member_media_insert_uploaded(character varying, bigint, bigint, text, text, text, text, bigint, integer, integer, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_media_insert_uploaded(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint, p_filename text, p_original_filename text, p_storage_rel_path text, p_mime_type text, p_size_bytes bigint, p_width_px integer, p_height_px integer, p_alt_text text, p_credit_text text) RETURNS TABLE(media_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_media_insert_uploaded                                                        ////
--//// PURPOSE: Persists actor-owned member image metadata after the app writes the uploaded file                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_inserted web_priv.web_media%ROWTYPE;
	v_mime_type text;
BEGIN
	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', p_category_id, p_subcategory_id);
	PERFORM web_priv.web_media_assert_valid_category_subcategory(p_category_id, p_subcategory_id);

	v_mime_type := NULLIF(btrim(lower(COALESCE(p_mime_type, ''))), '');
	IF v_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/gif') THEN
		RAISE EXCEPTION 'Unsupported member media MIME type: %.', COALESCE(v_mime_type, 'unknown');
	END IF;

	IF NULLIF(btrim(p_alt_text), '') IS NULL THEN
		RAISE EXCEPTION 'Alt text is required for member image uploads.';
	END IF;

	INSERT INTO web_priv.web_media(category_id,
								subcategory_id,
								owner_discord_id,
								is_shared,
								storage_rel_path,
								filename,
								original_filename,
								mime_type,
								size_bytes,
								width_px,
								height_px,
								alt_text,
								credit_text,
								created_by_discord_id,
								updated_by_discord_id)
	VALUES (p_category_id,
			p_subcategory_id,
			p_actor_discord_id,
			false,
			NULLIF(btrim(p_storage_rel_path), ''),
			NULLIF(btrim(p_filename), ''),
			NULLIF(btrim(p_original_filename), ''),
			v_mime_type,
			COALESCE(p_size_bytes, 0),
			p_width_px,
			p_height_px,
			NULLIF(btrim(p_alt_text), ''),
			NULLIF(btrim(p_credit_text), ''),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING *
	INTO v_inserted;

	PERFORM web_priv.web_media_record_history(v_inserted.media_id, 'create', p_actor_discord_id);
	media_id := v_inserted.media_id;
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_media_insert_uploaded(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint, p_filename text, p_original_filename text, p_storage_rel_path text, p_mime_type text, p_size_bytes bigint, p_width_px integer, p_height_px integer, p_alt_text text, p_credit_text text) OWNER TO cm;

--
-- Name: web_member_media_list(character varying); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_media_list(p_actor_discord_id character varying) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_media_list                                                                   ////
--//// PURPOSE: Lists actor-owned media that the actor may still manage through member authoring rights           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT COALESCE(jsonb_agg(jsonb_build_object(
					'id', m.media_id::text,
					'categoryId', c.category_id::text,
					'categoryTitle', c.title,
					'categorySlug', c.slug,
					'subcategoryId', sc.subcategory_id::text,
					'subcategoryTitle', sc.title,
					'subcategorySlug', sc.slug,
					'filename', m.filename,
					'originalFilename', m.original_filename,
					'storageRelPath', m.storage_rel_path,
					'mimeType', m.mime_type,
					'sizeBytes', m.size_bytes,
					'width', m.width_px,
					'height', m.height_px,
					'alt', COALESCE(m.alt_text, ''),
					'credit', COALESCE(m.credit_text, ''),
					'createdAt', m.created_dt,
					'updatedAt', m.updated_dt)
				ORDER BY m.updated_dt DESC, m.media_id DESC), '[]'::jsonb)
FROM web_priv.web_media m
JOIN web_priv.web_categories c ON c.category_id = m.category_id
JOIN web_priv.web_subcategories sc ON sc.subcategory_id = m.subcategory_id
WHERE m.owner_discord_id = p_actor_discord_id
  AND m.is_shared = false
  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, m.category_id, m.subcategory_id)
;
$$;


ALTER FUNCTION web_api.web_member_media_list(p_actor_discord_id character varying) OWNER TO cm;

--
-- Name: web_member_media_update_meta(character varying, bigint, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_media_update_meta(p_actor_discord_id character varying, p_media_id bigint, p_alt_text text, p_credit_text text) RETURNS TABLE(media_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_media_update_meta                                                            ////
--//// PURPOSE: Updates actor-owned member media metadata after live permission validation                       ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing web_priv.web_media%ROWTYPE;
BEGIN
	SELECT m.*
	INTO v_existing
	FROM web_priv.web_media m
	WHERE m.media_id = p_media_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Media % was not found.', p_media_id;
	END IF;

	IF v_existing.is_shared = true OR v_existing.owner_discord_id IS DISTINCT FROM p_actor_discord_id THEN
		RAISE EXCEPTION 'Actor % does not own media %.', p_actor_discord_id, p_media_id;
	END IF;

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', v_existing.category_id, v_existing.subcategory_id);

	IF NULLIF(btrim(p_alt_text), '') IS NULL THEN
		RAISE EXCEPTION 'Alt text is required for member image media.';
	END IF;

	UPDATE web_priv.web_media m
	SET alt_text = NULLIF(btrim(p_alt_text), ''),
		credit_text = NULLIF(btrim(p_credit_text), ''),
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE m.media_id = p_media_id
	RETURNING m.media_id
	INTO media_id;

	PERFORM web_priv.web_media_record_history(media_id, 'update', p_actor_discord_id);
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_media_update_meta(p_actor_discord_id character varying, p_media_id bigint, p_alt_text text, p_credit_text text) OWNER TO cm;

--
-- Name: web_member_profile_upsert_self(character varying, text, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_profile_upsert_self(p_actor_discord_id character varying, p_game_username text, p_alias text, p_theme_style_code text, p_notes text) RETURNS TABLE(member_profile_id bigint, auth_user_id bigint, theme_style_code text, theme_style_label text, theme_style_class text, game_username text, alias text, notes text, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_profile_upsert_self                                                          ////
--//// PURPOSE: Upserts member-editable profile fields and selected CSS theme style for current actor             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE v_auth_user_id bigint;
DECLARE v_theme_style_code text;
BEGIN
	SELECT du.auth_user_id
	INTO v_auth_user_id
	FROM web_priv.discord_users du
	JOIN web_priv.auth_users au ON au.auth_user_id = du.auth_user_id
	WHERE du.discord_id = p_actor_discord_id
	  AND au.is_disabled = false
	LIMIT 1
	;

	IF v_auth_user_id IS NULL THEN
		RAISE EXCEPTION 'Signed-in actor profile was not found.';
	END IF;

	v_theme_style_code := lower(NULLIF(btrim(p_theme_style_code), ''));

	IF v_theme_style_code IS NULL THEN
		v_theme_style_code := 'vintage';
	END IF;

	IF v_theme_style_code NOT IN ('dark', 'light', 'vintage') THEN
		RAISE EXCEPTION 'Selected theme style must be dark, light, or vintage.';
	END IF;

	INSERT INTO web_priv.web_member_profiles(auth_user_id,
										  theme_style_code,
										  game_username,
										  alias,
										  notes,
										  created_by_discord_id,
										  created_dt,
										  updated_by_discord_id,
										  updated_dt)
	VALUES (v_auth_user_id,
			v_theme_style_code,
			NULLIF(btrim(p_game_username), ''),
			NULLIF(btrim(p_alias), ''),
			NULLIF(btrim(p_notes), ''),
			p_actor_discord_id,
			now(),
			p_actor_discord_id,
			now())
	ON CONFLICT ON CONSTRAINT web_member_profiles_auth_user_id_uq DO UPDATE
	SET theme_style_code     = EXCLUDED.theme_style_code,
		game_username         = EXCLUDED.game_username,
		alias                 = EXCLUDED.alias,
		notes                 = EXCLUDED.notes,
		updated_by_discord_id = EXCLUDED.updated_by_discord_id,
		updated_dt            = now()
	;

	RETURN QUERY
	SELECT mp.member_profile_id,
		   mp.auth_user_id,
		   mp.theme_style_code,
		   mp.theme_style_label,
		   mp.theme_style_class,
		   mp.game_username,
		   mp.alias,
		   mp.notes,
		   mp.created_dt,
		   mp.updated_dt
	FROM web_view.web_member_profiles mp
	WHERE mp.auth_user_id = v_auth_user_id
	LIMIT 1
	;
END;
$$;


ALTER FUNCTION web_api.web_member_profile_upsert_self(p_actor_discord_id character varying, p_game_username text, p_alias text, p_theme_style_code text, p_notes text) OWNER TO cm;

--
-- Name: FUNCTION web_member_profile_upsert_self(p_actor_discord_id character varying, p_game_username text, p_alias text, p_theme_style_code text, p_notes text); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_member_profile_upsert_self(p_actor_discord_id character varying, p_game_username text, p_alias text, p_theme_style_code text, p_notes text) IS 'Upserts member-editable profile fields and selected CSS theme style for the current actor after resolving the actor through discord_users.';


--
-- Name: web_member_series_create(character varying, text, text, bigint, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_series_create(p_actor_discord_id character varying, p_title text, p_description text, p_category_id bigint, p_subcategory_id bigint) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_series_create                                                               ////
--//// PURPOSE: Creates an actor-owned member series in a currently authorable collection                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_title text;
	v_slug text;
	v_icon_key_id bigint;
	v_icon_color_id bigint;
BEGIN
	v_title := NULLIF(btrim(p_title), '');
	IF v_title IS NULL THEN
		RAISE EXCEPTION 'Series title is required.';
	END IF;

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', p_category_id, p_subcategory_id);

	SELECT COALESCE(sc.icon_key_id, c.icon_key_id),
		   COALESCE(sc.icon_color_id, c.icon_color_id)
	INTO v_icon_key_id,
		 v_icon_color_id
	FROM web_priv.web_categories c
	JOIN web_priv.web_subcategories sc ON sc.category_id = c.category_id
	WHERE c.category_id = p_category_id
	  AND sc.subcategory_id = p_subcategory_id;

	IF v_icon_key_id IS NULL OR v_icon_color_id IS NULL THEN
		RAISE EXCEPTION 'Could not resolve series icon defaults for category % and subcategory %.', p_category_id, p_subcategory_id;
	END IF;

	v_slug := web_priv.web_member_next_series_slug(v_title);

	INSERT INTO web_priv.web_series(title,
								 slug,
								 description,
								 category_id,
								 subcategory_id,
								 author_discord_id,
								 read_policy_code,
								 read_rank,
								 read_effective_policy_code,
								 read_effective_rank,
								 write_policy_code,
								 write_rank,
								 write_effective_policy_code,
								 write_effective_rank,
								 icon_key_id,
								 icon_color_id,
								 created_by_discord_id,
								 updated_by_discord_id)
	VALUES (v_title,
			v_slug,
			NULLIF(btrim(p_description), ''),
			p_category_id,
			p_subcategory_id,
			p_actor_discord_id,
			'inherit',
			NULL,
			'public',
			NULL,
			'inherit',
			NULL,
			'min_rank',
			100,
			v_icon_key_id,
			v_icon_color_id,
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING web_series.series_id
	INTO series_id;

	PERFORM web_priv.web_series_recalculate_effective(series_id);
	PERFORM web_priv.web_series_record_history(series_id, 'create', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_series_create(p_actor_discord_id character varying, p_title text, p_description text, p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_member_series_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_series_delete(p_actor_discord_id character varying, p_series_id bigint) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_series_delete                                                               ////
--//// PURPOSE: Deletes an actor-owned member series after live permission and dependency validation             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing web_priv.web_series%ROWTYPE;
BEGIN
	SELECT s.*
	INTO v_existing
	FROM web_priv.web_series s
	WHERE s.series_id = p_series_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Series % was not found.', p_series_id;
	END IF;

	IF v_existing.author_discord_id IS DISTINCT FROM p_actor_discord_id THEN
		RAISE EXCEPTION 'Actor % does not own series %.', p_actor_discord_id, p_series_id;
	END IF;

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', v_existing.category_id, v_existing.subcategory_id);
	PERFORM web_priv.web_series_assert_can_delete(p_series_id);
	PERFORM web_priv.web_series_record_history(p_series_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_series s
	WHERE s.series_id = p_series_id;

	series_id := p_series_id;
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_series_delete(p_actor_discord_id character varying, p_series_id bigint) OWNER TO cm;

--
-- Name: web_member_series_delete_dependencies(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_series_delete_dependencies(p_actor_discord_id character varying, p_series_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_series_delete_dependencies                                                    ////
--//// PURPOSE: Lists member-visible content rows that block deleting an actor-owned series                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT CASE WHEN EXISTS (SELECT 1
						 FROM web_priv.web_series s
						 WHERE s.series_id = p_series_id
						   AND s.author_discord_id = p_actor_discord_id
						   AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, s.category_id, s.subcategory_id))
			THEN COALESCE((SELECT jsonb_agg(jsonb_build_object(
								'contentId', wc.content_id::text,
								'title', wc.title,
								'statusCode', wc.status_code,
								'categoryTitle', c.title,
								'subcategoryTitle', COALESCE(sc.title, ''),
								'publicHref', CASE WHEN NULLIF(btrim(COALESCE(ck.public_route_prefix, '')), '') IS NULL
													  THEN '/' || c.slug || '/' || COALESCE(sc.slug, '') || '/' || wc.slug
													  ELSE '/' || ck.public_route_prefix || '/' || c.slug || '/' || COALESCE(sc.slug, '') || '/' || wc.slug
													  END)
							  ORDER BY wc.updated_dt DESC, wc.content_id DESC)
					   FROM web_priv.web_content wc
					   JOIN web_priv.web_categories c ON c.category_id = wc.category_id
					   LEFT JOIN web_priv.web_subcategories sc ON sc.subcategory_id = wc.subcategory_id
					   JOIN web_priv.web_templates t ON t.template_id = wc.template_id
					   JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
					   WHERE wc.series_id = p_series_id), '[]'::jsonb)
			ELSE '[]'::jsonb
			END
;
$$;


ALTER FUNCTION web_api.web_member_series_delete_dependencies(p_actor_discord_id character varying, p_series_id bigint) OWNER TO cm;

--
-- Name: web_member_series_list(character varying); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_series_list(p_actor_discord_id character varying) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_series_list                                                                  ////
--//// PURPOSE: Lists actor-owned series that the actor may still manage through member authoring rights          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT COALESCE(jsonb_agg(jsonb_build_object(
					'id', s.series_id::text,
					'title', s.title,
					'slug', s.slug,
					'description', COALESCE(s.description, ''),
					'categoryId', c.category_id::text,
					'categoryTitle', c.title,
					'categorySlug', c.slug,
					'subcategoryId', sc.subcategory_id::text,
					'subcategoryTitle', sc.title,
					'subcategorySlug', sc.slug,
					'createdAt', s.created_dt,
					'updatedAt', s.updated_dt)
				ORDER BY s.updated_dt DESC, s.series_id DESC), '[]'::jsonb)
FROM web_priv.web_series s
JOIN web_priv.web_categories c ON c.category_id = s.category_id
JOIN web_priv.web_subcategories sc ON sc.subcategory_id = s.subcategory_id
WHERE s.author_discord_id = p_actor_discord_id
  AND web_priv.web_member_actor_can_author_collection(p_actor_discord_id, s.category_id, s.subcategory_id)
;
$$;


ALTER FUNCTION web_api.web_member_series_list(p_actor_discord_id character varying) OWNER TO cm;

--
-- Name: web_member_series_update(character varying, bigint, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_member_series_update(p_actor_discord_id character varying, p_series_id bigint, p_title text, p_description text) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_member_series_update                                                               ////
--//// PURPOSE: Updates title and description for an actor-owned manageable member series                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing record;
	v_title text;
BEGIN
	v_title := NULLIF(btrim(p_title), '');
	IF v_title IS NULL THEN
		RAISE EXCEPTION 'Series title is required.';
	END IF;

	SELECT s.series_id,
		   s.category_id,
		   s.subcategory_id,
		   s.author_discord_id
	INTO v_existing
	FROM web_priv.web_series s
	WHERE s.series_id = p_series_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Series % was not found.', p_series_id;
	END IF;

	IF v_existing.author_discord_id IS DISTINCT FROM p_actor_discord_id THEN
		RAISE EXCEPTION 'Actor % does not own series %.', p_actor_discord_id, p_series_id;
	END IF;

	PERFORM web_priv.web_content_assert_actor_can_author(p_actor_discord_id, 'public', v_existing.category_id, v_existing.subcategory_id);

	UPDATE web_priv.web_series s
	SET title = v_title,
		description = NULLIF(btrim(p_description), ''),
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE s.series_id = p_series_id
	RETURNING s.series_id
	INTO series_id;

	PERFORM web_priv.web_series_record_history(series_id, 'update', p_actor_discord_id);

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_member_series_update(p_actor_discord_id character varying, p_series_id bigint, p_title text, p_description text) OWNER TO cm;

--
-- Name: web_navigation_admin_get(text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_navigation_admin_get(p_panel_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RETURNS A FULL ADMIN NAVIGATION TREE FOR ONE PANEL                                                          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'panel', jsonb_build_object(
		'id', p.navigation_panel_id::text,
		'panelKey', p.panel_key,
		'label', p.label,
		'panelTypeCode', p.panel_type_code,
		'panelSlotCode', p.panel_slot_code,
		'isDefault', p.is_default,
		'selectionOrder', p.selection_order,
		'readPolicyCode', p.read_policy_code,
		'readRank', p.read_rank,
		'maxCategories', p.max_categories,
		'maxSubcategoriesPerCategory', p.max_subcategories_per_category,
		'maxTargetsPerSubcategory', p.max_targets_per_subcategory,
		'enabled', p.is_enabled
	),
	'items', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
			'id', pc.navigation_panel_category_id::text,
			'categoryId', pc.category_id::text,
			'title', c.title,
			'slug', c.slug,
			'isEnabled', pc.is_enabled,
			'isSelectable', c.nav_hidden = false,
			'subcategories', COALESCE((
				SELECT jsonb_agg(jsonb_build_object(
					'id', ps.navigation_panel_subcategory_id::text,
					'subcategoryId', ps.subcategory_id::text,
					'title', s.title,
					'slug', s.slug,
					'isEnabled', ps.is_enabled,
					'isSelectable', s.nav_hidden_effective = false,
					'content', COALESCE((
						SELECT jsonb_agg(jsonb_build_object(
							'id', pt.navigation_panel_target_id::text,
							'contentId', pt.content_id::text,
							'title', ct.title,
							'slug', ct.slug,
							'summary', ct.summary,
							'statusCode', ct.status_code,
							'isEnabled', pt.is_enabled,
							'isSelectable', ct.nav_hidden_effective = false,
							'contentKindCode', t.content_kind_code,
							'contentKindLabel', ck.label,
							'publicRoutePrefix', ck.public_route_prefix,
							'rendererCode', ck.renderer_code
						) ORDER BY pt.display_order, pt.navigation_panel_target_id)
						FROM web_priv.web_navigation_panel_targets pt
						JOIN web_priv.web_content ct ON ct.content_id = pt.content_id
						JOIN web_priv.web_templates t ON t.template_id = ct.template_id
						JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
						WHERE pt.navigation_panel_subcategory_id = ps.navigation_panel_subcategory_id
					), '[]'::jsonb)
				) ORDER BY ps.display_order, ps.navigation_panel_subcategory_id)
				FROM web_priv.web_navigation_panel_subcategories ps
				JOIN web_priv.web_subcategories s ON s.subcategory_id = ps.subcategory_id
				WHERE ps.navigation_panel_category_id = pc.navigation_panel_category_id
			), '[]'::jsonb)
		) ORDER BY pc.display_order, pc.navigation_panel_category_id)
		FROM web_priv.web_navigation_panel_categories pc
		JOIN web_priv.web_categories c ON c.category_id = pc.category_id
		WHERE pc.navigation_panel_id = p.navigation_panel_id
	), '[]'::jsonb)
)
FROM web_priv.web_navigation_panels p
WHERE p.panel_key = NULLIF(BTRIM(LOWER(p_panel_key)), '')
LIMIT 1;
$$;


ALTER FUNCTION web_api.web_navigation_admin_get(p_panel_key text) OWNER TO cm;

--
-- Name: web_navigation_admin_replace_panel(character varying, text, jsonb); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_navigation_admin_replace_panel(p_actor_discord_id character varying, p_panel_key text, p_items jsonb) RETURNS TABLE(navigation_panel_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// REPLACES THE FULL NAVIGATION TREE FOR ONE PANEL                                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_navigation_panel_id bigint;
	v_category jsonb;
	v_subcategory jsonb;
	v_target jsonb;
	v_category_id bigint;
	v_subcategory_id bigint;
	v_content_id bigint;
	v_category_count integer;
	v_subcategory_count integer;
	v_target_count integer;
	v_panel_category_id bigint;
	v_panel_subcategory_id bigint;
	v_category_order integer := 0;
	v_subcategory_order integer;
	v_target_order integer;
	v_max_categories integer;
	v_max_subcategories integer;
	v_max_targets integer;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT p.navigation_panel_id,
		   p.max_categories,
		   p.max_subcategories_per_category,
		   p.max_targets_per_subcategory
	INTO v_navigation_panel_id,
		 v_max_categories,
		 v_max_subcategories,
		 v_max_targets
	FROM web_priv.web_navigation_panels p
	WHERE p.panel_key = NULLIF(BTRIM(LOWER(p_panel_key)), '');

	IF v_navigation_panel_id IS NULL THEN
		RAISE EXCEPTION 'Navigation panel % was not found.', p_panel_key;
	END IF;

	IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
		RAISE EXCEPTION 'Navigation panel items must be a JSON array.';
	END IF;

	v_category_count := jsonb_array_length(p_items);
	IF v_max_categories IS NOT NULL AND v_category_count > v_max_categories THEN
		RAISE EXCEPTION 'Navigation panel allows at most % categories.', v_max_categories;
	END IF;

	FOR v_category IN SELECT value FROM jsonb_array_elements(p_items) LOOP
		v_category_id := NULLIF(v_category ->> 'categoryId', '')::bigint;

		IF v_category_id IS NULL THEN
			RAISE EXCEPTION 'Navigation category id is required.';
		END IF;

		IF NOT EXISTS (SELECT 1
					   FROM web_priv.web_categories c
					   WHERE c.category_id = v_category_id
					     AND c.nav_hidden = false)
		   AND NOT EXISTS (SELECT 1
					   FROM web_priv.web_navigation_panel_categories pc
					   WHERE pc.navigation_panel_id = v_navigation_panel_id
					     AND pc.category_id = v_category_id) THEN
			RAISE EXCEPTION 'Category % is not selectable for navigation.', v_category_id;
		END IF;

		v_subcategory_count := jsonb_array_length(COALESCE(v_category -> 'subcategories', '[]'::jsonb));
		IF v_max_subcategories IS NOT NULL AND v_subcategory_count > v_max_subcategories THEN
			RAISE EXCEPTION 'Navigation category % allows at most % subcategories.', v_category_id, v_max_subcategories;
		END IF;

		FOR v_subcategory IN SELECT value FROM jsonb_array_elements(COALESCE(v_category -> 'subcategories', '[]'::jsonb)) LOOP
			v_subcategory_id := NULLIF(v_subcategory ->> 'subcategoryId', '')::bigint;

			IF v_subcategory_id IS NULL THEN
				RAISE EXCEPTION 'Navigation subcategory id is required.';
			END IF;

			IF NOT EXISTS (SELECT 1
						   FROM web_priv.web_subcategories s
						   WHERE s.category_id = v_category_id
						     AND s.subcategory_id = v_subcategory_id
						     AND s.nav_hidden_effective = false)
			   AND NOT EXISTS (SELECT 1
						   FROM web_priv.web_navigation_panel_subcategories ps
						   JOIN web_priv.web_navigation_panel_categories pc ON pc.navigation_panel_category_id = ps.navigation_panel_category_id
						   WHERE pc.navigation_panel_id = v_navigation_panel_id
						     AND ps.category_id = v_category_id
						     AND ps.subcategory_id = v_subcategory_id) THEN
				RAISE EXCEPTION 'Subcategory % is not selectable for category % navigation.', v_subcategory_id, v_category_id;
			END IF;

			v_target_count := jsonb_array_length(COALESCE(v_subcategory -> 'content', '[]'::jsonb));
			IF v_max_targets IS NOT NULL AND v_target_count > v_max_targets THEN
				RAISE EXCEPTION 'Navigation subcategory % allows at most % content targets.', v_subcategory_id, v_max_targets;
			END IF;

			FOR v_target IN SELECT value FROM jsonb_array_elements(COALESCE(v_subcategory -> 'content', '[]'::jsonb)) LOOP
				v_content_id := NULLIF(v_target ->> 'contentId', '')::bigint;

				IF v_content_id IS NULL THEN
					RAISE EXCEPTION 'Navigation content id is required.';
				END IF;

				IF NOT EXISTS (SELECT 1
							   FROM web_priv.web_content c
							   WHERE c.content_id = v_content_id
							     AND c.category_id = v_category_id
							     AND c.subcategory_id = v_subcategory_id
							     AND c.nav_hidden_effective = false)
				   AND NOT EXISTS (SELECT 1
							   FROM web_priv.web_navigation_panel_targets pt
							   JOIN web_priv.web_navigation_panel_subcategories ps ON ps.navigation_panel_subcategory_id = pt.navigation_panel_subcategory_id
							   JOIN web_priv.web_navigation_panel_categories pc ON pc.navigation_panel_category_id = ps.navigation_panel_category_id
							   WHERE pc.navigation_panel_id = v_navigation_panel_id
							     AND pt.category_id = v_category_id
							     AND pt.subcategory_id = v_subcategory_id
							     AND pt.content_id = v_content_id) THEN
					RAISE EXCEPTION 'Content % is not selectable for navigation under category % and subcategory %.', v_content_id, v_category_id, v_subcategory_id;
				END IF;
			END LOOP;
		END LOOP;
	END LOOP;

	DELETE FROM web_priv.web_navigation_panel_categories pc
	WHERE pc.navigation_panel_id = v_navigation_panel_id;

	FOR v_category IN SELECT value FROM jsonb_array_elements(p_items) LOOP
		v_category_order := v_category_order + 1;
		v_category_id := NULLIF(v_category ->> 'categoryId', '')::bigint;

		INSERT INTO web_priv.web_navigation_panel_categories(navigation_panel_id,
													category_id,
													display_order,
													is_enabled,
													created_by_discord_id,
													updated_by_discord_id)
		VALUES (v_navigation_panel_id,
				v_category_id,
				v_category_order,
				COALESCE((v_category ->> 'isEnabled')::boolean, true),
				p_actor_discord_id,
				p_actor_discord_id)
		RETURNING navigation_panel_category_id
		INTO v_panel_category_id;

		v_subcategory_order := 0;
		FOR v_subcategory IN SELECT value FROM jsonb_array_elements(COALESCE(v_category -> 'subcategories', '[]'::jsonb)) LOOP
			v_subcategory_order := v_subcategory_order + 1;
			v_subcategory_id := NULLIF(v_subcategory ->> 'subcategoryId', '')::bigint;

			INSERT INTO web_priv.web_navigation_panel_subcategories(navigation_panel_category_id,
															 category_id,
															 subcategory_id,
															 display_order,
															 is_enabled,
															 created_by_discord_id,
															 updated_by_discord_id)
			VALUES (v_panel_category_id,
					v_category_id,
					v_subcategory_id,
					v_subcategory_order,
					COALESCE((v_subcategory ->> 'isEnabled')::boolean, true),
					p_actor_discord_id,
					p_actor_discord_id)
			RETURNING navigation_panel_subcategory_id
			INTO v_panel_subcategory_id;

			v_target_order := 0;
			FOR v_target IN SELECT value FROM jsonb_array_elements(COALESCE(v_subcategory -> 'content', '[]'::jsonb)) LOOP
				v_target_order := v_target_order + 1;
				v_content_id := NULLIF(v_target ->> 'contentId', '')::bigint;

				INSERT INTO web_priv.web_navigation_panel_targets(navigation_panel_subcategory_id,
																category_id,
																subcategory_id,
																content_id,
																display_order,
																is_enabled,
																created_by_discord_id,
																updated_by_discord_id)
				VALUES (v_panel_subcategory_id,
						v_category_id,
						v_subcategory_id,
						v_content_id,
						v_target_order,
						COALESCE((v_target ->> 'isEnabled')::boolean, true),
						p_actor_discord_id,
						p_actor_discord_id);
			END LOOP;
		END LOOP;
	END LOOP;

	UPDATE web_priv.web_navigation_panels p
	SET updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE p.navigation_panel_id = v_navigation_panel_id;

	PERFORM web_priv.web_navigation_panel_record_history(v_navigation_panel_id, 'update', p_actor_discord_id);

	RETURN QUERY SELECT v_navigation_panel_id;
END;
$$;


ALTER FUNCTION web_api.web_navigation_admin_replace_panel(p_actor_discord_id character varying, p_panel_key text, p_items jsonb) OWNER TO cm;

--
-- Name: web_navigation_panel_delete_admin(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_navigation_panel_delete_admin(p_actor_discord_id character varying, p_panel_key text) RETURNS TABLE(navigation_panel_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A NAVIGATION PANEL DEFINITION                                                                       ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_navigation_panel_id bigint;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT p.navigation_panel_id
	INTO v_navigation_panel_id
	FROM web_priv.web_navigation_panels p
	WHERE p.panel_key = NULLIF(BTRIM(LOWER(p_panel_key)), '');

	IF v_navigation_panel_id IS NULL THEN
		RAISE EXCEPTION 'Navigation panel % was not found.', p_panel_key;
	END IF;

	PERFORM web_priv.web_navigation_panel_record_history(v_navigation_panel_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_navigation_panels p
	WHERE p.navigation_panel_id = v_navigation_panel_id;

	RETURN QUERY SELECT v_navigation_panel_id;
END;
$$;


ALTER FUNCTION web_api.web_navigation_panel_delete_admin(p_actor_discord_id character varying, p_panel_key text) OWNER TO cm;

--
-- Name: web_navigation_panel_save_admin(character varying, text, text, text, text, boolean, integer, text, integer, integer, integer, integer, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_navigation_panel_save_admin(p_actor_discord_id character varying, p_panel_key text, p_label text, p_panel_type_code text, p_panel_slot_code text, p_is_default boolean, p_selection_order integer, p_read_policy_code text, p_read_rank integer, p_max_categories integer, p_max_subcategories_per_category integer, p_max_targets_per_subcategory integer, p_is_enabled boolean) RETURNS TABLE(navigation_panel_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_navigation_panel_save_admin                                                          ////
--//// PURPOSE: Creates or updates a navigation panel definition                                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE v_panel_key text;
DECLARE v_label text;
DECLARE v_panel_type_code text;
DECLARE v_panel_slot_code text;
DECLARE v_read_policy_code text;
DECLARE v_read_rank integer;
DECLARE v_navigation_panel_id bigint;
DECLARE v_is_default boolean;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_panel_key := NULLIF(BTRIM(LOWER(p_panel_key)), '');
	v_label := NULLIF(BTRIM(p_label), '');
	v_panel_type_code := COALESCE(NULLIF(BTRIM(LOWER(p_panel_type_code)), ''), 'header');
	v_panel_slot_code := COALESCE(NULLIF(BTRIM(LOWER(p_panel_slot_code)), ''), v_panel_key);
	v_read_policy_code := COALESCE(NULLIF(BTRIM(LOWER(p_read_policy_code)), ''), 'public');
	v_read_rank := p_read_rank;
	v_is_default := COALESCE(p_is_default, false);

	IF v_is_default THEN
		v_read_policy_code := 'public';
		v_read_rank := NULL;
	END IF;

	IF v_panel_key IS NULL THEN
		RAISE EXCEPTION 'web_navigation_panels.panel_key is required.';
	END IF;

	IF v_panel_key !~ '^[a-z0-9._-]{1,96}$' THEN
		RAISE EXCEPTION 'web_navigation_panels.panel_key must match ^[a-z0-9._-]{1,96}$.';
	END IF;

	IF v_label IS NULL THEN
		RAISE EXCEPTION 'web_navigation_panels.label is required.';
	END IF;

	IF v_read_policy_code = 'public' AND v_read_rank IS NOT NULL THEN
		RAISE EXCEPTION 'Public navigation panel policy cannot have read_rank.';
	END IF;

	IF v_read_policy_code <> 'public' AND v_read_rank IS NULL THEN
		RAISE EXCEPTION 'Rank navigation panel policies require read_rank.';
	END IF;

	IF v_is_default THEN
		UPDATE web_priv.web_navigation_panels p
		SET is_default = false,
			updated_by_discord_id = p_actor_discord_id,
			updated_dt = CURRENT_TIMESTAMP
		WHERE p.panel_slot_code = v_panel_slot_code
		  AND p.panel_key <> v_panel_key
		  AND p.is_default = true;
	END IF;

	INSERT INTO web_priv.web_navigation_panels(panel_key,
											label,
											panel_type_code,
											panel_slot_code,
											is_default,
											selection_order,
											read_policy_code,
											read_rank,
											max_categories,
											max_subcategories_per_category,
											max_targets_per_subcategory,
											is_enabled,
											created_by_discord_id,
											updated_by_discord_id)
	VALUES (v_panel_key,
			v_label,
			v_panel_type_code,
			v_panel_slot_code,
			v_is_default,
			COALESCE(p_selection_order, 100),
			v_read_policy_code,
			v_read_rank,
			p_max_categories,
			p_max_subcategories_per_category,
			p_max_targets_per_subcategory,
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id)
	ON CONFLICT (panel_key) DO UPDATE
	SET label = EXCLUDED.label,
		panel_type_code = EXCLUDED.panel_type_code,
		panel_slot_code = EXCLUDED.panel_slot_code,
		is_default = EXCLUDED.is_default,
		selection_order = EXCLUDED.selection_order,
		read_policy_code = EXCLUDED.read_policy_code,
		read_rank = EXCLUDED.read_rank,
		max_categories = EXCLUDED.max_categories,
		max_subcategories_per_category = EXCLUDED.max_subcategories_per_category,
		max_targets_per_subcategory = EXCLUDED.max_targets_per_subcategory,
		is_enabled = EXCLUDED.is_enabled,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	RETURNING web_navigation_panels.navigation_panel_id
	INTO v_navigation_panel_id;

	PERFORM web_priv.web_navigation_panel_record_history(v_navigation_panel_id, 'update', p_actor_discord_id);

	RETURN QUERY SELECT v_navigation_panel_id;
END;
$_$;


ALTER FUNCTION web_api.web_navigation_panel_save_admin(p_actor_discord_id character varying, p_panel_key text, p_label text, p_panel_type_code text, p_panel_slot_code text, p_is_default boolean, p_selection_order integer, p_read_policy_code text, p_read_rank integer, p_max_categories integer, p_max_subcategories_per_category integer, p_max_targets_per_subcategory integer, p_is_enabled boolean) OWNER TO cm;

--
-- Name: web_navigation_public_get(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_navigation_public_get(p_actor_discord_id character varying, p_panel_slot_code text DEFAULT 'header_main'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_navigation_public_get                                                               ////
--//// PURPOSE: Returns the best public navigation panel for an actor and slot                                    ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE v_panel_slot_code text;
DECLARE v_selected_panel_id bigint;
DECLARE v_default_panel_id bigint;
DECLARE v_result jsonb;
BEGIN
	v_panel_slot_code := COALESCE(NULLIF(BTRIM(LOWER(p_panel_slot_code)), ''), 'header_main');

	SELECT p.navigation_panel_id
	INTO v_default_panel_id
	FROM web_priv.web_navigation_panels p
	WHERE p.panel_slot_code = v_panel_slot_code
	  AND p.is_default = true
	  AND p.is_enabled = true
	  AND p.read_policy_code = 'public'
	  AND p.read_rank IS NULL
	  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, p.read_policy_code, p.read_rank)
	ORDER BY p.selection_order ASC,
			 p.navigation_panel_id ASC
	LIMIT 1;

	SELECT p.navigation_panel_id
	INTO v_selected_panel_id
	FROM web_priv.web_navigation_panels p
	WHERE p.panel_slot_code = v_panel_slot_code
	  AND p.is_default = false
	  AND p.is_enabled = true
	  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, p.read_policy_code, p.read_rank)
	ORDER BY p.selection_order ASC,
			 p.navigation_panel_id ASC
	LIMIT 1;

	v_selected_panel_id := COALESCE(v_selected_panel_id, v_default_panel_id);

	IF v_selected_panel_id IS NULL THEN
		RETURN jsonb_build_object('items', '[]'::jsonb);
	END IF;

	v_result := web_priv.web_navigation_public_build_panel_json(v_selected_panel_id, p_actor_discord_id);

	IF jsonb_array_length(COALESCE(v_result -> 'items', '[]'::jsonb)) = 0
	   AND v_default_panel_id IS NOT NULL
	   AND v_default_panel_id <> v_selected_panel_id THEN
		v_result := web_priv.web_navigation_public_build_panel_json(v_default_panel_id, p_actor_discord_id);
	END IF;

	RETURN v_result;
END;
$$;


ALTER FUNCTION web_api.web_navigation_public_get(p_actor_discord_id character varying, p_panel_slot_code text) OWNER TO cm;

--
-- Name: web_series_create(character varying, text, text, text, bigint, bigint, text, integer, text, integer, bigint, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_series_create(p_actor_discord_id character varying, p_title text, p_slug text, p_description text, p_category_id bigint, p_subcategory_id bigint, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_icon_key_id bigint, p_icon_color_id bigint) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);

    INSERT INTO web_priv.web_series (
        title, slug, description, category_id, subcategory_id, author_discord_id,
        read_policy_code, read_rank, read_effective_policy_code, read_effective_rank,
        write_policy_code, write_rank, write_effective_policy_code, write_effective_rank,
        icon_key_id, icon_color_id, created_by_discord_id, updated_by_discord_id
    ) VALUES (
        btrim(p_title), btrim(p_slug), NULLIF(btrim(p_description), ''), p_category_id, p_subcategory_id, p_actor_discord_id,
        p_read_policy_code, p_read_rank,
        CASE WHEN p_read_policy_code = 'inherit' THEN 'public' ELSE p_read_policy_code END,
        CASE WHEN p_read_policy_code IN ('inherit', 'public') THEN NULL ELSE p_read_rank END,
        p_write_policy_code, p_write_rank,
        CASE WHEN p_write_policy_code = 'inherit' THEN 'min_rank' ELSE p_write_policy_code END,
        COALESCE(p_write_rank, 100),
        p_icon_key_id, p_icon_color_id, p_actor_discord_id, p_actor_discord_id
    ) RETURNING web_series.series_id INTO series_id;

    PERFORM web_priv.web_series_recalculate_effective(series_id);
    PERFORM web_priv.web_series_record_history(series_id, 'create', p_actor_discord_id);
    RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_series_create(p_actor_discord_id character varying, p_title text, p_slug text, p_description text, p_category_id bigint, p_subcategory_id bigint, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_icon_key_id bigint, p_icon_color_id bigint) OWNER TO cm;

--
-- Name: web_series_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_series_delete(p_actor_discord_id character varying, p_series_id bigint) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A SERIES ROW THROUGH THE DB-FIRST ADMIN API AFTER DEPENDENCY VALIDATION                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);

    PERFORM 1
      FROM web_priv.web_series AS s
     WHERE s.series_id = p_series_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Series % was not found.', p_series_id;
    END IF;

    PERFORM web_priv.web_series_assert_can_delete(p_series_id);
    PERFORM web_priv.web_series_record_history(p_series_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_series
     WHERE web_series.series_id = p_series_id;

    series_id := p_series_id;

    RETURN NEXT;
END;
$$;


