--
-- Name: web_series_public_find_by_slug(character varying, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_series_public_find_by_slug(p_actor_discord_id character varying, p_series_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_series_public_find_by_slug                                                        ////
--//// PURPOSE: Resolves one readable public series and its readable published episode list                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'series', jsonb_build_object(
		'id', s.series_id::text,
		'title', s.title,
		'slug', s.slug,
		'description', s.description,
		'categoryId', cat.category_id::text,
		'categoryTitle', cat.title,
		'categorySlug', cat.slug,
		'subcategoryId', CASE WHEN sc.subcategory_id IS NULL THEN NULL ELSE sc.subcategory_id::text END,
		'subcategoryTitle', sc.title,
		'subcategorySlug', sc.slug,
		'href', '/series/' || s.slug,
		'iconKey', CASE WHEN series_icon.icon_id IS NULL THEN NULL
			ELSE jsonb_build_object(
				'key', series_icon.key,
				'label', series_icon.label,
				'source', series_icon.source_code,
				'lucideName', series_icon.lucide_name,
				'iconMedia', CASE WHEN series_icon_media.media_id IS NULL THEN NULL
					ELSE jsonb_build_object(
						'id', series_icon_media.media_id::text,
						'filename', series_icon_media.filename,
						'originalFilename', series_icon_media.original_filename,
						'mimeType', series_icon_media.mime_type,
						'storageRelPath', series_icon_media.storage_rel_path
					)
					END
			)
			END,
		'iconColor', CASE WHEN series_icon_color.theme_color_id IS NULL THEN NULL
			ELSE jsonb_build_object('preview', series_icon_color.preview)
			END
	),
	'episodes', COALESCE((
		SELECT jsonb_agg(jsonb_build_object(
			'id', content.content_id::text,
			'title', content.title,
			'slug', content.slug,
			'summary', content.summary,
			'partNo', content.series_part_no,
			'templateId', template.template_id::text,
			'templateLabel', template.label,
			'contentKindCode', template.content_kind_code,
			'contentKindLabel', kind.label,
			'rendererCode', kind.renderer_code,
			'publicRoutePrefix', kind.public_route_prefix,
			'categoryId', content_cat.category_id::text,
			'categoryTitle', content_cat.title,
			'categorySlug', content_cat.slug,
			'subcategoryId', content_sc.subcategory_id::text,
			'subcategoryTitle', content_sc.title,
			'subcategorySlug', content_sc.slug,
			'href', CASE WHEN kind.public_route_prefix IS NULL
				THEN '/' || content_cat.slug || '/' || content_sc.slug || '/' || content.slug
				ELSE '/' || kind.public_route_prefix || '/' || content_cat.slug || '/' || content_sc.slug || '/' || content.slug
				END,
			'publishedAt', content.published_dt,
			'updatedAt', content.updated_dt,
			'iconKey', CASE WHEN content_icon.icon_id IS NULL THEN NULL
				ELSE jsonb_build_object(
					'key', content_icon.key,
					'label', content_icon.label,
					'source', content_icon.source_code,
					'lucideName', content_icon.lucide_name,
					'iconMedia', CASE WHEN content_icon_media.media_id IS NULL THEN NULL
						ELSE jsonb_build_object(
							'id', content_icon_media.media_id::text,
							'filename', content_icon_media.filename,
							'originalFilename', content_icon_media.original_filename,
							'mimeType', content_icon_media.mime_type,
							'storageRelPath', content_icon_media.storage_rel_path
						)
						END
				)
				END,
			'iconColor', CASE WHEN content_icon_color.theme_color_id IS NULL THEN NULL
				ELSE jsonb_build_object('preview', content_icon_color.preview)
				END
		) ORDER BY content.series_part_no ASC NULLS LAST,
				 content.published_dt ASC NULLS LAST,
				 content.content_id ASC)
		FROM web_priv.web_content content
		JOIN web_priv.web_templates template ON template.template_id = content.template_id
		JOIN web_priv.web_content_kind_c kind ON kind.content_kind_code = template.content_kind_code
		JOIN web_priv.web_categories content_cat ON content_cat.category_id = content.category_id
		JOIN web_priv.web_subcategories content_sc ON content_sc.subcategory_id = content.subcategory_id
		LEFT JOIN web_priv.web_icons content_icon ON content_icon.icon_id = content.icon_key_effective_id
		LEFT JOIN web_priv.web_media content_icon_media ON content_icon_media.media_id = content_icon.media_id
		LEFT JOIN web_priv.web_theme_colors content_icon_color ON content_icon_color.theme_color_id = content.icon_color_effective_id
		WHERE content.series_id      = s.series_id
		  AND content.status_code    = 'published'
		  AND kind.renderer_code     = ANY (ARRAY['page'::text,
												'map'::text,
												'tool'::text,
												'app'::text,
												'event'::text,
												'custom'::text,
												'youtube'::text,
												'stream'::text,
												'calendar'::text])
		  AND web_priv.actor_passes_effective_policy(p_actor_discord_id,
												content.read_effective_policy_code,
												content.read_effective_rank)
	), '[]'::jsonb)
)
FROM web_priv.web_series s
JOIN web_priv.web_categories cat ON cat.category_id = s.category_id
LEFT JOIN web_priv.web_subcategories sc ON sc.category_id    = s.category_id
									   AND sc.subcategory_id = s.subcategory_id
LEFT JOIN web_priv.web_icons series_icon ON series_icon.icon_id = s.icon_key_id
LEFT JOIN web_priv.web_media series_icon_media ON series_icon_media.media_id = series_icon.media_id
LEFT JOIN web_priv.web_theme_colors series_icon_color ON series_icon_color.theme_color_id = s.icon_color_id
WHERE s.slug = btrim(p_series_slug)
  AND web_priv.actor_passes_effective_policy(p_actor_discord_id,
											 s.read_effective_policy_code,
											 s.read_effective_rank)
LIMIT 1
;
$$;


ALTER FUNCTION web_api.web_series_public_find_by_slug(p_actor_discord_id character varying, p_series_slug text) OWNER TO cm;

--
-- Name: web_series_update(character varying, bigint, text, text, text, bigint, bigint, text, integer, text, integer, bigint, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_series_update(p_actor_discord_id character varying, p_series_id bigint, p_title text, p_slug text, p_description text, p_category_id bigint, p_subcategory_id bigint, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_icon_key_id bigint, p_icon_color_id bigint) RETURNS TABLE(series_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);

    UPDATE web_priv.web_series
       SET title = btrim(p_title),
           slug = btrim(p_slug),
           description = NULLIF(btrim(p_description), ''),
           category_id = p_category_id,
           subcategory_id = p_subcategory_id,
           read_policy_code = p_read_policy_code,
           read_rank = p_read_rank,
           write_policy_code = p_write_policy_code,
           write_rank = p_write_rank,
           icon_key_id = p_icon_key_id,
           icon_color_id = p_icon_color_id,
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE web_series.series_id = p_series_id;

    PERFORM web_priv.web_series_recalculate_effective(p_series_id);
    PERFORM web_priv.web_series_record_history(p_series_id, 'update', p_actor_discord_id);
    series_id := p_series_id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_series_update(p_actor_discord_id character varying, p_series_id bigint, p_title text, p_slug text, p_description text, p_category_id bigint, p_subcategory_id bigint, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_icon_key_id bigint, p_icon_color_id bigint) OWNER TO cm;

--
-- Name: web_subcategory_create(character varying, bigint, text, text, text, integer, text, integer, text, boolean, bigint, bigint, bigint[]); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_subcategory_create(p_actor_discord_id character varying, p_category_id bigint, p_title text, p_slug text, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_key_id bigint, p_icon_color_id bigint, p_template_ids bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE(subcategory_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    INSERT INTO web_priv.web_subcategories (
        category_id, title, slug,
        read_policy_code, read_rank, read_effective_policy_code, read_effective_rank,
        write_policy_code, write_rank, write_effective_policy_code, write_effective_rank,
        nav_hidden_mode_code, nav_hidden, nav_hidden_effective,
        icon_key_id, icon_color_id, created_by_discord_id, updated_by_discord_id
    ) VALUES (
        p_category_id, btrim(p_title), btrim(p_slug),
        p_read_policy_code, p_read_rank,
        CASE WHEN p_read_policy_code = 'inherit' THEN 'public' ELSE p_read_policy_code END,
        CASE WHEN p_read_policy_code IN ('inherit', 'public') THEN NULL ELSE p_read_rank END,
        p_write_policy_code, p_write_rank,
        CASE WHEN p_write_policy_code = 'inherit' THEN 'min_rank' ELSE p_write_policy_code END,
        COALESCE(p_write_rank, 100),
        p_nav_hidden_mode_code, p_nav_hidden, false,
        p_icon_key_id, p_icon_color_id, p_actor_discord_id, p_actor_discord_id
    ) RETURNING web_subcategories.subcategory_id INTO subcategory_id;

    PERFORM web_priv.web_subcategory_recalculate_effective(subcategory_id);
    PERFORM web_priv.web_subcategory_record_history(subcategory_id, 'create', p_actor_discord_id);
    PERFORM web_priv.web_subcategory_template_replace(p_actor_discord_id, p_category_id, subcategory_id, p_template_ids);
END;
$$;


ALTER FUNCTION web_api.web_subcategory_create(p_actor_discord_id character varying, p_category_id bigint, p_title text, p_slug text, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_key_id bigint, p_icon_color_id bigint, p_template_ids bigint[]) OWNER TO cm;

--
-- Name: web_subcategory_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_subcategory_delete(p_actor_discord_id character varying, p_subcategory_id bigint) RETURNS TABLE(subcategory_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A SUBCATEGORY ROW THROUGH THE ADMIN DATABASE API                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    PERFORM 1
      FROM web_priv.web_subcategories AS s
     WHERE s.subcategory_id = p_subcategory_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Subcategory % was not found.', p_subcategory_id;
    END IF;

    PERFORM web_priv.web_subcategory_assert_can_delete(p_subcategory_id);
    PERFORM web_priv.web_subcategory_record_history(p_subcategory_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_subcategories AS s
     WHERE s.subcategory_id = p_subcategory_id;

    subcategory_id := p_subcategory_id;
END;
$$;


