--
-- Name: web_subcategory_toggle_nav_hidden(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_subcategory_toggle_nav_hidden(p_actor_discord_id character varying, p_subcategory_id bigint) RETURNS TABLE(subcategory_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// TOGGLES SUBCATEGORY NAV HIDDEN STATE THROUGH THE DB-FIRST ADMIN API                                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    UPDATE web_priv.web_subcategories
       SET nav_hidden_mode_code = 'explicit',
           nav_hidden = NOT COALESCE(web_subcategories.nav_hidden, false),
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE web_subcategories.subcategory_id = p_subcategory_id
     RETURNING web_subcategories.subcategory_id INTO subcategory_id;

    IF subcategory_id IS NULL THEN
        RAISE EXCEPTION 'Subcategory not found.';
    END IF;

    PERFORM web_priv.web_subcategory_recalculate_effective(p_subcategory_id);
    PERFORM web_priv.web_subcategory_record_history(p_subcategory_id, 'update', p_actor_discord_id);
END;
$$;


