--
-- Name: web_subcategory_update(character varying, bigint, bigint, text, text, text, integer, text, integer, text, boolean, bigint, bigint, bigint[]); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_subcategory_update(p_actor_discord_id character varying, p_subcategory_id bigint, p_category_id bigint, p_title text, p_slug text, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_key_id bigint, p_icon_color_id bigint, p_template_ids bigint[] DEFAULT NULL::bigint[]) RETURNS TABLE(subcategory_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES A SUBCATEGORY ROW WITH EXPLICIT WRITE POLICY THROUGH THE ADMIN DATABASE API                          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);
    PERFORM web_priv.web_subcategory_assert_can_reparent(p_subcategory_id, p_category_id);

    UPDATE web_priv.web_subcategories AS s
       SET category_id = p_category_id,
           title = btrim(p_title),
           slug = btrim(p_slug),
           read_policy_code = p_read_policy_code,
           read_rank = p_read_rank,
           write_policy_code = p_write_policy_code,
           write_rank = p_write_rank,
           nav_hidden_mode_code = p_nav_hidden_mode_code,
           nav_hidden = p_nav_hidden,
           icon_key_id = p_icon_key_id,
           icon_color_id = p_icon_color_id,
           updated_by_discord_id = p_actor_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE s.subcategory_id = p_subcategory_id
     RETURNING s.subcategory_id
          INTO subcategory_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Subcategory % was not found.', p_subcategory_id;
    END IF;

    PERFORM web_priv.web_subcategory_record_history(p_subcategory_id, 'update', p_actor_discord_id);
    PERFORM web_priv.web_subcategory_template_replace(p_actor_discord_id, p_category_id, p_subcategory_id, p_template_ids);
    PERFORM web_priv.web_subcategory_recalculate_dependents(p_subcategory_id);
END;
$$;


ALTER FUNCTION web_api.web_subcategory_update(p_actor_discord_id character varying, p_subcategory_id bigint, p_category_id bigint, p_title text, p_slug text, p_read_policy_code text, p_read_rank integer, p_write_policy_code text, p_write_rank integer, p_nav_hidden_mode_code text, p_nav_hidden boolean, p_icon_key_id bigint, p_icon_color_id bigint, p_template_ids bigint[]) OWNER TO cm;

--
-- Name: web_template_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_delete(p_actor_discord_id character varying, p_template_id bigint) RETURNS TABLE(template_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_delete                                                                    ////
--//// PURPOSE: Deletes a template after named dependency validation                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_id bigint;
	v_subject_label text;
	v_template_field_id bigint;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT t.template_id,
		   t.label || ' (' || t.template_code || ')'
	INTO v_template_id,
		 v_subject_label
	FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id;

	IF v_template_id IS NULL THEN
		RAISE EXCEPTION 'Template % was not found.', p_template_id;
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_content c WHERE c.template_id = p_template_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' (' || c.status_code || ')' AS label,
					 c.content_id
			  FROM web_priv.web_content c
			  WHERE c.template_id = p_template_id
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template', v_subject_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_category_template_r r WHERE r.template_id = p_template_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.category_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title, c.category_id
			  FROM web_priv.web_category_template_r r
			  JOIN web_priv.web_categories c ON c.category_id = r.category_id
			  WHERE r.template_id = p_template_id
			  ORDER BY c.title, c.category_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template', v_subject_label, 'category assignment', 'category assignments', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_subcategory_template_r r WHERE r.template_id = p_template_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.category_title, dep.title, dep.subcategory_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT sc.title,
					 c.title AS category_title,
					 c.title || ' / ' || sc.title AS label,
					 sc.subcategory_id
			  FROM web_priv.web_subcategory_template_r r
			  JOIN web_priv.web_subcategories sc ON sc.subcategory_id = r.subcategory_id
			  JOIN web_priv.web_categories c ON c.category_id = sc.category_id
			  WHERE r.template_id = p_template_id
			  ORDER BY c.title, sc.title, sc.subcategory_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template', v_subject_label, 'subcategory assignment', 'subcategory assignments', v_reference_count, v_reference_labels);
	END IF;

	FOR v_template_field_id IN
		SELECT f.template_field_id
		FROM web_priv.web_template_fields f
		WHERE f.template_id = p_template_id
		ORDER BY f.display_order,
				 f.template_field_id
	LOOP
		PERFORM web_priv.web_template_field_record_history(v_template_field_id, 'delete', p_actor_discord_id);
	END LOOP;

	DELETE FROM web_priv.web_template_fields f
	WHERE f.template_id = p_template_id;

	PERFORM web_priv.web_template_record_history(p_template_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_templates t
	WHERE t.template_id = p_template_id
	RETURNING t.template_id
	INTO template_id;

	IF template_id IS NULL THEN
		RAISE EXCEPTION 'Template % was not found.', p_template_id;
	END IF;

	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_template_delete(p_actor_discord_id character varying, p_template_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_template_delete(p_actor_discord_id character varying, p_template_id bigint); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_template_delete(p_actor_discord_id character varying, p_template_id bigint) IS 'Deletes an unused template and its owned template field placements through the admin database API.';


--
-- Name: web_template_field_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_delete(p_actor_discord_id character varying, p_template_field_id bigint) RETURNS TABLE(template_field_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_delete                                                             ////
--//// PURPOSE: Deletes a template field placement after named dependency validation                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_id bigint;
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT f.template_id,
		   t.label || ' / ' || COALESCE(NULLIF(btrim(f.label_override), ''), fl.label)
	INTO v_template_id,
		 v_subject_label
	FROM web_priv.web_template_fields f
	JOIN web_priv.web_templates t ON t.template_id = f.template_id
	JOIN web_priv.web_template_field_list fl ON fl.field_list_id = f.field_list_id
	WHERE f.template_field_id = p_template_field_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field placement % was not found.', p_template_field_id;
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_content_field_values v WHERE v.template_field_id = p_template_field_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' (' || c.status_code || ')' AS label,
					 c.content_id
			  FROM web_priv.web_content_field_values v
			  JOIN web_priv.web_content c ON c.content_id = v.content_id
			  WHERE v.template_field_id = p_template_field_id
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field', v_subject_label, 'content field value', 'content field values', v_reference_count, v_reference_labels);
	END IF;

	PERFORM web_priv.web_template_field_record_history(p_template_field_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_template_fields f
	WHERE f.template_field_id = p_template_field_id
	RETURNING f.template_field_id
	INTO template_field_id;

	PERFORM web_priv.web_template_bump_schema_version(v_template_id, p_actor_discord_id);
END;
$$;


ALTER FUNCTION web_api.web_template_field_delete(p_actor_discord_id character varying, p_template_field_id bigint) OWNER TO cm;

--
-- Name: web_template_field_force_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_force_delete(p_actor_discord_id character varying, p_template_field_id bigint) RETURNS TABLE(template_field_id bigint, deleted_field_value_count integer, deleted_external_link_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FORCE DELETES A REFERENCED TEMPLATE FIELD PLACEMENT THROUGH THE ADMIN DATABASE API                          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_template_id bigint;
    v_template_field_id bigint;
    v_content_field_value_id bigint;
    v_content_external_link_id bigint;
    v_deleted_field_value_count integer := 0;
    v_deleted_external_link_count integer := 0;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    SELECT f.template_id
      INTO v_template_id
      FROM web_priv.web_template_fields f
     WHERE f.template_field_id = p_template_field_id;

    IF v_template_id IS NULL THEN
        RAISE EXCEPTION 'Template field placement % was not found.', p_template_field_id;
    END IF;

    FOR v_content_external_link_id IN
        SELECT r.content_external_link_id
          FROM web_priv.web_content_external_link_r r
         WHERE r.template_field_id = p_template_field_id
         ORDER BY r.content_external_link_id
    LOOP
        PERFORM web_priv.web_content_external_link_record_history(
            v_content_external_link_id,
            'delete',
            p_actor_discord_id
        );
    END LOOP;

    DELETE FROM web_priv.web_content_external_link_r r
     WHERE r.template_field_id = p_template_field_id;

    GET DIAGNOSTICS v_deleted_external_link_count = ROW_COUNT;

    FOR v_content_field_value_id IN
        SELECT v.content_field_value_id
          FROM web_priv.web_content_field_values v
         WHERE v.template_field_id = p_template_field_id
         ORDER BY v.content_field_value_id
    LOOP
        PERFORM web_priv.web_content_field_value_record_history(
            v_content_field_value_id,
            'delete',
            p_actor_discord_id
        );
    END LOOP;

    DELETE FROM web_priv.web_content_field_values v
     WHERE v.template_field_id = p_template_field_id;

    GET DIAGNOSTICS v_deleted_field_value_count = ROW_COUNT;

    PERFORM web_priv.web_template_field_record_history(p_template_field_id, 'delete', p_actor_discord_id);

    DELETE FROM web_priv.web_template_fields f
     WHERE f.template_field_id = p_template_field_id
     RETURNING f.template_field_id
          INTO v_template_field_id;

    IF v_template_field_id IS NULL THEN
        RAISE EXCEPTION 'Template field placement % was not found.', p_template_field_id;
    END IF;

    PERFORM web_priv.web_template_bump_schema_version(v_template_id, p_actor_discord_id);

    template_field_id := v_template_field_id;
    deleted_field_value_count := v_deleted_field_value_count;
    deleted_external_link_count := v_deleted_external_link_count;

    RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_template_field_force_delete(p_actor_discord_id character varying, p_template_field_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_template_field_force_delete(p_actor_discord_id character varying, p_template_field_id bigint); Type: COMMENT; Schema: web_api; Owner: cm
--

COMMENT ON FUNCTION web_api.web_template_field_force_delete(p_actor_discord_id character varying, p_template_field_id bigint) IS 'Force deletes a template field placement and removes existing field values and external link registrations that reference it.';


--
-- Name: web_template_field_insert(character varying, bigint, bigint, text, text, integer, boolean, boolean, text, text, boolean, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_insert(p_actor_discord_id character varying, p_template_id bigint, p_field_list_id bigint, p_label_override text, p_help_text_override text, p_display_order integer, p_is_required boolean, p_is_enabled boolean DEFAULT true, p_layout_width_code text DEFAULT 'full'::text, p_layout_align_code text DEFAULT 'stretch'::text, p_show_label_flag boolean DEFAULT true, p_label_style_code text DEFAULT 'label'::text, p_label_position_code text DEFAULT 'above'::text, p_label_separator_code text DEFAULT 'colon'::text) RETURNS TABLE(template_field_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_insert                                                               ////
--//// PURPOSE: Inserts a template field placement through the admin database API                                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_layout_width_code text;
	v_layout_align_code text;
	v_label_style_code text;
	v_label_position_code text;
	v_label_separator_code text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_layout_width_code    := lower(btrim(COALESCE(p_layout_width_code, 'full')));
	v_layout_align_code    := lower(btrim(COALESCE(p_layout_align_code, 'stretch')));
	v_label_style_code     := lower(btrim(COALESCE(p_label_style_code, 'label')));
	v_label_position_code  := lower(btrim(COALESCE(p_label_position_code, 'above')));
	v_label_separator_code := lower(btrim(COALESCE(p_label_separator_code, 'colon')));

	IF v_layout_width_code NOT IN ('full', 'half', 'third') THEN
		RAISE EXCEPTION 'Template field layout width % is invalid.', p_layout_width_code;
	END IF;

	IF v_layout_align_code NOT IN ('left', 'center', 'right', 'stretch') THEN
		RAISE EXCEPTION 'Template field layout alignment % is invalid.', p_layout_align_code;
	END IF;

	IF v_label_position_code NOT IN ('above', 'inline') THEN
		RAISE EXCEPTION 'Template field label position % is invalid.', p_label_position_code;
	END IF;

	IF v_label_style_code NOT IN ('title', 'label', 'text', 'muted') THEN
		RAISE EXCEPTION 'Template field label style % is invalid.', p_label_style_code;
	END IF;

	IF v_label_position_code = 'inline' AND v_label_style_code = 'title' THEN
		RAISE EXCEPTION 'Template field title label style requires top label position.';
	END IF;

	IF v_label_separator_code NOT IN ('none', 'colon', 'dash') THEN
		RAISE EXCEPTION 'Template field label separator % is invalid.', p_label_separator_code;
	END IF;

	IF v_label_position_code = 'above' AND v_label_separator_code = 'dash' THEN
		RAISE EXCEPTION 'Template field dash label separator requires same-row label position.';
	END IF;

	INSERT INTO web_priv.web_template_fields(template_id,
										   field_list_id,
										   label_override,
										   help_text_override,
										   display_order,
										   layout_width_code,
										   layout_align_code,
										   show_label_flag,
										   label_style_code,
										   label_position_code,
										   label_separator_code,
										   is_required,
										   is_enabled,
										   created_by_discord_id,
										   updated_by_discord_id)
	VALUES (p_template_id,
			p_field_list_id,
			p_label_override,
			p_help_text_override,
			p_display_order,
			v_layout_width_code,
			v_layout_align_code,
			COALESCE(p_show_label_flag, true),
			v_label_style_code,
			v_label_position_code,
			v_label_separator_code,
			COALESCE(p_is_required, false),
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING web_template_fields.template_field_id
	INTO template_field_id;

	PERFORM web_priv.web_template_field_record_history(template_field_id, 'create', p_actor_discord_id);
	PERFORM web_priv.web_template_bump_schema_version(p_template_id, p_actor_discord_id);
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_template_field_insert(p_actor_discord_id character varying, p_template_id bigint, p_field_list_id bigint, p_label_override text, p_help_text_override text, p_display_order integer, p_is_required boolean, p_is_enabled boolean, p_layout_width_code text, p_layout_align_code text, p_show_label_flag boolean, p_label_style_code text, p_label_position_code text, p_label_separator_code text) OWNER TO cm;

--
-- Name: web_template_field_list_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_list_delete(p_actor_discord_id character varying, p_field_list_id bigint) RETURNS TABLE(field_list_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_list_delete                                                        ////
--//// PURPOSE: Deletes an unused template field list row after named dependency validation                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT fl.label || ' (' || fl.field_list_code || ')'
	INTO v_subject_label
	FROM web_priv.web_template_field_list fl
	WHERE fl.field_list_id = p_field_list_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_field_list_id::text);

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_template_fields f WHERE f.field_list_id = p_field_list_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.template_label, dep.display_order, dep.template_field_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT t.label AS template_label,
					 t.label || ' / ' || COALESCE(NULLIF(btrim(f.label_override), ''), fl.label) AS label,
					 f.display_order,
					 f.template_field_id
			  FROM web_priv.web_template_fields f
			  JOIN web_priv.web_templates t ON t.template_id = f.template_id
			  JOIN web_priv.web_template_field_list fl ON fl.field_list_id = f.field_list_id
			  WHERE f.field_list_id = p_field_list_id
			  ORDER BY t.label, f.display_order, f.template_field_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field list', v_subject_label, 'template field placement', 'template field placements', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_template_field_options o WHERE o.field_list_id = p_field_list_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.display_order, dep.field_option_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT o.label || ' (' || o.option_key || ')' AS label,
					 o.display_order,
					 o.field_option_id
			  FROM web_priv.web_template_field_options o
			  WHERE o.field_list_id = p_field_list_id
			  ORDER BY o.display_order, o.field_option_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field list', v_subject_label, 'field option', 'field options', v_reference_count, v_reference_labels);
	END IF;

	PERFORM web_priv.web_template_field_list_record_history(p_field_list_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_template_field_list f
	WHERE f.field_list_id = p_field_list_id
	RETURNING f.field_list_id
	INTO field_list_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field list row % was not found.', p_field_list_id;
	END IF;
END;
$$;


