    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INSERTS A TEMPLATE FIELD LIST ROW THROUGH THE ADMIN DATABASE API                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_render_destination_code text;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    v_render_destination_code := lower(btrim(COALESCE(p_render_destination_code, 'main')));

    IF v_render_destination_code NOT IN ('seo', 'hero', 'top', 'left', 'main', 'right', 'bottom', 'hidden') THEN
        RAISE EXCEPTION 'Template field render destination % is invalid.', p_render_destination_code;
    END IF;

    INSERT INTO web_priv.web_template_field_list (
        field_list_code,
        label,
        help_text,
        field_type_code,
        render_destination_code,
        is_enabled,
        created_by_discord_id,
        updated_by_discord_id
    ) VALUES (
        lower(btrim(p_field_list_code)),
        btrim(p_label),
        p_help_text,
        lower(btrim(p_field_type_code)),
        v_render_destination_code,
        COALESCE(p_is_enabled, true),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING web_template_field_list.field_list_id
         INTO field_list_id;

    PERFORM web_priv.web_template_field_list_record_history(field_list_id, 'create', p_actor_discord_id);
END;
