--
-- Name: web_template_field_list_tools_replace(character varying, bigint, text[]); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_list_tools_replace(p_actor_discord_id character varying, p_field_list_id bigint, p_field_tool_codes text[] DEFAULT ARRAY[]::text[]) RETURNS TABLE(field_list_id bigint, selected_tool_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// REPLACES TEMPLATE FIELD LIST TOOL SELECTION THROUGH THE ADMIN DATABASE API                                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_field_type_code text;
	v_field_list_tool_id bigint;
	v_invalid_tool_count integer;
	v_selected_tool_count integer;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT field_list.field_type_code
	INTO v_field_type_code
	FROM web_priv.web_template_field_list field_list
	WHERE field_list.field_list_id = p_field_list_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field list row % was not found.', p_field_list_id;
	END IF;

	SELECT COUNT(*)
	INTO v_invalid_tool_count
	FROM (SELECT DISTINCT lower(btrim(raw_tool.field_tool_code)) AS field_tool_code
		  FROM unnest(COALESCE(p_field_tool_codes, ARRAY[]::text[])) AS raw_tool(field_tool_code)
		  WHERE btrim(COALESCE(raw_tool.field_tool_code, '')) <> '') requested_tool
	LEFT JOIN web_priv.web_template_field_tools_c tool ON tool.field_tool_code = requested_tool.field_tool_code
												AND tool.field_type_code = v_field_type_code
												AND tool.is_enabled = true
	WHERE tool.field_tool_code IS NULL;

	IF v_invalid_tool_count > 0 THEN
		RAISE EXCEPTION 'One or more template field tools are invalid for field type %.', v_field_type_code;
	END IF;

	FOR v_field_list_tool_id IN
		WITH requested_tool AS (SELECT DISTINCT lower(btrim(raw_tool.field_tool_code)) AS field_tool_code
								FROM unnest(COALESCE(p_field_tool_codes, ARRAY[]::text[])) AS raw_tool(field_tool_code)
								WHERE btrim(COALESCE(raw_tool.field_tool_code, '')) <> '')
		SELECT rel.field_list_tool_id
		FROM web_priv.web_template_field_list_tools_r rel
		WHERE rel.field_list_id = p_field_list_id
		  AND NOT EXISTS (SELECT 1
						  FROM requested_tool requested
						  WHERE requested.field_tool_code = rel.field_tool_code)
	LOOP
		PERFORM web_priv.web_template_field_list_tool_record_history(v_field_list_tool_id, 'delete', p_actor_discord_id);
	END LOOP;

	WITH requested_tool AS (SELECT DISTINCT lower(btrim(raw_tool.field_tool_code)) AS field_tool_code
						  FROM unnest(COALESCE(p_field_tool_codes, ARRAY[]::text[])) AS raw_tool(field_tool_code)
						  WHERE btrim(COALESCE(raw_tool.field_tool_code, '')) <> '')
	DELETE FROM web_priv.web_template_field_list_tools_r rel
	WHERE rel.field_list_id = p_field_list_id
	  AND NOT EXISTS (SELECT 1
					  FROM requested_tool requested
					  WHERE requested.field_tool_code = rel.field_tool_code);

	FOR v_field_list_tool_id IN
		WITH requested_tool AS (SELECT DISTINCT lower(btrim(raw_tool.field_tool_code)) AS field_tool_code
								FROM unnest(COALESCE(p_field_tool_codes, ARRAY[]::text[])) AS raw_tool(field_tool_code)
								WHERE btrim(COALESCE(raw_tool.field_tool_code, '')) <> '')
		UPDATE web_priv.web_template_field_list_tools_r rel
		SET is_enabled = true,
			updated_by_discord_id = p_actor_discord_id,
			updated_dt = CURRENT_TIMESTAMP
		FROM requested_tool requested
		WHERE rel.field_list_id = p_field_list_id
		  AND rel.field_tool_code = requested.field_tool_code
		  AND rel.is_enabled = false
		RETURNING rel.field_list_tool_id
	LOOP
		PERFORM web_priv.web_template_field_list_tool_record_history(v_field_list_tool_id, 'update', p_actor_discord_id);
	END LOOP;

	FOR v_field_list_tool_id IN
		WITH requested_tool AS (SELECT DISTINCT lower(btrim(raw_tool.field_tool_code)) AS field_tool_code
								FROM unnest(COALESCE(p_field_tool_codes, ARRAY[]::text[])) AS raw_tool(field_tool_code)
								WHERE btrim(COALESCE(raw_tool.field_tool_code, '')) <> '')
		INSERT INTO web_priv.web_template_field_list_tools_r(field_list_id,
												field_tool_code,
												is_enabled,
												created_by_discord_id,
												created_dt,
												updated_by_discord_id,
												updated_dt)
		SELECT p_field_list_id,
			   requested.field_tool_code,
			   true,
			   p_actor_discord_id,
			   CURRENT_TIMESTAMP,
			   p_actor_discord_id,
			   CURRENT_TIMESTAMP
		FROM requested_tool requested
		WHERE NOT EXISTS (SELECT 1
						  FROM web_priv.web_template_field_list_tools_r rel
						  WHERE rel.field_list_id = p_field_list_id
							AND rel.field_tool_code = requested.field_tool_code)
		RETURNING field_list_tool_id
	LOOP
		PERFORM web_priv.web_template_field_list_tool_record_history(v_field_list_tool_id, 'create', p_actor_discord_id);
	END LOOP;

	SELECT COUNT(*)
	INTO v_selected_tool_count
	FROM web_priv.web_template_field_list_tools_r rel
	WHERE rel.field_list_id = p_field_list_id
	  AND rel.is_enabled = true;

	PERFORM web_priv.web_template_bump_schema_version_by_field_list(p_field_list_id, p_actor_discord_id);

	RETURN QUERY SELECT p_field_list_id, v_selected_tool_count;
END;
$$;


ALTER FUNCTION web_api.web_template_field_list_tools_replace(p_actor_discord_id character varying, p_field_list_id bigint, p_field_tool_codes text[]) OWNER TO cm;

--
-- Name: web_template_field_list_update(character varying, bigint, text, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_list_update(p_actor_discord_id character varying, p_field_list_id bigint, p_field_list_code text, p_label text, p_help_text text, p_field_type_code text, p_render_destination_code text, p_is_enabled boolean) RETURNS TABLE(field_list_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_list_update                                                        ////
--//// PURPOSE: Updates a template field list row after named dependency validation                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_value_column_name text;
	v_render_destination_code text;
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_render_destination_code := lower(btrim(COALESCE(p_render_destination_code, 'main')));

	IF v_render_destination_code NOT IN ('seo', 'hero', 'top', 'left', 'main', 'right', 'bottom', 'hidden') THEN
		RAISE EXCEPTION 'Template field render destination % is invalid.', p_render_destination_code;
	END IF;

	SELECT ft.value_column_name
	INTO v_value_column_name
	FROM web_priv.web_template_field_type_c ft
	WHERE ft.field_type_code = lower(btrim(p_field_type_code));

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field type % was not found.', p_field_type_code;
	END IF;

	SELECT fl.label || ' (' || fl.field_list_code || ')'
	INTO v_subject_label
	FROM web_priv.web_template_field_list fl
	WHERE fl.field_list_id = p_field_list_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_field_list_id::text);

	IF v_value_column_name <> 'value_option_key'
	   AND EXISTS (SELECT 1
				   FROM web_priv.web_template_field_options o
				   WHERE o.field_list_id = p_field_list_id) THEN
		SELECT COUNT(*)
		INTO v_reference_count
		FROM web_priv.web_template_field_options o
		WHERE o.field_list_id = p_field_list_id;

		SELECT COALESCE(array_agg(dep.label ORDER BY dep.display_order, dep.field_option_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT o.label || ' (' || o.option_key || ')' AS label,
					 o.display_order,
					 o.field_option_id
			  FROM web_priv.web_template_field_options o
			  WHERE o.field_list_id = p_field_list_id
			  ORDER BY o.display_order, o.field_option_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('change field type for', 'template field list', v_subject_label, 'field option', 'field options', v_reference_count, v_reference_labels);
	END IF;

	UPDATE web_priv.web_template_field_list f
	SET field_list_code = lower(btrim(p_field_list_code)),
		label = btrim(p_label),
		help_text = p_help_text,
		field_type_code = lower(btrim(p_field_type_code)),
		render_destination_code = v_render_destination_code,
		is_enabled = p_is_enabled,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE f.field_list_id = p_field_list_id
	RETURNING f.field_list_id
	INTO field_list_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field list row % was not found.', p_field_list_id;
	END IF;

	PERFORM web_priv.web_template_field_list_record_history(field_list_id, 'update', p_actor_discord_id);
	PERFORM web_priv.web_template_bump_schema_version_by_field_list(field_list_id, p_actor_discord_id);
END;
$$;


ALTER FUNCTION web_api.web_template_field_list_update(p_actor_discord_id character varying, p_field_list_id bigint, p_field_list_code text, p_label text, p_help_text text, p_field_type_code text, p_render_destination_code text, p_is_enabled boolean) OWNER TO cm;

--
-- Name: web_template_field_option_delete(character varying, bigint); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_option_delete(p_actor_discord_id character varying, p_field_option_id bigint) RETURNS TABLE(field_option_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_option_delete                                                      ////
--//// PURPOSE: Deletes a template field option after named dependency validation                                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_field_list_id bigint;
	v_option_key text;
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT o.field_list_id,
		   o.option_key,
		   o.label || ' (' || o.option_key || ')'
	INTO v_field_list_id,
		 v_option_key,
		 v_subject_label
	FROM web_priv.web_template_field_options o
	WHERE o.field_option_id = p_field_option_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field option % was not found.', p_field_option_id;
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content_field_values v
	JOIN web_priv.web_template_fields tf ON tf.template_field_id = v.template_field_id
	WHERE tf.field_list_id = v_field_list_id
	  AND v.value_option_key = v_option_key;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' / ' || COALESCE(NULLIF(btrim(tf.label_override), ''), fl.label) AS label,
					 c.content_id
			  FROM web_priv.web_content_field_values v
			  JOIN web_priv.web_content c ON c.content_id = v.content_id
			  JOIN web_priv.web_template_fields tf ON tf.template_field_id = v.template_field_id
			  JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
			  WHERE tf.field_list_id = v_field_list_id
				AND v.value_option_key = v_option_key
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field option', v_subject_label, 'content field value', 'content field values', v_reference_count, v_reference_labels);
	END IF;

	PERFORM web_priv.web_template_field_option_record_history(p_field_option_id, 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_template_field_options o
	WHERE o.field_option_id = p_field_option_id
	RETURNING o.field_option_id
	INTO field_option_id;

	PERFORM web_priv.web_template_bump_schema_version_by_field_list(v_field_list_id, p_actor_discord_id);
END;
$$;


