    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INSERTS A TEMPLATE FIELD OPTION THROUGH THE ADMIN DATABASE API                                               ////
