    SELECT ft.value_column_name
      INTO v_value_column_name
      FROM web_priv.web_template_field_list fl
      JOIN web_priv.web_template_field_type_c ft
        ON ft.field_type_code = fl.field_type_code
     WHERE fl.field_list_id = p_field_list_id;

