    INSERT INTO web_priv.web_template_field_options (
        field_list_id,
        option_key,
        label,
        display_order,
        is_enabled,
        created_by_discord_id,
        updated_by_discord_id
    ) VALUES (
        p_field_list_id,
        lower(btrim(p_option_key)),
        btrim(p_label),
        p_display_order,
        COALESCE(p_is_enabled, true),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING web_template_field_options.field_option_id
         INTO field_option_id;

    PERFORM web_priv.web_template_field_option_record_history(field_option_id, 'create', p_actor_discord_id);
    PERFORM web_priv.web_template_bump_schema_version_by_field_list(p_field_list_id, p_actor_discord_id);
END;
$$;


