--

CREATE FUNCTION web_api.web_template_field_tool_delete(p_actor_discord_id character varying, p_field_tool_code text) RETURNS TABLE(field_tool_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_tool_delete                                                        ////
--//// PURPOSE: Deletes an unused template field editor tool after named dependency validation                   ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT tool.label || ' (' || tool.field_tool_code || ')'
	INTO v_subject_label
	FROM web_priv.web_template_field_tools_c tool
	WHERE tool.field_tool_code = lower(btrim(p_field_tool_code));

	v_subject_label := COALESCE(v_subject_label, lower(btrim(p_field_tool_code)));

	SELECT COUNT(*) INTO v_reference_count
	FROM web_priv.web_template_field_list_tools_r rel
	WHERE rel.field_tool_code = lower(btrim(p_field_tool_code));

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.field_list_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT fl.label || ' (' || fl.field_list_code || ')' AS label,
					 fl.field_list_id
			  FROM web_priv.web_template_field_list_tools_r rel
			  JOIN web_priv.web_template_field_list fl ON fl.field_list_id = rel.field_list_id
			  WHERE rel.field_tool_code = lower(btrim(p_field_tool_code))
			  ORDER BY fl.label, fl.field_list_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field tool', v_subject_label, 'field list selection', 'field list selections', v_reference_count, v_reference_labels);
	END IF;

	PERFORM web_priv.web_template_field_tool_record_history(lower(btrim(p_field_tool_code)), 'delete', p_actor_discord_id);

	DELETE FROM web_priv.web_template_field_tools_c tool
	WHERE tool.field_tool_code = lower(btrim(p_field_tool_code))
	RETURNING tool.field_tool_code
	INTO field_tool_code;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field tool % was not found.', p_field_tool_code;
	END IF;
END;
$$;


