    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_tool_insert                                                         ////
--//// PURPOSE: Inserts a template field editor tool catalog row through the admin database API                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	IF p_display_order IS NULL OR p_display_order < 1 THEN
		RAISE EXCEPTION 'Display order must be a positive integer.';
	END IF;

	INSERT INTO web_priv.web_template_field_tools_c(field_tool_code,
													field_type_code,
													label,
													tool_group_code,
													display_order,
													description,
													is_enabled,
													created_by_discord_id,
													updated_by_discord_id)
	VALUES (lower(btrim(p_field_tool_code)),
			lower(btrim(p_field_type_code)),
			btrim(p_label),
			lower(btrim(p_tool_group_code)),
			p_display_order,
			NULLIF(btrim(COALESCE(p_description, '')), ''),
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING web_template_field_tools_c.field_tool_code
		 INTO field_tool_code;

	PERFORM web_priv.web_template_field_tool_record_history(field_tool_code, 'create', p_actor_discord_id);
