--
-- Name: web_template_field_tool_update(character varying, text, text, text, text, integer, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_tool_update(p_actor_discord_id character varying, p_field_tool_code text, p_field_type_code text, p_label text, p_tool_group_code text, p_display_order integer, p_description text, p_is_enabled boolean) RETURNS TABLE(field_tool_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_tool_update                                                        ////
--//// PURPOSE: Updates a template field editor tool after named dependency validation                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing_field_type_code text;
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	IF p_display_order IS NULL OR p_display_order < 1 THEN
		RAISE EXCEPTION 'Display order must be a positive integer.';
	END IF;

	SELECT tool.field_type_code,
		   tool.label || ' (' || tool.field_tool_code || ')'
	INTO v_existing_field_type_code,
		 v_subject_label
	FROM web_priv.web_template_field_tools_c tool
	WHERE tool.field_tool_code = lower(btrim(p_field_tool_code));

	IF v_existing_field_type_code IS NULL THEN
		RAISE EXCEPTION 'Template field tool % was not found.', p_field_tool_code;
	END IF;

	IF v_existing_field_type_code <> lower(btrim(p_field_type_code))
	   AND EXISTS (SELECT 1 FROM web_priv.web_template_field_list_tools_r rel WHERE rel.field_tool_code = lower(btrim(p_field_tool_code))) THEN
		SELECT COUNT(*)
		INTO v_reference_count
		FROM web_priv.web_template_field_list_tools_r rel
		WHERE rel.field_tool_code = lower(btrim(p_field_tool_code));

		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.field_list_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT fl.label || ' (' || fl.field_list_code || ')' AS label,
					 fl.field_list_id
			  FROM web_priv.web_template_field_list_tools_r rel
			  JOIN web_priv.web_template_field_list fl ON fl.field_list_id = rel.field_list_id
			  WHERE rel.field_tool_code = lower(btrim(p_field_tool_code))
			  ORDER BY fl.label, fl.field_list_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('change field type for', 'template field tool', v_subject_label, 'field list selection', 'field list selections', v_reference_count, v_reference_labels);
	END IF;

	UPDATE web_priv.web_template_field_tools_c tool
	SET field_type_code = lower(btrim(p_field_type_code)),
		label = btrim(p_label),
		tool_group_code = lower(btrim(p_tool_group_code)),
		display_order = p_display_order,
		description = NULLIF(btrim(COALESCE(p_description, '')), ''),
		is_enabled = COALESCE(p_is_enabled, true),
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE tool.field_tool_code = lower(btrim(p_field_tool_code))
	RETURNING tool.field_tool_code
	INTO field_tool_code;

	PERFORM web_priv.web_template_field_tool_record_history(field_tool_code, 'update', p_actor_discord_id);
END;
$$;


