			  WHERE f.field_type_code = p_field_type_code
			  ORDER BY f.label, f.field_list_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'template field type', v_subject_label, 'field list', 'field lists', v_reference_count, v_reference_labels);
