--
-- Name: web_template_field_type_update(character varying, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_type_update(p_actor_discord_id character varying, p_field_type_code text, p_label text, p_value_column_name text, p_description text, p_is_enabled boolean) RETURNS TABLE(field_type_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_type_update                                                        ////
--//// PURPOSE: Updates a template field type after named dependency validation                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT t.label || ' (' || t.field_type_code || ')'
	INTO v_subject_label
	FROM web_priv.web_template_field_type_c t
	WHERE t.field_type_code = p_field_type_code;

	v_subject_label := COALESCE(v_subject_label, p_field_type_code);

	IF btrim(p_value_column_name) <> 'value_option_key'
	   AND EXISTS (SELECT 1
				   FROM web_priv.web_template_field_list fl
				   JOIN web_priv.web_template_field_options o ON o.field_list_id = fl.field_list_id
				   WHERE fl.field_type_code = p_field_type_code) THEN
		SELECT COUNT(*)
		INTO v_reference_count
		FROM web_priv.web_template_field_list fl
		JOIN web_priv.web_template_field_options o ON o.field_list_id = fl.field_list_id
		WHERE fl.field_type_code = p_field_type_code;

		SELECT COALESCE(array_agg(dep.label ORDER BY dep.field_list_label, dep.display_order, dep.field_option_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT fl.label AS field_list_label,
					 fl.label || ' / ' || o.label || ' (' || o.option_key || ')' AS label,
					 o.display_order,
					 o.field_option_id
			  FROM web_priv.web_template_field_list fl
			  JOIN web_priv.web_template_field_options o ON o.field_list_id = fl.field_list_id
			  WHERE fl.field_type_code = p_field_type_code
			  ORDER BY fl.label, o.display_order, o.field_option_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('change value storage for', 'template field type', v_subject_label, 'field option', 'field options', v_reference_count, v_reference_labels);
	END IF;

	UPDATE web_priv.web_template_field_type_c t
	SET label = btrim(p_label),
		value_column_name = btrim(p_value_column_name),
		description = p_description,
		is_enabled = p_is_enabled,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE t.field_type_code = p_field_type_code
	RETURNING t.field_type_code
	INTO field_type_code;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field type % was not found.', p_field_type_code;
	END IF;

	PERFORM web_priv.web_template_field_type_record_history(field_type_code, 'update', p_actor_discord_id);
	PERFORM web_priv.web_template_bump_schema_version_by_field_type(field_type_code, p_actor_discord_id);
END;
$$;


ALTER FUNCTION web_api.web_template_field_type_update(p_actor_discord_id character varying, p_field_type_code text, p_label text, p_value_column_name text, p_description text, p_is_enabled boolean) OWNER TO cm;

--
-- Name: web_template_field_update(character varying, bigint, bigint, text, text, integer, boolean, boolean, text, text, boolean, text, text, text); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_field_update(p_actor_discord_id character varying, p_template_field_id bigint, p_field_list_id bigint, p_label_override text, p_help_text_override text, p_display_order integer, p_is_required boolean, p_is_enabled boolean, p_layout_width_code text DEFAULT 'full'::text, p_layout_align_code text DEFAULT 'stretch'::text, p_show_label_flag boolean DEFAULT true, p_label_style_code text DEFAULT 'label'::text, p_label_position_code text DEFAULT 'above'::text, p_label_separator_code text DEFAULT 'colon'::text) RETURNS TABLE(template_field_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_template_field_update                                                               ////
--//// PURPOSE: Updates a template field placement through the admin database API                                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_template_id bigint;
	v_layout_width_code text;
	v_layout_align_code text;
	v_label_style_code text;
	v_label_position_code text;
	v_label_separator_code text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_layout_width_code    := lower(btrim(COALESCE(p_layout_width_code, 'full')));
	v_layout_align_code    := lower(btrim(COALESCE(p_layout_align_code, 'stretch')));
	v_label_style_code     := lower(btrim(COALESCE(p_label_style_code, 'label')));
	v_label_position_code  := lower(btrim(COALESCE(p_label_position_code, 'above')));
	v_label_separator_code := lower(btrim(COALESCE(p_label_separator_code, 'colon')));

	IF v_layout_width_code NOT IN ('full', 'half', 'third') THEN
		RAISE EXCEPTION 'Template field layout width % is invalid.', p_layout_width_code;
	END IF;

	IF v_layout_align_code NOT IN ('left', 'center', 'right', 'stretch') THEN
		RAISE EXCEPTION 'Template field layout alignment % is invalid.', p_layout_align_code;
	END IF;

	IF v_label_position_code NOT IN ('above', 'inline') THEN
		RAISE EXCEPTION 'Template field label position % is invalid.', p_label_position_code;
	END IF;

	IF v_label_style_code NOT IN ('title', 'label', 'text', 'muted') THEN
		RAISE EXCEPTION 'Template field label style % is invalid.', p_label_style_code;
	END IF;

	IF v_label_position_code = 'inline' AND v_label_style_code = 'title' THEN
		RAISE EXCEPTION 'Template field title label style requires top label position.';
	END IF;

	IF v_label_separator_code NOT IN ('none', 'colon', 'dash') THEN
		RAISE EXCEPTION 'Template field label separator % is invalid.', p_label_separator_code;
	END IF;

	IF v_label_position_code = 'above' AND v_label_separator_code = 'dash' THEN
		RAISE EXCEPTION 'Template field dash label separator requires same-row label position.';
	END IF;

	UPDATE web_priv.web_template_fields f
	SET field_list_id         = p_field_list_id,
		label_override        = p_label_override,
		help_text_override    = p_help_text_override,
		display_order         = p_display_order,
		layout_width_code     = v_layout_width_code,
		layout_align_code     = v_layout_align_code,
		show_label_flag       = COALESCE(p_show_label_flag, true),
		label_style_code      = v_label_style_code,
		label_position_code   = v_label_position_code,
		label_separator_code  = v_label_separator_code,
		is_required           = p_is_required,
		is_enabled            = p_is_enabled,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt            = CURRENT_TIMESTAMP
	WHERE f.template_field_id = p_template_field_id
	RETURNING f.template_field_id,
			  f.template_id
	INTO template_field_id,
		 v_template_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template field placement % was not found.', p_template_field_id;
	END IF;

	PERFORM web_priv.web_template_field_record_history(template_field_id, 'update', p_actor_discord_id);
	PERFORM web_priv.web_template_bump_schema_version(v_template_id, p_actor_discord_id);
	RETURN NEXT;
END;
$$;


ALTER FUNCTION web_api.web_template_field_update(p_actor_discord_id character varying, p_template_field_id bigint, p_field_list_id bigint, p_label_override text, p_help_text_override text, p_display_order integer, p_is_required boolean, p_is_enabled boolean, p_layout_width_code text, p_layout_align_code text, p_show_label_flag boolean, p_label_style_code text, p_label_position_code text, p_label_separator_code text) OWNER TO cm;

--
-- Name: web_template_insert(character varying, text, text, text, text, text, boolean, bigint, bigint, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_insert(p_actor_discord_id character varying, p_template_code text, p_label text, p_description text, p_content_kind_code text, p_surface_scope_code text, p_requires_series boolean, p_default_icon_key_id bigint, p_default_icon_color_id bigint, p_is_enabled boolean) RETURNS TABLE(template_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INSERTS A TEMPLATE WITH CONTENT KIND, SURFACE, AND SERIES METADATA                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    INSERT INTO web_priv.web_templates (
        template_code,
        label,
        description,
        content_kind_code,
        surface_scope_code,
        requires_series,
        default_icon_key_id,
        default_icon_color_id,
        schema_version_no,
        is_enabled,
        created_by_discord_id,
        updated_by_discord_id
    )
    VALUES (
        lower(BTRIM(p_template_code)),
        BTRIM(p_label),
        p_description,
        lower(BTRIM(p_content_kind_code)),
        lower(BTRIM(p_surface_scope_code)),
        COALESCE(p_requires_series, false),
        p_default_icon_key_id,
        p_default_icon_color_id,
        1,
        COALESCE(p_is_enabled, true),
        p_actor_discord_id,
        p_actor_discord_id
    )
    RETURNING web_templates.template_id
         INTO template_id;

    PERFORM web_priv.web_template_record_history(template_id, 'create', p_actor_discord_id);
END;
$$;


ALTER FUNCTION web_api.web_template_insert(p_actor_discord_id character varying, p_template_code text, p_label text, p_description text, p_content_kind_code text, p_surface_scope_code text, p_requires_series boolean, p_default_icon_key_id bigint, p_default_icon_color_id bigint, p_is_enabled boolean) OWNER TO cm;

--
-- Name: web_template_update(character varying, bigint, text, text, text, text, text, boolean, bigint, bigint, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_template_update(p_actor_discord_id character varying, p_template_id bigint, p_template_code text, p_label text, p_description text, p_content_kind_code text, p_surface_scope_code text, p_requires_series boolean, p_default_icon_key_id bigint, p_default_icon_color_id bigint, p_is_enabled boolean) RETURNS TABLE(template_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPDATES A TEMPLATE INCLUDING CONTENT KIND, SURFACE, SERIES, AND DEFAULT ICON METADATA                       ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	UPDATE web_priv.web_templates t
	SET template_code = LOWER(BTRIM(p_template_code)),
		label = BTRIM(p_label),
		description = p_description,
		content_kind_code = LOWER(BTRIM(p_content_kind_code)),
		surface_scope_code = LOWER(BTRIM(p_surface_scope_code)),
		requires_series = COALESCE(p_requires_series, false),
		default_icon_key_id = p_default_icon_key_id,
		default_icon_color_id = p_default_icon_color_id,
		is_enabled = p_is_enabled,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE t.template_id = p_template_id
	RETURNING t.template_id
	INTO template_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Template % was not found.', p_template_id;
	END IF;

	PERFORM web_priv.web_content_recalculate_effective(c.content_id)
	FROM web_priv.web_content c
	WHERE c.template_id = p_template_id
	  AND (c.icon_mode_code = 'template_default'
		   OR c.icon_color_mode_code = 'template_default')
	;

	PERFORM web_priv.web_template_record_history(template_id, 'update', p_actor_discord_id);
END;
$$;


