-- Name: web_theme_color_create(character varying, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_theme_color_create(p_actor_discord_id character varying, p_key text, p_label text, p_preview text, p_is_enabled boolean DEFAULT true) RETURNS TABLE(theme_color_id bigint, key text, label text, preview text, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CREATES A THEME COLOR ROW THROUGH THE ADMIN DATABASE API                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_key text;
	v_label text;
	v_preview text;
	v_existing web_priv.web_theme_colors%ROWTYPE;
	v_theme_color_id bigint;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_key := NULLIF(btrim(lower(p_key)), '');
	v_label := NULLIF(btrim(p_label), '');
	v_preview := NULLIF(btrim(p_preview), '');

	IF v_key IS NULL THEN
		RAISE EXCEPTION 'web_theme_colors.key is required.';
	END IF;

	IF v_key !~ '^[a-z0-9._-]{1,64}$' THEN
		RAISE EXCEPTION 'web_theme_colors.key must match ^[a-z0-9._-]{1,64}$.';
	END IF;

	IF v_label IS NULL THEN
		RAISE EXCEPTION 'web_theme_colors.label is required.';
	END IF;

	IF v_preview IS NULL THEN
		RAISE EXCEPTION 'web_theme_colors.preview is required.';
	END IF;

	IF NOT (
		lower(v_preview) = 'currentcolor'
		OR v_preview ~ '^#[0-9A-Fa-f]{6}$'
		OR v_preview ~ '^--[a-z0-9-]+$'
		OR v_preview ~ '^var\(--[a-z0-9-]+\)$'
	) THEN
		RAISE EXCEPTION 'web_theme_colors.preview must use #RRGGBB, currentColor, --token-name, or var(--token-name).';
	END IF;

	SELECT *
	INTO v_existing
	FROM web_priv.web_theme_color_find_by_key(v_key);

	IF v_existing.theme_color_id IS NOT NULL THEN
		RAISE EXCEPTION 'web_theme_colors.key already exists: %.', v_key;
	END IF;

	INSERT INTO web_priv.web_theme_colors(key,
									   label,
									   preview,
									   is_enabled,
									   created_by_discord_id,
									   updated_by_discord_id)
	VALUES (v_key,
			v_label,
			v_preview,
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING web_theme_colors.theme_color_id
	INTO v_theme_color_id;

	PERFORM web_priv.web_theme_color_record_history(v_theme_color_id, 'create', p_actor_discord_id, now());

	RETURN QUERY
	SELECT vtc.theme_color_id,
		   vtc.key,
		   vtc.label,
		   vtc.preview,
		   vtc.is_enabled,
		   vtc.created_dt,
		   vtc.updated_dt
	FROM web_view.web_theme_colors vtc
	WHERE vtc.theme_color_id = v_theme_color_id;
END;
$_$;


