CREATE FUNCTION web_api.web_theme_color_delete(p_actor_discord_id character varying, p_theme_color_id bigint) RETURNS TABLE(theme_color_id bigint, key text, label text, preview text, is_enabled boolean, created_dt timestamp with time zone, updated_dt timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// DELETES A THEME COLOR ROW THROUGH THE ADMIN DATABASE API                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_existing web_priv.web_theme_colors%ROWTYPE;
    v_deleted web_priv.web_theme_colors%ROWTYPE;
BEGIN
    PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

    SELECT *
      INTO v_existing
      FROM web_priv.web_theme_color_find_by_id(p_theme_color_id);

    IF v_existing.theme_color_id IS NULL THEN
        RAISE EXCEPTION 'web_theme_colors row % was not found.', p_theme_color_id;
    END IF;

    PERFORM web_priv.web_theme_color_assert_can_delete(p_theme_color_id);
    PERFORM web_priv.web_theme_color_record_history(p_theme_color_id, 'delete', p_actor_discord_id, now());

    DELETE FROM web_priv.web_theme_colors tc
     WHERE tc.theme_color_id = p_theme_color_id
     RETURNING tc.*
      INTO v_deleted;

    IF v_deleted.theme_color_id IS NULL THEN
        RAISE EXCEPTION 'web_theme_colors row % was not found.', p_theme_color_id;
    END IF;

    RETURN QUERY
    SELECT
        v_deleted.theme_color_id,
        v_deleted.key,
        v_deleted.label,
        v_deleted.preview,
        v_deleted.is_enabled,
        v_deleted.created_dt,
        v_deleted.updated_dt;
END;
$$;


