		RAISE EXCEPTION 'web_theme_colors.label is required.';
	END IF;

	IF v_preview IS NULL THEN
		RAISE EXCEPTION 'web_theme_colors.preview is required.';
	END IF;

	IF NOT (
		lower(v_preview) = 'currentcolor'
		OR v_preview ~ '^#[0-9A-Fa-f]{6}$'
