		OR v_preview ~ '^var\(--[a-z0-9-]+\)$'
	) THEN
		RAISE EXCEPTION 'web_theme_colors.preview must use #RRGGBB, currentColor, --token-name, or var(--token-name).';
	END IF;

	UPDATE web_priv.web_theme_colors tc
	SET label                 = v_label,
		preview               = v_preview,
		is_enabled            = COALESCE(p_is_enabled, tc.is_enabled),
