	WHERE tc.theme_color_id = p_theme_color_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'web_theme_colors row % was not found.', p_theme_color_id;
	END IF;

	PERFORM web_priv.web_theme_color_record_history(p_theme_color_id, 'update', p_actor_discord_id, now());

	RETURN QUERY
	SELECT vtc.theme_color_id,
		   vtc.key,
