-- Name: web_youtube_channel_insert(character varying, text, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_youtube_channel_insert(p_actor_discord_id character varying, p_channel_external_id text, p_channel_handle text, p_channel_title text, p_channel_url text, p_comment text, p_is_enabled boolean DEFAULT true) RETURNS TABLE(youtube_channel_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_youtube_channel_insert                                                           ////
--//// PURPOSE: Creates a YouTube channel allowlist row through the admin database API                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_channel_external_id text;
	v_channel_handle text;
	v_channel_title text;
	v_channel_url text;
	v_comment text;
	v_existing web_priv.web_youtube_channels_c%ROWTYPE;
	v_youtube_channel_id bigint;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	v_channel_external_id := NULLIF(btrim(COALESCE(p_channel_external_id, '')), '');
	v_channel_handle      := NULLIF(btrim(COALESCE(p_channel_handle, '')), '');
	v_channel_title       := NULLIF(btrim(COALESCE(p_channel_title, '')), '');
	v_channel_url         := NULLIF(btrim(COALESCE(p_channel_url, '')), '');
	v_comment             := NULLIF(btrim(COALESCE(p_comment, '')), '');

	IF v_channel_external_id IS NULL THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_external_id is required.';
	END IF;

	IF v_channel_external_id !~ '^UC[A-Za-z0-9_-]{22}$' THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_external_id must be a stable UC... YouTube channel ID.';
	END IF;

	IF v_channel_handle IS NOT NULL AND v_channel_handle !~ '^@[A-Za-z0-9._-]{3,64}$' THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_handle must use @ plus 3-64 allowed characters.';
	END IF;

	IF v_channel_title IS NULL THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_title is required.';
	END IF;

	IF v_channel_url IS NOT NULL AND v_channel_url !~ '^https://[^[:space:]]+$' THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_url must be a valid https URL.';
	END IF;

	SELECT *
	INTO v_existing
	FROM web_priv.web_youtube_channel_find_by_external_id(v_channel_external_id);

	IF v_existing.youtube_channel_id IS NOT NULL THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_external_id already exists: %.', v_channel_external_id;
	END IF;

	IF v_channel_handle IS NOT NULL THEN
		SELECT ytc.*
		INTO v_existing
		FROM web_priv.web_youtube_channels_c ytc
		WHERE LOWER(ytc.channel_handle) = LOWER(v_channel_handle)
		LIMIT 1
		;

		IF v_existing.youtube_channel_id IS NOT NULL THEN
			RAISE EXCEPTION 'web_youtube_channels_c.channel_handle already exists: %.', v_channel_handle;
		END IF;
	END IF;

	INSERT INTO web_priv.web_youtube_channels_c(channel_external_id,
										 channel_handle,
										 channel_title,
										 channel_url,
										 comment,
										 is_enabled,
										 created_by_discord_id,
										 updated_by_discord_id)
	VALUES (v_channel_external_id,
			v_channel_handle,
			v_channel_title,
			v_channel_url,
			v_comment,
			COALESCE(p_is_enabled, true),
			p_actor_discord_id,
			p_actor_discord_id)
	RETURNING web_youtube_channels_c.youtube_channel_id
	INTO v_youtube_channel_id;

	RETURN QUERY
	SELECT v_youtube_channel_id;
END;
$_$;


