--
-- Name: web_youtube_channel_update(character varying, bigint, text, text, text, text, boolean); Type: FUNCTION; Schema: web_api; Owner: cm
--

CREATE FUNCTION web_api.web_youtube_channel_update(p_actor_discord_id character varying, p_youtube_channel_id bigint, p_channel_handle text, p_channel_title text, p_channel_url text, p_comment text, p_is_enabled boolean) RETURNS TABLE(youtube_channel_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_youtube_channel_update                                                           ////
--//// PURPOSE: Updates a YouTube channel allowlist row through the admin database API                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_existing web_priv.web_youtube_channels_c%ROWTYPE;
	v_conflict web_priv.web_youtube_channels_c%ROWTYPE;
	v_channel_handle text;
	v_channel_title text;
	v_channel_url text;
	v_comment text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin(p_actor_discord_id);

	SELECT *
	INTO v_existing
	FROM web_priv.web_youtube_channel_find_by_id(p_youtube_channel_id);

	IF v_existing.youtube_channel_id IS NULL THEN
		RAISE EXCEPTION 'web_youtube_channels_c row % was not found.', p_youtube_channel_id;
	END IF;

	v_channel_handle := NULLIF(btrim(COALESCE(p_channel_handle, '')), '');
	v_channel_title  := NULLIF(btrim(COALESCE(p_channel_title, '')), '');
	v_channel_url    := NULLIF(btrim(COALESCE(p_channel_url, '')), '');
	v_comment        := NULLIF(btrim(COALESCE(p_comment, '')), '');

	IF v_channel_handle IS NOT NULL AND v_channel_handle !~ '^@[A-Za-z0-9._-]{3,64}$' THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_handle must use @ plus 3-64 allowed characters.';
	END IF;

	IF v_channel_title IS NULL THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_title is required.';
	END IF;

	IF v_channel_url IS NOT NULL AND v_channel_url !~ '^https://[^[:space:]]+$' THEN
		RAISE EXCEPTION 'web_youtube_channels_c.channel_url must be a valid https URL.';
	END IF;

	IF v_channel_handle IS NOT NULL THEN
		SELECT ytc.*
		INTO v_conflict
		FROM web_priv.web_youtube_channels_c ytc
		WHERE LOWER(ytc.channel_handle) = LOWER(v_channel_handle)
		  AND ytc.youtube_channel_id <> p_youtube_channel_id
		LIMIT 1
		;

		IF v_conflict.youtube_channel_id IS NOT NULL THEN
			RAISE EXCEPTION 'web_youtube_channels_c.channel_handle already exists: %.', v_channel_handle;
		END IF;
	END IF;

	UPDATE web_priv.web_youtube_channels_c ytc
	SET channel_handle        = v_channel_handle,
		channel_title         = v_channel_title,
		channel_url           = v_channel_url,
		comment               = v_comment,
		is_enabled            = COALESCE(p_is_enabled, ytc.is_enabled),
		updated_by_discord_id = p_actor_discord_id,
		updated_dt            = now()
	WHERE ytc.youtube_channel_id = p_youtube_channel_id
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'web_youtube_channels_c row % was not found.', p_youtube_channel_id;
	END IF;

	RETURN QUERY
	SELECT p_youtube_channel_id;
END;
$_$;


