--

CREATE FUNCTION web_api.web_youtube_video_assert_allowed_admin(p_actor_discord_id character varying, p_video_id text, p_channel_external_id text, p_video_title text DEFAULT NULL::text, p_channel_title text DEFAULT NULL::text) RETURNS TABLE(video_id text, channel_external_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_api.web_youtube_video_assert_allowed_admin                                                ////
--//// PURPOSE: Validates resolved YouTube video metadata against the enabled channel allowlist                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_video_id text;
	v_channel_external_id text;
	v_video_title text;
	v_channel_title text;
BEGIN
	PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);

	v_video_id             := NULLIF(btrim(COALESCE(p_video_id, '')), '');
	v_channel_external_id  := NULLIF(btrim(COALESCE(p_channel_external_id, '')), '');
	v_video_title          := NULLIF(btrim(COALESCE(p_video_title, '')), '');
	v_channel_title        := NULLIF(btrim(COALESCE(p_channel_title, '')), '');

	IF v_video_id IS NULL THEN
		RAISE EXCEPTION 'YouTube video ID is required.';
	END IF;

	IF v_video_id !~ '^[A-Za-z0-9_-]{11}$' THEN
		RAISE EXCEPTION 'YouTube video ID % is not valid.', v_video_id;
	END IF;

	IF v_channel_external_id IS NULL THEN
		RAISE EXCEPTION 'Resolved YouTube channel ID is required for video %.', v_video_id;
	END IF;

	IF v_channel_external_id !~ '^UC[A-Za-z0-9_-]{22}$' THEN
		RAISE EXCEPTION 'Resolved YouTube channel ID % is not valid.', v_channel_external_id;
	END IF;

	PERFORM web_priv.web_youtube_channel_assert_allowed(v_channel_external_id);

	RETURN QUERY
	SELECT v_video_id,
		   v_channel_external_id;
END;
$_$;


ALTER FUNCTION web_api.web_youtube_video_assert_allowed_admin(p_actor_discord_id character varying, p_video_id text, p_channel_external_id text, p_video_title text, p_channel_title text) OWNER TO cm;

--
-- Name: FUNCTION web_youtube_video_assert_allowed_admin(p_actor_discord_id character varying, p_video_id text, p_channel_external_id text, p_video_title text, p_channel_title text); Type: COMMENT; Schema: web_api; Owner: cm
--

