--
-- Name: actor_assert_can_meet_rank_policy(character varying, text, integer, text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.actor_assert_can_meet_rank_policy(p_actor_discord_id character varying, p_policy_code text, p_policy_rank integer, p_operation_label text DEFAULT 'content authoring'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT AN AUTHENTICATED MEMBER CAN SATISFY A RANK-BASED POLICY                                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_summary record;
BEGIN
    SELECT *
      INTO v_summary
      FROM web_priv.actor_get_access_summary(p_actor_discord_id);

    IF COALESCE(v_summary.is_authenticated, false) = false THEN
        RAISE EXCEPTION 'Actor % must be authenticated for %.', p_actor_discord_id, p_operation_label;
    END IF;

    IF COALESCE(v_summary.is_member, false) = false THEN
        RAISE EXCEPTION 'Actor % must be a guild member for %.', p_actor_discord_id, p_operation_label;
    END IF;

    IF p_policy_code = 'public' THEN
        RETURN;
    ELSIF p_policy_code = 'min_rank' THEN
        IF COALESCE(v_summary.max_rank, -1) < COALESCE(p_policy_rank, 0) THEN
            RAISE EXCEPTION 'Actor % does not satisfy min_rank % for %.', p_actor_discord_id, p_policy_rank, p_operation_label;
        END IF;
    ELSIF p_policy_code = 'equal_rank' THEN
        IF COALESCE(v_summary.max_rank, -1) <> COALESCE(p_policy_rank, -999999) THEN
            RAISE EXCEPTION 'Actor % does not satisfy equal_rank % for %.', p_actor_discord_id, p_policy_rank, p_operation_label;
        END IF;
    ELSE
        RAISE EXCEPTION 'Unsupported policy code % for %.', p_policy_code, p_operation_label;
    END IF;
END;
$$;


