--
-- Name: actor_get_access_summary(character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.actor_get_access_summary(p_actor_discord_id character varying) RETURNS TABLE(is_authenticated boolean, is_member boolean, is_admin boolean, is_editor boolean, max_rank integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_auth_user_id bigint;
    v_discord_user_id bigint;
    v_is_authenticated boolean := false;
    v_is_member boolean := false;
BEGIN
    SELECT au.auth_user_id
      INTO v_auth_user_id
      FROM web_priv.auth_users au
     WHERE au.discord_id = p_actor_discord_id
       AND au.is_disabled = false
     LIMIT 1;

    IF v_auth_user_id IS NOT NULL THEN
        v_is_authenticated := true;

        SELECT du.discord_user_id,
               COALESCE(du.is_member, false)
          INTO v_discord_user_id,
               v_is_member
          FROM web_priv.discord_users du
         WHERE du.auth_user_id = v_auth_user_id
         LIMIT 1;
    END IF;

    RETURN QUERY
    SELECT
        v_is_authenticated AS is_authenticated,
        v_is_member AS is_member,
        COALESCE(bool_or(src.is_admin), false) AS is_admin,
        COALESCE(bool_or(src.is_editor), false) AS is_editor,
        COALESCE(MAX(src.rank), 0) AS max_rank
    FROM (
        SELECT dr.rank, dr.is_admin, dr.is_editor
        FROM web_priv.discord_roles dr
        WHERE dr.is_public_default = true

        UNION ALL

        SELECT dr.rank, dr.is_admin, dr.is_editor
        FROM web_priv.discord_roles dr
        WHERE dr.is_authenticated_default = true
          AND v_is_authenticated = true

        UNION ALL

        SELECT dr.rank, dr.is_admin, dr.is_editor
        FROM web_priv.discord_roles dr
        LEFT JOIN web_priv.discord_user_role_cache durc
               ON durc.discord_role_id = dr.role_id
        WHERE dr.source = 'discord'::web_priv.enum_discord_roles_source
          AND dr.is_access_role = true
          AND durc.discord_user_id = v_discord_user_id
    ) src;
END;
$$;


ALTER FUNCTION web_priv.actor_get_access_summary(p_actor_discord_id character varying) OWNER TO cm;

--
-- Name: FUNCTION actor_get_access_summary(p_actor_discord_id character varying); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.actor_get_access_summary(p_actor_discord_id character varying) IS 'Returns the effective actor access summary based on defaults plus configured Discord roles matched through the role cache.';


--
-- Name: actor_has_exact_rank(character varying, integer); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.actor_has_exact_rank(p_actor_discord_id character varying, p_rank integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_auth_user_id bigint;
    v_discord_user_id bigint;
    v_is_authenticated boolean := false;
    v_has_exact_rank boolean := false;
BEGIN
    SELECT au.auth_user_id
      INTO v_auth_user_id
      FROM web_priv.auth_users au
     WHERE au.discord_id = p_actor_discord_id
       AND au.is_disabled = false
     LIMIT 1;

    IF v_auth_user_id IS NOT NULL THEN
        v_is_authenticated := true;
        SELECT du.discord_user_id INTO v_discord_user_id FROM web_priv.discord_users du WHERE du.auth_user_id = v_auth_user_id LIMIT 1;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM (
            SELECT dr.rank FROM web_priv.discord_roles dr WHERE dr.is_public_default = true
            UNION ALL
            SELECT dr.rank FROM web_priv.discord_roles dr WHERE dr.is_authenticated_default = true AND v_is_authenticated = true
            UNION ALL
            SELECT dr.rank
            FROM web_priv.discord_roles dr
            LEFT JOIN web_priv.discord_user_role_cache durc ON durc.discord_role_id = dr.role_id
            WHERE dr.source = 'discord'::web_priv.enum_discord_roles_source
              AND dr.is_access_role = true
              AND durc.discord_user_id = v_discord_user_id
        ) src
        WHERE src.rank = p_rank
    ) INTO v_has_exact_rank;

    RETURN COALESCE(v_has_exact_rank, false);
END;
$$;


ALTER FUNCTION web_priv.actor_has_exact_rank(p_actor_discord_id character varying, p_rank integer) OWNER TO cm;

--
-- Name: FUNCTION actor_has_exact_rank(p_actor_discord_id character varying, p_rank integer); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.actor_has_exact_rank(p_actor_discord_id character varying, p_rank integer) IS 'Returns true when the actor has any applicable configured role or default with exactly the requested rank.';


--
-- Name: actor_passes_effective_policy(character varying, text, integer); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.actor_passes_effective_policy(p_actor_discord_id character varying, p_effective_policy_code text, p_effective_rank integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// EVALUATES ACCESS AGAINST STORED EFFECTIVE POLICY CODE AND RANK                                               ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_summary record;
BEGIN
    SELECT *
      INTO v_summary
      FROM web_priv.actor_get_access_summary(p_actor_discord_id);

    IF p_effective_policy_code IS NULL THEN
        RAISE EXCEPTION 'Effective policy code cannot be null.';
    END IF;

    CASE p_effective_policy_code
        WHEN 'public' THEN
            RETURN true;

        WHEN 'min_rank' THEN
            RETURN COALESCE(v_summary.max_rank, 0) >= COALESCE(p_effective_rank, 0);

        WHEN 'equal_rank' THEN
            RETURN web_priv.actor_has_exact_rank(
                p_actor_discord_id,
                COALESCE(p_effective_rank, 0)
            );

        WHEN 'inherit' THEN
            RAISE EXCEPTION 'Effective policy code cannot be inherit.';

        ELSE
            RAISE EXCEPTION 'Unsupported effective policy code: %', p_effective_policy_code;
    END CASE;
END;
$$;


ALTER FUNCTION web_priv.actor_passes_effective_policy(p_actor_discord_id character varying, p_effective_policy_code text, p_effective_rank integer) OWNER TO cm;

