COMMENT ON FUNCTION web_priv.actor_passes_effective_policy(p_actor_discord_id character varying, p_effective_policy_code text, p_effective_rank integer) IS 'Evaluates access against effective policy columns. Effective policy must not be inherit.';


--
-- Name: auth_user_assert_discord_link(bigint, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.auth_user_assert_discord_link(p_auth_user_id bigint, p_discord_id character varying) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT AUTH USER IS LINKED TO THE PROVIDED DISCORD ID                                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_auth_user record;
BEGIN
    SELECT
        au.auth_user_id,
        au.discord_id,
        au.is_disabled
      INTO v_auth_user
      FROM web_priv.auth_users au
     WHERE au.auth_user_id = p_auth_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Auth user % does not exist.', p_auth_user_id;
    END IF;

    IF v_auth_user.is_disabled = true THEN
        RAISE EXCEPTION 'Auth user % is disabled.', p_auth_user_id;
    END IF;

    IF v_auth_user.discord_id IS NULL THEN
        RAISE EXCEPTION 'Auth user % is not linked to any Discord ID.', p_auth_user_id;
    END IF;

    IF v_auth_user.discord_id <> p_discord_id THEN
        RAISE EXCEPTION
            'Auth user % is linked to Discord ID %, not %.',
            p_auth_user_id,
            v_auth_user.discord_id,
            p_discord_id;
    END IF;
END;
$$;


