--
-- Name: discord_role_assert_defaults_present(); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.discord_role_assert_defaults_present() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_public_count integer;
    v_authenticated_count integer;
BEGIN
    SELECT COUNT(*) INTO v_public_count FROM web_priv.discord_roles WHERE is_public_default = true;
    SELECT COUNT(*) INTO v_authenticated_count FROM web_priv.discord_roles WHERE is_authenticated_default = true;

    IF v_public_count <> 1 THEN
        RAISE EXCEPTION 'Exactly one public default Discord role row is required. Found: %.', v_public_count;
    END IF;

    IF v_authenticated_count <> 1 THEN
        RAISE EXCEPTION 'Exactly one authenticated default Discord role row is required. Found: %.', v_authenticated_count;
    END IF;
END;
$$;


