--

COMMENT ON FUNCTION web_priv.discord_role_assert_defaults_present() IS 'Raises when the required public or authenticated default Discord role rows are missing or duplicated.';


--
-- Name: discord_role_upsert_discovered(jsonb); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.discord_role_upsert_discovered(p_roles jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_processed_count integer;
BEGIN
    INSERT INTO web_priv.discord_roles (
        name,
        source,
        role_id,
        color_hex,
        rank,
        is_access_role,
        is_editor,
        is_admin,
        is_public_default,
        is_authenticated_default
    )
    SELECT
        src.role_name,
        'discord'::web_priv.enum_discord_roles_source,
        src.role_id,
        CASE WHEN src.color_integer IS NULL OR src.color_integer < 0 THEN NULL ELSE '#' || lpad(upper(to_hex(src.color_integer)), 6, '0') END,
        0,
        false,
        false,
        false,
        false,
        false
    FROM (
        SELECT DISTINCT ON (parsed.role_id)
            parsed.role_id,
            parsed.role_name,
            parsed.color_integer
        FROM jsonb_to_recordset(COALESCE(p_roles, '[]'::jsonb)) AS parsed(
            role_id varchar(32),
            role_name text,
            role_position integer,
            is_managed boolean,
            color_integer integer
        )
        WHERE parsed.role_id IS NOT NULL
          AND btrim(parsed.role_id) <> ''
          AND parsed.role_name IS NOT NULL
          AND btrim(parsed.role_name) <> ''
        ORDER BY parsed.role_id
    ) src
    ON CONFLICT (role_id) WHERE role_id IS NOT NULL
    DO UPDATE
          SET name = EXCLUDED.name,
              color_hex = EXCLUDED.color_hex,
              updated_dt = now();

    GET DIAGNOSTICS v_processed_count = ROW_COUNT;
    RETURN COALESCE(v_processed_count, 0);
END;
$$;


ALTER FUNCTION web_priv.discord_role_upsert_discovered(p_roles jsonb) OWNER TO cm;

--
-- Name: FUNCTION discord_role_upsert_discovered(p_roles jsonb); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.discord_role_upsert_discovered(p_roles jsonb) IS 'Discovers missing real Discord roles from a sync payload and refreshes Discord-owned metadata without changing local privilege configuration.';


--
-- Name: discord_user_role_cache_replace(bigint, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.discord_user_role_cache_replace(p_discord_user_id bigint, p_roles jsonb, p_sync_source text DEFAULT 'login'::text, p_sync_dt timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// REPLACES THE FULL CACHED ROLE SET FOR ONE DISCORD USER USING A SHARED SYNC TIMESTAMP                       ////
--//// -----------------------------------------Powered by Wooden Engine----------------------------------------- ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_inserted_count integer;
BEGIN
    DELETE FROM web_priv.discord_user_role_cache durc
     WHERE durc.discord_user_id = p_discord_user_id;

    INSERT INTO web_priv.discord_user_role_cache (
        discord_user_id,
        discord_role_id,
        role_name,
        role_position,
        is_managed,
        color_integer,
        synced_dt,
        sync_source
    )
    SELECT
        p_discord_user_id,
        src.role_id,
        src.role_name,
        src.role_position,
        COALESCE(src.is_managed, false),
        src.color_integer,
        p_sync_dt,
        p_sync_source
    FROM (
        SELECT DISTINCT ON (parsed.role_id)
            parsed.role_id,
            parsed.role_name,
            parsed.role_position,
            parsed.is_managed,
            parsed.color_integer
        FROM jsonb_to_recordset(COALESCE(p_roles, '[]'::jsonb)) AS parsed(
            role_id varchar(32),
            role_name text,
            role_position integer,
            is_managed boolean,
            color_integer integer
        )
        WHERE parsed.role_id IS NOT NULL
          AND btrim(parsed.role_id) <> ''
          AND parsed.role_name IS NOT NULL
          AND btrim(parsed.role_name) <> ''
        ORDER BY parsed.role_id
    ) src;

    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;

    RETURN COALESCE(v_inserted_count, 0);
END;
$$;


ALTER FUNCTION web_priv.discord_user_role_cache_replace(p_discord_user_id bigint, p_roles jsonb, p_sync_source text, p_sync_dt timestamp with time zone) OWNER TO cm;

--
-- Name: FUNCTION discord_user_role_cache_replace(p_discord_user_id bigint, p_roles jsonb, p_sync_source text, p_sync_dt timestamp with time zone); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.discord_user_role_cache_replace(p_discord_user_id bigint, p_roles jsonb, p_sync_source text, p_sync_dt timestamp with time zone) IS 'Replaces the full cached Discord role set for one user using a caller-supplied sync timestamp.';


--
-- Name: discord_user_role_refresh_is_due(character varying, interval); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.discord_user_role_refresh_is_due(p_actor_discord_id character varying, p_max_age interval DEFAULT '00:15:00'::interval) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RETURNS TRUE WHEN DISCORD ROLE VERIFICATION SHOULD BE REFRESHED                                            ////
--//// -----------------------------------------Powered by Wooden Engine----------------------------------------- ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_auth_user_id bigint;
    v_roles_synced_dt timestamptz;
BEGIN
    SELECT au.auth_user_id
      INTO v_auth_user_id
      FROM web_priv.auth_users au
     WHERE au.discord_id = p_actor_discord_id
       AND au.is_disabled = false
     LIMIT 1;

    IF v_auth_user_id IS NULL THEN
        RETURN false;
    END IF;

    SELECT du.roles_synced_dt
      INTO v_roles_synced_dt
      FROM web_priv.discord_users du
     WHERE du.auth_user_id = v_auth_user_id
     LIMIT 1;

    IF v_roles_synced_dt IS NULL THEN
        RETURN true;
    END IF;

    RETURN v_roles_synced_dt < now() - p_max_age;
END;
$$;


ALTER FUNCTION web_priv.discord_user_role_refresh_is_due(p_actor_discord_id character varying, p_max_age interval) OWNER TO cm;

--
-- Name: FUNCTION discord_user_role_refresh_is_due(p_actor_discord_id character varying, p_max_age interval); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.discord_user_role_refresh_is_due(p_actor_discord_id character varying, p_max_age interval) IS 'Returns true when the current Discord role snapshot is missing or older than the allowed maximum age.';


--
-- Name: discord_user_upsert_from_login(bigint, character varying, text, text, text, text, timestamp with time zone, boolean, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.discord_user_upsert_from_login(p_auth_user_id bigint, p_discord_id character varying, p_username text, p_global_name text, p_avatar_hash text, p_avatar_url text, p_created_from_snowflake timestamp with time zone, p_is_member boolean, p_joined_dt timestamp with time zone, p_sync_dt timestamp with time zone, p_touch_last_login boolean DEFAULT true) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// UPSERTS CURRENT DISCORD USER SNAPSHOT DURING LOGIN OR VERIFY SYNC                                          ////
--//// -----------------------------------------Powered by Wooden Engine----------------------------------------- ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_discord_user_id bigint;
    v_conflict_auth_user_id bigint;
BEGIN
    SELECT du.auth_user_id
      INTO v_conflict_auth_user_id
      FROM web_priv.discord_users du
     WHERE du.discord_id = p_discord_id
       AND du.auth_user_id <> p_auth_user_id;

    IF FOUND THEN
        RAISE EXCEPTION
            'Discord ID % is already connected to auth user % in discord_users.',
            p_discord_id,
            v_conflict_auth_user_id;
    END IF;

    INSERT INTO web_priv.discord_users (
        auth_user_id,
        discord_id,
        username,
        global_name,
        avatar_hash,
        avatar_url,
        created_from_snowflake,
        is_member,
        joined_dt,
        roles_synced_dt,
        last_login_dt
    )
    VALUES (
        p_auth_user_id,
        p_discord_id,
        p_username,
        p_global_name,
        p_avatar_hash,
        p_avatar_url,
        p_created_from_snowflake,
        COALESCE(p_is_member, false),
        p_joined_dt,
        p_sync_dt,
        CASE
            WHEN p_touch_last_login THEN p_sync_dt
            ELSE NULL
        END
    )
    ON CONFLICT (auth_user_id)
    DO UPDATE
          SET discord_id = EXCLUDED.discord_id,
              username = EXCLUDED.username,
              global_name = EXCLUDED.global_name,
              avatar_hash = EXCLUDED.avatar_hash,
              avatar_url = EXCLUDED.avatar_url,
              created_from_snowflake = EXCLUDED.created_from_snowflake,
              is_member = EXCLUDED.is_member,
              joined_dt = EXCLUDED.joined_dt,
              roles_synced_dt = EXCLUDED.roles_synced_dt,
              last_login_dt = CASE
                                  WHEN p_touch_last_login THEN EXCLUDED.last_login_dt
                                  ELSE web_priv.discord_users.last_login_dt
                              END
    RETURNING discord_user_id
         INTO v_discord_user_id;

    RETURN v_discord_user_id;
END;
$$;


ALTER FUNCTION web_priv.discord_user_upsert_from_login(p_auth_user_id bigint, p_discord_id character varying, p_username text, p_global_name text, p_avatar_hash text, p_avatar_url text, p_created_from_snowflake timestamp with time zone, p_is_member boolean, p_joined_dt timestamp with time zone, p_sync_dt timestamp with time zone, p_touch_last_login boolean) OWNER TO cm;

