--
-- Name: web_category_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_assert_can_delete(p_category_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_category_assert_can_delete                                                        ////
--//// PURPOSE: Raises when a category is still referenced by named current child or content rows                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT c.title
	INTO v_subject_label
	FROM web_priv.web_categories c
	WHERE c.category_id = p_category_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_category_id::text);

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_subcategories s
	WHERE s.category_id = p_category_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.subcategory_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title,
					 s.subcategory_id
			  FROM web_priv.web_subcategories s
			  WHERE s.category_id = p_category_id
			  ORDER BY s.title,
					   s.subcategory_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'category', v_subject_label, 'subcategory', 'subcategories', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_media m
	WHERE m.category_id = p_category_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.media_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename) AS label,
					 m.media_id
			  FROM web_priv.web_media m
			  WHERE m.category_id = p_category_id
			  ORDER BY COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename),
					   m.media_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'category', v_subject_label, 'media item', 'media items', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_series s
	WHERE s.category_id = p_category_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.series_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title,
					 s.series_id
			  FROM web_priv.web_series s
			  WHERE s.category_id = p_category_id
			  ORDER BY s.title,
					   s.series_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'category', v_subject_label, 'series', 'series', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content wc
	WHERE wc.category_id = p_category_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' (' || wc.status_code || ')' AS label,
					 wc.content_id
			  FROM web_priv.web_content wc
			  WHERE wc.category_id = p_category_id
			  ORDER BY wc.title,
					   wc.content_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'category', v_subject_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


ALTER FUNCTION web_priv.web_category_assert_can_delete(p_category_id bigint) OWNER TO cm;

--
-- Name: web_category_recalculate_dependents(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_recalculate_dependents(p_category_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECALCULATES CATEGORY-DEPENDENT SUBCATEGORY AND SERIES EFFECTIVE FIELDS                                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_series_id bigint;
BEGIN
    PERFORM web_priv.web_category_recalculate_subcategories(p_category_id);

    FOR v_series_id IN
        SELECT s.series_id
          FROM web_priv.web_series AS s
         WHERE s.category_id = p_category_id
    LOOP
        PERFORM web_priv.web_series_recalculate_effective(v_series_id);
    END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_category_recalculate_dependents(p_category_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_category_recalculate_dependents(p_category_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_category_recalculate_dependents(p_category_id bigint) IS 'Recalculates dependent subcategory and series effective fields for a category row.';


--
-- Name: web_category_recalculate_subcategories(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_recalculate_subcategories(p_category_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE web_priv.web_subcategories s
       SET read_effective_policy_code = CASE
               WHEN s.read_policy_code = 'inherit' THEN c.read_effective_policy_code
               ELSE s.read_policy_code
           END,
           read_effective_rank = CASE
               WHEN s.read_policy_code = 'inherit' THEN c.read_effective_rank
               WHEN s.read_policy_code = 'public' THEN NULL
               ELSE s.read_rank
           END,
           write_effective_policy_code = CASE
               WHEN s.write_policy_code = 'inherit' THEN c.write_effective_policy_code
               ELSE s.write_policy_code
           END,
           write_effective_rank = CASE
               WHEN s.write_policy_code = 'inherit' THEN c.write_effective_rank
               ELSE s.write_rank
           END,
           nav_hidden_effective = CASE
               WHEN s.nav_hidden_mode_code = 'inherit' THEN c.nav_hidden
               ELSE COALESCE(s.nav_hidden, false)
           END
      FROM web_priv.web_categories c
     WHERE c.category_id = p_category_id
       AND s.category_id = c.category_id;
END;
$$;


ALTER FUNCTION web_priv.web_category_recalculate_subcategories(p_category_id bigint) OWNER TO cm;

--
-- Name: web_category_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_record_history(p_category_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_categories_h
       SET is_current = false
     WHERE category_id = p_category_id
       AND is_current = true;

    SELECT COALESCE(MAX(version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_categories_h
     WHERE category_id = p_category_id;

    INSERT INTO web_priv.web_categories_h (
        category_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        title,
        slug,
        nav_hidden,
        read_policy_code,
        read_rank,
        write_policy_code,
        write_rank,
        icon_key_id,
        icon_color_id,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        c.category_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        c.title,
        c.slug,
        c.nav_hidden,
        c.read_policy_code,
        c.read_rank,
        c.write_policy_code,
        c.write_rank,
        c.icon_key_id,
        c.icon_color_id,
        c.created_by_discord_id,
        c.created_dt,
        c.updated_by_discord_id,
        c.updated_dt
      FROM web_priv.web_categories c
     WHERE c.category_id = p_category_id;
END;
$$;


ALTER FUNCTION web_priv.web_category_record_history(p_category_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_category_template_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_template_record_history(p_category_template_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CATEGORY-TEMPLATE RELATION HISTORY SNAPSHOT                                                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_category_template_r_h
       SET is_current = false
     WHERE category_template_id = p_category_template_id
       AND is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_category_template_r_h h
     WHERE h.category_template_id = p_category_template_id;

    INSERT INTO web_priv.web_category_template_r_h (
        category_template_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        category_id,
        template_id,
        is_enabled,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        r.category_template_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        r.category_id,
        r.template_id,
        r.is_enabled,
        r.created_by_discord_id,
        r.created_dt,
        r.updated_by_discord_id,
        r.updated_dt
      FROM web_priv.web_category_template_r r
     WHERE r.category_template_id = p_category_template_id;
END;
$$;


ALTER FUNCTION web_priv.web_category_template_record_history(p_category_template_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_category_template_replace(character varying, bigint, bigint[]); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_category_template_replace(p_actor_discord_id character varying, p_category_id bigint, p_template_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// REPLACES THE FULL ALLOWED TEMPLATE SET FOR ONE CATEGORY                                                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_existing record;
    v_template_id bigint;
    v_category_template_id bigint;
    v_template_ids bigint[];
BEGIN
    v_template_ids := COALESCE(p_template_ids, ARRAY[]::bigint[]);

    FOR v_existing IN
        SELECT r.*
          FROM web_priv.web_category_template_r r
         WHERE r.category_id = p_category_id
           AND NOT (r.template_id = ANY (v_template_ids))
    LOOP
        PERFORM web_priv.web_category_template_record_history(v_existing.category_template_id, 'delete', p_actor_discord_id);
        DELETE FROM web_priv.web_category_template_r
         WHERE category_template_id = v_existing.category_template_id;
    END LOOP;

    FOREACH v_template_id IN ARRAY v_template_ids LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM web_priv.web_category_template_r r
             WHERE r.category_id = p_category_id
               AND r.template_id = v_template_id
        ) THEN
            INSERT INTO web_priv.web_category_template_r (
                category_id,
                template_id,
                is_enabled,
                created_by_discord_id,
                updated_by_discord_id
            ) VALUES (
                p_category_id,
                v_template_id,
                true,
                p_actor_discord_id,
                p_actor_discord_id
            )
            RETURNING category_template_id
                 INTO v_category_template_id;

            PERFORM web_priv.web_category_template_record_history(v_category_template_id, 'create', p_actor_discord_id);
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_category_template_replace(p_actor_discord_id character varying, p_category_id bigint, p_template_ids bigint[]) OWNER TO cm;

--
-- Name: web_content_assert_actor_can_author(character varying, text, bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_assert_actor_can_author(p_actor_discord_id character varying, p_surface_scope_code text, p_category_id bigint, p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT THE ACTOR MAY AUTHOR CONTENT IN THE REQUESTED SURFACE AND PLACEMENT                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_policy_code text;
    v_policy_rank integer;
BEGIN
    IF p_surface_scope_code = 'admin' THEN
        PERFORM web_priv.actor_assert_is_admin_or_editor(p_actor_discord_id);
        RETURN;
    END IF;

    IF p_surface_scope_code <> 'public' THEN
        RAISE EXCEPTION 'Unsupported surface scope %.', p_surface_scope_code;
    END IF;

    SELECT
        COALESCE(sc.write_effective_policy_code, c.write_effective_policy_code),
        COALESCE(sc.write_effective_rank, c.write_effective_rank)
      INTO v_policy_code,
           v_policy_rank
      FROM web_priv.web_categories c
      LEFT JOIN web_priv.web_subcategories sc
        ON sc.subcategory_id = p_subcategory_id
     WHERE c.category_id = p_category_id;

    IF v_policy_code IS NULL THEN
        RAISE EXCEPTION 'Could not resolve effective write policy for category % and subcategory %.', p_category_id, p_subcategory_id;
    END IF;

    PERFORM web_priv.actor_assert_can_meet_rank_policy(
        p_actor_discord_id,
        v_policy_code,
        v_policy_rank,
        'public content authoring'
    );
END;
$$;


ALTER FUNCTION web_priv.web_content_assert_actor_can_author(p_actor_discord_id character varying, p_surface_scope_code text, p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_content_assert_category_subcategory(bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_assert_category_subcategory(p_category_id bigint, p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT CATEGORY AND OPTIONAL SUBCATEGORY FORM A VALID PLACEMENT                                        ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_subcategory_category_id bigint;
BEGIN
    PERFORM 1
      FROM web_priv.web_categories c
     WHERE c.category_id = p_category_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Category % was not found.', p_category_id;
    END IF;

    IF p_subcategory_id IS NULL THEN
        RETURN;
    END IF;

    SELECT s.category_id
      INTO v_subcategory_category_id
      FROM web_priv.web_subcategories s
     WHERE s.subcategory_id = p_subcategory_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Subcategory % was not found.', p_subcategory_id;
    END IF;

    IF v_subcategory_category_id <> p_category_id THEN
        RAISE EXCEPTION 'Subcategory % does not belong to category %.', p_subcategory_id, p_category_id;
    END IF;
END;
$$;


ALTER FUNCTION web_priv.web_content_assert_category_subcategory(p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_content_assert_resolved_icon_defaults(bigint, text, bigint, text, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_assert_resolved_icon_defaults(p_template_id bigint, p_icon_mode_code text, p_icon_key_id bigint, p_icon_color_mode_code text, p_icon_color_id bigint) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT THE REQUEST CAN RESOLVE A NON-NULL EFFECTIVE ICON AND COLOR                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_template_default_icon_key_id bigint;
    v_template_default_icon_color_id bigint;
BEGIN
    SELECT
        t.default_icon_key_id,
        t.default_icon_color_id
      INTO v_template_default_icon_key_id,
           v_template_default_icon_color_id
      FROM web_priv.web_templates t
     WHERE t.template_id = p_template_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template % was not found while validating icon defaults.', p_template_id;
    END IF;

    IF p_icon_mode_code = 'template_default' AND v_template_default_icon_key_id IS NULL THEN
        RAISE EXCEPTION 'Template % does not define default_icon_key_id, so icon_mode_code template_default cannot be used.', p_template_id;
    END IF;

    IF p_icon_color_mode_code = 'template_default' AND v_template_default_icon_color_id IS NULL THEN
        RAISE EXCEPTION 'Template % does not define default_icon_color_id, so icon_color_mode_code template_default cannot be used.', p_template_id;
    END IF;

    IF p_icon_mode_code = 'explicit' AND p_icon_key_id IS NULL THEN
        RAISE EXCEPTION 'icon_key_id is required when icon_mode_code = explicit.';
    END IF;

    IF p_icon_color_mode_code = 'explicit' AND p_icon_color_id IS NULL THEN
        RAISE EXCEPTION 'icon_color_id is required when icon_color_mode_code = explicit.';
    END IF;
END;
$$;


ALTER FUNCTION web_priv.web_content_assert_resolved_icon_defaults(p_template_id bigint, p_icon_mode_code text, p_icon_key_id bigint, p_icon_color_mode_code text, p_icon_color_id bigint) OWNER TO cm;

--
-- Name: web_content_assert_series_input(bigint, bigint, integer, bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_assert_series_input(p_template_id bigint, p_series_id bigint, p_series_part_no integer, p_category_id bigint, p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT SERIES INPUT SATISFIES THE TEMPLATE REQUIREMENT AND PLACEMENT                                   ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_requires_series boolean;
    v_series_category_id bigint;
    v_series_subcategory_id bigint;
BEGIN
    SELECT t.requires_series
      INTO v_requires_series
      FROM web_priv.web_templates t
     WHERE t.template_id = p_template_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template % was not found while validating series input.', p_template_id;
    END IF;

    IF v_requires_series = true AND (p_series_id IS NULL OR p_series_part_no IS NULL) THEN
        RAISE EXCEPTION 'Template % requires both series_id and series_part_no.', p_template_id;
    END IF;

    IF p_series_id IS NULL AND p_series_part_no IS NOT NULL THEN
        RAISE EXCEPTION 'series_part_no cannot be provided without series_id.';
    END IF;

    IF p_series_id IS NULL THEN
        RETURN;
    END IF;

    IF COALESCE(p_series_part_no, 0) < 1 THEN
        RAISE EXCEPTION 'series_part_no must be at least 1 when series_id is provided.';
    END IF;

    SELECT
        s.category_id,
        s.subcategory_id
      INTO v_series_category_id,
           v_series_subcategory_id
      FROM web_priv.web_series s
     WHERE s.series_id = p_series_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Series % was not found.', p_series_id;
    END IF;

    IF v_series_category_id <> p_category_id THEN
        RAISE EXCEPTION 'Series % belongs to category % instead of category %.', p_series_id, v_series_category_id, p_category_id;
    END IF;

    IF v_series_subcategory_id IS NOT NULL
       AND v_series_subcategory_id <> p_subcategory_id THEN
        RAISE EXCEPTION 'Series % belongs to subcategory % instead of subcategory %.', p_series_id, v_series_subcategory_id, p_subcategory_id;
    END IF;
END;
$$;


ALTER FUNCTION web_priv.web_content_assert_series_input(p_template_id bigint, p_series_id bigint, p_series_part_no integer, p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_content_assert_template_allowed(bigint, bigint, bigint, text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_assert_template_allowed(p_template_id bigint, p_category_id bigint, p_subcategory_id bigint, p_surface_scope_code text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// ASSERTS THAT A TEMPLATE IS ENABLED, SURFACE-COMPATIBLE, AND ALLOWED FOR THE REQUESTED PLACEMENT            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_template record;
    v_allowed boolean := false;
    v_surface_scope_code text;
BEGIN
    v_surface_scope_code := COALESCE(NULLIF(BTRIM(LOWER(p_surface_scope_code)), ''), 'admin');

    SELECT t.template_id,
           t.surface_scope_code,
           t.is_enabled
    INTO v_template
    FROM web_priv.web_templates t
    WHERE t.template_id = p_template_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template % was not found.', p_template_id;
    END IF;

    IF v_template.is_enabled = false THEN
        RAISE EXCEPTION 'Template % is disabled.', p_template_id;
    END IF;

    IF v_surface_scope_code = 'admin' THEN
        IF v_template.surface_scope_code NOT IN ('admin', 'public') THEN
            RAISE EXCEPTION 'Template % is not allowed for admin content authoring.', p_template_id;
        END IF;
    ELSIF v_surface_scope_code = 'public' THEN
        IF v_template.surface_scope_code <> 'public' THEN
            RAISE EXCEPTION 'Template % is not allowed for surface %.', p_template_id, v_surface_scope_code;
        END IF;
    ELSE
        RAISE EXCEPTION 'Unsupported template surface scope: %.', v_surface_scope_code;
    END IF;

    IF p_subcategory_id IS NOT NULL THEN
        SELECT EXISTS (SELECT 1
                      FROM web_priv.web_subcategory_template_r r
                      WHERE r.subcategory_id = p_subcategory_id
                        AND r.template_id = p_template_id
                        AND r.is_enabled = true)
        INTO v_allowed;
    END IF;

    IF COALESCE(v_allowed, false) = false THEN
        SELECT EXISTS (SELECT 1
                      FROM web_priv.web_category_template_r r
                      WHERE r.category_id = p_category_id
                        AND r.template_id = p_template_id
                        AND r.is_enabled = true)
        INTO v_allowed;
    END IF;

    IF COALESCE(v_allowed, false) = false THEN
        RAISE EXCEPTION 'Template % is not allowed for category % and subcategory %.', p_template_id, p_category_id, p_subcategory_id;
    END IF;
END;
$$;


ALTER FUNCTION web_priv.web_content_assert_template_allowed(p_template_id bigint, p_category_id bigint, p_subcategory_id bigint, p_surface_scope_code text) OWNER TO cm;

--
-- Name: web_content_current_public_path(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_current_public_path(p_content_id bigint) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_current_public_path                                                         ////
--//// PURPOSE: Returns the current canonical public path for renderable content routes                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT CASE
		   WHEN ck.renderer_code = 'external_link' THEN NULL
		   WHEN NULLIF(BTRIM(ck.public_route_prefix), '') IS NULL
			   THEN '/' || LOWER(cat.slug) || '/' || LOWER(sc.slug) || '/' || LOWER(c.slug)
		   ELSE '/' || LOWER(ck.public_route_prefix) || '/' || LOWER(cat.slug) || '/' || LOWER(sc.slug) || '/' || LOWER(c.slug)
	   END
FROM web_priv.web_content c
JOIN web_priv.web_templates t ON t.template_id = c.template_id
JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
WHERE c.content_id = p_content_id
LIMIT 1;
$$;


ALTER FUNCTION web_priv.web_content_current_public_path(p_content_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_content_current_public_path(p_content_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_current_public_path(p_content_id bigint) IS 'Returns the current canonical public path for renderable content routes. External-link content returns NULL because its public href is resolved from the registered external link field instead of an internal content route.';


--
-- Name: web_content_external_link_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_external_link_record_history(p_content_external_link_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CONTENT EXTERNAL LINK HISTORY SNAPSHOT                                                             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_content_external_link_r_h
       SET is_current = false
     WHERE content_external_link_id = p_content_external_link_id
       AND is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_content_external_link_r_h h
     WHERE h.content_external_link_id = p_content_external_link_id;

    INSERT INTO web_priv.web_content_external_link_r_h (
        content_external_link_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        content_id,
        template_field_id,
        source_kind_code,
        value_seq_no,
        link_index_no,
        display_text,
        normalized_url,
        url_scheme,
        url_host,
        url_path,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        r.content_external_link_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        r.content_id,
        r.template_field_id,
        r.source_kind_code,
        r.value_seq_no,
        r.link_index_no,
        r.display_text,
        r.normalized_url,
        r.url_scheme,
        r.url_host,
        r.url_path,
        r.created_by_discord_id,
        r.created_dt,
        r.updated_by_discord_id,
        r.updated_dt
      FROM web_priv.web_content_external_link_r r
     WHERE r.content_external_link_id = p_content_external_link_id;
END;
$$;


