--
-- Name: web_content_is_external_host_allowed(text, text, timestamp with time zone); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_is_external_host_allowed(p_url_host text, p_surface_scope_code text, p_reference_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// BACKWARD-COMPATIBILITY WRAPPER FOR HOST-ONLY EXTERNAL LINK CHECKS                                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT web_priv.web_content_is_external_link_allowed(p_url_host, '/', p_surface_scope_code, p_reference_dt)
;
$$;


ALTER FUNCTION web_priv.web_content_is_external_host_allowed(p_url_host text, p_surface_scope_code text, p_reference_dt timestamp with time zone) OWNER TO cm;

--
-- Name: web_content_is_external_link_allowed(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_is_external_link_allowed(p_url_host text, p_url_path text, p_surface_scope_code text, p_reference_dt timestamp with time zone DEFAULT CURRENT_TIMESTAMP) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// CHECKS THE WHITELIST FOR A NORMALIZED EXTERNAL LINK HOST AND PATH                                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT EXISTS (SELECT 1
			   FROM web_priv.web_external_link_host_c h
			   WHERE h.is_enabled = true
				 AND h.allowed_surface_scope_code IN (p_surface_scope_code, 'all')
				 AND (h.valid_from_dt IS NULL OR h.valid_from_dt <= p_reference_dt::date)
				 AND (h.valid_to_dt IS NULL OR h.valid_to_dt >= p_reference_dt::date)
				 AND h.host_match_mode_code = 'exact_host'
				 AND lower(btrim(p_url_host)) = h.host_pattern
				 AND (h.path_match_mode_code = 'any_path'
				   OR (h.path_match_mode_code = 'exact_path' AND COALESCE(NULLIF(btrim(p_url_path), ''), '/') = h.path_pattern)
				   OR (h.path_match_mode_code = 'path_prefix' AND (COALESCE(NULLIF(btrim(p_url_path), ''), '/') = h.path_pattern
															 OR COALESCE(NULLIF(btrim(p_url_path), ''), '/') LIKE (h.path_pattern || '/%')))))
;
$$;


ALTER FUNCTION web_priv.web_content_is_external_link_allowed(p_url_host text, p_url_path text, p_surface_scope_code text, p_reference_dt timestamp with time zone) OWNER TO cm;

