											 updated_dt)
	SELECT ck.content_kind_code,
		   v_version_no,
		   p_change_type <> 'delete',
		   p_change_type,
		   p_changed_by_discord_id,
		   CURRENT_TIMESTAMP,
		   ck.label,
		   ck.description,
		   ck.public_route_prefix,
		   ck.renderer_code,
