--
-- Name: web_content_make_unique_slug(text, bigint, bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_make_unique_slug(p_slug text, p_category_id bigint, p_subcategory_id bigint, p_exclude_content_id bigint DEFAULT NULL::bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_make_unique_slug                                                          ////
--//// PURPOSE: Returns a normalized unique content slug inside one category/subcategory URL scope                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_base_slug text;
	v_candidate_slug text;
	v_suffix integer := 1;
BEGIN
	v_base_slug := LOWER(NULLIF(BTRIM(p_slug), ''));

	IF v_base_slug IS NULL THEN
		RAISE EXCEPTION 'Content slug is required.';
	END IF;

	v_candidate_slug := v_base_slug;

	LOOP
		IF NOT EXISTS (SELECT 1
					   FROM web_priv.web_content c
					   WHERE c.category_id = p_category_id
					     AND c.subcategory_id IS NOT DISTINCT FROM p_subcategory_id
					     AND LOWER(c.slug) = v_candidate_slug
					     AND (p_exclude_content_id IS NULL OR c.content_id <> p_exclude_content_id)) THEN
			RETURN v_candidate_slug;
		END IF;

		v_suffix := v_suffix + 1;
		v_candidate_slug := v_base_slug || '-' || v_suffix::text;
	END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_content_make_unique_slug(p_slug text, p_category_id bigint, p_subcategory_id bigint, p_exclude_content_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_content_make_unique_slug(p_slug text, p_category_id bigint, p_subcategory_id bigint, p_exclude_content_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_make_unique_slug(p_slug text, p_category_id bigint, p_subcategory_id bigint, p_exclude_content_id bigint) IS 'Returns a collision-safe content slug in the same category/subcategory route scope.';


--
-- Name: web_content_media_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_media_record_history(p_content_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_media_record_history                                                       ////
--//// PURPOSE: Writes an explicit history snapshot for a content-media relationship row.                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_row web_priv.web_content_media_r%ROWTYPE;
	v_next_version_no integer;
BEGIN
	IF p_change_type NOT IN ('create', 'update', 'delete') THEN
		RAISE EXCEPTION 'Unsupported content-media history change_type: %.', p_change_type;
	END IF;

	SELECT r.*
	INTO v_row
	FROM web_priv.web_content_media_r r
	WHERE r.content_media_id = p_content_media_id
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'content-media row % was not found while recording history.', p_content_media_id;
	END IF;

	UPDATE web_priv.web_content_media_r_h h
	SET is_current = false
	WHERE h.content_media_id = p_content_media_id
	  AND h.is_current = true
	;

	SELECT COALESCE(MAX(h.version_no), 0) + 1
	INTO v_next_version_no
	FROM web_priv.web_content_media_r_h h
	WHERE h.content_media_id = p_content_media_id
	;

	INSERT INTO web_priv.web_content_media_r_h(content_media_id,
											   version_no,
											   is_current,
											   change_type,
											   changed_by_discord_id,
											   changed_dt,
											   content_id,
											   media_id,
											   usage_code,
											   display_order,
											   caption,
											   created_by_discord_id,
											   created_dt,
											   updated_by_discord_id,
											   updated_dt)
	VALUES (v_row.content_media_id,
			v_next_version_no,
			true,
			p_change_type,
			NULLIF(BTRIM(p_changed_by_discord_id), ''),
			CURRENT_TIMESTAMP,
			v_row.content_id,
			v_row.media_id,
			v_row.usage_code,
			v_row.display_order,
			v_row.caption,
			v_row.created_by_discord_id,
			v_row.created_dt,
			v_row.updated_by_discord_id,
			v_row.updated_dt);
END;
$$;


ALTER FUNCTION web_priv.web_content_media_record_history(p_content_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: FUNCTION web_content_media_record_history(p_content_media_id bigint, p_change_type text, p_changed_by_discord_id character varying); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_media_record_history(p_content_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) IS 'Writes a current-row snapshot into web_content_media_r_h and marks older snapshots as non-current.';


--
-- Name: web_content_media_replace(character varying, bigint, jsonb); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_media_replace(p_actor_discord_id character varying, p_content_id bigint, p_media_refs jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_media_replace                                                              ////
--//// PURPOSE: Replaces the structured media references for one content row without scanning content at read time. ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_row record;
	v_existing record;
	v_inserted_id bigint;
	v_input_count integer;
	v_unique_count integer;
BEGIN
	IF p_content_id IS NULL THEN
		RAISE EXCEPTION 'p_content_id is required.';
	END IF;

	PERFORM 1
	FROM web_priv.web_content c
	WHERE c.content_id = p_content_id
	;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'content % was not found.', p_content_id;
	END IF;

	IF jsonb_typeof(COALESCE(p_media_refs, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_media_refs must be a JSON array.';
	END IF;

	SELECT COUNT(*)
	INTO v_input_count
	FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																			usage_code text,
																			display_order integer,
																			caption text)
	;

	SELECT COUNT(*)
	INTO v_unique_count
	FROM (SELECT DISTINCT parsed.media_id,
							NULLIF(BTRIM(LOWER(parsed.usage_code)), '') AS usage_code
		  FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																				  usage_code text,
																				  display_order integer,
																				  caption text)) src
	;

	IF v_input_count <> v_unique_count THEN
		RAISE EXCEPTION 'p_media_refs contains duplicate (media_id, usage_code) rows.';
	END IF;

	FOR v_row IN
		SELECT parsed.media_id,
			   NULLIF(BTRIM(LOWER(parsed.usage_code)), '') AS usage_code,
			   COALESCE(parsed.display_order, 1) AS display_order,
			   NULLIF(BTRIM(parsed.caption), '') AS caption
		FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																				usage_code text,
																				display_order integer,
																				caption text)
	LOOP
		IF v_row.media_id IS NULL THEN
			RAISE EXCEPTION 'content media reference media_id is required.';
		END IF;

		IF v_row.usage_code IS NULL THEN
			RAISE EXCEPTION 'content media reference usage_code is required.';
		END IF;

		IF v_row.display_order < 1 THEN
			RAISE EXCEPTION 'content media reference display_order must be positive.';
		END IF;

		PERFORM 1
		FROM web_priv.web_media m
		WHERE m.media_id = v_row.media_id
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'media % was not found.', v_row.media_id;
		END IF;
	END LOOP;

	FOR v_existing IN
		SELECT r.content_media_id
		FROM web_priv.web_content_media_r r
		WHERE r.content_id = p_content_id
		  AND NOT EXISTS (SELECT 1
						  FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																								  usage_code text,
																								  display_order integer,
																								  caption text)
						  WHERE parsed.media_id = r.media_id
						    AND NULLIF(BTRIM(LOWER(parsed.usage_code)), '') = r.usage_code)
	LOOP
		PERFORM web_priv.web_content_media_record_history(v_existing.content_media_id,
														  'delete',
														  p_actor_discord_id);
	END LOOP;

	DELETE FROM web_priv.web_content_media_r r
	WHERE r.content_id = p_content_id
	  AND NOT EXISTS (SELECT 1
					  FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																							  usage_code text,
																							  display_order integer,
																							  caption text)
					  WHERE parsed.media_id = r.media_id
					    AND NULLIF(BTRIM(LOWER(parsed.usage_code)), '') = r.usage_code)
	;

	FOR v_row IN
		SELECT r.content_media_id,
			   COALESCE(parsed.display_order, 1) AS display_order,
			   NULLIF(BTRIM(parsed.caption), '') AS caption
		FROM web_priv.web_content_media_r r
		JOIN jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																			   usage_code text,
																			   display_order integer,
																			   caption text) ON parsed.media_id = r.media_id
																						AND NULLIF(BTRIM(LOWER(parsed.usage_code)), '') = r.usage_code
		WHERE r.content_id = p_content_id
		  AND (r.display_order IS DISTINCT FROM COALESCE(parsed.display_order, 1)
		   OR r.caption IS DISTINCT FROM NULLIF(BTRIM(parsed.caption), ''))
	LOOP
		UPDATE web_priv.web_content_media_r r
		SET display_order = v_row.display_order,
			caption = v_row.caption,
			updated_by_discord_id = NULLIF(BTRIM(p_actor_discord_id), ''),
			updated_dt = CURRENT_TIMESTAMP
		WHERE r.content_media_id = v_row.content_media_id
		;

		PERFORM web_priv.web_content_media_record_history(v_row.content_media_id,
														  'update',
														  p_actor_discord_id);
	END LOOP;

	FOR v_row IN
		SELECT parsed.media_id,
			   NULLIF(BTRIM(LOWER(parsed.usage_code)), '') AS usage_code,
			   COALESCE(parsed.display_order, 1) AS display_order,
			   NULLIF(BTRIM(parsed.caption), '') AS caption
		FROM jsonb_to_recordset(COALESCE(p_media_refs, '[]'::jsonb)) AS parsed(media_id bigint,
																				usage_code text,
																				display_order integer,
																				caption text)
		WHERE NOT EXISTS (SELECT 1
						  FROM web_priv.web_content_media_r r
						  WHERE r.content_id = p_content_id
						    AND r.media_id = parsed.media_id
						    AND r.usage_code = NULLIF(BTRIM(LOWER(parsed.usage_code)), ''))
		ORDER BY COALESCE(parsed.display_order, 1),
				 parsed.media_id
	LOOP
		INSERT INTO web_priv.web_content_media_r(content_id,
												 media_id,
												 usage_code,
												 display_order,
												 caption,
												 created_by_discord_id,
												 updated_by_discord_id)
		VALUES (p_content_id,
				v_row.media_id,
				v_row.usage_code,
				v_row.display_order,
				v_row.caption,
				NULLIF(BTRIM(p_actor_discord_id), ''),
				NULLIF(BTRIM(p_actor_discord_id), ''))
		RETURNING content_media_id
		INTO v_inserted_id;

		PERFORM web_priv.web_content_media_record_history(v_inserted_id,
														  'create',
														  p_actor_discord_id);
	END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_content_media_replace(p_actor_discord_id character varying, p_content_id bigint, p_media_refs jsonb) OWNER TO cm;

--
-- Name: FUNCTION web_content_media_replace(p_actor_discord_id character varying, p_content_id bigint, p_media_refs jsonb); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_media_replace(p_actor_discord_id character varying, p_content_id bigint, p_media_refs jsonb) IS 'Replaces explicit media references for one content row and records history without requiring public media requests to inspect content JSON.';


--
-- Name: web_content_normalize_public_path(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_normalize_public_path(p_raw_path text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_normalize_public_path                                                       ////
--//// PURPOSE: Normalizes and validates full public content paths used by internal links and redirects           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_path text;
	v_trimmed_path text;
	v_parts text[];
	v_part_count integer;
BEGIN
	v_path := btrim(COALESCE(p_raw_path, ''));

	IF v_path = '' THEN
		RAISE EXCEPTION 'Public path is required.';
	END IF;

	IF v_path !~ '^/' THEN
		RAISE EXCEPTION 'Public path must start with /.';
	END IF;

	IF v_path LIKE '//%' THEN
		RAISE EXCEPTION 'Protocol-relative paths are not allowed.';
	END IF;

	IF POSITION('?' IN v_path) > 0 OR POSITION('#' IN v_path) > 0 THEN
		RAISE EXCEPTION 'Public paths cannot include query strings or anchors.';
	END IF;

	IF v_path ~ '[[:space:]]' OR v_path LIKE '%' || CHR(92) || '%' THEN
		RAISE EXCEPTION 'Public paths cannot include whitespace or backslashes.';
	END IF;

	IF LOWER(v_path) ~ '(%2e|%2f|%5c|%00)' OR v_path ~ '(^|/)\.\.(/|$)' THEN
		RAISE EXCEPTION 'Public paths cannot include encoded separators or path traversal.';
	END IF;

	IF v_path ~* '^/(admin|api|auth|login|logout|_next|media|uploads)(/|$)' THEN
		RAISE EXCEPTION 'Public paths must point to content routes.';
	END IF;

	v_trimmed_path := btrim(v_path, '/');

	IF v_trimmed_path = '' THEN
		RAISE EXCEPTION 'Public paths must point to content routes.';
	END IF;

	v_parts := regexp_split_to_array(v_trimmed_path, '/');
	v_part_count := cardinality(v_parts);

	IF '' = ANY(v_parts) THEN
		RAISE EXCEPTION 'Public paths cannot include empty path segments.';
	END IF;

	IF v_part_count = 3 THEN
		RETURN '/' || lower(v_parts[1]) || '/' || lower(v_parts[2]) || '/' || lower(v_parts[3]);
	END IF;

	IF v_part_count = 4 AND lower(v_parts[1]) IN ('map', 'tool', 'app', 'event', 'custom', 'video') THEN
		RETURN '/' || lower(v_parts[1]) || '/' || lower(v_parts[2]) || '/' || lower(v_parts[3]) || '/' || lower(v_parts[4]);
	END IF;

	RAISE EXCEPTION 'Public paths must point to a content route.';
END;
$_$;


ALTER FUNCTION web_priv.web_content_normalize_public_path(p_raw_path text) OWNER TO cm;

--
-- Name: web_content_parse_external_url(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_parse_external_url(p_raw_url text) RETURNS TABLE(url_scheme text, url_host text, url_path text, normalized_url text)
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_parse_external_url                                                        ////
--//// PURPOSE: Normalizes a raw external link into HTTPS, host, whitelist path, and canonical storage text      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_trimmed text;
	v_after_scheme text;
	v_host_port text;
	v_rest text;
	v_path_part text;
	v_suffix text;
	v_query_pos integer;
	v_hash_pos integer;
	v_split_pos integer;
BEGIN
	v_trimmed := btrim(COALESCE(p_raw_url, ''));

	IF v_trimmed = '' THEN
		RAISE EXCEPTION 'External URL cannot be blank.';
	END IF;

	IF v_trimmed LIKE '//%' THEN
		RAISE EXCEPTION 'External URL % must not be protocol-relative.', v_trimmed;
	END IF;

	IF v_trimmed ~* '^[a-z][a-z0-9+.-]*://' THEN
		url_scheme := lower(split_part(v_trimmed, '://', 1));
		IF url_scheme <> 'https' THEN
			RAISE EXCEPTION 'External URL % must use https.', v_trimmed;
		END IF;
		v_after_scheme := substring(v_trimmed from '^[A-Za-z][A-Za-z0-9+.\-]*://(.*)$');
	ELSIF v_trimmed ~* '^[a-z][a-z0-9+.-]*:' THEN
		RAISE EXCEPTION 'Unsupported external URL scheme for URL %.', v_trimmed;
	ELSE
		url_scheme := 'https';
		v_after_scheme := v_trimmed;
	END IF;

	v_host_port := substring(v_after_scheme from '^[^/?#]+');
	IF COALESCE(v_host_port, '') = '' THEN
		RAISE EXCEPTION 'External URL % does not contain a valid host.', v_trimmed;
	END IF;

	v_rest := substring(v_after_scheme from length(v_host_port) + 1);
	v_rest := COALESCE(v_rest, '');

	IF position('@' IN v_host_port) > 0 THEN
		RAISE EXCEPTION 'External URL % must not include credentials.', v_trimmed;
	END IF;

	IF position(':' IN v_host_port) > 0 THEN
		RAISE EXCEPTION 'External URL % must not include a custom port.', v_trimmed;
	END IF;

	url_host := lower(v_host_port);
	IF right(url_host, 1) = '.' THEN
		url_host := left(url_host, length(url_host) - 1);
	END IF;

	IF url_host !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' THEN
		RAISE EXCEPTION 'External URL % does not contain a normalized host.', v_trimmed;
	END IF;

	v_query_pos := NULLIF(position('?' IN v_rest), 0);
	v_hash_pos  := NULLIF(position('#' IN v_rest), 0);

	IF v_query_pos IS NULL AND v_hash_pos IS NULL THEN
		v_split_pos := NULL;
	ELSIF v_query_pos IS NULL THEN
		v_split_pos := v_hash_pos;
	ELSIF v_hash_pos IS NULL THEN
		v_split_pos := v_query_pos;
	ELSE
		v_split_pos := LEAST(v_query_pos, v_hash_pos);
	END IF;

	IF v_split_pos IS NULL THEN
		v_path_part := v_rest;
		v_suffix := '';
	ELSE
		v_path_part := substring(v_rest from 1 for v_split_pos - 1);
		v_suffix := substring(v_rest from v_split_pos);
	END IF;

	url_path := COALESCE(NULLIF(v_path_part, ''), '/');
	IF left(url_path, 1) <> '/' THEN
		url_path := '/' || url_path;
	END IF;

	IF url_path !~ '^/[^[:space:]?#]*$'
	   OR position(CHR(92) in url_path) > 0
	   OR url_path LIKE '%..%'
	   OR url_path LIKE '%//%'
	   OR lower(url_path) ~ '(%2e|%2f|%5c|%00)' THEN
		RAISE EXCEPTION 'External URL % contains an unsupported path.', v_trimmed;
	END IF;

	IF v_suffix <> ''
	   AND (v_suffix ~ '[[:space:]]'
			OR v_suffix ~ '[[:cntrl:]]'
			OR position(CHR(92) in v_suffix) > 0
			OR v_suffix ~ '[<>"'']') THEN
		RAISE EXCEPTION 'External URL % contains an unsupported query string or anchor.', v_trimmed;
	END IF;

	normalized_url := url_scheme || '://' || url_host || url_path || v_suffix;
	RETURN NEXT;
END;
$_$;


ALTER FUNCTION web_priv.web_content_parse_external_url(p_raw_url text) OWNER TO cm;

--
-- Name: FUNCTION web_content_parse_external_url(p_raw_url text); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_parse_external_url(p_raw_url text) IS 'Normalizes external links to HTTPS, validates host/path syntax, preserves safe query/hash suffixes, and returns path-only data for whitelist matching.';


--
-- Name: web_content_parse_public_path(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_parse_public_path(p_raw_path text) RETURNS TABLE(normalized_path text, public_route_prefix text, category_slug text, subcategory_slug text, content_slug text)
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_parse_public_path                                                           ////
--//// PURPOSE: Parses a normalized full public content path into route lookup parts                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_path text;
	v_parts text[];
BEGIN
	v_path := web_priv.web_content_normalize_public_path(p_raw_path);
	v_parts := regexp_split_to_array(btrim(v_path, '/'), '/');

	IF cardinality(v_parts) = 3 THEN
		normalized_path := v_path;
		public_route_prefix := NULL;
		category_slug := v_parts[1];
		subcategory_slug := v_parts[2];
		content_slug := v_parts[3];

		RETURN NEXT;
		RETURN;
	END IF;

	normalized_path := v_path;
	public_route_prefix := v_parts[1];
	category_slug := v_parts[2];
	subcategory_slug := v_parts[3];
	content_slug := v_parts[4];

	RETURN NEXT;
	RETURN;
END;
$$;


ALTER FUNCTION web_priv.web_content_parse_public_path(p_raw_path text) OWNER TO cm;

--
-- Name: FUNCTION web_content_parse_public_path(p_raw_path text); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_content_parse_public_path(p_raw_path text) IS 'Parses default and official prefixed public content paths, including /video/category/subcategory/content.';


--
-- Name: web_content_public_path_has_current_content(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_public_path_has_current_content(p_raw_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_public_path_has_current_content                                             ////
--//// PURPOSE: Checks whether a full public path is already occupied by current content                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
WITH parsed AS (
	SELECT *
	FROM web_priv.web_content_parse_public_path(p_raw_path)
	LIMIT 1
)
SELECT EXISTS (
	SELECT 1
	FROM parsed p
	JOIN web_priv.web_categories cat ON cat.slug = p.category_slug
	JOIN web_priv.web_subcategories sc ON sc.category_id = cat.category_id
									   AND sc.slug = p.subcategory_slug
	JOIN web_priv.web_content c ON c.category_id = cat.category_id
							   AND c.subcategory_id = sc.subcategory_id
							   AND c.slug = p.content_slug
	JOIN web_priv.web_templates t ON t.template_id = c.template_id
	JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
	WHERE COALESCE(ck.public_route_prefix, '') = COALESCE(p.public_route_prefix, '')
);
$$;


ALTER FUNCTION web_priv.web_content_public_path_has_current_content(p_raw_path text) OWNER TO cm;

--
-- Name: web_content_recalculate_effective(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_recalculate_effective(p_content_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECALCULATES EFFECTIVE POLICY, NAV, AND ICON VALUES FOR ONE CONTENT ROW                                      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    UPDATE web_priv.web_content c
       SET read_effective_policy_code = CASE
               WHEN c.read_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.read_effective_policy_code FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = c.subcategory_id),
                    (SELECT cat.read_effective_policy_code FROM web_priv.web_categories cat WHERE cat.category_id = c.category_id)
               )
               ELSE c.read_policy_code
           END,
           read_effective_rank = CASE
               WHEN c.read_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.read_effective_rank FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = c.subcategory_id),
                    (SELECT cat.read_effective_rank FROM web_priv.web_categories cat WHERE cat.category_id = c.category_id)
               )
               WHEN c.read_policy_code = 'public' THEN NULL
               ELSE c.read_rank
           END,
           write_effective_policy_code = CASE
               WHEN c.write_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.write_effective_policy_code FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = c.subcategory_id),
                    (SELECT cat.write_effective_policy_code FROM web_priv.web_categories cat WHERE cat.category_id = c.category_id)
               )
               ELSE c.write_policy_code
           END,
           write_effective_rank = CASE
               WHEN c.write_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.write_effective_rank FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = c.subcategory_id),
                    (SELECT cat.write_effective_rank FROM web_priv.web_categories cat WHERE cat.category_id = c.category_id)
               )
               ELSE c.write_rank
           END,
           nav_hidden_effective = CASE
               WHEN c.nav_hidden_mode_code = 'inherit' THEN COALESCE(
                    (SELECT sc.nav_hidden_effective FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = c.subcategory_id),
                    (SELECT cat.nav_hidden FROM web_priv.web_categories cat WHERE cat.category_id = c.category_id),
                    false
               )
               ELSE COALESCE(c.nav_hidden, false)
           END,
           icon_key_effective_id = CASE
               WHEN c.icon_mode_code = 'template_default' THEN (
                    SELECT t.default_icon_key_id
                      FROM web_priv.web_templates t
                     WHERE t.template_id = c.template_id
               )
               ELSE c.icon_key_id
           END,
           icon_color_effective_id = CASE
               WHEN c.icon_color_mode_code = 'template_default' THEN (
                    SELECT t.default_icon_color_id
                      FROM web_priv.web_templates t
                     WHERE t.template_id = c.template_id
               )
               ELSE c.icon_color_id
           END
     WHERE c.content_id = p_content_id;
END;
$$;


ALTER FUNCTION web_priv.web_content_recalculate_effective(p_content_id bigint) OWNER TO cm;

--
-- Name: web_content_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_record_history(p_content_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CURRENT-STATE HISTORY SNAPSHOT FOR WEB_CONTENT                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_content_h
       SET is_current = false
     WHERE content_id = p_content_id
       AND is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_content_h h
     WHERE h.content_id = p_content_id;

    INSERT INTO web_priv.web_content_h (
        content_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        template_id,
        template_schema_version_no,
        title,
        slug,
        summary,
        category_id,
        subcategory_id,
        series_id,
        series_part_no,
        author_discord_id,
        status_code,
        published_dt,
        archived_dt,
        read_policy_code,
        read_rank,
        write_policy_code,
        write_rank,
        nav_hidden_mode_code,
        nav_hidden,
        icon_mode_code,
        icon_key_id,
        icon_color_mode_code,
        icon_color_id,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        c.content_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        c.template_id,
        c.template_schema_version_no,
        c.title,
        c.slug,
        c.summary,
        c.category_id,
        c.subcategory_id,
        c.series_id,
        c.series_part_no,
        c.author_discord_id,
        c.status_code,
        c.published_dt,
        c.archived_dt,
        c.read_policy_code,
        c.read_rank,
        c.write_policy_code,
        c.write_rank,
        c.nav_hidden_mode_code,
        c.nav_hidden,
        c.icon_mode_code,
        c.icon_key_id,
        c.icon_color_mode_code,
        c.icon_color_id,
        c.created_by_discord_id,
        c.created_dt,
        c.updated_by_discord_id,
        c.updated_dt
      FROM web_priv.web_content c
     WHERE c.content_id = p_content_id;
END;
$$;


ALTER FUNCTION web_priv.web_content_record_history(p_content_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_content_redirect_ensure_for_path_change(character varying, bigint, text, text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_redirect_ensure_for_path_change(p_actor_discord_id character varying, p_content_id bigint, p_old_path text, p_new_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_redirect_ensure_for_path_change                                             ////
--//// PURPOSE: Creates or refreshes old-path redirects when a content row moves to a new public path              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_old_path text;
	v_new_path text;
BEGIN
	IF NULLIF(btrim(COALESCE(p_old_path, '')), '') IS NULL
	   OR NULLIF(btrim(COALESCE(p_new_path, '')), '') IS NULL THEN
		RETURN;
	END IF;

	v_old_path := web_priv.web_content_normalize_public_path(p_old_path);
	v_new_path := web_priv.web_content_normalize_public_path(p_new_path);

	IF v_old_path = v_new_path THEN
		RETURN;
	END IF;

	DELETE FROM web_priv.web_content_redirects r
	WHERE r.content_id = p_content_id
	  AND r.old_path = v_new_path;

	IF web_priv.web_content_public_path_has_current_content(v_old_path) THEN
		RETURN;
	END IF;

	INSERT INTO web_priv.web_content_redirects (
		content_id,
		old_path,
		redirect_type_code,
		is_enabled,
		created_by_discord_id,
		updated_by_discord_id
	)
	VALUES (
		p_content_id,
		v_old_path,
		'permanent',
		true,
		p_actor_discord_id,
		p_actor_discord_id
	)
	ON CONFLICT (old_path) DO UPDATE
	SET content_id = EXCLUDED.content_id,
		redirect_type_code = EXCLUDED.redirect_type_code,
		is_enabled = true,
		updated_by_discord_id = p_actor_discord_id,
		updated_dt = CURRENT_TIMESTAMP
	WHERE web_priv.web_content_redirects.content_id = EXCLUDED.content_id
	   OR web_priv.web_content_redirects.is_enabled = false;
END;
$$;


ALTER FUNCTION web_priv.web_content_redirect_ensure_for_path_change(p_actor_discord_id character varying, p_content_id bigint, p_old_path text, p_new_path text) OWNER TO cm;

--
-- Name: web_content_replace_external_links(character varying, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_replace_external_links(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_surface_scope_code text, p_external_links jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// REPLACES REGISTERED EXTERNAL LINKS FOR A CONTENT ROW USING CALLER-PROVIDED EXTRACTION INPUT                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_existing record;
	v_link record;
	v_parsed record;
	v_inserted_id bigint;
BEGIN
	IF jsonb_typeof(COALESCE(p_external_links, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_external_links must be a JSON array.';
	END IF;

	FOR v_existing IN
		SELECT r.content_external_link_id
		FROM web_priv.web_content_external_link_r r
		WHERE r.content_id = p_content_id
	LOOP
		PERFORM web_priv.web_content_external_link_record_history(v_existing.content_external_link_id,
													 'delete',
													 p_actor_discord_id);
	END LOOP;

	DELETE FROM web_priv.web_content_external_link_r r
	WHERE r.content_id = p_content_id;

	FOR v_link IN
		SELECT parsed.template_field_id,
			   COALESCE(parsed.value_seq_no, 1) AS value_seq_no,
			   COALESCE(parsed.link_index_no, 1) AS link_index_no,
			   COALESCE(parsed.source_kind_code, 'rich_text') AS source_kind_code,
			   parsed.raw_url,
			   NULLIF(btrim(parsed.link_text), '') AS display_text
		FROM jsonb_to_recordset(COALESCE(p_external_links, '[]'::jsonb)) AS parsed(template_field_id bigint,
																		 value_seq_no integer,
																		 link_index_no integer,
																		 source_kind_code text,
																		 raw_url text,
																		 link_text text)
	LOOP
		PERFORM 1
		FROM web_priv.web_template_fields tf
		WHERE tf.template_field_id = v_link.template_field_id
		  AND tf.template_id = p_template_id
		  AND tf.is_enabled = true;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'External link references template_field_id % that does not belong to template %.', v_link.template_field_id, p_template_id;
		END IF;

		SELECT *
		INTO v_parsed
		FROM web_priv.web_content_parse_external_url(v_link.raw_url);

		IF COALESCE(web_priv.web_content_is_external_link_allowed(v_parsed.url_host, v_parsed.url_path, p_surface_scope_code, CURRENT_TIMESTAMP), false) = false THEN
			RAISE EXCEPTION 'External link % is not allowed for surface %.', v_parsed.normalized_url, p_surface_scope_code;
		END IF;

		INSERT INTO web_priv.web_content_external_link_r(content_id,
												 template_field_id,
												 value_seq_no,
												 link_index_no,
												 source_kind_code,
												 url_scheme,
												 url_host,
												 url_path,
												 normalized_url,
												 display_text,
												 created_by_discord_id,
												 updated_by_discord_id)
		VALUES (p_content_id,
				v_link.template_field_id,
				v_link.value_seq_no,
				v_link.link_index_no,
				v_link.source_kind_code,
				v_parsed.url_scheme,
				v_parsed.url_host,
				v_parsed.url_path,
				v_parsed.normalized_url,
				v_link.display_text,
				p_actor_discord_id,
				p_actor_discord_id)
		RETURNING content_external_link_id
		INTO v_inserted_id;

		PERFORM web_priv.web_content_external_link_record_history(v_inserted_id,
													 'create',
													 p_actor_discord_id);
	END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_content_replace_external_links(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_surface_scope_code text, p_external_links jsonb) OWNER TO cm;

--
-- Name: web_content_replace_field_values(character varying, bigint, bigint, jsonb); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_content_replace_field_values(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_field_values jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_content_replace_field_values                                                        ////
--//// PURPOSE: Replaces active field values while preserving saved disabled fields for the current template       ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_row record;
	v_expected record;
	v_populated_columns text[];
	v_populated_count integer;
	v_existing record;
	v_inserted_id bigint;
	v_input_count integer;
	v_unique_count integer;
BEGIN
	IF jsonb_typeof(COALESCE(p_field_values, '[]'::jsonb)) <> 'array' THEN
		RAISE EXCEPTION 'p_field_values must be a JSON array.';
	END IF;

	SELECT COUNT(*)
	INTO v_input_count
	FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(template_field_id bigint,
																  value_seq_no integer,
																  value_text text,
																  value_long_text text,
																  value_integer integer,
																  value_numeric numeric,
																  value_boolean boolean,
																  value_date date,
																  value_timestamp timestamptz,
																  value_discord_id character varying(32),
																  value_media_id bigint,
																  value_content_id bigint,
																  value_option_key text,
																  value_rich_text_json jsonb)
	;

	SELECT COUNT(*)
	INTO v_unique_count
	FROM (SELECT DISTINCT parsed.template_field_id,
							COALESCE(parsed.value_seq_no, 1) AS value_seq_no
		  FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(template_field_id bigint,
																	value_seq_no integer,
																	value_text text,
																	value_long_text text,
																	value_integer integer,
																	value_numeric numeric,
																	value_boolean boolean,
																	value_date date,
																	value_timestamp timestamptz,
																	value_discord_id character varying(32),
																	value_media_id bigint,
																	value_content_id bigint,
																	value_option_key text,
																	value_rich_text_json jsonb)) src
	;

	IF v_input_count <> v_unique_count THEN
		RAISE EXCEPTION 'p_field_values contains duplicate (template_field_id, value_seq_no) rows.';
	END IF;

	FOR v_row IN
		SELECT parsed.template_field_id,
			   COALESCE(parsed.value_seq_no, 1) AS value_seq_no,
			   parsed.value_text,
			   parsed.value_long_text,
			   parsed.value_integer,
			   parsed.value_numeric,
			   parsed.value_boolean,
			   parsed.value_date,
			   parsed.value_timestamp,
			   parsed.value_discord_id,
			   parsed.value_media_id,
			   parsed.value_content_id,
			   parsed.value_option_key,
			   parsed.value_rich_text_json
		FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(template_field_id bigint,
																  value_seq_no integer,
																  value_text text,
																  value_long_text text,
																  value_integer integer,
																  value_numeric numeric,
																  value_boolean boolean,
																  value_date date,
																  value_timestamp timestamptz,
																  value_discord_id character varying(32),
																  value_media_id bigint,
																  value_content_id bigint,
																  value_option_key text,
																  value_rich_text_json jsonb)
	LOOP
		SELECT tf.template_field_id,
			   tf.template_id,
			   tf.is_required,
			   tf.is_enabled,
			   fl.field_list_id,
			   fl.field_type_code,
			   ft.value_column_name
		INTO v_expected
		FROM web_priv.web_template_fields tf
		JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
		JOIN web_priv.web_template_field_type_c ft ON ft.field_type_code = fl.field_type_code
		WHERE tf.template_field_id = v_row.template_field_id
		  AND tf.template_id = p_template_id
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'template_field_id % does not belong to template %.', v_row.template_field_id, p_template_id;
		END IF;

		IF v_expected.is_enabled = false THEN
			RAISE EXCEPTION 'template_field_id % is disabled for template %.', v_row.template_field_id, p_template_id;
		END IF;

		v_populated_columns := array_remove(ARRAY[
			CASE WHEN v_row.value_text IS NOT NULL THEN 'value_text' END,
			CASE WHEN v_row.value_long_text IS NOT NULL THEN 'value_long_text' END,
			CASE WHEN v_row.value_integer IS NOT NULL THEN 'value_integer' END,
			CASE WHEN v_row.value_numeric IS NOT NULL THEN 'value_numeric' END,
			CASE WHEN v_row.value_boolean IS NOT NULL THEN 'value_boolean' END,
			CASE WHEN v_row.value_date IS NOT NULL THEN 'value_date' END,
			CASE WHEN v_row.value_timestamp IS NOT NULL THEN 'value_timestamp' END,
			CASE WHEN v_row.value_discord_id IS NOT NULL THEN 'value_discord_id' END,
			CASE WHEN v_row.value_media_id IS NOT NULL THEN 'value_media_id' END,
			CASE WHEN v_row.value_content_id IS NOT NULL THEN 'value_content_id' END,
			CASE WHEN v_row.value_option_key IS NOT NULL THEN 'value_option_key' END,
			CASE WHEN v_row.value_rich_text_json IS NOT NULL THEN 'value_rich_text_json' END
		], NULL);

		v_populated_count := COALESCE(array_length(v_populated_columns, 1), 0);

		IF v_populated_count <> 1 THEN
			RAISE EXCEPTION 'template_field_id % must populate exactly one value_* column.', v_row.template_field_id;
		END IF;

		IF v_populated_columns[1] <> v_expected.value_column_name THEN
			RAISE EXCEPTION 'template_field_id % expects %, but received %.', v_row.template_field_id, v_expected.value_column_name, v_populated_columns[1];
		END IF;

		IF v_expected.value_column_name = 'value_option_key' THEN
			PERFORM 1
			FROM web_priv.web_template_field_options o
			WHERE o.field_list_id = v_expected.field_list_id
			  AND o.option_key = v_row.value_option_key
			  AND o.is_enabled = true
			;

			IF NOT FOUND THEN
				PERFORM 1
				FROM web_priv.web_content_field_values v
				WHERE v.content_id = p_content_id
				  AND v.template_field_id = v_row.template_field_id
				  AND v.value_seq_no = v_row.value_seq_no
				  AND v.value_option_key IS NOT DISTINCT FROM v_row.value_option_key
				;

				IF NOT FOUND THEN
					RAISE EXCEPTION 'Option key % is not enabled for template_field_id %.', v_row.value_option_key, v_row.template_field_id;
				END IF;
			END IF;
		END IF;

		IF v_expected.field_type_code = 'youtube_url'
		   AND web_priv.web_youtube_video_id_from_url(v_row.value_text) IS NULL THEN
			RAISE EXCEPTION 'template_field_id % must contain a valid YouTube video URL.', v_row.template_field_id;
		END IF;
	END LOOP;

	FOR v_expected IN
		SELECT tf.template_field_id
		FROM web_priv.web_template_fields tf
		WHERE tf.template_id = p_template_id
		  AND tf.is_enabled = true
		  AND tf.is_required = true
	LOOP
		PERFORM 1
		FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(template_field_id bigint,
																  value_seq_no integer,
																  value_text text,
																  value_long_text text,
																  value_integer integer,
																  value_numeric numeric,
																  value_boolean boolean,
																  value_date date,
																  value_timestamp timestamptz,
																  value_discord_id character varying(32),
																  value_media_id bigint,
																  value_content_id bigint,
																  value_option_key text,
																  value_rich_text_json jsonb)
		WHERE parsed.template_field_id = v_expected.template_field_id
		;

		IF NOT FOUND THEN
			RAISE EXCEPTION 'Required template_field_id % is missing from p_field_values.', v_expected.template_field_id;
		END IF;
	END LOOP;

	FOR v_existing IN
		SELECT v.content_field_value_id
		FROM web_priv.web_content_field_values v
		JOIN web_priv.web_template_fields tf ON tf.template_field_id = v.template_field_id
		WHERE v.content_id = p_content_id
		  AND (tf.template_id <> p_template_id OR tf.is_enabled = true)
	LOOP
		PERFORM web_priv.web_content_field_value_record_history(v_existing.content_field_value_id,
															'delete',
															p_actor_discord_id);
	END LOOP;

	DELETE FROM web_priv.web_content_field_values v
	USING web_priv.web_template_fields tf
	WHERE v.template_field_id = tf.template_field_id
	  AND v.content_id = p_content_id
	  AND (tf.template_id <> p_template_id OR tf.is_enabled = true)
	;

	FOR v_row IN
		SELECT parsed.template_field_id,
			   COALESCE(parsed.value_seq_no, 1) AS value_seq_no,
			   parsed.value_text,
			   parsed.value_long_text,
			   parsed.value_integer,
			   parsed.value_numeric,
			   parsed.value_boolean,
			   parsed.value_date,
			   parsed.value_timestamp,
			   parsed.value_discord_id,
			   parsed.value_media_id,
			   parsed.value_content_id,
			   parsed.value_option_key,
			   parsed.value_rich_text_json
		FROM jsonb_to_recordset(COALESCE(p_field_values, '[]'::jsonb)) AS parsed(template_field_id bigint,
																  value_seq_no integer,
																  value_text text,
																  value_long_text text,
																  value_integer integer,
																  value_numeric numeric,
																  value_boolean boolean,
																  value_date date,
																  value_timestamp timestamptz,
																  value_discord_id character varying(32),
																  value_media_id bigint,
																  value_content_id bigint,
																  value_option_key text,
																  value_rich_text_json jsonb)
	LOOP
		INSERT INTO web_priv.web_content_field_values(content_id,
													  template_field_id,
													  value_seq_no,
													  value_text,
													  value_long_text,
													  value_integer,
													  value_numeric,
													  value_boolean,
													  value_date,
													  value_timestamp,
													  value_discord_id,
													  value_media_id,
													  value_content_id,
													  value_option_key,
													  value_rich_text_json,
													  created_by_discord_id,
													  updated_by_discord_id)
		VALUES (p_content_id,
				v_row.template_field_id,
				v_row.value_seq_no,
				v_row.value_text,
				v_row.value_long_text,
				v_row.value_integer,
				v_row.value_numeric,
				v_row.value_boolean,
				v_row.value_date,
				v_row.value_timestamp,
				v_row.value_discord_id,
				v_row.value_media_id,
				v_row.value_content_id,
				v_row.value_option_key,
				v_row.value_rich_text_json,
				p_actor_discord_id,
				p_actor_discord_id)
		RETURNING content_field_value_id
		INTO v_inserted_id;

		PERFORM web_priv.web_content_field_value_record_history(v_inserted_id,
															'create',
															p_actor_discord_id);
	END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_content_replace_field_values(p_actor_discord_id character varying, p_content_id bigint, p_template_id bigint, p_field_values jsonb) OWNER TO cm;

--
-- Name: web_dependency_raise_guard(text, text, text, text, text, bigint, text[]); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_dependency_raise_guard(p_action text, p_subject_kind text, p_subject_label text, p_dependency_singular text, p_dependency_plural text, p_dependency_count bigint, p_dependency_labels text[] DEFAULT ARRAY[]::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_dependency_raise_guard                                                            ////
--//// PURPOSE: Raises user-facing dependency guard errors with dependent row labels                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_action text := COALESCE(NULLIF(btrim(p_action), ''), 'change');
	v_subject_kind text := COALESCE(NULLIF(btrim(p_subject_kind), ''), 'item');
	v_subject_label text := COALESCE(NULLIF(btrim(p_subject_label), ''), 'Unknown');
	v_dependency_count bigint := COALESCE(p_dependency_count, 0);
	v_dependency_name text;
	v_labels text[] := ARRAY[]::text[];
	v_label_count integer := 0;
	v_more_count bigint := 0;
	v_label_text text := '';
BEGIN
	IF v_dependency_count <= 0 THEN
		RETURN;
	END IF;

	v_dependency_name := CASE WHEN v_dependency_count = 1
								THEN COALESCE(NULLIF(btrim(p_dependency_singular), ''), 'dependency')
								ELSE COALESCE(NULLIF(btrim(p_dependency_plural), ''), 'dependencies')
								END;

	SELECT COALESCE(array_agg(label_src.label ORDER BY label_src.ordinal), ARRAY[]::text[])
	INTO v_labels
	FROM (SELECT NULLIF(btrim(raw_label.label), '') AS label,
				 raw_label.ordinal
		  FROM unnest(COALESCE(p_dependency_labels, ARRAY[]::text[])) WITH ORDINALITY AS raw_label(label, ordinal)
		  WHERE NULLIF(btrim(raw_label.label), '') IS NOT NULL
		  ORDER BY raw_label.ordinal
		  LIMIT 5) label_src;

	v_label_count := COALESCE(array_length(v_labels, 1), 0);
	v_more_count := GREATEST(v_dependency_count - v_label_count, 0);

	IF v_label_count > 0 THEN
		v_label_text := array_to_string(v_labels, '; ');

		IF v_more_count > 0 THEN
			RAISE EXCEPTION 'Cannot % % "%" because % % still depend on it: %; and % more.',
				v_action,
				v_subject_kind,
				v_subject_label,
				v_dependency_count,
				v_dependency_name,
				v_label_text,
				v_more_count;
		END IF;

		RAISE EXCEPTION 'Cannot % % "%" because % % still depend on it: %.',
			v_action,
			v_subject_kind,
			v_subject_label,
			v_dependency_count,
			v_dependency_name,
			v_label_text;
	END IF;

	RAISE EXCEPTION 'Cannot % % "%" because % % still depend on it.',
		v_action,
		v_subject_kind,
		v_subject_label,
		v_dependency_count,
		v_dependency_name;
END;
$$;


ALTER FUNCTION web_priv.web_dependency_raise_guard(p_action text, p_subject_kind text, p_subject_label text, p_dependency_singular text, p_dependency_plural text, p_dependency_count bigint, p_dependency_labels text[]) OWNER TO cm;

--
-- Name: web_external_link_host_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_external_link_host_record_history(p_external_link_host_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS AN EXTERNAL LINK HOST RULE HISTORY SNAPSHOT                                                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_version_no integer;
BEGIN
	UPDATE web_priv.web_external_link_host_c_h h
	SET is_current = false
	WHERE h.external_link_host_id = p_external_link_host_id
	  AND h.is_current = true;

	SELECT COALESCE(MAX(h.version_no), 0) + 1
	INTO v_version_no
	FROM web_priv.web_external_link_host_c_h h
	WHERE h.external_link_host_id = p_external_link_host_id;

	INSERT INTO web_priv.web_external_link_host_c_h(external_link_host_id,
											 version_no,
											 is_current,
											 change_type,
											 changed_by_discord_id,
											 changed_dt,
											 host_pattern,
											 host_match_mode_code,
											 path_pattern,
											 path_match_mode_code,
											 allowed_surface_scope_code,
											 comment,
											 is_enabled,
											 valid_from_dt,
											 valid_to_dt,
											 created_by_discord_id,
											 created_dt,
											 updated_by_discord_id,
											 updated_dt)
	SELECT c.external_link_host_id,
		   v_version_no,
		   p_change_type <> 'delete',
		   p_change_type,
		   p_changed_by_discord_id,
		   CURRENT_TIMESTAMP,
		   c.host_pattern,
		   c.host_match_mode_code,
		   c.path_pattern,
		   c.path_match_mode_code,
		   c.allowed_surface_scope_code,
		   c.comment,
		   c.is_enabled,
		   c.valid_from_dt,
		   c.valid_to_dt,
		   c.created_by_discord_id,
		   c.created_dt,
		   c.updated_by_discord_id,
		   c.updated_dt
	FROM web_priv.web_external_link_host_c c
	WHERE c.external_link_host_id = p_external_link_host_id;
END;
$$;


ALTER FUNCTION web_priv.web_external_link_host_record_history(p_external_link_host_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_icon_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_icon_assert_can_delete(p_icon_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_icon_assert_can_delete                                                           ////
--//// PURPOSE: Raises when an icon is still referenced by named current web rows                                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT i.label || ' (' || i.key || ')'
	INTO v_subject_label
	FROM web_priv.web_icons i
	WHERE i.icon_id = p_icon_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_icon_id::text);

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_categories c WHERE c.icon_key_id = p_icon_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.category_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title, c.category_id FROM web_priv.web_categories c WHERE c.icon_key_id = p_icon_id ORDER BY c.title, c.category_id LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'icon', v_subject_label, 'category', 'categories', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_subcategories sc WHERE sc.icon_key_id = p_icon_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.category_title, dep.title, dep.subcategory_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT sc.title,
					 c.title AS category_title,
					 c.title || ' / ' || sc.title AS label,
					 sc.subcategory_id
			  FROM web_priv.web_subcategories sc
			  JOIN web_priv.web_categories c ON c.category_id = sc.category_id
			  WHERE sc.icon_key_id = p_icon_id
			  ORDER BY c.title, sc.title, sc.subcategory_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'icon', v_subject_label, 'subcategory', 'subcategories', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_series s WHERE s.icon_key_id = p_icon_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.series_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title, s.series_id FROM web_priv.web_series s WHERE s.icon_key_id = p_icon_id ORDER BY s.title, s.series_id LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'icon', v_subject_label, 'series', 'series', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_templates t WHERE t.default_icon_key_id = p_icon_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.template_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT t.label || ' (' || t.template_code || ')' AS label,
					 t.template_id
			  FROM web_priv.web_templates t
			  WHERE t.default_icon_key_id = p_icon_id
			  ORDER BY t.label, t.template_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'icon', v_subject_label, 'template', 'templates', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count
	FROM web_priv.web_content c
	WHERE c.icon_key_id = p_icon_id
	   OR c.icon_key_effective_id = p_icon_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' (' || c.status_code || ')' AS label,
					 c.content_id
			  FROM web_priv.web_content c
			  WHERE c.icon_key_id = p_icon_id
				 OR c.icon_key_effective_id = p_icon_id
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'icon', v_subject_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


