--
-- Name: web_icon_record_history(bigint, text, character varying, timestamp with time zone); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_icon_record_history(p_icon_id bigint, p_change_type text, p_changed_by_discord_id character varying, p_changed_dt timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CURRENT ICON SNAPSHOT INTO WEB_ICONS_H                                                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_icon web_priv.web_icons%ROWTYPE;
    v_version_no integer;
BEGIN
    IF p_change_type NOT IN ('create', 'update', 'delete') THEN
        RAISE EXCEPTION 'Unsupported web_icons_h.change_type value: %.', p_change_type;
    END IF;

    SELECT *
      INTO v_icon
      FROM web_priv.web_icon_find_by_id(p_icon_id);

    IF v_icon.icon_id IS NULL THEN
        RAISE EXCEPTION 'web_icons row % was not found for history recording.', p_icon_id;
    END IF;

    UPDATE web_priv.web_icons_h ih
       SET is_current = false
     WHERE ih.icon_id = p_icon_id
       AND ih.is_current = true;

    SELECT COALESCE(MAX(ih.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_icons_h ih
     WHERE ih.icon_id = p_icon_id;

    INSERT INTO web_priv.web_icons_h (
        icon_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        key,
        label,
        source_code,
        lucide_name,
        media_id,
        is_enabled,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    VALUES (
        v_icon.icon_id,
        v_version_no,
        true,
        p_change_type,
        NULLIF(btrim(p_changed_by_discord_id), ''),
        COALESCE(p_changed_dt, now()),
        v_icon.key,
        v_icon.label,
        v_icon.source_code,
        v_icon.lucide_name,
        v_icon.media_id,
        v_icon.is_enabled,
        v_icon.created_by_discord_id,
        v_icon.created_dt,
        v_icon.updated_by_discord_id,
        v_icon.updated_dt
    );

    RETURN v_version_no;
END;
$$;


