--
-- Name: web_media_actor_can_read(character varying, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_media_actor_can_read(p_actor_discord_id character varying, p_media_id bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_media_actor_can_read                                                               ////
--//// PURPOSE: Checks whether media is directly readable or referenced by content the actor can read.               ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_actor_discord_id character varying(32);
	v_direct_allowed boolean;
BEGIN
	IF p_media_id IS NULL THEN
		RETURN false;
	END IF;

	v_actor_discord_id := NULLIF(BTRIM(p_actor_discord_id), '');

	SELECT EXISTS (SELECT 1
				   FROM web_priv.web_media m
				   WHERE m.media_id = p_media_id
				     AND (m.is_shared = true
				      OR (v_actor_discord_id IS NOT NULL AND m.owner_discord_id = v_actor_discord_id)))
	INTO v_direct_allowed
	;

	IF COALESCE(v_direct_allowed, false) THEN
		RETURN true;
	END IF;

	RETURN EXISTS (SELECT 1
				   FROM web_priv.web_content_media_r r
				   JOIN web_priv.web_content c ON c.content_id = r.content_id
				   JOIN web_priv.web_categories cat ON cat.category_id = c.category_id
				   LEFT JOIN web_priv.web_subcategories sc ON sc.subcategory_id = c.subcategory_id
				   JOIN web_priv.web_templates t ON t.template_id = c.template_id
				   JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = t.content_kind_code
				   WHERE r.media_id = p_media_id
				     AND c.status_code = 'published'
				     AND web_priv.actor_passes_effective_policy(v_actor_discord_id, c.read_effective_policy_code, c.read_effective_rank));
END;
$$;


