--
-- Name: web_media_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_media_assert_can_delete(p_media_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_media_assert_can_delete                                                          ////
--//// PURPOSE: Raises when a media row is still referenced by named icons, content media, or field values       ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename)
	INTO v_subject_label
	FROM web_priv.web_media m
	WHERE m.media_id = p_media_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_media_id::text);

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_icons i
	WHERE i.media_id = p_media_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.icon_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT i.label || ' (' || i.key || ')' AS label,
					 i.icon_id
			  FROM web_priv.web_icons i
			  WHERE i.media_id = p_media_id
			  ORDER BY i.label,
					   i.icon_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'media item', v_subject_label, 'icon', 'icons', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content_media_r r
	WHERE r.media_id = p_media_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' (' || r.usage_code || ')' AS label,
					 wc.content_id
			  FROM web_priv.web_content_media_r r
			  JOIN web_priv.web_content wc ON wc.content_id = r.content_id
			  WHERE r.media_id = p_media_id
			  ORDER BY wc.title,
					   wc.content_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'media item', v_subject_label, 'content media use', 'content media uses', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content_field_values fv
	WHERE fv.value_media_id = p_media_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' / ' || COALESCE(NULLIF(btrim(tf.label_override), ''), fl.label) AS label,
					 wc.content_id
			  FROM web_priv.web_content_field_values fv
			  JOIN web_priv.web_content wc ON wc.content_id = fv.content_id
			  JOIN web_priv.web_template_fields tf ON tf.template_field_id = fv.template_field_id
			  JOIN web_priv.web_template_field_list fl ON fl.field_list_id = tf.field_list_id
			  WHERE fv.value_media_id = p_media_id
			  ORDER BY wc.title,
					   wc.content_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'media item', v_subject_label, 'content field value', 'content field values', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


