-- Name: FUNCTION web_media_assert_can_delete(p_media_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_media_assert_can_delete(p_media_id bigint) IS 'Raises when a media row is still referenced by icons or current content relations.';


--
-- Name: web_media_assert_valid_category_subcategory(bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_media_assert_valid_category_subcategory(p_category_id bigint, p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// VALIDATES CATEGORY / SUBCATEGORY CONSISTENCY FOR MEDIA ROWS                                                  ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_actual_category_id bigint;
BEGIN
    IF p_subcategory_id IS NOT NULL AND p_category_id IS NULL THEN
        RAISE EXCEPTION 'media.subcategory_id requires media.category_id.';
    END IF;

    IF p_category_id IS NOT NULL THEN
        PERFORM 1
          FROM web_priv.web_categories c
         WHERE c.category_id = p_category_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'media.category_id % does not exist.', p_category_id;
        END IF;
    END IF;

    IF p_subcategory_id IS NOT NULL THEN
        SELECT s.category_id
          INTO v_actual_category_id
          FROM web_priv.web_subcategories s
         WHERE s.subcategory_id = p_subcategory_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'media.subcategory_id % does not exist.', p_subcategory_id;
        END IF;

        IF v_actual_category_id IS DISTINCT FROM p_category_id THEN
            RAISE EXCEPTION 'media.subcategory_id % does not belong to media.category_id %.', p_subcategory_id, p_category_id;
        END IF;
    END IF;
END;
$$;


