--
-- Name: web_media; Type: TABLE; Schema: web_priv; Owner: cm
--

CREATE TABLE web_priv.web_media (
    media_id bigint NOT NULL,
    category_id bigint,
    subcategory_id bigint,
    owner_discord_id character varying(32),
    is_shared boolean DEFAULT false NOT NULL,
    storage_rel_path text NOT NULL,
    filename text NOT NULL,
    original_filename text NOT NULL,
    mime_type text NOT NULL,
    size_bytes bigint NOT NULL,
    width_px integer,
    height_px integer,
    alt_text text,
    credit_text text,
    created_by_discord_id character varying(32),
    created_dt timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_discord_id character varying(32),
    updated_dt timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT web_media_filename_not_blank_chk CHECK ((btrim(filename) <> ''::text)),
    CONSTRAINT web_media_height_px_positive_chk CHECK (((height_px IS NULL) OR (height_px > 0))),
    CONSTRAINT web_media_mime_type_not_blank_chk CHECK ((btrim(mime_type) <> ''::text)),
    CONSTRAINT web_media_original_filename_not_blank_chk CHECK ((btrim(original_filename) <> ''::text)),
    CONSTRAINT web_media_owner_shared_consistency_chk CHECK ((((is_shared = true) AND (owner_discord_id IS NULL)) OR ((is_shared = false) AND (owner_discord_id IS NOT NULL)))),
    CONSTRAINT web_media_size_bytes_non_negative_chk CHECK ((size_bytes >= 0)),
    CONSTRAINT web_media_storage_rel_path_not_blank_chk CHECK ((btrim(storage_rel_path) <> ''::text)),
    CONSTRAINT web_media_subcategory_requires_category_chk CHECK (((subcategory_id IS NULL) OR (category_id IS NOT NULL))),
    CONSTRAINT web_media_width_px_positive_chk CHECK (((width_px IS NULL) OR (width_px > 0)))
);


