--
-- Name: web_media_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_media_record_history(p_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// WRITES AN EXPLICIT HISTORY SNAPSHOT FOR THE CURRENT MEDIA ROW                                                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_row web_priv.web_media%ROWTYPE;
    v_next_version_no integer;
BEGIN
    IF p_change_type NOT IN ('create', 'update', 'delete') THEN
        RAISE EXCEPTION 'Unsupported media history change_type: %.', p_change_type;
    END IF;

    SELECT m.*
      INTO v_row
      FROM web_priv.web_media m
     WHERE m.media_id = p_media_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'media row % was not found while recording history.', p_media_id;
    END IF;

    UPDATE web_priv.web_media_h h
       SET is_current = false
     WHERE h.media_id = p_media_id
       AND h.is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_next_version_no
      FROM web_priv.web_media_h h
     WHERE h.media_id = p_media_id;

    INSERT INTO web_priv.web_media_h (
        media_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        category_id,
        subcategory_id,
        owner_discord_id,
        is_shared,
        storage_rel_path,
        filename,
        original_filename,
        mime_type,
        size_bytes,
        width_px,
        height_px,
        alt_text,
        credit_text,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    VALUES (
        v_row.media_id,
        v_next_version_no,
        true,
        p_change_type,
        p_changed_by_discord_id,
        now(),
        v_row.category_id,
        v_row.subcategory_id,
        v_row.owner_discord_id,
        v_row.is_shared,
        v_row.storage_rel_path,
        v_row.filename,
        v_row.original_filename,
        v_row.mime_type,
        v_row.size_bytes,
        v_row.width_px,
        v_row.height_px,
        v_row.alt_text,
        v_row.credit_text,
        v_row.created_by_discord_id,
        v_row.created_dt,
        v_row.updated_by_discord_id,
        v_row.updated_dt
    );
END;
$$;


ALTER FUNCTION web_priv.web_media_record_history(p_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: FUNCTION web_media_record_history(p_media_id bigint, p_change_type text, p_changed_by_discord_id character varying); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_media_record_history(p_media_id bigint, p_change_type text, p_changed_by_discord_id character varying) IS 'Writes a current-state snapshot into web_media_h and advances the media history version.';


--
-- Name: web_member_actor_can_author_collection(character varying, bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_member_actor_can_author_collection(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_member_actor_can_author_collection                                                  ////
--//// PURPOSE: Checks current member authoring rights for one category/subcategory placement                    ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT EXISTS (SELECT 1
				  FROM web_priv.web_categories c
				  JOIN web_priv.web_subcategories sc ON sc.category_id = c.category_id
				  WHERE c.category_id = p_category_id
					AND sc.subcategory_id = p_subcategory_id
					AND web_priv.actor_passes_effective_policy(p_actor_discord_id, c.write_effective_policy_code, c.write_effective_rank)
					AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.write_effective_policy_code, sc.write_effective_rank))
;
$$;


ALTER FUNCTION web_priv.web_member_actor_can_author_collection(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_member_collection_has_public_template(bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_member_collection_has_public_template(p_category_id bigint, p_subcategory_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_member_collection_has_public_template                                             ////
--//// PURPOSE: Checks if a collection has at least one enabled public template valid for that exact placement   ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT EXISTS (SELECT 1
				  FROM web_priv.web_templates t
				  WHERE web_priv.web_member_template_allowed_for_collection(t.template_id,
																		 p_category_id,
																		 p_subcategory_id,
																		 'public'))
;
$$;


ALTER FUNCTION web_priv.web_member_collection_has_public_template(p_category_id bigint, p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_member_next_series_slug(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_member_next_series_slug(p_title text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_member_next_series_slug                                                            ////
--//// PURPOSE: Resolves a unique series slug for member-created series                                          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_base_slug text;
	v_slug text;
	v_suffix integer;
BEGIN
	v_base_slug := web_priv.web_member_slugify(p_title);
	v_slug := v_base_slug;
	v_suffix := 2;

	WHILE EXISTS (SELECT 1
					  FROM web_priv.web_series s
					  WHERE s.slug = v_slug) LOOP
		v_slug := v_base_slug || '-' || v_suffix::text;
		v_suffix := v_suffix + 1;
	END LOOP;

	RETURN v_slug;
END;
$$;


ALTER FUNCTION web_priv.web_member_next_series_slug(p_title text) OWNER TO cm;

--
-- Name: web_member_slugify(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_member_slugify(p_input text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_member_slugify                                                                     ////
--//// PURPOSE: Produces a conservative URL slug for member-created supporting rows                              ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT COALESCE(NULLIF(regexp_replace(regexp_replace(lower(btrim(COALESCE(p_input, ''))), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g'), ''), 'item')
;
$_$;


ALTER FUNCTION web_priv.web_member_slugify(p_input text) OWNER TO cm;

--
-- Name: web_member_template_allowed_for_collection(bigint, bigint, bigint, text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_member_template_allowed_for_collection(p_template_id bigint, p_category_id bigint, p_subcategory_id bigint, p_surface_scope_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_member_template_allowed_for_collection                                           ////
--//// PURPOSE: Checks whether one enabled template is valid for one member category/subcategory placement      ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT EXISTS (SELECT 1
				  FROM web_priv.web_templates t
				  WHERE t.template_id         = p_template_id
					AND t.surface_scope_code  = p_surface_scope_code
					AND t.is_enabled          = true
					AND (EXISTS (SELECT 1
									 FROM web_priv.web_subcategory_template_r str
									 WHERE str.category_id    = p_category_id
									   AND str.subcategory_id = p_subcategory_id
									   AND str.template_id    = p_template_id
									   AND str.is_enabled     = true)
					  OR EXISTS (SELECT 1
								 FROM web_priv.web_category_template_r ctr
								 WHERE ctr.category_id = p_category_id
								   AND ctr.template_id = p_template_id
								   AND ctr.is_enabled  = true)))
;
$$;


ALTER FUNCTION web_priv.web_member_template_allowed_for_collection(p_template_id bigint, p_category_id bigint, p_subcategory_id bigint, p_surface_scope_code text) OWNER TO cm;

--
-- Name: web_navigation_panel_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_navigation_panel_record_history(p_navigation_panel_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A NAVIGATION PANEL HISTORY SNAPSHOT                                                                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_version_no integer;
BEGIN
	UPDATE web_priv.web_navigation_panels_h h
	SET is_current = false
	WHERE h.navigation_panel_id = p_navigation_panel_id
	  AND h.is_current = true;

	SELECT COALESCE(MAX(h.version_no), 0) + 1
	INTO v_version_no
	FROM web_priv.web_navigation_panels_h h
	WHERE h.navigation_panel_id = p_navigation_panel_id;

	INSERT INTO web_priv.web_navigation_panels_h(navigation_panel_id,
										 version_no,
										 is_current,
										 change_type,
										 changed_by_discord_id,
										 changed_dt,
										 panel_key,
										 label,
										 panel_type_code,
										 panel_slot_code,
										 is_default,
										 selection_order,
										 read_policy_code,
										 read_rank,
										 max_categories,
										 max_subcategories_per_category,
										 max_targets_per_subcategory,
										 is_enabled,
										 created_by_discord_id,
										 created_dt,
										 updated_by_discord_id,
										 updated_dt)
	SELECT p.navigation_panel_id,
		   v_version_no,
		   p_change_type <> 'delete',
		   p_change_type,
		   p_changed_by_discord_id,
		   CURRENT_TIMESTAMP,
		   p.panel_key,
		   p.label,
		   p.panel_type_code,
		   p.panel_slot_code,
		   p.is_default,
		   p.selection_order,
		   p.read_policy_code,
		   p.read_rank,
		   p.max_categories,
		   p.max_subcategories_per_category,
		   p.max_targets_per_subcategory,
		   p.is_enabled,
		   p.created_by_discord_id,
		   p.created_dt,
		   p.updated_by_discord_id,
		   p.updated_dt
	FROM web_priv.web_navigation_panels p
	WHERE p.navigation_panel_id = p_navigation_panel_id;
END;
$$;


ALTER FUNCTION web_priv.web_navigation_panel_record_history(p_navigation_panel_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_navigation_public_build_panel_json(bigint, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_navigation_public_build_panel_json(p_navigation_panel_id bigint, p_actor_discord_id character varying) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// BUILDS A PUBLIC NAVIGATION PANEL JSON TREE AFTER ACCESS FILTERING                                            ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
SELECT jsonb_build_object(
	'items', COALESCE((
		SELECT jsonb_agg(category_row.payload ORDER BY category_row.display_order)
		FROM (SELECT pc.display_order,
					 jsonb_build_object(
						 'id', cat.category_id::text,
						 'title', cat.title,
						 'href', '/' || cat.slug,
						 'iconKey', CASE WHEN cat_icon.icon_id IS NULL THEN NULL
							 ELSE jsonb_build_object(
								 'id', cat_icon.icon_id::text,
								 'key', cat_icon.key,
								 'label', cat_icon.label,
								 'source', cat_icon.source_code,
								 'lucideName', cat_icon.lucide_name,
								 'iconMedia', CASE WHEN cat_icon.source_code = 'media'
											   AND cat_icon_media.media_id IS NOT NULL THEN jsonb_build_object(
									 'id', cat_icon_media.media_id::text,
									 'filename', cat_icon_media.filename,
									 'originalFilename', cat_icon_media.original_filename,
									 'mimeType', cat_icon_media.mime_type,
									 'storageRelPath', cat_icon_media.storage_rel_path)
									 ELSE NULL
									 END)
							 END,
						 'iconColor', CASE WHEN cat_icon_color.theme_color_id IS NULL THEN NULL
							 ELSE jsonb_build_object(
								 'id', cat_icon_color.theme_color_id::text,
								 'key', cat_icon_color.key,
								 'label', cat_icon_color.label,
								 'preview', cat_icon_color.preview)
							 END,
						 'columns', category_subcategories.columns
					 ) AS payload
			  FROM web_priv.web_navigation_panel_categories pc
			  JOIN web_priv.web_categories cat ON cat.category_id = pc.category_id
			  LEFT JOIN web_priv.web_icons cat_icon ON cat_icon.icon_id = cat.icon_key_id
			  LEFT JOIN web_priv.web_media cat_icon_media ON cat_icon_media.media_id = cat_icon.media_id
			  LEFT JOIN web_priv.web_theme_colors cat_icon_color ON cat_icon_color.theme_color_id = cat.icon_color_id
			  CROSS JOIN LATERAL (
				  SELECT COALESCE(jsonb_agg(subcategory_row.payload ORDER BY subcategory_row.display_order), '[]'::jsonb) AS columns
				  FROM (SELECT ps.display_order,
							   jsonb_build_object(
								   'id', sc.subcategory_id::text,
								   'title', sc.title,
								   'seeAllHref', '/' || cat.slug || '/' || sc.slug,
								   'iconKey', CASE WHEN sc_icon.icon_id IS NULL THEN NULL
									   ELSE jsonb_build_object(
										   'id', sc_icon.icon_id::text,
										   'key', sc_icon.key,
										   'label', sc_icon.label,
										   'source', sc_icon.source_code,
										   'lucideName', sc_icon.lucide_name,
										   'iconMedia', CASE WHEN sc_icon.source_code = 'media'
													 AND sc_icon_media.media_id IS NOT NULL THEN jsonb_build_object(
										   'id', sc_icon_media.media_id::text,
										   'filename', sc_icon_media.filename,
										   'originalFilename', sc_icon_media.original_filename,
										   'mimeType', sc_icon_media.mime_type,
										   'storageRelPath', sc_icon_media.storage_rel_path)
										   ELSE NULL
										   END)
									   END,
								   'iconColor', CASE WHEN sc_icon_color.theme_color_id IS NULL THEN NULL
									   ELSE jsonb_build_object(
										   'id', sc_icon_color.theme_color_id::text,
										   'key', sc_icon_color.key,
										   'label', sc_icon_color.label,
										   'preview', sc_icon_color.preview)
									   END,
								   'pages', subcategory_targets.pages
							   ) AS payload
						FROM web_priv.web_navigation_panel_subcategories ps
						JOIN web_priv.web_subcategories sc ON sc.subcategory_id = ps.subcategory_id
						LEFT JOIN web_priv.web_icons sc_icon ON sc_icon.icon_id = sc.icon_key_id
						LEFT JOIN web_priv.web_media sc_icon_media ON sc_icon_media.media_id = sc_icon.media_id
						LEFT JOIN web_priv.web_theme_colors sc_icon_color ON sc_icon_color.theme_color_id = sc.icon_color_id
						CROSS JOIN LATERAL (
							SELECT COALESCE(jsonb_agg(target_row.payload ORDER BY target_row.display_order), '[]'::jsonb) AS pages
							FROM (SELECT pt.display_order,
										 jsonb_build_object(
											 'id', content.content_id::text,
											 'title', content.title,
											 'href', CASE WHEN ck.renderer_code = 'external_link' THEN external_link.normalized_url
												 WHEN ck.public_route_prefix IS NULL THEN '/' || cat.slug || '/' || sc.slug || '/' || content.slug
												 ELSE '/' || ck.public_route_prefix || '/' || cat.slug || '/' || sc.slug || '/' || content.slug
												 END,
											 'isExternal', ck.renderer_code = 'external_link',
											 'target', CASE WHEN ck.renderer_code = 'external_link' THEN '_blank' ELSE NULL END,
											 'rel', CASE WHEN ck.renderer_code = 'external_link' THEN 'noopener noreferrer' ELSE NULL END,
											 'rendererCode', ck.renderer_code,
											 'contentKindCode', template.content_kind_code,
											 'iconKey', CASE WHEN content_icon.icon_id IS NULL THEN NULL
												 ELSE jsonb_build_object(
													 'id', content_icon.icon_id::text,
													 'key', content_icon.key,
													 'label', content_icon.label,
													 'source', content_icon.source_code,
													 'lucideName', content_icon.lucide_name,
													 'iconMedia', CASE WHEN content_icon.source_code = 'media'
															   AND content_icon_media.media_id IS NOT NULL THEN jsonb_build_object(
													 'id', content_icon_media.media_id::text,
													 'filename', content_icon_media.filename,
													 'originalFilename', content_icon_media.original_filename,
													 'mimeType', content_icon_media.mime_type,
													 'storageRelPath', content_icon_media.storage_rel_path)
													 ELSE NULL
													 END)
												 END,
											 'iconColor', CASE WHEN content_icon_color.theme_color_id IS NULL THEN NULL
												 ELSE jsonb_build_object(
													 'id', content_icon_color.theme_color_id::text,
													 'key', content_icon_color.key,
													 'label', content_icon_color.label,
													 'preview', content_icon_color.preview)
												 END
										 ) AS payload
								  FROM web_priv.web_navigation_panel_targets pt
								  JOIN web_priv.web_content content ON content.content_id = pt.content_id
								  JOIN web_priv.web_templates template ON template.template_id = content.template_id
								  JOIN web_priv.web_content_kind_c ck ON ck.content_kind_code = template.content_kind_code
								  LEFT JOIN web_priv.web_icons content_icon ON content_icon.icon_id = content.icon_key_effective_id
								  LEFT JOIN web_priv.web_media content_icon_media ON content_icon_media.media_id = content_icon.media_id
								  LEFT JOIN web_priv.web_theme_colors content_icon_color ON content_icon_color.theme_color_id = content.icon_color_effective_id
								  LEFT JOIN LATERAL (
									  SELECT link.normalized_url
									  FROM web_priv.web_content_external_link_r link
									  JOIN web_priv.web_template_fields template_field ON template_field.template_field_id = link.template_field_id
									  JOIN web_priv.web_template_field_list field_list ON field_list.field_list_id = template_field.field_list_id
									  WHERE link.content_id = content.content_id
										AND link.source_kind_code = 'field'
										AND field_list.field_list_code IN ('link_url', 'hidden_link_url')
									  ORDER BY link.value_seq_no,
											   link.link_index_no,
											   link.content_external_link_id
									  LIMIT 1
								  ) external_link ON true
								  WHERE pt.navigation_panel_subcategory_id = ps.navigation_panel_subcategory_id
									AND pt.is_enabled = true
									AND content.status_code = 'published'
									AND content.nav_hidden_effective = false
									AND (ck.renderer_code <> 'external_link' OR external_link.normalized_url IS NOT NULL)
									AND web_priv.actor_passes_effective_policy(p_actor_discord_id, content.read_effective_policy_code, content.read_effective_rank)
							) target_row
						) subcategory_targets
						WHERE ps.navigation_panel_category_id = pc.navigation_panel_category_id
						  AND ps.is_enabled = true
						  AND web_priv.actor_passes_effective_policy(p_actor_discord_id, sc.read_effective_policy_code, sc.read_effective_rank)
				  ) subcategory_row
			  ) category_subcategories
			  WHERE pc.navigation_panel_id = p_navigation_panel_id
				AND pc.is_enabled = true
				AND web_priv.actor_passes_effective_policy(p_actor_discord_id, cat.read_effective_policy_code, cat.read_effective_rank)
		) category_row
	), '[]'::jsonb)
);
$$;


