-- Name: web_series_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_series_assert_can_delete(p_series_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_series_assert_can_delete                                                         ////
--//// PURPOSE: Raises when a series is still referenced by named current content rows                           ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT s.title
	INTO v_subject_label
	FROM web_priv.web_series s
	WHERE s.series_id = p_series_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_series_id::text);

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content wc
	WHERE wc.series_id = p_series_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' (' || wc.status_code || ')' AS label,
					 wc.content_id
			  FROM web_priv.web_content wc
			  WHERE wc.series_id = p_series_id
			  ORDER BY wc.title,
					   wc.content_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'series', v_subject_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


