--
-- Name: web_series_recalculate_effective(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_series_recalculate_effective(p_series_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE web_priv.web_series AS s
       SET read_effective_policy_code = CASE
               WHEN s.read_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.read_effective_policy_code FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = s.subcategory_id),
                    (SELECT c.read_effective_policy_code FROM web_priv.web_categories c WHERE c.category_id = s.category_id)
               )
               ELSE s.read_policy_code
           END,
           read_effective_rank = CASE
               WHEN s.read_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.read_effective_rank FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = s.subcategory_id),
                    (SELECT c.read_effective_rank FROM web_priv.web_categories c WHERE c.category_id = s.category_id)
               )
               WHEN s.read_policy_code = 'public' THEN NULL
               ELSE s.read_rank
           END,
           write_effective_policy_code = CASE
               WHEN s.write_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.write_effective_policy_code FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = s.subcategory_id),
                    (SELECT c.write_effective_policy_code FROM web_priv.web_categories c WHERE c.category_id = s.category_id)
               )
               ELSE s.write_policy_code
           END,
           write_effective_rank = CASE
               WHEN s.write_policy_code = 'inherit' THEN COALESCE(
                    (SELECT sc.write_effective_rank FROM web_priv.web_subcategories sc WHERE sc.subcategory_id = s.subcategory_id),
                    (SELECT c.write_effective_rank FROM web_priv.web_categories c WHERE c.category_id = s.category_id)
               )
               ELSE s.write_rank
           END
     WHERE s.series_id = p_series_id;
END;
$$;


ALTER FUNCTION web_priv.web_series_recalculate_effective(p_series_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_series_recalculate_effective(p_series_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_series_recalculate_effective(p_series_id bigint) IS 'Recalculates effective read and write policy for a series row.';


--
-- Name: web_series_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_series_record_history(p_series_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CURRENT-STATE HISTORY SNAPSHOT FOR WEB_SERIES                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_series_h
       SET is_current = false
     WHERE series_id = p_series_id
       AND is_current = true;

    SELECT COALESCE(MAX(version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_series_h
     WHERE series_id = p_series_id;

    INSERT INTO web_priv.web_series_h (
        series_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        title,
        slug,
        description,
        category_id,
        subcategory_id,
        author_discord_id,
        read_policy_code,
        read_rank,
        write_policy_code,
        write_rank,
        icon_key_id,
        icon_color_id,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        s.series_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        s.title,
        s.slug,
        s.description,
        s.category_id,
        s.subcategory_id,
        s.author_discord_id,
        s.read_policy_code,
        s.read_rank,
        s.write_policy_code,
        s.write_rank,
        s.icon_key_id,
        s.icon_color_id,
        s.created_by_discord_id,
        s.created_dt,
        s.updated_by_discord_id,
        s.updated_dt
      FROM web_priv.web_series AS s
     WHERE s.series_id = p_series_id;
END;
$$;


