--
-- Name: web_subcategory_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_assert_can_delete(p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_subcategory_assert_can_delete                                                     ////
--//// PURPOSE: Raises when a subcategory is still referenced by named media, series or content rows             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT sc.title
	INTO v_subject_label
	FROM web_priv.web_subcategories sc
	WHERE sc.subcategory_id = p_subcategory_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_subcategory_id::text);

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_media m
	WHERE m.subcategory_id = p_subcategory_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.media_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename) AS label,
					 m.media_id
			  FROM web_priv.web_media m
			  WHERE m.subcategory_id = p_subcategory_id
			  ORDER BY COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename),
					   m.media_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'subcategory', v_subject_label, 'media item', 'media items', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_series s
	WHERE s.subcategory_id = p_subcategory_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.series_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title,
					 s.series_id
			  FROM web_priv.web_series s
			  WHERE s.subcategory_id = p_subcategory_id
			  ORDER BY s.title,
					   s.series_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'subcategory', v_subject_label, 'series', 'series', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_content wc
	WHERE wc.subcategory_id = p_subcategory_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' (' || wc.status_code || ')' AS label,
					 wc.content_id
			  FROM web_priv.web_content wc
			  WHERE wc.subcategory_id = p_subcategory_id
			  ORDER BY wc.title,
					   wc.content_id
			  LIMIT 5) dep;

		PERFORM web_priv.web_dependency_raise_guard('delete', 'subcategory', v_subject_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


ALTER FUNCTION web_priv.web_subcategory_assert_can_delete(p_subcategory_id bigint) OWNER TO cm;

--
-- Name: web_subcategory_assert_can_reparent(bigint, bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_assert_can_reparent(p_subcategory_id bigint, p_target_category_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_subcategory_assert_can_reparent                                                   ////
--//// PURPOSE: Raises when a subcategory cannot move because named dependent rows still belong to it             ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_current_category_id bigint;
	v_subject_label text;
	v_target_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT s.category_id,
		   s.title
	INTO v_current_category_id,
		 v_subject_label
	FROM web_priv.web_subcategories s
	WHERE s.subcategory_id = p_subcategory_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Subcategory % was not found.', p_subcategory_id;
	END IF;

	IF v_current_category_id = p_target_category_id THEN
		RETURN;
	END IF;

	SELECT c.title
	INTO v_target_label
	FROM web_priv.web_categories c
	WHERE c.category_id = p_target_category_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_subcategory_id::text);
	v_target_label := COALESCE(v_target_label, '#' || p_target_category_id::text);

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_media m WHERE m.subcategory_id = p_subcategory_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.media_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename) AS label,
					 m.media_id
			  FROM web_priv.web_media m
			  WHERE m.subcategory_id = p_subcategory_id
			  ORDER BY COALESCE(NULLIF(btrim(m.original_filename), ''), m.filename), m.media_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('move', 'subcategory', v_subject_label || ' to category ' || v_target_label, 'media item', 'media items', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_series s WHERE s.subcategory_id = p_subcategory_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.series_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title, s.series_id FROM web_priv.web_series s WHERE s.subcategory_id = p_subcategory_id ORDER BY s.title, s.series_id LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('move', 'subcategory', v_subject_label || ' to category ' || v_target_label, 'series', 'series', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_content wc WHERE wc.subcategory_id = p_subcategory_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT wc.title,
					 wc.title || ' (' || wc.status_code || ')' AS label,
					 wc.content_id
			  FROM web_priv.web_content wc
			  WHERE wc.subcategory_id = p_subcategory_id
			  ORDER BY wc.title, wc.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('move', 'subcategory', v_subject_label || ' to category ' || v_target_label, 'content item', 'content items', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*)
	INTO v_reference_count
	FROM web_priv.web_navigation_panel_subcategories nps
	WHERE nps.subcategory_id = p_subcategory_id;

	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.navigation_panel_subcategory_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT np.label || ' navigation panel' AS label,
					 nps.navigation_panel_subcategory_id
			  FROM web_priv.web_navigation_panel_subcategories nps
			  JOIN web_priv.web_navigation_panel_categories npc ON npc.navigation_panel_category_id = nps.navigation_panel_category_id
			  JOIN web_priv.web_navigation_panels np ON np.navigation_panel_id = npc.navigation_panel_id
			  WHERE nps.subcategory_id = p_subcategory_id
			  ORDER BY np.label, nps.navigation_panel_subcategory_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('move', 'subcategory', v_subject_label || ' to category ' || v_target_label, 'navigation panel entry', 'navigation panel entries', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_subcategory_template_r str WHERE str.subcategory_id = p_subcategory_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.subcategory_template_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT t.label || ' (' || t.template_code || ')' AS label,
					 str.subcategory_template_id
			  FROM web_priv.web_subcategory_template_r str
			  JOIN web_priv.web_templates t ON t.template_id = str.template_id
			  WHERE str.subcategory_id = p_subcategory_id
			  ORDER BY t.label, str.subcategory_template_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('move', 'subcategory', v_subject_label || ' to category ' || v_target_label, 'template assignment', 'template assignments', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


ALTER FUNCTION web_priv.web_subcategory_assert_can_reparent(p_subcategory_id bigint, p_target_category_id bigint) OWNER TO cm;

