-- Name: FUNCTION web_subcategory_assert_can_reparent(p_subcategory_id bigint, p_target_category_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_subcategory_assert_can_reparent(p_subcategory_id bigint, p_target_category_id bigint) IS 'Raises when a subcategory cannot safely move to a different category without explicit dependent rewrites.';


--
-- Name: web_subcategory_recalculate_dependents(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_recalculate_dependents(p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECALCULATES SUBCATEGORY EFFECTIVE FIELDS AND DEPENDENT SERIES                                               ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_series_id bigint;
BEGIN
    PERFORM web_priv.web_subcategory_recalculate_effective(p_subcategory_id);

    FOR v_series_id IN
        SELECT s.series_id
          FROM web_priv.web_series AS s
         WHERE s.subcategory_id = p_subcategory_id
    LOOP
        PERFORM web_priv.web_series_recalculate_effective(v_series_id);
    END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_subcategory_recalculate_dependents(p_subcategory_id bigint) OWNER TO cm;

--
-- Name: FUNCTION web_subcategory_recalculate_dependents(p_subcategory_id bigint); Type: COMMENT; Schema: web_priv; Owner: cm
--

COMMENT ON FUNCTION web_priv.web_subcategory_recalculate_dependents(p_subcategory_id bigint) IS 'Recalculates a subcategory row and all dependent series effective fields.';


--
-- Name: web_subcategory_recalculate_effective(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_recalculate_effective(p_subcategory_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE web_priv.web_subcategories s
       SET read_effective_policy_code = CASE
               WHEN s.read_policy_code = 'inherit' THEN c.read_effective_policy_code
               ELSE s.read_policy_code
           END,
           read_effective_rank = CASE
               WHEN s.read_policy_code = 'inherit' THEN c.read_effective_rank
               WHEN s.read_policy_code = 'public' THEN NULL
               ELSE s.read_rank
           END,
           write_effective_policy_code = CASE
               WHEN s.write_policy_code = 'inherit' THEN c.write_effective_policy_code
               ELSE s.write_policy_code
           END,
           write_effective_rank = CASE
               WHEN s.write_policy_code = 'inherit' THEN c.write_effective_rank
               ELSE s.write_rank
           END,
           nav_hidden_effective = CASE
               WHEN s.nav_hidden_mode_code = 'inherit' THEN c.nav_hidden
               ELSE COALESCE(s.nav_hidden, false)
           END
      FROM web_priv.web_categories c
     WHERE s.subcategory_id = p_subcategory_id
       AND c.category_id = s.category_id;
END;
$$;


