-- Name: web_subcategory_template_record_history(bigint, text, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_template_record_history(p_subcategory_template_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A SUBCATEGORY-TEMPLATE RELATION HISTORY SNAPSHOT                                                     ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_subcategory_template_r_h
       SET is_current = false
     WHERE subcategory_template_id = p_subcategory_template_id
       AND is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_subcategory_template_r_h h
     WHERE h.subcategory_template_id = p_subcategory_template_id;

    INSERT INTO web_priv.web_subcategory_template_r_h (
