        updated_dt
    )
    SELECT
        r.subcategory_template_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        r.category_id,
        r.subcategory_id,
        r.template_id,
        r.is_enabled,
        r.created_by_discord_id,
        r.created_dt,
        r.updated_by_discord_id,
        r.updated_dt
      FROM web_priv.web_subcategory_template_r r
     WHERE r.subcategory_template_id = p_subcategory_template_id;
END;
$$;


ALTER FUNCTION web_priv.web_subcategory_template_record_history(p_subcategory_template_id bigint, p_change_type text, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_subcategory_template_replace(character varying, bigint, bigint, bigint[]); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_subcategory_template_replace(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint, p_template_ids bigint[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing record;
    v_template_id bigint;
BEGIN
    FOR v_existing IN
        SELECT *
          FROM web_priv.web_subcategory_template_r r
         WHERE r.subcategory_id = p_subcategory_id
           AND NOT (r.template_id = ANY (COALESCE(p_template_ids, ARRAY[]::bigint[])))
    LOOP
        PERFORM web_priv.web_subcategory_template_record_history(v_existing.subcategory_template_id, 'delete', p_actor_discord_id);
        DELETE FROM web_priv.web_subcategory_template_r WHERE subcategory_template_id = v_existing.subcategory_template_id;
    END LOOP;

    IF p_template_ids IS NULL THEN
        RETURN;
    END IF;

    FOREACH v_template_id IN ARRAY p_template_ids LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM web_priv.web_subcategory_template_r r
             WHERE r.category_id = p_category_id
               AND r.subcategory_id = p_subcategory_id
               AND r.template_id = v_template_id
        ) THEN
            INSERT INTO web_priv.web_subcategory_template_r (
                category_id,
                subcategory_id,
                template_id,
                is_enabled,
                created_by_discord_id,
                updated_by_discord_id
            ) VALUES (
                p_category_id,
                p_subcategory_id,
                v_template_id,
                true,
                p_actor_discord_id,
                p_actor_discord_id
            );

            PERFORM web_priv.web_subcategory_template_record_history(
                currval(pg_get_serial_sequence('web_priv.web_subcategory_template_r', 'subcategory_template_id')),
                'create',
                p_actor_discord_id
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION web_priv.web_subcategory_template_replace(p_actor_discord_id character varying, p_category_id bigint, p_subcategory_id bigint, p_template_ids bigint[]) OWNER TO cm;

--
-- Name: web_template_bump_schema_version(bigint, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_template_bump_schema_version(p_template_id bigint, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INCREMENTS A TEMPLATE SCHEMA VERSION                                                                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
BEGIN
    UPDATE web_priv.web_templates
       SET schema_version_no = schema_version_no + 1,
           updated_by_discord_id = p_changed_by_discord_id,
           updated_dt = CURRENT_TIMESTAMP
     WHERE template_id = p_template_id;

    IF FOUND THEN
        PERFORM web_priv.web_template_record_history(p_template_id, 'update', p_changed_by_discord_id);
    END IF;
END;
$$;


ALTER FUNCTION web_priv.web_template_bump_schema_version(p_template_id bigint, p_changed_by_discord_id character varying) OWNER TO cm;

--
-- Name: web_template_bump_schema_version_by_field_list(bigint, character varying); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_template_bump_schema_version_by_field_list(p_field_list_id bigint, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// INCREMENTS SCHEMA VERSIONS FOR TEMPLATES USING ONE FIELD LIST                                                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_template_id bigint;
BEGIN
    FOR v_template_id IN
        SELECT DISTINCT f.template_id
          FROM web_priv.web_template_fields f
         WHERE f.field_list_id = p_field_list_id
    LOOP
        PERFORM web_priv.web_template_bump_schema_version(v_template_id, p_changed_by_discord_id);
    END LOOP;
END;
$$;


