--

CREATE FUNCTION web_priv.web_template_field_list_record_history(p_field_list_id bigint, p_change_type text, p_changed_by_discord_id character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A TEMPLATE FIELD LIST HISTORY SNAPSHOT                                                               ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_version_no integer;
BEGIN
    UPDATE web_priv.web_template_field_list_h
       SET is_current = false
     WHERE field_list_id = p_field_list_id
       AND is_current = true;

    SELECT COALESCE(MAX(h.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_template_field_list_h h
     WHERE h.field_list_id = p_field_list_id;

    INSERT INTO web_priv.web_template_field_list_h (
        field_list_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        field_list_code,
        label,
        help_text,
        field_type_code,
        render_destination_code,
        is_enabled,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    SELECT
        f.field_list_id,
        v_version_no,
        p_change_type <> 'delete',
        p_change_type,
        p_changed_by_discord_id,
        CURRENT_TIMESTAMP,
        f.field_list_code,
        f.label,
        f.help_text,
        f.field_type_code,
        f.render_destination_code,
        f.is_enabled,
        f.created_by_discord_id,
        f.created_dt,
        f.updated_by_discord_id,
        f.updated_dt
      FROM web_priv.web_template_field_list f
     WHERE f.field_list_id = p_field_list_id;
END;
$$;


