--
-- Name: web_theme_color_assert_can_delete(bigint); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_theme_color_assert_can_delete(p_theme_color_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_theme_color_assert_can_delete                                                    ////
--//// PURPOSE: Raises when a theme color is still referenced by named current web rows                          ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
	v_subject_label text;
	v_reference_count bigint;
	v_reference_labels text[];
BEGIN
	SELECT tc.label || ' (' || tc.key || ')'
	INTO v_subject_label
	FROM web_priv.web_theme_colors tc
	WHERE tc.theme_color_id = p_theme_color_id;

	v_subject_label := COALESCE(v_subject_label, '#' || p_theme_color_id::text);

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_categories c WHERE c.icon_color_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.category_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title, c.category_id FROM web_priv.web_categories c WHERE c.icon_color_id = p_theme_color_id ORDER BY c.title, c.category_id LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'category', 'categories', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_subcategories sc WHERE sc.icon_color_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.category_title, dep.title, dep.subcategory_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT sc.title,
					 c.title AS category_title,
					 c.title || ' / ' || sc.title AS label,
					 sc.subcategory_id
			  FROM web_priv.web_subcategories sc
			  JOIN web_priv.web_categories c ON c.category_id = sc.category_id
			  WHERE sc.icon_color_id = p_theme_color_id
			  ORDER BY c.title, sc.title, sc.subcategory_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'subcategory', 'subcategories', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_series s WHERE s.icon_color_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.title ORDER BY dep.title, dep.series_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT s.title, s.series_id FROM web_priv.web_series s WHERE s.icon_color_id = p_theme_color_id ORDER BY s.title, s.series_id LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'series', 'series', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_templates t WHERE t.default_icon_color_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.label, dep.template_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT t.label || ' (' || t.template_code || ')' AS label,
					 t.template_id
			  FROM web_priv.web_templates t
			  WHERE t.default_icon_color_id = p_theme_color_id
			  ORDER BY t.label, t.template_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'template', 'templates', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_content c WHERE c.icon_color_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' (' || c.status_code || ')' AS label,
					 c.content_id
			  FROM web_priv.web_content c
			  WHERE c.icon_color_id = p_theme_color_id
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'explicit content color', 'explicit content colors', v_reference_count, v_reference_labels);
	END IF;

	SELECT COUNT(*) INTO v_reference_count FROM web_priv.web_content c WHERE c.icon_color_effective_id = p_theme_color_id;
	IF v_reference_count > 0 THEN
		SELECT COALESCE(array_agg(dep.label ORDER BY dep.title, dep.content_id), ARRAY[]::text[])
		INTO v_reference_labels
		FROM (SELECT c.title,
					 c.title || ' (' || c.status_code || ')' AS label,
					 c.content_id
			  FROM web_priv.web_content c
			  WHERE c.icon_color_effective_id = p_theme_color_id
			  ORDER BY c.title, c.content_id
			  LIMIT 5) dep;
		PERFORM web_priv.web_dependency_raise_guard('delete', 'theme color', v_subject_label, 'effective content color', 'effective content colors', v_reference_count, v_reference_labels);
	END IF;
END;
$$;


