--
-- Name: web_theme_color_record_history(bigint, text, character varying, timestamp with time zone); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_theme_color_record_history(p_theme_color_id bigint, p_change_type text, p_changed_by_discord_id character varying, p_changed_dt timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// RECORDS A CURRENT THEME COLOR SNAPSHOT INTO WEB_THEME_COLORS_H                                                ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
DECLARE
    v_theme_color web_priv.web_theme_colors%ROWTYPE;
    v_version_no integer;
BEGIN
    IF p_change_type NOT IN ('create', 'update', 'delete') THEN
        RAISE EXCEPTION 'Unsupported web_theme_colors_h.change_type value: %.', p_change_type;
    END IF;

    SELECT *
      INTO v_theme_color
      FROM web_priv.web_theme_color_find_by_id(p_theme_color_id);

    IF v_theme_color.theme_color_id IS NULL THEN
        RAISE EXCEPTION 'web_theme_colors row % was not found for history recording.', p_theme_color_id;
    END IF;

    UPDATE web_priv.web_theme_colors_h tch
       SET is_current = false
     WHERE tch.theme_color_id = p_theme_color_id
       AND tch.is_current = true;

    SELECT COALESCE(MAX(tch.version_no), 0) + 1
      INTO v_version_no
      FROM web_priv.web_theme_colors_h tch
     WHERE tch.theme_color_id = p_theme_color_id;

    INSERT INTO web_priv.web_theme_colors_h (
        theme_color_id,
        version_no,
        is_current,
        change_type,
        changed_by_discord_id,
        changed_dt,
        key,
        label,
        preview,
        is_enabled,
        created_by_discord_id,
        created_dt,
        updated_by_discord_id,
        updated_dt
    )
    VALUES (
        v_theme_color.theme_color_id,
        v_version_no,
        true,
        p_change_type,
        NULLIF(btrim(p_changed_by_discord_id), ''),
        COALESCE(p_changed_dt, now()),
        v_theme_color.key,
        v_theme_color.label,
        v_theme_color.preview,
        v_theme_color.is_enabled,
        v_theme_color.created_by_discord_id,
        v_theme_color.created_dt,
        v_theme_color.updated_by_discord_id,
        v_theme_color.updated_dt
    );

    RETURN v_version_no;
END;
$$;


