COMMENT ON FUNCTION web_priv.web_theme_color_record_history(p_theme_color_id bigint, p_change_type text, p_changed_by_discord_id character varying, p_changed_dt timestamp with time zone) IS 'Writes a current-row snapshot into web_theme_colors_h and marks older snapshots as non-current.';


--
-- Name: web_youtube_channel_assert_allowed(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_youtube_channel_assert_allowed(p_channel_external_id text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_youtube_channel_assert_allowed                                                    ////
--//// PURPOSE: Validates that a resolved YouTube channel ID is enabled in the allowlist                         ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_channel_external_id text;
BEGIN
	v_channel_external_id := NULLIF(btrim(COALESCE(p_channel_external_id, '')), '');

	IF v_channel_external_id IS NULL THEN
		RAISE EXCEPTION 'YouTube channel ID is required.';
	END IF;

	IF NOT web_priv.web_youtube_channel_is_allowed(v_channel_external_id) THEN
		RAISE EXCEPTION 'YouTube channel % is not allowlisted.', v_channel_external_id;
	END IF;
END;
$$;


