--

CREATE FUNCTION web_priv.web_youtube_channel_is_allowed(p_channel_external_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
	SELECT EXISTS (SELECT 1
				   FROM web_priv.web_youtube_channels_c ytc
				   WHERE ytc.channel_external_id = btrim(COALESCE(p_channel_external_id, ''))
					 AND ytc.is_enabled = true)
	;
$$;


