--
-- Name: web_youtube_video_id_from_url(text); Type: FUNCTION; Schema: web_priv; Owner: cm
--

CREATE FUNCTION web_priv.web_youtube_video_id_from_url(p_raw_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$

--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
--//// FUNCTION: web_priv.web_youtube_video_id_from_url                                                        ////
--//// PURPOSE: Extracts a safe YouTube video id from accepted watch, short-link, or shorts URLs                 ////
--//// ------------------------------------------Powered by Wooden Engine------------------------------------------ ////
--//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

DECLARE
	v_url text;
	v_match text[];
BEGIN
	v_url := btrim(COALESCE(p_raw_url, ''));

	IF v_url = '' OR v_url ~ '[[:cntrl:][:space:]]' THEN
		RETURN NULL;
	END IF;

	v_match := regexp_match(v_url, '^https://youtu\.be/([A-Za-z0-9_-]{11})([/\?#].*)?$', 'i');
	IF v_match IS NOT NULL THEN
		RETURN v_match[1];
	END IF;

	v_match := regexp_match(v_url, '^https://(www\.)?youtube\.com/shorts/([A-Za-z0-9_-]{11})([/\?#].*)?$', 'i');
	IF v_match IS NOT NULL THEN
		RETURN v_match[2];
	END IF;

	v_match := regexp_match(v_url, '^https://(www\.)?youtube\.com/watch\?([^#]*&)?v=([A-Za-z0-9_-]{11})(&[^#]*)?(#.*)?$', 'i');
	IF v_match IS NOT NULL THEN
		RETURN v_match[3];
	END IF;

	RETURN NULL;
END;
$_$;


