--
-- Name: web_navigation_panels; Type: TABLE; Schema: web_priv; Owner: cm
--

CREATE TABLE web_priv.web_navigation_panels (
    navigation_panel_id bigint NOT NULL,
    panel_key text NOT NULL,
    label text NOT NULL,
    panel_type_code text NOT NULL,
    panel_slot_code text NOT NULL,
    is_default boolean DEFAULT true NOT NULL,
    selection_order integer DEFAULT 100 NOT NULL,
    read_policy_code text DEFAULT 'public'::text NOT NULL,
    read_rank integer,
    max_categories integer,
    max_subcategories_per_category integer,
    max_targets_per_subcategory integer,
    is_enabled boolean DEFAULT true NOT NULL,
    created_by_discord_id character varying(32),
    created_dt timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_discord_id character varying(32),
    updated_dt timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT web_nav_panels_key_not_blank_chk CHECK ((btrim(panel_key) <> ''::text)),
    CONSTRAINT web_nav_panels_label_not_blank_chk CHECK ((btrim(label) <> ''::text)),
    CONSTRAINT web_nav_panels_max_cat_chk CHECK (((max_categories IS NULL) OR (max_categories >= 1))),
    CONSTRAINT web_nav_panels_max_subcat_chk CHECK (((max_subcategories_per_category IS NULL) OR (max_subcategories_per_category >= 1))),
    CONSTRAINT web_nav_panels_max_target_chk CHECK (((max_targets_per_subcategory IS NULL) OR (max_targets_per_subcategory >= 1))),
    CONSTRAINT web_nav_panels_read_policy_code_chk CHECK ((read_policy_code = ANY (ARRAY['public'::text, 'min_rank'::text, 'equal_rank'::text]))),
    CONSTRAINT web_nav_panels_read_policy_shape_chk CHECK ((((read_policy_code = 'public'::text) AND (read_rank IS NULL)) OR ((read_policy_code = ANY (ARRAY['min_rank'::text, 'equal_rank'::text])) AND (read_rank IS NOT NULL) AND (read_rank >= 0)))),
    CONSTRAINT web_nav_panels_selection_order_positive_chk CHECK ((selection_order >= 1)),
