   FROM web_priv.auth_users au;


ALTER VIEW web_view.auth_users OWNER TO cm;

--
-- Name: discord_actor_access; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.discord_actor_access AS
 SELECT du.discord_user_id,
    du.auth_user_id,
    du.discord_id,
    du.username,
    du.global_name,
    du.avatar_url,
    du.is_member,
    du.roles_synced_dt,
    du.last_login_dt,
    ((du.roles_synced_dt IS NULL) OR (du.roles_synced_dt < (now() - '00:15:00'::interval))) AS is_role_refresh_due,
    true AS is_authenticated,
    (COALESCE(dp.is_admin, false) OR COALESCE(da.is_admin, false) OR COALESCE(cra.configured_is_admin, false)) AS is_admin,
    (COALESCE(dp.is_editor, false) OR COALESCE(da.is_editor, false) OR COALESCE(cra.configured_is_editor, false)) AS is_editor,
    GREATEST(COALESCE(dp.max_rank, 0), COALESCE(da.max_rank, 0), COALESCE(cra.configured_max_rank, 0)) AS max_rank
   FROM ((((web_priv.discord_users du
     JOIN web_priv.auth_users au ON (((au.auth_user_id = du.auth_user_id) AND (au.is_disabled = false))))
     LEFT JOIN ( SELECT du_agg.discord_user_id,
            COALESCE(bool_or(dr_agg.is_admin), false) AS configured_is_admin,
            COALESCE(bool_or(dr_agg.is_editor), false) AS configured_is_editor,
            COALESCE(max(dr_agg.rank), 0) AS configured_max_rank
           FROM ((web_priv.discord_users du_agg
             LEFT JOIN web_priv.discord_user_role_cache durc ON ((durc.discord_user_id = du_agg.discord_user_id)))
             LEFT JOIN web_priv.discord_roles dr_agg ON ((((dr_agg.role_id)::text = (durc.discord_role_id)::text) AND (dr_agg.source = 'discord'::web_priv.enum_discord_roles_source) AND (dr_agg.is_access_role = true))))
          GROUP BY du_agg.discord_user_id) cra ON ((cra.discord_user_id = du.discord_user_id)))
     CROSS JOIN ( SELECT COALESCE(bool_or(dr_public.is_admin), false) AS is_admin,
            COALESCE(bool_or(dr_public.is_editor), false) AS is_editor,
            COALESCE(max(dr_public.rank), 0) AS max_rank
           FROM web_priv.discord_roles dr_public
          WHERE (dr_public.is_public_default = true)) dp)
     CROSS JOIN ( SELECT COALESCE(bool_or(dr_authenticated.is_admin), false) AS is_admin,
            COALESCE(bool_or(dr_authenticated.is_editor), false) AS is_editor,
            COALESCE(max(dr_authenticated.rank), 0) AS max_rank
           FROM web_priv.discord_roles dr_authenticated
          WHERE (dr_authenticated.is_authenticated_default = true)) da);


ALTER VIEW web_view.discord_actor_access OWNER TO cm;

--
-- Name: discord_roles; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.discord_roles AS
 SELECT id,
    name,
    (source)::text AS source,
    role_id,
    color_hex,
    rank,
    is_access_role,
    is_public_default,
    is_authenticated_default,
    is_admin,
    is_editor,
    created_dt,
    updated_dt
   FROM web_priv.discord_roles;


ALTER VIEW web_view.discord_roles OWNER TO cm;

--
-- Name: discord_user_cached_roles; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.discord_user_cached_roles AS
 SELECT du.discord_user_id,
    du.auth_user_id,
    du.discord_id,
    durc.discord_role_id,
    dr.id AS configured_role_id,
    COALESCE(dr.name, (durc.role_name)::character varying) AS name,
    COALESCE((dr.source)::text, 'discord'::text) AS source,
    dr.color_hex,
    durc.color_integer,
    COALESCE(dr.rank, 0) AS rank,
    COALESCE(dr.is_access_role, false) AS is_access_role,
    COALESCE(dr.is_public_default, false) AS is_public_default,
    COALESCE(dr.is_authenticated_default, false) AS is_authenticated_default,
    COALESCE(dr.is_admin, false) AS is_admin,
    COALESCE(dr.is_editor, false) AS is_editor,
    durc.role_position,
    durc.is_managed,
    durc.synced_dt,
    durc.sync_source
   FROM ((web_priv.discord_users du
     JOIN web_priv.discord_user_role_cache durc ON ((durc.discord_user_id = du.discord_user_id)))
     LEFT JOIN web_priv.discord_roles dr ON ((((dr.role_id)::text = (durc.discord_role_id)::text) AND (dr.source = 'discord'::web_priv.enum_discord_roles_source))));


ALTER VIEW web_view.discord_user_cached_roles OWNER TO cm;

