   FROM web_priv.discord_users du;


ALTER VIEW web_view.discord_users OWNER TO cm;

--
-- Name: web_categories_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_categories_admin AS
 SELECT c.category_id,
    c.title,
    c.slug,
    c.nav_hidden,
    c.read_policy_code,
    c.read_rank,
    c.write_policy_code,
    c.write_rank,
    c.icon_key_id,
    i.key AS icon_key_key,
    i.label AS icon_key_label,
    i.source_code AS icon_key_source_code,
    i.lucide_name AS icon_key_lucide_name,
    m.media_id AS icon_media_id,
    m.storage_rel_path AS icon_media_storage_rel_path,
    m.filename AS icon_media_filename,
    m.original_filename AS icon_media_original_filename,
    m.mime_type AS icon_media_mime_type,
    c.icon_color_id,
    tc.key AS icon_color_key,
    tc.label AS icon_color_label,
    tc.preview AS icon_color_preview,
    ( SELECT array_agg(r.template_id ORDER BY r.template_id) AS array_agg
           FROM web_priv.web_category_template_r r
          WHERE ((r.category_id = c.category_id) AND (r.is_enabled = true))) AS template_ids,
    c.created_dt,
    c.updated_dt
   FROM (((web_priv.web_categories c
     JOIN web_priv.web_icons i ON ((i.icon_id = c.icon_key_id)))
     LEFT JOIN web_priv.web_media m ON ((m.media_id = i.media_id)))
     JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = c.icon_color_id)));


ALTER VIEW web_view.web_categories_admin OWNER TO cm;

