--
-- Name: web_category_template_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_category_template_admin AS
 SELECT r.category_template_id,
    r.category_id,
    c.title AS category_title,
    c.slug AS category_slug,
    r.template_id,
    t.template_code,
    t.label AS template_label,
    t.content_kind_code,
    t.surface_scope_code,
    t.requires_series,
    r.is_enabled,
    r.created_by_discord_id,
    r.created_dt,
    r.updated_by_discord_id,
    r.updated_dt
   FROM ((web_priv.web_category_template_r r
