    c.author_discord_id,
    COALESCE(NULLIF(btrim(du.global_name), ''::text), NULLIF(btrim(du.username), ''::text), NULLIF(btrim((c.author_discord_id)::text), ''::text)) AS author_username,
    c.status_code,
    c.published_dt,
    c.archived_dt,
    c.read_policy_code,
    c.read_rank,
    c.read_effective_policy_code,
    c.read_effective_rank,
    c.write_policy_code,
    c.write_rank,
