    ck.public_route_prefix,
    ck.renderer_code
   FROM (((((((((((web_priv.web_content c
     JOIN web_priv.web_templates t ON ((t.template_id = c.template_id)))
     JOIN web_priv.web_content_kind_c ck ON ((ck.content_kind_code = t.content_kind_code)))
     JOIN web_priv.web_categories cat ON ((cat.category_id = c.category_id)))
     LEFT JOIN web_priv.web_subcategories sc ON ((sc.subcategory_id = c.subcategory_id)))
     LEFT JOIN web_priv.web_series s ON ((s.series_id = c.series_id)))
     LEFT JOIN web_priv.discord_users du ON (((du.discord_id)::text = (c.author_discord_id)::text)))
     LEFT JOIN web_priv.web_icons ik ON ((ik.icon_id = c.icon_key_id)))
     LEFT JOIN web_priv.web_media im ON ((im.media_id = ik.media_id)))
     LEFT JOIN web_priv.web_icons ike ON ((ike.icon_id = c.icon_key_effective_id)))
     LEFT JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = c.icon_color_id)))
     LEFT JOIN web_priv.web_theme_colors tce ON ((tce.theme_color_id = c.icon_color_effective_id)));


