    c.author_discord_id,
    COALESCE(NULLIF(btrim(du.global_name), ''::text), NULLIF(btrim(du.username), ''::text), NULLIF(btrim((c.author_discord_id)::text), ''::text)) AS author_username,
    c.status_code,
    c.published_dt,
    c.read_effective_policy_code,
    c.read_effective_rank,
    c.write_effective_policy_code,
    c.write_effective_rank,
    c.nav_hidden_effective,
    c.icon_key_effective_id,
    ik.key AS icon_key_effective_key,
    ik.label AS icon_key_effective_label,
    ik.source_code AS icon_key_effective_source_code,
    ik.lucide_name AS icon_key_effective_lucide_name,
    ik.media_id AS icon_media_id,
    im.storage_rel_path AS icon_media_storage_rel_path,
    im.filename AS icon_media_filename,
    im.original_filename AS icon_media_original_filename,
    im.mime_type AS icon_media_mime_type,
    c.icon_color_effective_id,
    tc.key AS icon_color_effective_key,
    tc.label AS icon_color_effective_label,
    tc.preview AS icon_color_effective_preview,
    c.created_dt,
    c.updated_dt
   FROM (((((((web_priv.web_content c
     JOIN web_priv.web_templates t ON ((t.template_id = c.template_id)))
     JOIN web_priv.web_categories cat ON ((cat.category_id = c.category_id)))
     LEFT JOIN web_priv.web_subcategories sc ON ((sc.subcategory_id = c.subcategory_id)))
     LEFT JOIN web_priv.discord_users du ON (((du.discord_id)::text = (c.author_discord_id)::text)))
     LEFT JOIN web_priv.web_icons ik ON ((ik.icon_id = c.icon_key_effective_id)))
     LEFT JOIN web_priv.web_media im ON ((im.media_id = ik.media_id)))
     LEFT JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = c.icon_color_effective_id)));


