--

CREATE VIEW web_view.web_content_template_fields_lookup AS
 SELECT tf.template_field_id,
    tf.template_id,
    t.template_code,
    t.label AS template_label,
    t.content_kind_code,
    t.surface_scope_code,
    t.requires_series,
    tf.field_list_id,
    fl.field_list_code,
    COALESCE(NULLIF(btrim(tf.label_override), ''::text), fl.label) AS label,
    COALESCE(NULLIF(btrim(tf.help_text_override), ''::text), fl.help_text) AS help_text,
    fl.field_type_code,
    fl.render_destination_code,
    tf.layout_width_code,
    tf.layout_align_code,
    ft.label AS field_type_label,
    ft.value_column_name,
    tf.display_order,
    tf.is_required,
    tf.is_enabled,
    ( SELECT count(*) AS count
           FROM web_priv.web_template_field_options o
          WHERE ((o.field_list_id = tf.field_list_id) AND (o.is_enabled = true))) AS option_count,
    tf.show_label_flag,
    tf.label_style_code,
    tf.label_position_code,
    tf.label_separator_code
   FROM (((web_priv.web_template_fields tf
     JOIN web_priv.web_templates t ON ((t.template_id = tf.template_id)))
     JOIN web_priv.web_template_field_list fl ON ((fl.field_list_id = tf.field_list_id)))
     JOIN web_priv.web_template_field_type_c ft ON ((ft.field_type_code = fl.field_type_code)))
  WHERE ((tf.is_enabled = true) AND (t.is_enabled = true))
  ORDER BY tf.template_id, tf.display_order, tf.template_field_id;


