    updated_dt,
    (( SELECT count(*) AS count
           FROM web_priv.web_navigation_panel_categories pc
          WHERE (pc.navigation_panel_id = p.navigation_panel_id)))::integer AS category_count,
    (( SELECT count(*) AS count
           FROM (web_priv.web_navigation_panel_subcategories ps
             JOIN web_priv.web_navigation_panel_categories pc ON ((pc.navigation_panel_category_id = ps.navigation_panel_category_id)))
          WHERE (pc.navigation_panel_id = p.navigation_panel_id)))::integer AS subcategory_count,
    (( SELECT count(*) AS count
           FROM ((web_priv.web_navigation_panel_targets pt
             JOIN web_priv.web_navigation_panel_subcategories ps ON ((ps.navigation_panel_subcategory_id = pt.navigation_panel_subcategory_id)))
             JOIN web_priv.web_navigation_panel_categories pc ON ((pc.navigation_panel_category_id = ps.navigation_panel_category_id)))
          WHERE (pc.navigation_panel_id = p.navigation_panel_id)))::integer AS target_count
   FROM web_priv.web_navigation_panels p;


