-- Name: web_navigation_subcategories_lookup; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_navigation_subcategories_lookup AS
 SELECT s.subcategory_id,
    s.category_id,
    c.title AS category_title,
    c.slug AS category_slug,
    s.title,
    s.slug,
    s.nav_hidden_effective,
    s.read_effective_policy_code,
    s.read_effective_rank,
    s.icon_key_id AS icon_key_effective_id,
    ik.key AS icon_key_key,
    ik.label AS icon_key_label,
    ik.source_code AS icon_key_source_code,
    ik.lucide_name AS icon_key_lucide_name,
    im.media_id AS icon_media_id,
    im.storage_rel_path AS icon_media_storage_rel_path,
    s.icon_color_id AS icon_color_effective_id,
    tc.preview AS icon_color_preview
   FROM ((((web_priv.web_subcategories s
     JOIN web_priv.web_categories c ON ((c.category_id = s.category_id)))
     LEFT JOIN web_priv.web_icons ik ON ((ik.icon_id = s.icon_key_id)))
     LEFT JOIN web_priv.web_media im ON ((im.media_id = ik.media_id)))
     LEFT JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = s.icon_color_id)))
  WHERE ((c.nav_hidden = false) AND (s.nav_hidden_effective = false));


ALTER VIEW web_view.web_navigation_subcategories_lookup OWNER TO cm;

--
-- Name: web_series_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_series_admin AS
 SELECT s.series_id,
    s.title,
    s.slug,
    s.description,
    s.category_id,
    c.title AS category_title,
    c.slug AS category_slug,
    s.subcategory_id,
    sc.title AS subcategory_title,
    sc.slug AS subcategory_slug,
    s.author_discord_id,
    COALESCE(NULLIF(btrim(du.global_name), ''::text), NULLIF(btrim(du.username), ''::text), NULLIF(btrim((s.author_discord_id)::text), ''::text)) AS author_username,
    s.read_policy_code,
    s.read_rank,
    s.read_effective_policy_code,
    s.read_effective_rank,
    s.write_policy_code,
    s.write_rank,
    s.write_effective_policy_code,
    s.write_effective_rank,
    s.icon_key_id,
    i.key AS icon_key_key,
    i.label AS icon_key_label,
    i.source_code AS icon_key_source_code,
    i.lucide_name AS icon_key_lucide_name,
    i.media_id AS icon_media_id,
    m.storage_rel_path AS icon_media_storage_rel_path,
    m.filename AS icon_media_filename,
    m.original_filename AS icon_media_original_filename,
    m.mime_type AS icon_media_mime_type,
    s.icon_color_id,
    tc.key AS icon_color_key,
    tc.label AS icon_color_label,
    tc.preview AS icon_color_preview,
    s.created_by_discord_id,
    s.created_dt,
    s.updated_by_discord_id,
    s.updated_dt
   FROM ((((((web_priv.web_series s
     JOIN web_priv.web_categories c ON ((c.category_id = s.category_id)))
     LEFT JOIN web_priv.web_subcategories sc ON (((sc.category_id = s.category_id) AND (sc.subcategory_id = s.subcategory_id))))
     JOIN web_priv.web_icons i ON ((i.icon_id = s.icon_key_id)))
     LEFT JOIN web_priv.web_media m ON ((m.media_id = i.media_id)))
     JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = s.icon_color_id)))
     LEFT JOIN web_priv.discord_users du ON (((du.discord_id)::text = (s.author_discord_id)::text)));


ALTER VIEW web_view.web_series_admin OWNER TO cm;

--
-- Name: VIEW web_series_admin; Type: COMMENT; Schema: web_view; Owner: cm
--

COMMENT ON VIEW web_view.web_series_admin IS 'Admin-facing series read surface with joined category, subcategory, icon, color, and author metadata.';


