CREATE VIEW web_view.web_series_lookup AS
 SELECT series_id,
    title,
    slug,
    category_id,
    subcategory_id,
    read_effective_policy_code,
    read_effective_rank,
    icon_key_id,
    icon_color_id,
    COALESCE(( SELECT (max(c.series_part_no) + 1)
           FROM web_priv.web_content c
          WHERE ((c.series_id = s.series_id) AND (c.series_part_no IS NOT NULL) AND (c.status_code <> 'archived'::text))), 1) AS next_part_no
   FROM web_priv.web_series s;


