--
-- Name: web_template_field_list_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_template_field_list_admin AS
 SELECT fl.field_list_id,
    fl.field_list_code,
    fl.label,
    fl.help_text,
    fl.field_type_code,
    fl.render_destination_code,
    ft.label AS field_type_label,
    ft.value_column_name,
    fl.is_enabled,
    ( SELECT count(*) AS count
           FROM web_priv.web_template_fields tf
          WHERE (tf.field_list_id = fl.field_list_id)) AS template_usage_count,
    ( SELECT count(*) AS count
           FROM web_priv.web_template_field_options o
          WHERE (o.field_list_id = fl.field_list_id)) AS option_count,
    ( SELECT count(*) AS count
           FROM (web_priv.web_template_field_list_tools_r rel
             JOIN web_priv.web_template_field_tools_c tool ON ((tool.field_tool_code = rel.field_tool_code)))
          WHERE ((rel.field_list_id = fl.field_list_id) AND (rel.is_enabled = true) AND (tool.is_enabled = true))) AS tool_count,
    fl.created_by_discord_id,
    fl.created_dt,
    fl.updated_by_discord_id,
    fl.updated_dt
   FROM (web_priv.web_template_field_list fl
     JOIN web_priv.web_template_field_type_c ft ON ((ft.field_type_code = fl.field_type_code)));


ALTER VIEW web_view.web_template_field_list_admin OWNER TO cm;

--
-- Name: web_template_field_list_tools_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_template_field_list_tools_admin AS
 SELECT rel.field_list_tool_id,
    rel.field_list_id,
    field_list.field_list_code,
    field_list.label AS field_list_label,
    field_list.field_type_code,
    field_type.label AS field_type_label,
    field_type.value_column_name,
    rel.field_tool_code,
    tool.label AS field_tool_label,
    tool.tool_group_code,
    tool.display_order,
    tool.description,
    tool.is_enabled AS field_tool_enabled,
    rel.is_enabled,
    rel.created_by_discord_id,
    rel.created_dt,
    rel.updated_by_discord_id,
    rel.updated_dt
   FROM (((web_priv.web_template_field_list_tools_r rel
     JOIN web_priv.web_template_field_list field_list ON ((field_list.field_list_id = rel.field_list_id)))
     JOIN web_priv.web_template_field_type_c field_type ON ((field_type.field_type_code = field_list.field_type_code)))
     JOIN web_priv.web_template_field_tools_c tool ON ((tool.field_tool_code = rel.field_tool_code)));


ALTER VIEW web_view.web_template_field_list_tools_admin OWNER TO cm;

--
-- Name: web_template_field_list_tools_lookup; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_template_field_list_tools_lookup AS
 SELECT rel.field_list_id,
    field_list.field_list_code,
    field_list.field_type_code,
    rel.field_tool_code,
    tool.label AS field_tool_label,
    tool.tool_group_code,
    tool.display_order
   FROM (((web_priv.web_template_field_list_tools_r rel
     JOIN web_priv.web_template_field_list field_list ON ((field_list.field_list_id = rel.field_list_id)))
     JOIN web_priv.web_template_field_type_c field_type ON ((field_type.field_type_code = field_list.field_type_code)))
     JOIN web_priv.web_template_field_tools_c tool ON ((tool.field_tool_code = rel.field_tool_code)))
  WHERE ((rel.is_enabled = true) AND (tool.is_enabled = true) AND (field_list.is_enabled = true) AND (field_type.is_enabled = true) AND (tool.field_type_code = field_list.field_type_code));


ALTER VIEW web_view.web_template_field_list_tools_lookup OWNER TO cm;

