--
-- Name: web_template_field_tools_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_template_field_tools_admin AS
 SELECT tool.field_tool_code,
    tool.field_type_code,
    field_type.label AS field_type_label,
    field_type.value_column_name,
