    ( SELECT count(*) AS count
           FROM web_priv.web_template_field_list_tools_r selected_tool
          WHERE (selected_tool.field_tool_code = tool.field_tool_code)) AS field_list_usage_count,
    tool.created_by_discord_id,
    tool.created_dt,
    tool.updated_by_discord_id,
    tool.updated_dt
   FROM (web_priv.web_template_field_tools_c tool
     JOIN web_priv.web_template_field_type_c field_type ON ((field_type.field_type_code = tool.field_type_code)));


