--

CREATE VIEW web_view.web_template_fields_admin AS
 SELECT tf.template_field_id,
    tf.template_id,
    t.template_code,
    t.label AS template_label,
    tf.field_list_id,
    fl.field_list_code,
    fl.label AS field_list_label,
    fl.help_text AS field_list_help_text,
    fl.field_type_code,
    fl.render_destination_code,
    ft.label AS field_type_label,
    ft.value_column_name,
    tf.label_override,
    tf.help_text_override,
    tf.display_order,
    tf.layout_width_code,
    tf.layout_align_code,
    tf.is_required,
    tf.is_enabled,
    tf.created_by_discord_id,
    tf.created_dt,
    tf.updated_by_discord_id,
    tf.updated_dt,
    tf.show_label_flag,
    tf.label_style_code,
    tf.label_position_code,
    tf.label_separator_code
   FROM (((web_priv.web_template_fields tf
     JOIN web_priv.web_templates t ON ((t.template_id = tf.template_id)))
     JOIN web_priv.web_template_field_list fl ON ((fl.field_list_id = tf.field_list_id)))
     JOIN web_priv.web_template_field_type_c ft ON ((ft.field_type_code = fl.field_type_code)));


