--
-- Name: web_templates_admin; Type: VIEW; Schema: web_view; Owner: cm
--

CREATE VIEW web_view.web_templates_admin AS
 SELECT t.template_id,
    t.template_code,
    t.template_code AS template_key,
    t.label,
    t.description,
    t.content_kind_code,
    ck.label AS content_kind_label,
    t.surface_scope_code,
    t.requires_series,
    t.default_icon_key_id,
    i.key AS default_icon_key_key,
    i.label AS default_icon_key_label,
    i.source_code AS default_icon_key_source_code,
    i.lucide_name AS default_icon_key_lucide_name,
    i.media_id AS default_icon_media_id,
    m.storage_rel_path AS default_icon_media_storage_rel_path,
    m.filename AS default_icon_media_filename,
    m.original_filename AS default_icon_media_original_filename,
    m.mime_type AS default_icon_media_mime_type,
    t.default_icon_color_id,
    tc.key AS default_icon_color_key,
    tc.label AS default_icon_color_label,
    tc.preview AS default_icon_color_preview,
    t.schema_version_no,
    t.is_enabled,
    ( SELECT count(*) AS count
           FROM web_priv.web_template_fields tf
          WHERE (tf.template_id = t.template_id)) AS field_count,
    t.created_by_discord_id,
    t.created_dt,
    t.updated_by_discord_id,
    t.updated_dt
   FROM ((((web_priv.web_templates t
     JOIN web_priv.web_content_kind_c ck ON ((ck.content_kind_code = t.content_kind_code)))
     LEFT JOIN web_priv.web_icons i ON ((i.icon_id = t.default_icon_key_id)))
     LEFT JOIN web_priv.web_media m ON ((m.media_id = i.media_id)))
     LEFT JOIN web_priv.web_theme_colors tc ON ((tc.theme_color_id = t.default_icon_color_id)));


ALTER VIEW web_view.web_templates_admin OWNER TO cm;

